INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90912, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "追问原因或责任，查明缘由。", "primary_collocate": null, "pronunciation": "zhuī jiū", "ipa": "tʂweɪ˥ tɕjoʊ˥", "syllable_count": 2, "sentences": [{"text": "出了事故，公司一定会追究责任。", "target_word": "追究", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次错误很小，老师不想追究了。", "target_word": "追究", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察正在追究这起事故的原因。", "target_word": "追究", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你为什么总要追究别人的错？", "target_word": "追究", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "没人想追究，大家只想快点把事情做完。", "target_word": "追究", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说了对不起，我就不再追究他了。", "target_word": "追究", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院追究过这件事的责任。", "target_word": "追究", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁都不能因为怕麻烦，就不追究问题的原因。", "target_word": "追究", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校没有追究他迟到的原因，只让他快进教室。", "target_word": "追究", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律会追究他的责任，他不能躲。", "target_word": "追究", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "追究了", "label": "完成体"}, {"form": "追究过", "label": "经历体"}, {"form": "追究着", "label": "持续体"}], "register": "中性", "sense_fingerprint": "查问事情的原因，要弄清谁该负责", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b342a05-3699-4607-9d19-13216e1ae00e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90912, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "追究", "is_correct": true, "explanation": "追究指查问原因或责任，正合「公司一定会追究责任」。"}, {"text": "歌颂", "is_correct": false, "explanation": "语义：歌颂是赞美人或事，不能搭配「责任」，也不表示查问。"}, {"text": "安慰", "is_correct": false, "explanation": "配价：安慰的对象应是人，不能安慰「责任」。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：修理可以搭配机器等具体物件，不能搭配「责任」。"}], "explanations": {"追究": "追究指查问原因或责任，正合「公司一定会追究责任」。", "歌颂": "语义：歌颂是赞美人或事，不能搭配「责任」，也不表示查问。", "安慰": "配价：安慰的对象应是人，不能安慰「责任」。", "修理": "搭配：修理可以搭配机器等具体物件，不能搭配「责任」。"}, "sentence_index": 0, "correct_answer": "追究"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "人们在烈士陵园里追究牺牲的战士。", "explanation": "这里应该用〈追悼〉。追悼是哀悼死者，追究是查问原因或责任，不能用于哀悼牺牲的战士。"}, {"text": "她一直追究老师的脚步。", "explanation": "这里应该用〈追随〉。追随指跟在别人后面学习、效法，追究指查问原因或责任，不能用于跟随脚步。"}, {"text": "孩子们都追究这个新玩具。", "explanation": "这里应该用〈追捧〉。追捧指热烈地喜爱、争相购买，追究指查问原因或责任，不能用于形容对玩具的喜爱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90912, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "追究", "is_correct": true, "explanation": "追究指查问责任，与「医院追究过这件事的责任」相合。"}, {"text": "欢迎", "is_correct": false, "explanation": "语义：欢迎表示接受或喜爱，不能用来指查问责任。"}, {"text": "修补", "is_correct": false, "explanation": "搭配：修补多接关系、漏洞等，不说「修补责任」。"}, {"text": "讨好", "is_correct": false, "explanation": "配价：讨好的对象应是人，不能讨好「责任」。"}], "explanations": {"追究": "追究指查问责任，与「医院追究过这件事的责任」相合。", "欢迎": "语义：欢迎表示接受或喜爱，不能用来指查问责任。", "修补": "搭配：修补多接关系、漏洞等，不说「修补责任」。", "讨好": "配价：讨好的对象应是人，不能讨好「责任」。"}, "sentence_index": 6, "correct_answer": "追究"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "部队在山谷里追究敌人。", "explanation": "这里应该用〈追击〉。追击指追赶逃跑的敌人，追究指查问原因或责任，不能用于追赶敌人。"}, {"text": "他在雨中追究公交车。", "explanation": "这里应该用〈追赶〉。追赶指跑着赶上，追究指查问原因或责任，不能说「追究公交车」。"}, {"text": "他常常追究往日的欢乐时光。", "explanation": "这里应该用〈追忆〉。追忆指回想过去的事，追究指查问原因或责任，不能用于回想欢乐的时光。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90912, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们正在追究了这起事故的责任。", "corrected_sentence": "我们正在追究这起事故的责任。", "error_description": "「正在」表示动作进行，不能与完成体「了」同用，应去掉「了」，改为「正在追究这起事故的责任」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90912, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他不追究过这件事。", "corrected_sentence": "他没追究过这件事。", "error_description": "否定已发生的经历要用「没」，不能用「不」，应为「他没追究过这件事」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
