INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90913, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家分成省、市、县这样的一块一块。", "primary_collocate": null, "pronunciation": "xíng zhèng qū huà", "ipa": "ɕiŋ˧˥ ʈʂɤŋ˥˩ tɕʰy˥ xua˥˩", "syllable_count": 4, "sentences": [{"text": "中国的行政区划有省、市、县几级。", "target_word": "行政区划", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们在地理课上学习中国的行政区划。", "target_word": "行政区划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张地图上画着各省的行政区划。", "target_word": "行政区划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，行政区划就是把国家分成很多地方。", "target_word": "行政区划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同国家的行政区划不一样。", "target_word": "行政区划", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个城市的行政区划最近改变了。", "target_word": "行政区划", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想了解一下美国的行政区划。", "target_word": "行政区划", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "看地图可以知道中国的行政区划。", "target_word": "行政区划", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这本书详细介绍了日本的行政区划。", "target_word": "行政区划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在研究法国的行政区划是怎么变化的。", "target_word": "行政区划", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "行政區劃", "label": "繁体"}], "register": "书面", "sense_fingerprint": "国家分成省、市、县等层级的划分方式", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d48bf1a-fcce-4795-8810-0494f4f470de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90913, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行政区划", "is_correct": true, "explanation": "行政区划指国家划分出的省、市、县等层级，与“有省、市、县几级”相符。"}, {"text": "人口", "is_correct": false, "explanation": "语义：人口说的是人的数量，不能按省、市、县来划分。"}, {"text": "气候", "is_correct": false, "explanation": "语义：气候分热带、温带等类型，没有省、市、县这样的级别。"}, {"text": "历史", "is_correct": false, "explanation": "语义：历史是时间的过程，不是可以划分成省、市、县的对象。"}], "explanations": {"行政区划": "行政区划指国家划分出的省、市、县等层级，与“有省、市、县几级”相符。", "人口": "语义：人口说的是人的数量，不能按省、市、县来划分。", "气候": "语义：气候分热带、温带等类型，没有省、市、县这样的级别。", "历史": "语义：历史是时间的过程，不是可以划分成省、市、县的对象。"}, "sentence_index": 0, "correct_answer": "行政区划"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "中国的行政区划有十四亿。", "explanation": "这里应该用〈人口〉。行政区划指国家的划分方式，不能用来说人数，说人数要用人口。"}, {"text": "中国的行政区划有九百六十万平方公里。", "explanation": "这里应该用〈面积〉。行政区划说的是怎样划分，不指土地大小，说大小要用面积。"}, {"text": "他把这个行政区划穿在身上。", "explanation": "这里应该用〈外套〉。行政区划是划分地区的体系，不是衣服，不能穿在身上；穿的东西要用外套等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90913, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行政区划", "is_correct": true, "explanation": "行政区划指国家的划分方式，与“了解美国的”所指的内容相符。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的体貌特征，不能用来说一个国家。"}, {"text": "心情", "is_correct": false, "explanation": "语义：心情属于人的感受，“美国的心情”说不通。"}, {"text": "食欲", "is_correct": false, "explanation": "语义：食欲是人的生理感受，不能用来说美国。"}], "explanations": {"行政区划": "行政区划指国家的划分方式，与“了解美国的”所指的内容相符。", "身高": "体貌：身高是人的体貌特征，不能用来说一个国家。", "心情": "语义：心情属于人的感受，“美国的心情”说不通。", "食欲": "语义：食欲是人的生理感受，不能用来说美国。"}, "sentence_index": 6, "correct_answer": "行政区划"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把法国的行政区划吃掉了。", "explanation": "这里应该用〈调整〉。行政区划是可以调整、重划的划分体系，不能被吃掉。"}, {"text": "他研究的是法国的一只行政区划。", "explanation": "这里应该用〈套〉。行政区划是一整套划分体系，计量用“套”或“个”，不用动物用的“只”。"}, {"text": "他是法国的行政区划。", "explanation": "这里应该用〈官员〉。行政区划是划分方式，不是人，指人要用官员等词，这里把抽象的划分体系当成了人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90913, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们要研究国家地行政区划。", "corrected_sentence": "我们要研究国家的行政区划。", "error_description": "修饰名词“行政区划”要用“的”，不用“地”。“国家地行政区划”应改为“国家的行政区划”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90913, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只行政区划已经用了很多年。", "corrected_sentence": "这套行政区划已经用了很多年。", "error_description": "量词“只”用于动物或小的个体，不能用于行政区划。这里应该用“套”，正确形式为“这套行政区划”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
