INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90914, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家为管理而划分的地方行政区域。", "primary_collocate": null, "pronunciation": "xíng zhèng qū huà", "ipa": "ɕiŋ˧˥ ʈʂɤŋ˥˩ tɕʰy˥ xua˥˩", "syllable_count": 4, "sentences": [{"text": "省、市、县都是中国的行政区划。", "target_word": "行政区划", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个镇属于哪个行政区划？", "target_word": "行政区划", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "北京和上海是两个不同的行政区划。", "target_word": "行政区划", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了方便管理，政府新设了一个行政区划。", "target_word": "行政区划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座小城以前属于另一个行政区划。", "target_word": "行政区划", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "填表时要写清楚你所在的行政区划。", "target_word": "行政区划", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "县比乡大，是更高一级的行政区划。", "target_word": "行政区划", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "政府把两个县合成了一个新的行政区划。", "target_word": "行政区划", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个行政区划都有自己的政府。", "target_word": "行政区划", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地图上用不同的颜色表示不同的行政区划。", "target_word": "行政区划", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "行政區劃", "label": "繁体"}], "register": "书面", "sense_fingerprint": "国家为管理而划出的具体地方行政区域", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d48bf1a-fcce-4795-8810-0494f4f470de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90914, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "行政区划", "is_correct": true, "explanation": "行政区划指国家划出的具体行政区域，省、市、县都属于这类。"}, {"text": "人口", "is_correct": false, "explanation": "语义：人口指人的数量，省、市、县不是人口。"}, {"text": "历史", "is_correct": false, "explanation": "语义：历史是时间的过程，省、市、县不属于历史。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是人的体貌特征，不能说省、市、县是身高。"}], "explanations": {"行政区划": "行政区划指国家划出的具体行政区域，省、市、县都属于这类。", "人口": "语义：人口指人的数量，省、市、县不是人口。", "历史": "语义：历史是时间的过程，省、市、县不属于历史。", "身高": "体貌：身高是人的体貌特征，不能说省、市、县是身高。"}, "sentence_index": 0, "correct_answer": "行政区划"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我还没写完行政区划。", "explanation": "这里应该用〈作业〉。行政区划指地方区域，不能用“写完”；写完的东西要说作业、文章等。"}, {"text": "我们在这张地图上找到了一只行政区划。", "explanation": "这里应该用〈个〉。行政区划是地区单位，用“个”计量，“只”用于动物，不能用于它。"}, {"text": "我们把行政区划吃掉了。", "explanation": "这里应该用〈饭〉。行政区划是地方区域，不是食物，不能吃；能吃的东西要说饭等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90914, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "行政区划", "is_correct": true, "explanation": "行政区划指划分出的地方行政单位，“更高一级的”指的正是这类单位。"}, {"text": "人口", "is_correct": false, "explanation": "语义：人口指人的数量，不是可以分出“高一级”的单位。"}, {"text": "学位", "is_correct": false, "explanation": "语义：学位是学历的等级，“县比乡大”的比较对象不是学位。"}, {"text": "年级", "is_correct": false, "explanation": "搭配：“县比乡大”比较的是行政单位的大小，“年级”是学习阶段，不能这样比较。"}], "explanations": {"行政区划": "行政区划指划分出的地方行政单位，“更高一级的”指的正是这类单位。", "人口": "语义：人口指人的数量，不是可以分出“高一级”的单位。", "学位": "语义：学位是学历的等级，“县比乡大”的比较对象不是学位。", "年级": "搭配：“县比乡大”比较的是行政单位的大小，“年级”是学习阶段，不能这样比较。"}, "sentence_index": 6, "correct_answer": "行政区划"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她用红色和蓝色的毛线织了一个行政区划。", "explanation": "这里应该用〈毛衣〉。行政区划是地方区域，不是能织出来的物品；织出来的东西要说毛衣、围巾等。"}, {"text": "地图上有一颗行政区划。", "explanation": "这里应该用〈个〉。行政区划是地区单位，计量用“个”，“颗”用于小而圆的东西，不能用于它。"}, {"text": "这个行政区划的朋友很多。", "explanation": "这里应该用〈居民〉。行政区划是地方区域，不是人，不能交朋友；说朋友的对象要指居民等人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90914, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个县属于一条新的行政区划。", "corrected_sentence": "这个县属于一个新的行政区划。", "error_description": "量词“条”用于细长的东西，不能用于行政区划。这里应该用“个”，正确形式为“这个县属于一个新的行政区划”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90914, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个镇属于一颗较大的行政区划。", "corrected_sentence": "这个镇属于一个较大的行政区划。", "error_description": "量词“颗”用于小而圆的东西，不能用于行政区划。这里应该用“个”，正确形式为“这个镇属于一个较大的行政区划”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90916, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自然", "is_correct": true, "explanation": "正确：“人为”与“自然”是反义词，指人造与自然发生。"}, {"text": "复杂", "is_correct": false, "explanation": "“复杂”与“人为”不构成反义关系，“复杂”形容事情繁多。"}, {"text": "幸运", "is_correct": false, "explanation": "“幸运”形容遭遇好，与“人为”没有反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "“漂亮”与“人为”无反义关系，只说外观好看。"}], "correct_answer": "自然", "explanations": {"自然": "正确：“人为”与“自然”是反义词，指人造与自然发生。", "复杂": "“复杂”与“人为”不构成反义关系，“复杂”形容事情繁多。", "幸运": "“幸运”形容遭遇好，与“人为”没有反义关系。", "漂亮": "“漂亮”与“人为”无反义关系，只说外观好看。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcda1516-089b-43a9-89fd-53dfeb9462c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90916, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "自然", "is_correct": true, "explanation": "正确：“人为”与“自然”是反义词，指人造与自然发生。"}, {"text": "简单", "is_correct": false, "explanation": "“简单”与“人为”不构成反义关系，“简单”形容事情不复杂。"}, {"text": "认真", "is_correct": false, "explanation": "“认真”形容态度，与“人为”没有反义关系。"}, {"text": "高兴", "is_correct": false, "explanation": "“高兴”形容心情，与“人为”不是反义关系。"}], "correct_answer": "自然", "explanations": {"自然": "正确：“人为”与“自然”是反义词，指人造与自然发生。", "简单": "“简单”与“人为”不构成反义关系，“简单”形容事情不复杂。", "认真": "“认真”形容态度，与“人为”没有反义关系。", "高兴": "“高兴”形容心情，与“人为”不是反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcda1516-089b-43a9-89fd-53dfeb9462c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90916, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "由人造成的或由人做的。", "primary_collocate": null, "pronunciation": "rén wéi", "ipa": "ɻən˧˥ weɪ˧˥", "syllable_count": 2, "sentences": [{"text": "这次事故不是天气的问题，是人为的。", "target_word": "人为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个错误是人为造成的，可以避免。", "target_word": "人为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的树少了，这是人为的结果。", "target_word": "人为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察发现，这次火灾是人为的。", "target_word": "人为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人为的错误可以避免，自然的灾害不能。", "target_word": "人为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的垃圾太多了，是人为的问题。", "target_word": "人为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桥断了，不是地震，而是人为的。", "target_word": "人为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想知道，这次停电是不是人为的。", "target_word": "人为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气变差，有自然的原因，也有人为的原因。", "target_word": "人为", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河的污染主要是人为造成的。", "target_word": "人为", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "人为的", "label": "的字结构"}, {"form": "人为地", "label": "状语形式"}], "register": "中性", "sense_fingerprint": "由人引起的、不是自然发生的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4256b07-2d2b-4db1-830f-e6bafd30f388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90916, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "人为", "is_correct": true, "explanation": "正确：“人为”指由人造成的，不是自然发生的。"}, {"text": "人文", "is_correct": false, "explanation": "wén（第二声）与 wéi（第二声）韵母不同（en 与 ei），意思是人文学科或人文精神。"}, {"text": "认为", "is_correct": false, "explanation": "rèn（第四声）与 rén（第二声）声调不同，意思是认定、觉得。"}, {"text": "人味", "is_correct": false, "explanation": "wèi（第四声）与 wéi（第二声）声调不同，意思是人情味。"}], "explanations": {"人为": "正确：“人为”指由人造成的，不是自然发生的。", "人文": "wén（第二声）与 wéi（第二声）韵母不同（en 与 ei），意思是人文学科或人文精神。", "认为": "rèn（第四声）与 rén（第二声）声调不同，意思是认定、觉得。", "人味": "wèi（第四声）与 wéi（第二声）声调不同，意思是人情味。"}, "sentence_index": null, "correct_answer": "人为"}, "level_3": {"options": [{"text": "人为", "is_correct": true, "explanation": "正确：与“不是天气的问题”对照，表示由人引起的。"}, {"text": "聪明", "is_correct": false, "explanation": "搭配：“事故”不能用“聪明”形容。"}, {"text": "安静", "is_correct": false, "explanation": "语义：“事故”不能“安静”，与“是……的”的说明不通。"}, {"text": "灵活", "is_correct": false, "explanation": "搭配：“灵活”形容动作或思维，不能说“事故灵活”。"}], "explanations": {"人为": "正确：与“不是天气的问题”对照，表示由人引起的。", "聪明": "搭配：“事故”不能用“聪明”形容。", "安静": "语义：“事故”不能“安静”，与“是……的”的说明不通。", "灵活": "搭配：“灵活”形容动作或思维，不能说“事故灵活”。"}, "sentence_index": 0, "correct_answer": "人为"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "警察发现，这次火灾是人为地，不是天气造成的。", "explanation": "这里〈人为地〉是副词，不能作谓语，应说〈是人为的〉。"}, {"text": "警察发现，这次火灾是人为智能控制的，不是天气造成的。", "explanation": "这里应该用〈人工〉，如“人工智能”。〈人为〉不能修饰〈智能〉。"}, {"text": "警察发现，那位消防员是人为的。", "explanation": "〈人为〉用于事物或现象，不用来指人，应说明他的行为是故意的。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcda1516-089b-43a9-89fd-53dfeb9462c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90916, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "人为", "is_correct": true, "explanation": "正确：与“不是地震”对照，表示由人造成的。"}, {"text": "勇敢", "is_correct": false, "explanation": "搭配：“桥”不会“勇敢”，“勇敢”形容有胆量的人。"}, {"text": "热情", "is_correct": false, "explanation": "语义：“热情”只用于人的态度，桥断了不能热情。"}, {"text": "大方", "is_correct": false, "explanation": "语义：“大方”形容人的举止，不能用来说明桥断的原因。"}], "explanations": {"人为": "正确：与“不是地震”对照，表示由人造成的。", "勇敢": "搭配：“桥”不会“勇敢”，“勇敢”形容有胆量的人。", "热情": "语义：“热情”只用于人的态度，桥断了不能热情。", "大方": "语义：“大方”形容人的举止，不能用来说明桥断的原因。"}, "sentence_index": 6, "correct_answer": "人为"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条河的污染主要是人为智能造成的。", "explanation": "这里〈人为〉不能修饰〈智能〉，应说〈人工〉智能。"}, {"text": "这条河的污染是人为地。", "explanation": "这里〈人为地〉是副词，不能作谓语，应说〈是人为的〉。"}, {"text": "这条河的污染主要是人为的小孩造成的。", "explanation": "〈人为〉用于事物或现象，不用来指人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcda1516-089b-43a9-89fd-53dfeb9462c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90916, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这场大雾是自然形成的，不是人为了的。", "corrected_sentence": "这场大雾是自然形成的，不是人为的。", "error_description": "错误：“人为的”中间多加了“了”，形容词不能带“了”，应为“人为的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcda1516-089b-43a9-89fd-53dfeb9462c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90916, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座工厂的废水是人为了排放的。", "corrected_sentence": "这座工厂的废水是人为排放的。", "error_description": "错误：“人为”作状语修饰“排放”，后面不能加“了”，应为“人为排放的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcda1516-089b-43a9-89fd-53dfeb9462c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
