INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90917, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "逃脱是从被抓住或被关起来的地方跑出来了。", "primary_collocate": null, "pronunciation": "táo tuō", "ipa": "tʰɑʊ̯˧˥ tʰwo˧˥", "syllable_count": 2, "sentences": [{"text": "那个犯人昨晚从监狱逃脱了。", "target_word": "逃脱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小鸟从笼子里逃脱了，飞到了树上。", "target_word": "逃脱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "绑匪睡着以后，小男孩悄悄逃脱了。", "target_word": "逃脱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在押送的路上逃脱，警察找了三天。", "target_word": "逃脱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "狐狸从猎人的网里逃脱了。", "target_word": "逃脱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那只狗咬断绳子，从院子里逃脱了。", "target_word": "逃脱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "绑架他的人很多，他很难逃脱。", "target_word": "逃脱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "犯人想逃脱，可是门口有很多警察。", "target_word": "逃脱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把绳子解开，一个人逃脱了。", "target_word": "逃脱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个小偷以前逃脱过一次，这次警察看得很紧。", "target_word": "逃脱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "逃脱了", "label": "体标"}, {"form": "逃脱过", "label": "体标"}, {"form": "逃脫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "从被抓或被关押的地方跑出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c5d38-188c-4474-8f42-65925038992f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90917, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "逃脱", "is_correct": true, "explanation": "正确：“逃脱”指从被关押的地方跑出，与“从监狱”相符。"}, {"text": "进入", "is_correct": false, "explanation": "语义：“进入”的方向与“从监狱”相反，不能说从监狱进入。"}, {"text": "毕业", "is_correct": false, "explanation": "搭配：“毕业”只能从学校等处毕业，不能说“从监狱毕业”。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”指去看展览、场所，不能用于犯人的行动。"}], "explanations": {"逃脱": "正确：“逃脱”指从被关押的地方跑出，与“从监狱”相符。", "进入": "语义：“进入”的方向与“从监狱”相反，不能说从监狱进入。", "毕业": "搭配：“毕业”只能从学校等处毕业，不能说“从监狱毕业”。", "参观": "搭配：“参观”指去看展览、场所，不能用于犯人的行动。"}, "sentence_index": 0, "correct_answer": "逃脱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他想逃脱考试，所以没去。", "explanation": "这里应该用〈逃避〉。“逃脱”指从被抓或被关押的地方跑出，不能用来说躲避考试。"}, {"text": "他总是逃脱家务，不愿意洗碗。", "explanation": "这里应该用〈推托〉。“逃脱”指从被抓或被关的地方跑出，不能用来说推掉家务；推脱家务要用〈推托〉。"}, {"text": "他用力逃脱了绳子。", "explanation": "这里应该用〈挣脱〉。“逃脱”是人摆脱追捕或被关押而跑掉，不能直接以绳子为宾语；摆开绳子要用〈挣脱〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb58bb6-8a88-4756-9bac-5999758bfd60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90917, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "逃脱", "is_correct": true, "explanation": "正确：“很难逃脱”指被抓后难以摆脱，与“绑架他的人很多”相符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“唱歌”与“绑架他的人很多”的语境毫无关系。"}, {"text": "变胖", "is_correct": false, "explanation": "体貌：“变胖”指身体外形的变化，与此语境不相关。"}, {"text": "写作", "is_correct": false, "explanation": "语义：“写作”与“绑架他的人很多”的语境不相关。"}], "explanations": {"逃脱": "正确：“很难逃脱”指被抓后难以摆脱，与“绑架他的人很多”相符。", "唱歌": "语义：“唱歌”与“绑架他的人很多”的语境毫无关系。", "变胖": "体貌：“变胖”指身体外形的变化，与此语境不相关。", "写作": "语义：“写作”与“绑架他的人很多”的语境不相关。"}, "sentence_index": 6, "correct_answer": "逃脱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在医院里逃脱了三个星期。", "explanation": "这里应该用〈度过〉。“逃脱”指从被关押的地方跑出，不能用来说时间；在医院里过了三个星期要用〈度过〉。"}, {"text": "他一个晚上就逃脱了三本小说。", "explanation": "这里应该用〈读完〉。“逃脱”指从被抓或被关的地方跑出，不能用来说读书；一晚读完三本小说要用〈读完〉。"}, {"text": "警察终于逃脱了小偷。", "explanation": "这里应该用〈追上〉。“逃脱”的主语是被抓或被关的人，警察追捕小偷，不能说警察逃脱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb58bb6-8a88-4756-9bac-5999758bfd60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90917, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那个囚犯偷偷从牢房里逃脱着。", "corrected_sentence": "那个囚犯偷偷从牢房里逃脱了。", "error_description": "错误：“逃脱”后用了“着”，表示状态持续。正确：“逃脱”是一次性完成的动作，应用“了”，说“逃脱了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb58bb6-8a88-4756-9bac-5999758bfd60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90917, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "笼子里的鸟终于逃脱过。", "corrected_sentence": "笼子里的鸟终于逃脱了。", "error_description": "错误：“终于”表示动作最终完成，应用“了”；“过”表示曾经经历，不能用于此处。正确：应说“终于逃脱了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb58bb6-8a88-4756-9bac-5999758bfd60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
