INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90918, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb58bb6-8a88-4756-9bac-5999758bfd60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90918, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "摆脱束缚或危险，成功逃走。", "primary_collocate": null, "pronunciation": "táo tuō", "ipa": "tʰɑʊ̯˧˥ tʰwo˧˥", "syllable_count": 2, "sentences": [{"text": "小偷骑车跑了，警察没能追上，他逃脱了追捕。", "target_word": "逃脱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做错事的人很难逃脱法律的惩罚。", "target_word": "逃脱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她一直想逃脱家里的管束。", "target_word": "逃脱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那辆车失控了，司机跳下来才逃脱了危险。", "target_word": "逃脱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兔子跑得很快，逃脱了老鹰的追赶。", "target_word": "逃脱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想逃脱命运，可是没有成功。", "target_word": "逃脱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他趁着天黑，逃脱了敌人的包围。", "target_word": "逃脱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察已经围住了这座楼，坏人逃脱不了。", "target_word": "逃脱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他想办法逃脱了坏人的控制。", "target_word": "逃脱", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁都不能逃脱生老病死的规律。", "target_word": "逃脱", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "逃脱了", "label": "体标"}, {"form": "逃脱过", "label": "体标"}, {"form": "逃脫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "摆脱追捕、危险或控制而成功逃走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2b9c5d38-188c-4474-8f42-65925038992f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90918, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "逃脱", "is_correct": true, "explanation": "正确：“逃脱追捕”指摆脱追赶而跑掉，与“警察没能追上”相符。"}, {"text": "接受", "is_correct": false, "explanation": "语义：“接受追捕”与“警察没能追上”的情节相反，“他”是逃跑的人。"}, {"text": "参观", "is_correct": false, "explanation": "搭配：“参观”不能用于“追捕”。"}, {"text": "享受", "is_correct": false, "explanation": "语义：“享受追捕”与“他”逃跑的情节相矛盾。"}], "explanations": {"逃脱": "正确：“逃脱追捕”指摆脱追赶而跑掉，与“警察没能追上”相符。", "接受": "语义：“接受追捕”与“警察没能追上”的情节相反，“他”是逃跑的人。", "参观": "搭配：“参观”不能用于“追捕”。", "享受": "语义：“享受追捕”与“他”逃跑的情节相矛盾。"}, "sentence_index": 0, "correct_answer": "逃脱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "大家一起逃脱了胜利。", "explanation": "这里应该用〈庆祝〉。“逃脱”的对象是追捕、危险等要摆脱的东西，不能是“胜利”；欢庆胜利要用〈庆祝〉。"}, {"text": "他逃脱了错误，很快改正了。", "explanation": "这里应该用〈承认〉。“逃脱”指摆脱追捕或危险，不能用来说错误；说承认错误要用〈承认〉。"}, {"text": "大家享受了假期，又逃脱了假期。", "explanation": "这里应该用〈度过〉。“逃脱”的对象是危险或束缚，假期不是要摆脱的东西；说过完一段假期要用〈度过〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb58bb6-8a88-4756-9bac-5999758bfd60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90918, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "逃脱", "is_correct": true, "explanation": "正确：“逃脱包围”指从包围中成功跑出，与“趁着天黑”相符。"}, {"text": "扩大", "is_correct": false, "explanation": "语义：“扩大包围”与“趁着天黑”逃出的情节相反。"}, {"text": "加强", "is_correct": false, "explanation": "语义：“加强包围”与“趁着天黑”逃出的情节相反。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”不能用于“包围”。"}], "explanations": {"逃脱": "正确：“逃脱包围”指从包围中成功跑出，与“趁着天黑”相符。", "扩大": "语义：“扩大包围”与“趁着天黑”逃出的情节相反。", "加强": "语义：“加强包围”与“趁着天黑”逃出的情节相反。", "欣赏": "搭配：“欣赏”不能用于“包围”。"}, "sentence_index": 6, "correct_answer": "逃脱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他为这个目标逃脱了很多努力。", "explanation": "这里应该用〈付出〉。“逃脱”的对象是追捕、危险等要摆脱的东西，不能是“努力”；投入精力要用〈付出〉。"}, {"text": "他在这次活动里逃脱了很多朋友。", "explanation": "这里应该用〈收获〉。“逃脱”的对象是要摆脱的东西，不能是“朋友”；结识、得到的东西要用〈收获〉。"}, {"text": "大家逃脱了美丽的风景。", "explanation": "这里应该用〈欣赏〉。“逃脱”的对象是危险、束缚，不能是“风景”；观看美景要用〈欣赏〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb58bb6-8a88-4756-9bac-5999758bfd60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90918, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从火灾中逃脱着。", "corrected_sentence": "他从火灾中逃脱了。", "error_description": "错误：“逃脱”后用了“着”，表示状态持续。正确：“逃脱”是一次性完成的动作，应用“了”，说“逃脱了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb58bb6-8a88-4756-9bac-5999758bfd60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90918, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他趁乱从后门逃脱着。", "corrected_sentence": "他趁乱从后门逃脱了。", "error_description": "错误：“逃脱”后用了“着”，表示状态持续。正确：这是一次性完成的动作，应用“了”，说“逃脱了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccb58bb6-8a88-4756-9bac-5999758bfd60') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
