INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90919, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在法院里，被别人说做错事的人。", "primary_collocate": null, "pronunciation": "bèi gào", "ipa": "peɪ˥˩ kaʊ˥˩", "syllable_count": 2, "sentences": [{"text": "被告站在法院里，低着头不说话。", "target_word": "被告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官问被告昨天晚上在哪里。", "target_word": "被告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "被告说他没有做错事。", "target_word": "被告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "被告的妈妈在法院外面等着。", "target_word": "被告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个被告请了一位很好的律师。", "target_word": "被告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "被告走进法院的时候，很紧张。", "target_word": "被告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官让被告坐下来慢慢说。", "target_word": "被告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "被告想了很久，才回答问题。", "target_word": "被告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者问被告为什么要这样做。", "target_word": "被告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "被告今天没有来法院。", "target_word": "被告", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "被告人", "label": "复合词"}, {"form": "位", "label": "量词"}], "register": "书面", "sense_fingerprint": "法院里被指做了错事、要回答法官问题的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb5c31ff-f839-4074-902d-364e7269d3fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90919, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "被告", "is_correct": true, "explanation": "被告指法院里被控告做错事的人，与“法院里”“低着头不说话”的情境相符。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不能“站”，也不会“低着头不说话”，句子不成立。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会站立，也不会低头或说话，句子不成立。"}, {"text": "法槌", "is_correct": false, "explanation": "语义：法槌是器物，不能站立、低头或说话，句子不成立。"}], "explanations": {"被告": "被告指法院里被控告做错事的人，与“法院里”“低着头不说话”的情境相符。", "椅子": "语义：椅子不能“站”，也不会“低着头不说话”，句子不成立。", "石头": "语义：石头不会站立，也不会低头或说话，句子不成立。", "法槌": "语义：法槌是器物，不能站立、低头或说话，句子不成立。"}, "sentence_index": 0, "correct_answer": "被告"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我起诉了他，所以我是被告。", "explanation": "这里应该用〈原告〉。起诉别人的一方是原告，被起诉的一方才是被告。"}, {"text": "警察抓到了被告，正准备送他去法院。", "explanation": "这里应该用〈嫌疑人〉。被告指法院审理中被起诉的人，警察刚抓到的人在起诉前只能称嫌疑人。"}, {"text": "这次官司，我的律师是被告。", "explanation": "这里应该用〈代理人〉。被告是被控告的当事人，替当事人打官司的律师是代理人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90919, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "被告", "is_correct": true, "explanation": "被告是法院审理中被要求陈述的一方，能够“坐下来慢慢说”。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫不能陈述事情，“让……慢慢说”需要能说话的人。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：“让……说”的施事必须能说话，“桌子”不能充当说话者。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包不能“坐下来慢慢说”，句子与“法官让”的情境冲突。"}], "explanations": {"被告": "被告是法院审理中被要求陈述的一方，能够“坐下来慢慢说”。", "猫": "语义：猫不能陈述事情，“让……慢慢说”需要能说话的人。", "桌子": "配价：“让……说”的施事必须能说话，“桌子”不能充当说话者。", "面包": "语义：面包不能“坐下来慢慢说”，句子与“法官让”的情境冲突。"}, "sentence_index": 6, "correct_answer": "被告"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "法院已经判了他三年，他现在是被告。", "explanation": "这里应该用〈犯人〉。判决后被关押或服刑的人称犯人，被告只指审理过程中的当事人。"}, {"text": "张三在法庭上作证，他是被告。", "explanation": "这里应该用〈证人〉。在法庭上作证的人是证人，不是被告。"}, {"text": "那个孩子被撞伤了，他是被告。", "explanation": "这里应该用〈被害人〉。受伤、被侵害的一方是被害人，被告是被控告做错事的一方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90919, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "法院里来了一条被告，他看起来很害怕。", "corrected_sentence": "法院里来了一位被告，他看起来很害怕。", "error_description": "量词错误：“被告”指人，应用量词“位”，不能用“条”。“条”用于细长之物，错把它用于人。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90919, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那条被告在法庭上承认了错误。", "corrected_sentence": "那位被告在法庭上承认了错误。", "error_description": "量词错误：“被告”指人，应用量词“位”，不能用“条”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
