INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90920, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "诉讼中被控告的一方。", "primary_collocate": null, "pronunciation": "bèi gào", "ipa": "peɪ˥˩ kaʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司是这场官司的被告。", "target_word": "被告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原告说钱没还，被告说已经还了。", "target_word": "被告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "被告需要在十天内交材料。", "target_word": "被告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法院通知被告下个月来开庭。", "target_word": "被告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次官司里，原告是买房的人，被告是卖房的人。", "target_word": "被告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "被告公司愿意赔钱给原告。", "target_word": "被告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法官听完原告的话，又问了被告。", "target_word": "被告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "被告不同意法院的决定。", "target_word": "被告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场官司的被告是一家饭店。", "target_word": "被告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "被告一方请了两位律师。", "target_word": "被告", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "被告人", "label": "复合词"}, {"form": "被告方", "label": "复合词"}], "register": "书面", "sense_fingerprint": "官司中与原告相对、被控告的一方，可以是个人或公司", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fb5c31ff-f839-4074-902d-364e7269d3fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90920, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "被告", "is_correct": true, "explanation": "被告指官司中被控告的一方，公司可以是被告。"}, {"text": "法官", "is_correct": false, "explanation": "语义：公司不能担任法官，“这家公司是……的法官”与身份矛盾。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房不是诉讼中的任何一方，句子说不通。"}, {"text": "饭店", "is_correct": false, "explanation": "搭配：“这场官司的”后接的应是诉讼角色词，“饭店”不能与“这家公司是”构成角色。"}], "explanations": {"被告": "被告指官司中被控告的一方，公司可以是被告。", "法官": "语义：公司不能担任法官，“这家公司是……的法官”与身份矛盾。", "厨房": "语义：厨房不是诉讼中的任何一方，句子说不通。", "饭店": "搭配：“这场官司的”后接的应是诉讼角色词，“饭店”不能与“这家公司是”构成角色。"}, "sentence_index": 0, "correct_answer": "被告"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在法庭上作证，所以他是被告。", "explanation": "这里应该用〈证人〉。作证的是证人，被告是被控告的一方，不能因为作证就称被告。"}, {"text": "我去法院告他，所以我是被告。", "explanation": "这里应该用〈原告〉。去法院起诉别人的是原告，被告是被起诉的一方。"}, {"text": "主持这场审判的人是这场官司的被告。", "explanation": "这里应该用〈法官〉。主持审判的是法官，被告是被控告的一方，二者不能是同一个角色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90920, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "被告", "is_correct": true, "explanation": "被告是法官要询问的被控告一方，与“原告的话”相对应。"}, {"text": "证据", "is_correct": false, "explanation": "配价：“问”的对象须是人，“证据”不能被问。"}, {"text": "天气", "is_correct": false, "explanation": "语境：法官在法庭上不会询问天气，句意与法庭语境不符。"}, {"text": "窗户", "is_correct": false, "explanation": "配价：“问了”的宾语须是能回答的人，窗户不能被问。"}], "explanations": {"被告": "被告是法官要询问的被控告一方，与“原告的话”相对应。", "证据": "配价：“问”的对象须是人，“证据”不能被问。", "天气": "语境：法官在法庭上不会询问天气，句意与法庭语境不符。", "窗户": "配价：“问了”的宾语须是能回答的人，窗户不能被问。"}, "sentence_index": 6, "correct_answer": "被告"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "法院判决以后，他成了被告，正在服刑。", "explanation": "这里应该用〈犯人〉。判决后服刑的人称犯人，被告指审理中的当事人。"}, {"text": "那位老人被人抢了钱，他是被告。", "explanation": "这里应该用〈被害人〉。被抢、受害的一方是被害人，被告是被控告做错事的一方。"}, {"text": "我请来的律师，是这场官司的被告。", "explanation": "这里不能用〈被告〉指代理人。被告是被控告的一方，替当事人办案的只是代理人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90920, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那条被告是一家公司的老板。", "corrected_sentence": "那位被告是一家公司的老板。", "error_description": "量词错误：此处的被告是人，应用量词“位”，不能用“条”。“条”用于细长之物，错把它用于人。（若被告是公司，则用“家”。）", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90920, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "被告去法院告了张先生，要他还钱。", "corrected_sentence": "原告去法院告了张先生，要他还钱。", "error_description": "角色用错：去法院起诉别人的一方是原告，不是被告。应把“被告”改为“原告”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0794f560-6dd2-46c4-94f5-83542ffe89c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90921, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
