INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90921, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "尽快是越快越好，用最快的速度。", "primary_collocate": null, "pronunciation": "jǐn kuài", "ipa": "tɕin˨˩ kʰwai̯˥˩", "syllable_count": 2, "sentences": [{"text": "比赛快开始了，请尽快入场。", "target_word": "尽快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事很急，你要尽快办。", "target_word": "尽快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我会尽快回复你的邮件。", "target_word": "尽快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨要来了，我们尽快走吧。", "target_word": "尽快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请尽快付款，不然会没有货。", "target_word": "尽快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想尽快还钱给朋友。", "target_word": "尽快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子发烧，家长要尽快带他看医生。", "target_word": "尽快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你尽快把名字写在这里。", "target_word": "尽快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板要我尽快做完报告。", "target_word": "尽快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请尽快把门关上，风太大了。", "target_word": "尽快", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "盡快", "label": "繁体"}], "register": "中性", "sense_fingerprint": "越快越好，用最快的速度", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1815bc1-456a-4f8f-953b-62c1483087d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90921, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "尽快", "is_correct": true, "explanation": "尽快：表示用最快的速度，符合“请……入场”的催促语境。"}, {"text": "已经", "is_correct": false, "explanation": "语义：「已经」表示动作已经完成，与“请……入场”的指令和“快开始了”的时间冲突。"}, {"text": "偶尔", "is_correct": false, "explanation": "搭配：「偶尔」修饰反复出现的动作，不能修饰“入场”这种一次性行为。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：「刚刚」指过去不久，与“快开始了”的未来时间冲突。"}], "explanations": {"尽快": "尽快：表示用最快的速度，符合“请……入场”的催促语境。", "已经": "语义：「已经」表示动作已经完成，与“请……入场”的指令和“快开始了”的时间冲突。", "偶尔": "搭配：「偶尔」修饰反复出现的动作，不能修饰“入场”这种一次性行为。", "刚刚": "语义：「刚刚」指过去不久，与“快开始了”的未来时间冲突。"}, "sentence_index": 0, "correct_answer": "尽快"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "父母尽快地抚养我们。", "explanation": "这里应该用〈尽心〉。尽心表示全心全意地付出；尽快强调速度，不能用来形容抚养孩子这种长期的付出。"}, {"text": "事故尽快发生了。", "explanation": "这里应该用〈突然〉。突然表示事情出乎意料地忽然发生；尽快强调主动加快速度，事故不由人主动加快，不能用尽快来说。"}, {"text": "天色尽快暗了。", "explanation": "这里应该用〈逐渐〉。逐渐表示变化一点一点地慢慢发生；尽快表示主动加快速度，不能用来描述天色的自然变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90921, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尽快", "is_correct": true, "explanation": "尽快：表示用最快的速度，符合“家长要……带他看医生”的紧迫语境。"}, {"text": "慢慢", "is_correct": false, "explanation": "语义：「慢慢」表示速度缓慢，与“孩子发烧”需要及时就医的紧迫性不合。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：「曾经」指过去的经历，与“家长要……”表示的将来打算冲突。"}, {"text": "逐渐", "is_correct": false, "explanation": "搭配：「逐渐」表示渐进的变化，不能修饰“带他看医生”这一次性行动。"}], "explanations": {"尽快": "尽快：表示用最快的速度，符合“家长要……带他看医生”的紧迫语境。", "慢慢": "语义：「慢慢」表示速度缓慢，与“孩子发烧”需要及时就医的紧迫性不合。", "曾经": "语义：「曾经」指过去的经历，与“家长要……”表示的将来打算冲突。", "逐渐": "搭配：「逐渐」表示渐进的变化，不能修饰“带他看医生”这一次性行动。"}, "sentence_index": 6, "correct_answer": "尽快"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "警察尽快地守着路口。", "explanation": "这里应该用〈尽职〉。尽职表示认真履行职责；尽快只说速度，不能用来形容守岗的态度。"}, {"text": "我们要尽快而为，不放弃。", "explanation": "这里应该用〈尽力〉，即固定说法「尽力而为」，表示竭尽全力；尽快只强调速度，不能替换。"}, {"text": "他们尽快地唱了一晚上歌。", "explanation": "这里应该用〈尽兴〉。尽兴表示玩得痛快、满足；尽快只强调速度，不能用来形容唱歌的心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90921, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "大家很尽快离开教室吧。", "corrected_sentence": "大家尽快离开教室吧。", "error_description": "「尽快」是副词，前面不能加「很」来修饰。正确说法是「大家尽快离开教室吧」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90921, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老板让我们尽快的完成任务。", "corrected_sentence": "老板让我们尽快完成任务。", "error_description": "「尽快」是副词，修饰动词时不能用「的」（结构助词「的」用于名词前）。可以直接说「尽快完成任务」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
