INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90922, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，尽量加快速度。", "primary_collocate": null, "pronunciation": "jǐn kuài", "ipa": "tɕin˨˩ kʰwai̯˥˩", "syllable_count": 2, "sentences": [{"text": "请你尽快回电话给我。", "target_word": "尽快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我会尽快把文件发给你。", "target_word": "尽快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，作业要尽快交。", "target_word": "尽快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他生病了，要尽快去医院。", "target_word": "尽快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们尽快开会，好吗？", "target_word": "尽快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请尽快告诉我你的决定。", "target_word": "尽快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她想尽快找到新工作。", "target_word": "尽快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车坏了，师傅说会尽快修好。", "target_word": "尽快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈让我尽快回家吃饭。", "target_word": "尽快", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请大家尽快到教室集合。", "target_word": "尽快", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "盡快", "label": "繁体"}], "register": "中性", "sense_fingerprint": "尽量加快速度做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1815bc1-456a-4f8f-953b-62c1483087d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90922, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "尽快", "is_correct": true, "explanation": "尽快：表示尽量加快速度，符合“请你……回电话”的催促语气。"}, {"text": "已经", "is_correct": false, "explanation": "语义：「已经」表示动作已经完成，与祈使句“请你……”的要求冲突。"}, {"text": "逐渐", "is_correct": false, "explanation": "搭配：「逐渐」多用于变化的过程，不能修饰“回电话”这种一次性动作。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：「刚刚」指过去不久，与“请你……回”的未来要求矛盾。"}], "explanations": {"尽快": "尽快：表示尽量加快速度，符合“请你……回电话”的催促语气。", "已经": "语义：「已经」表示动作已经完成，与祈使句“请你……”的要求冲突。", "逐渐": "搭配：「逐渐」多用于变化的过程，不能修饰“回电话”这种一次性动作。", "刚刚": "语义：「刚刚」指过去不久，与“请你……回”的未来要求矛盾。"}, "sentence_index": 0, "correct_answer": "尽快"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "暑假里，我们尽快地玩耍。", "explanation": "这里应该用〈尽情〉。尽情表示痛快、不受约束地做某事；尽快只强调速度，不能用来形容玩耍的状态。"}, {"text": "他尽快病倒了。", "explanation": "这里应该用〈突然〉。突然表示事情出乎意料地忽然发生；尽快强调主动加快速度，病倒是不由人控制的事，不能用尽快来说。"}, {"text": "雪尽快下大了。", "explanation": "这里应该用〈渐渐〉。渐渐表示变化一点一点地慢慢发生；尽快表示主动加快速度，不能用来描述下雪这种自然变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90922, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "尽快", "is_correct": true, "explanation": "尽快：表示尽量加快速度，符合“她想……找到新工作”的愿望。"}, {"text": "曾经", "is_correct": false, "explanation": "语义：「曾经」指过去的经历，与“她想……找到”表示的将来意愿冲突。"}, {"text": "偶尔", "is_correct": false, "explanation": "搭配：「偶尔」修饰反复出现的动作，不能修饰“找到新工作”这一次性结果。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：「忽然」表示突然发生，与“她想……”表示有计划的意愿不合。"}], "explanations": {"尽快": "尽快：表示尽量加快速度，符合“她想……找到新工作”的愿望。", "曾经": "语义：「曾经」指过去的经历，与“她想……找到”表示的将来意愿冲突。", "偶尔": "搭配：「偶尔」修饰反复出现的动作，不能修饰“找到新工作”这一次性结果。", "忽然": "语义：「忽然」表示突然发生，与“她想……”表示有计划的意愿不合。"}, "sentence_index": 6, "correct_answer": "尽快"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "保安尽快地守着大门。", "explanation": "这里应该用〈尽职〉。尽职表示认真履行职责；尽快只说速度，不能用来形容守岗的态度。"}, {"text": "面对困难，我们要尽快而为。", "explanation": "这里应该用〈尽力〉，即固定说法「尽力而为」，表示竭尽全力；尽快只强调速度，不能替换。"}, {"text": "大家尽快地唱了一晚上歌。", "explanation": "这里应该用〈尽兴〉。尽兴表示玩得痛快、满足；尽快只强调速度，不能用来形容唱歌的心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90922, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们尽快的去车站吧。", "corrected_sentence": "我们尽快去车站吧。", "error_description": "「尽快」是副词，修饰动词时不能用「的」（「的」用于名词前）。正确说法是「我们尽快去车站吧」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90922, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你很尽快把钱还给他。", "corrected_sentence": "你尽快把钱还给他。", "error_description": "「尽快」是副词，前面不能加「很」来修饰。正确说法是「你尽快把钱还给他」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90923, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外带", "is_correct": true, "explanation": "外带与内用相对，指打包带走，不在店里吃。"}, {"text": "送", "is_correct": false, "explanation": "“送”与“内用”没有反义关系。"}, {"text": "等", "is_correct": false, "explanation": "“等”与“内用”没有反义关系。"}, {"text": "跳", "is_correct": false, "explanation": "“跳”与“内用”没有反义关系。"}], "correct_answer": "外带", "explanations": {"外带": "外带与内用相对，指打包带走，不在店里吃。", "送": "“送”与“内用”没有反义关系。", "等": "“等”与“内用”没有反义关系。", "跳": "“跳”与“内用”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90923, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "外带", "is_correct": true, "explanation": "外带与内用相对，指打包带走。"}, {"text": "拉", "is_correct": false, "explanation": "“拉”与“内用”没有反义关系。"}, {"text": "扫", "is_correct": false, "explanation": "“扫”与“内用”没有反义关系。"}, {"text": "穿", "is_correct": false, "explanation": "“穿”与“内用”没有反义关系。"}], "correct_answer": "外带", "explanations": {"外带": "外带与内用相对，指打包带走。", "拉": "“拉”与“内用”没有反义关系。", "扫": "“扫”与“内用”没有反义关系。", "穿": "“穿”与“内用”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90923, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "内用是在店里面吃，不带走。", "primary_collocate": null, "pronunciation": "nèi yòng", "ipa": "nei˥˩ jʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "您在这里吃，还是带走？我要内用。", "target_word": "内用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务员问我内用还是外带，我说内用。", "target_word": "内用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天下雨，我们不外带了，内用吧。", "target_word": "内用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店可以内用，里面有很多座位。", "target_word": "内用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "内用的话，可以免费续杯。", "target_word": "内用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想坐在店里吃，所以点内用。", "target_word": "内用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明说：“两个汉堡，内用。”", "target_word": "内用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面太冷了，我们内用吧，不带走了。", "target_word": "内用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家咖啡店内用要等十分钟。", "target_word": "内用", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店员问：“内用还是外带？”我说：“内用，谢谢。”", "target_word": "内用", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "內用", "label": "繁体"}], "register": "口语", "sense_fingerprint": "在店里面吃，不带走", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1815bc1-456a-4f8f-953b-62c1483087d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90923, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "内用", "is_correct": true, "explanation": "内用指在店里吃，与“带走”相对，正好对应前面的问题。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”与“在这里吃还是带走”的选择无关。"}, {"text": "睡", "is_correct": false, "explanation": "语义：睡觉不是吃饭，与“吃还是带走”的语境不符。"}, {"text": "打", "is_correct": false, "explanation": "语义：“打”与回答“在这里吃还是带走”无关，意思不通。"}], "explanations": {"内用": "内用指在店里吃，与“带走”相对，正好对应前面的问题。", "洗": "语义：“洗”与“在这里吃还是带走”的选择无关。", "睡": "语义：睡觉不是吃饭，与“吃还是带走”的语境不符。", "打": "语义：“打”与回答“在这里吃还是带走”无关，意思不通。"}, "sentence_index": 0, "correct_answer": "内用"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份餐点我要内用，打包带回家吃。", "explanation": "这里应该用〈外带〉。内用是在店里吃，打包带回家吃要说外带。"}, {"text": "这家店的内用包装很漂亮。", "explanation": "这里应该用〈外带〉。打包包装是外带才需要的，内用不需要包装，“内用包装”说不通。"}, {"text": "我在家里内用了一份盒饭。", "explanation": "语义：内用指在店里吃，在自己家里吃饭不能说内用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90923, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "内用", "is_correct": true, "explanation": "内用指在店里吃，小明说的是要在店里吃两个汉堡。"}, {"text": "唱", "is_correct": false, "explanation": "语义：汉堡不能唱，“两个汉堡，唱”不成立。"}, {"text": "摔", "is_correct": false, "explanation": "语义：“摔”是让东西掉在地上，与点餐时选择在哪里吃无关。"}, {"text": "修", "is_correct": false, "explanation": "语义：“修”是修理东西，与点餐时选择在店里吃无关。"}], "explanations": {"内用": "内用指在店里吃，小明说的是要在店里吃两个汉堡。", "唱": "语义：汉堡不能唱，“两个汉堡，唱”不成立。", "摔": "语义：“摔”是让东西掉在地上，与点餐时选择在哪里吃无关。", "修": "语义：“修”是修理东西，与点餐时选择在店里吃无关。"}, "sentence_index": 6, "correct_answer": "内用"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们点了外卖，就选择内用，送到家里。", "explanation": "这里应该用〈外送〉。内用指在店里吃，送到家里属于外送，二者矛盾。"}, {"text": "他一边走路一边内用汉堡。", "explanation": "语义：内用指在店里吃饭，边走路边吃不能说内用。"}, {"text": "我们去公园，在草地上内用了一顿野餐。", "explanation": "语义：内用只用于店铺、餐厅，公园草地上不能说内用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90923, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天太热了，我们被内用吧。", "corrected_sentence": "今天太热了，我们内用吧。", "error_description": "「内用」是人主动在店里吃，「我们被内用」让主语承受这个动作，意思不通。正确说法是「我们内用吧」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90923, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想带走，所以点内用。", "corrected_sentence": "我想带走，所以点外带。", "error_description": "「内用」指在店里吃，与“想带走”的意思矛盾。想带走应说「点外带」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
