INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90925, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "对别人喊话或说话，鼓励他们继续努力。", "primary_collocate": null, "pronunciation": "jiā yóu", "ipa": "tɕja˥ jou˧˥", "syllable_count": 2, "sentences": [{"text": "比赛开始了，大家一起喊加油！", "target_word": "加油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑快一点，加油！", "target_word": "加油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈对我说：“考试加油！”", "target_word": "加油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都给小明加油。", "target_word": "加油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "加油，你一定能做到！", "target_word": "加油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同学们站在路边给跑步的人加油。", "target_word": "加油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球队输了，球迷还在喊加油。", "target_word": "加油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友发短信说：“工作加油！”", "target_word": "加油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家一直给她加油，她跑得更快了。", "target_word": "加油", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别难过，明天继续加油！", "target_word": "加油", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "加油了", "label": "体标"}, {"form": "加加油", "label": "重叠"}], "register": "口语", "sense_fingerprint": "喊话鼓励别人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8bf72999-cc70-48ab-a55f-436b9cac05ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90925, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "加油", "is_correct": true, "explanation": "正确：比赛开始时大家喊加油，是对参赛的人鼓劲，与句意相符。"}, {"text": "投降", "is_correct": false, "explanation": "语义：比赛刚开始就喊投降，与鼓励的语境相反。"}, {"text": "停", "is_correct": false, "explanation": "语义：比赛刚开始就喊停，句意不通。"}, {"text": "道喜", "is_correct": false, "explanation": "搭配：“喊”通常不与“道喜”搭配，比赛开始时也不宜道喜。"}], "explanations": {"加油": "正确：比赛开始时大家喊加油，是对参赛的人鼓劲，与句意相符。", "投降": "语义：比赛刚开始就喊投降，与鼓励的语境相反。", "停": "语义：比赛刚开始就喊停，句意不通。", "道喜": "搭配：“喊”通常不与“道喜”搭配，比赛开始时也不宜道喜。"}, "sentence_index": 0, "correct_answer": "加油"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "饭卡里没钱了，我去给它加油。", "explanation": "这里应该用〈充值〉。给饭卡增加金额应说充值，加油不能用于此。"}, {"text": "充电宝没电了，我得给它加油。", "explanation": "这里应该用〈充电〉。给充电宝补充电量应说充电，加油不能用于此。"}, {"text": "轮胎没气了，我得给它加油。", "explanation": "这里应该用〈打气〉。给轮胎充气应说打气，加油不能用于此。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee5f5d5e-cc45-4c88-bbb0-9c5bab2b39a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90925, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "加油", "is_correct": true, "explanation": "正确：球队输了，球迷仍然喊加油，是为球队鼓劲，句意相符。"}, {"text": "恭喜", "is_correct": false, "explanation": "搭配：“喊”不与“恭喜”搭配，球队输了也不宜恭喜。"}, {"text": "庆祝", "is_correct": false, "explanation": "语义：球队输了，球迷不会去庆祝。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：球队输了，球迷在场边喊“睡觉”不合情理，与加油的语境不符。"}], "explanations": {"加油": "正确：球队输了，球迷仍然喊加油，是为球队鼓劲，句意相符。", "恭喜": "搭配：“喊”不与“恭喜”搭配，球队输了也不宜恭喜。", "庆祝": "语义：球队输了，球迷不会去庆祝。", "睡觉": "语义：球队输了，球迷在场边喊“睡觉”不合情理，与加油的语境不符。"}, "sentence_index": 6, "correct_answer": "加油"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "手机没电了，我要给它加油。", "explanation": "这里应该用〈充电〉。给手机补充电量应说充电，加油不能用于手机。"}, {"text": "游泳池的水不够，要给它加油。", "explanation": "这里应该用〈注水〉。往游泳池里加水应说注水，加油不能用于水池。"}, {"text": "奶茶太苦，我想给它加油。", "explanation": "这里应该用〈加糖〉。奶茶太苦要加糖调味，加油不能用于奶茶。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee5f5d5e-cc45-4c88-bbb0-9c5bab2b39a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90925, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把妹妹加油。", "corrected_sentence": "我给妹妹加油。", "error_description": "错误在介词：鼓励人时对象要用“给”引出，“把”不能用于“加油”，应把“把”改为“给”，说“我给妹妹加油”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee5f5d5e-cc45-4c88-bbb0-9c5bab2b39a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90925, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "球迷们都被球队加油。", "corrected_sentence": "球迷们都给球队加油。", "error_description": "错误在介词：“被”表示被动，意思变成球队给球迷加油，与句意相反。鼓励的对象要用“给”引出，应把“被”改为“给”，说“球迷们都给球队加油”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee5f5d5e-cc45-4c88-bbb0-9c5bab2b39a3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
