INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90927, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "北部是一个地方靠北的那一块。", "primary_collocate": null, "pronunciation": "běi bù", "ipa": "peɪ˨˩ pu˥˩", "syllable_count": 2, "sentences": [{"text": "中国的北部冬天很冷。", "target_word": "北部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的北部有一座山。", "target_word": "北部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家在这个国家的北部。", "target_word": "北部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北部的天气比南部冷。", "target_word": "北部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们去岛的北部露营。", "target_word": "北部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园北部有一个大湖。", "target_word": "北部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北部地区冬天常常下雪。", "target_word": "北部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥在北部的一所大学工作。", "target_word": "北部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个县的北部都是农田。", "target_word": "北部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北部的人喜欢吃面条。", "target_word": "北部", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "北部地区", "label": "复合"}], "register": "中性", "sense_fingerprint": "一个地方靠北的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bcfb73b-b30f-4f91-b98a-882ac61a0cd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90927, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "北部", "is_correct": true, "explanation": "北部指某地区靠北的部分，“中国的北部冬天很冷”通顺自然。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格是金钱的数目，不能作为地点，“中国的价格冬天很冷”说不通。"}, {"text": "股票", "is_correct": false, "explanation": "语义：股票是金融产品，不是地点，不能和“冬天很冷”搭配。"}, {"text": "指标", "is_correct": false, "explanation": "语义：指标是统计用语，不是地方，“中国的指标冬天很冷”说不通。"}], "explanations": {"北部": "北部指某地区靠北的部分，“中国的北部冬天很冷”通顺自然。", "价格": "语义：价格是金钱的数目，不能作为地点，“中国的价格冬天很冷”说不通。", "股票": "语义：股票是金融产品，不是地点，不能和“冬天很冷”搭配。", "指标": "语义：指标是统计用语，不是地方，“中国的指标冬天很冷”说不通。"}, "sentence_index": 0, "correct_answer": "北部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的北部很聪明。", "explanation": "“北部”指某地方靠北的部分，是地方名词，不能用来说人的性格或能力。"}, {"text": "这本书的北部很有意思。", "explanation": "“北部”只用于地方，书没有方位，应说“这本书的后半部分”。"}, {"text": "我昨天北部了一个朋友。", "explanation": "“北部”是名词，不能当动词用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90927, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "北部", "is_correct": true, "explanation": "北部与“地区”组成“北部地区”，指靠北的一片区域，“北部地区冬天常常下雪”通顺自然。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是机器，不是可以下雪的区域，“电脑地区”说不通。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是通讯工具，不能与“冬天常常下雪”构成地区。"}, {"text": "工资", "is_correct": false, "explanation": "搭配：“工资”不能修饰“地区”，也无法表示下雪的地方。"}], "explanations": {"北部": "北部与“地区”组成“北部地区”，指靠北的一片区域，“北部地区冬天常常下雪”通顺自然。", "电脑": "语义：电脑是机器，不是可以下雪的区域，“电脑地区”说不通。", "手机": "语义：手机是通讯工具，不能与“冬天常常下雪”构成地区。", "工资": "搭配：“工资”不能修饰“地区”，也无法表示下雪的地方。"}, "sentence_index": 6, "correct_answer": "北部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的北部说得很流利。", "explanation": "这里应该用〈北方话〉，即“他说一口流利的北方话”。〈北部〉只表示某地区靠北的部分，不能指语言。"}, {"text": "这个问题的北部很难回答。", "explanation": "这里的“北部”指某地区靠北的那一部分，是地方名词，不能用来指问题的某一方面。"}, {"text": "这只小鸟的北部很漂亮。", "explanation": "这里的“北部”指某地区靠北的那一部分，是地方名词，不能用来指动物的身体部位。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90927, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她住在中国北方部。", "corrected_sentence": "她住在中国北部。", "error_description": "用词错误：表示某地靠北的部分应说“北部”，没有“北方部”这种说法，应去掉“方”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90927, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他住在英国北面部。", "corrected_sentence": "他住在英国北部。", "error_description": "用词错误：表示某地靠北的部分应说“北部”，没有“北面部”这种说法，应去掉“面”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
