INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90928, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "某一地区北面的部分。", "primary_collocate": null, "pronunciation": "běi bù", "ipa": "peɪ˨˩ pu˥˩", "syllable_count": 2, "sentences": [{"text": "这个省的北部多山。", "target_word": "北部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的北部是运动场。", "target_word": "北部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校园北部有一个小花园。", "target_word": "北部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湖的北部水很深。", "target_word": "北部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "英国北部常常下雨。", "target_word": "北部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市北部新建了很多楼。", "target_word": "北部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "北部的农民种了很多小麦。", "target_word": "北部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天北部有雨，南部是晴天。", "target_word": "北部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司在市区北部。", "target_word": "北部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的北部有很多湖。", "target_word": "北部", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "北部地区", "label": "复合"}], "register": "中性", "sense_fingerprint": "某地区北面的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bcfb73b-b30f-4f91-b98a-882ac61a0cd5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90928, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "北部", "is_correct": true, "explanation": "北部指某地区北面的部分，“这个省的北部多山”通顺自然。"}, {"text": "河流", "is_correct": false, "explanation": "语义：河流是水体，“河流多山”说不通，不能作为“这个省的……多山”的对象。"}, {"text": "稻谷", "is_correct": false, "explanation": "语义：稻谷是农作物，不是地区，“这个省的稻谷多山”说不通。"}, {"text": "人口", "is_correct": false, "explanation": "搭配：“人口”可以说“多”，但说的是人数，不能说“多山”。"}], "explanations": {"北部": "北部指某地区北面的部分，“这个省的北部多山”通顺自然。", "河流": "语义：河流是水体，“河流多山”说不通，不能作为“这个省的……多山”的对象。", "稻谷": "语义：稻谷是农作物，不是地区，“这个省的稻谷多山”说不通。", "人口": "搭配：“人口”可以说“多”，但说的是人数，不能说“多山”。"}, "sentence_index": 0, "correct_answer": "北部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭馆专做北部菜。", "explanation": "这里应该用〈北方〉。“北方菜”是固定说法，指北方地区的菜式；〈北部〉只表示某地北面的部分，不能这样组合。"}, {"text": "她的北部很温柔。", "explanation": "这里的“北部”指某地区北面的部分，是地方名词，不能用来形容人的性格。"}, {"text": "我的作业北部写得很好。", "explanation": "这里的“北部”指某地区北面的部分，是地方名词，作业没有方位，不能用来指作业的某一部分。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90928, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "北部", "is_correct": true, "explanation": "北部指某地区北面的部分，修饰“农民”，表示农民所在的地方，句子通顺。"}, {"text": "建筑", "is_correct": false, "explanation": "语义：建筑是建造物，不是人，不能说“建筑的农民”。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是机器，不会有“农民”，“电脑的农民”说不通。"}, {"text": "外貌", "is_correct": false, "explanation": "语义：外貌指长相，不是地方，“外貌的农民”说不通。"}], "explanations": {"北部": "北部指某地区北面的部分，修饰“农民”，表示农民所在的地方，句子通顺。", "建筑": "语义：建筑是建造物，不是人，不能说“建筑的农民”。", "电脑": "语义：电脑是机器，不会有“农民”，“电脑的农民”说不通。", "外貌": "语义：外貌指长相，不是地方，“外貌的农民”说不通。"}, "sentence_index": 6, "correct_answer": "北部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个电影的北部很好看。", "explanation": "“北部”只用于地区的方位，电影没有方位，应说“后半部分”。"}, {"text": "他的北部很好。", "explanation": "“北部”是地方名词，不能用来指人的身体或情况。"}, {"text": "我们明天北部一下。", "explanation": "“北部”是名词，不能当动词用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90928, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们的工厂河的北部。", "corrected_sentence": "我们的工厂在河的北部。", "error_description": "介词错误：表示处所要用“在”，应说“在河的北部”，漏掉“在”后句子不通顺。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90928, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们住在法国的北部边。", "corrected_sentence": "他们住在法国的北部。", "error_description": "多余成分：“北部”本身就表示靠北的部分，后面不能再加“边”，应去掉“边”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1bd232e3-79d4-46c3-b67f-15c8c6c9adcf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
