INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90929, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "外部是东西的外面。", "primary_collocate": null, "pronunciation": "wài bù", "ipa": "wai̯˥˩ pu˥˩", "syllable_count": 2, "sentences": [{"text": "这个盒子的外部是红色的。", "target_word": "外部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房子外部刚刷了白漆。", "target_word": "外部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机外部有一点儿脏。", "target_word": "外部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杯子外部写着我的名字。", "target_word": "外部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先擦一擦冰箱外部吧。", "target_word": "外部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车的外部很漂亮。", "target_word": "外部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书包外部有两个小口袋。", "target_word": "外部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "锅的外部很烫，别用手摸。", "target_word": "外部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座楼外部看起来很新。", "target_word": "外部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把盒子外部包上一层纸。", "target_word": "外部", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "外部环境", "label": "复合词"}, {"form": "外部世界", "label": "复合词"}], "register": "中性", "sense_fingerprint": "东西的外面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940b2af-c4cb-48b8-9d0b-57e75b82fbed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90929, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "外部", "is_correct": true, "explanation": "外部：东西的外面。"}, {"text": "外币", "is_correct": false, "explanation": "wàibì（外币）与 wàibù（外部）只差第二音节的韵母（u 与 i），意思是外国的货币。"}, {"text": "胃部", "is_correct": false, "explanation": "wèibù（胃部）与 wàibù 只差第一音节的韵母（a 与 e），意思是胃的部位。"}, {"text": "尾部", "is_correct": false, "explanation": "wěibù（尾部）与 wàibù 第一音节的韵母不同，声调也不同（第三声），意思是末端部分。"}, {"text": "外务", "is_correct": false, "explanation": "wàiwù（外务）与 wàibù 只差第二音节的声母（w 与 b），意思是对外事务，多用于正式语境。"}], "explanations": {"外部": "外部：东西的外面。", "外币": "wàibì（外币）与 wàibù（外部）只差第二音节的韵母（u 与 i），意思是外国的货币。", "胃部": "wèibù（胃部）与 wàibù 只差第一音节的韵母（a 与 e），意思是胃的部位。", "尾部": "wěibù（尾部）与 wàibù 第一音节的韵母不同，声调也不同（第三声），意思是末端部分。", "外务": "wàiwù（外务）与 wàibù 只差第二音节的声母（w 与 b），意思是对外事务，多用于正式语境。"}, "sentence_index": null, "correct_answer": "外部"}, "level_3": {"options": [{"text": "外部", "is_correct": true, "explanation": "外部：指盒子的外面，与“是红色的”搭配，句意通顺。"}, {"text": "重量", "is_correct": false, "explanation": "语义：“重量”指轻重，不能是颜色，“重量是红色的”不通。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”指钱数，不能是颜色，“价格是红色的”不通。"}, {"text": "味道", "is_correct": false, "explanation": "搭配：“味道”不能与“红色”搭配，不能说“味道是红色的”。"}], "explanations": {"外部": "外部：指盒子的外面，与“是红色的”搭配，句意通顺。", "重量": "语义：“重量”指轻重，不能是颜色，“重量是红色的”不通。", "价格": "语义：“价格”指钱数，不能是颜色，“价格是红色的”不通。", "味道": "搭配：“味道”不能与“红色”搭配，不能说“味道是红色的”。"}, "sentence_index": 0, "correct_answer": "外部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家来了外部。", "explanation": "这里应该用〈外人〉。外部指东西的外面，不指人；说“家里来了外人”才对。"}, {"text": "我想去外部留学。", "explanation": "这里应该用〈外国〉。外部指东西的外面，不指国家；说“去外国留学”。"}, {"text": "他有个外部，大家都叫他小胖。", "explanation": "这里应该用〈外号〉。外部指东西的外面，不能指人的绰号；说人的绰号要用“外号”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90929, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外部", "is_correct": true, "explanation": "外部：指书包的外面，句意通顺。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”指色彩，不能作主语带“有两个小口袋”，句子不通。"}, {"text": "温度", "is_correct": false, "explanation": "搭配：“温度”不能与“有两个小口袋”搭配，说“温度有两个小口袋”不通。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”指听觉对象，不能有口袋，句子不通。"}], "explanations": {"外部": "外部：指书包的外面，句意通顺。", "颜色": "语义：“颜色”指色彩，不能作主语带“有两个小口袋”，句子不通。", "温度": "搭配：“温度”不能与“有两个小口袋”搭配，说“温度有两个小口袋”不通。", "声音": "语义：“声音”指听觉对象，不能有口袋，句子不通。"}, "sentence_index": 6, "correct_answer": "外部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的外部很高，比我高一头。", "explanation": "这里应该用〈个子〉。外部指东西的外面，不能用来说人的身高；说“个子很高”。"}, {"text": "他的外部很好，能用英文交流。", "explanation": "这里应该用〈外语〉。“外部”不能修饰能力，说“外语很好”才是能用英文交流的正确说法。"}, {"text": "他脱了外部，挂在椅子上。", "explanation": "这里应该用〈外套〉。外部是东西的外面，不能像衣服一样脱下来；脱下来的是外套。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90929, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "先把盒子在外部擦干净吧。", "corrected_sentence": "先把盒子外部擦干净吧。", "error_description": "错误：“把”字句中“外部”是被擦的对象，应直接放在“把”的宾语位置，不能在前面加“在”。正确：应说“先把盒子外部擦干净吧”，去掉“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90929, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器很外部有一个开关。", "corrected_sentence": "这台机器外部有一个开关。", "error_description": "错误：“外部”是方位名词，不能被程度副词“很”修饰。正确：去掉“很”，说“这台机器外部有一个开关”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90930, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "内部", "is_correct": true, "explanation": "内部：指某范围之内，与“外部”构成反义。"}, {"text": "中心", "is_correct": false, "explanation": "中心：指中间的位置，与“外部”没有反义关系。"}, {"text": "历史", "is_correct": false, "explanation": "历史：指过去的事情，与“外部”没有反义关系。"}, {"text": "天空", "is_correct": false, "explanation": "天空：指天上的空间，与“外部”没有反义关系。"}], "correct_answer": "内部", "explanations": {"内部": "内部：指某范围之内，与“外部”构成反义。", "中心": "中心：指中间的位置，与“外部”没有反义关系。", "历史": "历史：指过去的事情，与“外部”没有反义关系。", "天空": "天空：指天上的空间，与“外部”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90930, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "内部", "is_correct": true, "explanation": "内部：指某范围之内，与“外部”构成反义。"}, {"text": "春天", "is_correct": false, "explanation": "春天：指季节，与“外部”没有反义关系。"}, {"text": "文章", "is_correct": false, "explanation": "文章：指书面作品，与“外部”没有反义关系。"}, {"text": "夜晚", "is_correct": false, "explanation": "夜晚：指时间，与“外部”没有反义关系。"}], "correct_answer": "内部", "explanations": {"内部": "内部：指某范围之内，与“外部”构成反义。", "春天": "春天：指季节，与“外部”没有反义关系。", "文章": "文章：指书面作品，与“外部”没有反义关系。", "夜晚": "夜晚：指时间，与“外部”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90930, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "某个范围或组织之外。", "primary_collocate": null, "pronunciation": "wài bù", "ipa": "wai̯˥˩ pu˥˩", "syllable_count": 2, "sentences": [{"text": "公司外部的人不能进办公室。", "target_word": "外部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题要听听外部专家的意见。", "target_word": "外部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些规定对公司外部的人没有用。", "target_word": "外部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司外部的意见对我们也很重要。", "target_word": "外部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息没有传到公司外部。", "target_word": "外部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外部条件变了，我们的计划也要改。", "target_word": "外部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外部人员进来要先登记。", "target_word": "外部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的内部情况不让外部人士知道。", "target_word": "外部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外部的人很难了解公司内部的事。", "target_word": "外部", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛不对外部的人开放。", "target_word": "外部", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "外部环境", "label": "复合词"}, {"form": "外部世界", "label": "复合词"}], "register": "中性", "sense_fingerprint": "某个范围、组织之外", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940b2af-c4cb-48b8-9d0b-57e75b82fbed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90930, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "外部", "is_correct": true, "explanation": "外部：某个范围或组织之外。"}, {"text": "外币", "is_correct": false, "explanation": "wàibì（外币）与 wàibù（外部）只差第二音节的韵母（u 与 i），意思是外国的货币，不是范围之外。"}, {"text": "胃部", "is_correct": false, "explanation": "wèibù（胃部）与 wàibù 只差第一音节的韵母（a 与 e），意思是胃的部位。"}, {"text": "尾部", "is_correct": false, "explanation": "wěibù（尾部）与 wàibù 第一音节的韵母不同，声调也不同（第三声），意思是末端部分。"}, {"text": "外务", "is_correct": false, "explanation": "wàiwù（外务）与 wàibù 只差第二音节的声母（w 与 b），意思是对外事务，多用于正式语境。"}], "explanations": {"外部": "外部：某个范围或组织之外。", "外币": "wàibì（外币）与 wàibù（外部）只差第二音节的韵母（u 与 i），意思是外国的货币，不是范围之外。", "胃部": "wèibù（胃部）与 wàibù 只差第一音节的韵母（a 与 e），意思是胃的部位。", "尾部": "wěibù（尾部）与 wàibù 第一音节的韵母不同，声调也不同（第三声），意思是末端部分。", "外务": "wàiwù（外务）与 wàibù 只差第二音节的声母（w 与 b），意思是对外事务，多用于正式语境。"}, "sentence_index": null, "correct_answer": "外部"}, "level_3": {"options": [{"text": "外部", "is_correct": true, "explanation": "外部：指公司之外，修饰“的人”，与句意相符。"}, {"text": "外汇", "is_correct": false, "explanation": "搭配：“外汇”指外国货币，不能说“公司外汇的人”，句子不通。"}, {"text": "外墙", "is_correct": false, "explanation": "搭配：“外墙”是建筑的部件，不能修饰“人”，说“公司外墙的人”不通。"}, {"text": "外语", "is_correct": false, "explanation": "搭配：“外语”指语言，不能修饰“人”，说“公司外语的人”不通。"}], "explanations": {"外部": "外部：指公司之外，修饰“的人”，与句意相符。", "外汇": "搭配：“外汇”指外国货币，不能说“公司外汇的人”，句子不通。", "外墙": "搭配：“外墙”是建筑的部件，不能修饰“人”，说“公司外墙的人”不通。", "外语": "搭配：“外语”指语言，不能修饰“人”，说“公司外语的人”不通。"}, "sentence_index": 0, "correct_answer": "外部"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我想去外部留学。", "explanation": "这里应该用〈外国〉。外部指某范围之外的区域或组织，不指国家；说“去外国留学”。"}, {"text": "外部下雨了，我们先回屋吧。", "explanation": "这里应该用〈外面〉。“外部”多指组织或范围之外，描述天气和具体方位时要说“外面”。"}, {"text": "他的外部很普通，但是很聪明。", "explanation": "这里应该用〈外表〉。外部指某个范围或组织之外，不用来说人的样子；形容人的外貌要用“外表”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90930, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "外部", "is_correct": true, "explanation": "外部：指公司或范围之外的，修饰“人员”，句意通顺。"}, {"text": "水果", "is_correct": false, "explanation": "搭配：“水果”不能修饰“人员”，“水果人员进来要先登记”不通。"}, {"text": "石头", "is_correct": false, "explanation": "搭配：“石头”不能修饰“人员”，句子不通。"}, {"text": "夜晚", "is_correct": false, "explanation": "语义：“夜晚”指时间，不能说“夜晚人员”，与“进来要先登记”的语境不符。"}], "explanations": {"外部": "外部：指公司或范围之外的，修饰“人员”，句意通顺。", "水果": "搭配：“水果”不能修饰“人员”，“水果人员进来要先登记”不通。", "石头": "搭配：“石头”不能修饰“人员”，句子不通。", "夜晚": "语义：“夜晚”指时间，不能说“夜晚人员”，与“进来要先登记”的语境不符。"}, "sentence_index": 6, "correct_answer": "外部"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他有个外部，大家都叫他小胖。", "explanation": "这里应该用〈外号〉。外部不能指人的绰号，说人的绰号要用“外号”。"}, {"text": "那个运动员的外部很强，每场都得分。", "explanation": "这里应该用〈实力〉。外部指事物的外面或某范围之外，不能指人的能力；说“实力很强”。"}, {"text": "他的外部很好，能用英文交流。", "explanation": "这里应该用〈外语〉。“外部”不能修饰能力，说“外语很好”才是能用英文交流的正确说法。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90930, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校外表的人不能进教室。", "corrected_sentence": "学校外部的人不能进教室。", "error_description": "错误：“外表”指人或东西的样子，不能表示某个范围之外。这里要说学校以外的人，应该用“外部”。正确：“学校外部的人不能进教室”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90930, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份计划书不外部公开。", "corrected_sentence": "这份计划书不向外部公开。", "error_description": "“外部”作“公开”的处所，前面要加介词“向”，说“向外部公开”。漏掉“向”，“不外部公开”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
