INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90931, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "子女是爸爸妈妈的孩子，儿子和女儿。", "primary_collocate": null, "pronunciation": "zǐ nǚ", "ipa": "tsɨ˨˩ ny˨˩", "syllable_count": 2, "sentences": [{"text": "他们夫妻有两个子女，都在上大学。", "target_word": "子女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母都希望子女健康快乐。", "target_word": "子女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人的子女都住在外地。", "target_word": "子女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对自己的子女要求很严。", "target_word": "子女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "子女小的时候，妈妈天天陪着他们。", "target_word": "子女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王先生很爱他的子女。", "target_word": "子女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的子女都已经长大成人了。", "target_word": "子女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她为了子女，每天工作到很晚。", "target_word": "子女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人生病，子女轮流照顾。", "target_word": "子女", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没有子女，一个人生活。", "target_word": "子女", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "子女们", "label": "复数"}, {"form": "子女教育", "label": "复合词"}], "register": "中性", "sense_fingerprint": "父母的孩子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940b2af-c4cb-48b8-9d0b-57e75b82fbed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90931, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "子女", "is_correct": true, "explanation": "正确：“子女”指父母的孩子，与“都在上大学”相符。"}, {"text": "房子", "is_correct": false, "explanation": "语义：“房子”不是人，不能“上大学”。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：“电脑”不是人，不能“上大学”。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：汽车的量词是“辆”，不能用“个”来数，且不能“上大学”。"}], "explanations": {"子女": "正确：“子女”指父母的孩子，与“都在上大学”相符。", "房子": "语义：“房子”不是人，不能“上大学”。", "电脑": "语义：“电脑”不是人，不能“上大学”。", "汽车": "搭配：汽车的量词是“辆”，不能用“个”来数，且不能“上大学”。"}, "sentence_index": 0, "correct_answer": "子女"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "会议室里坐满了子女，大家都在讨论工作。", "explanation": "这里应该用〈同事〉。子女指父母的孩子，不指开会的同事。"}, {"text": "幼儿园里有很多子女，都很可爱。", "explanation": "这里应该用〈儿童〉。子女指父母的孩子，不泛指所有小孩。"}, {"text": "他是一位很严的子女，教育孩子很认真。", "explanation": "这里应该用〈家长〉。子女指被父母养育的孩子，不能指做父母的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90931, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "子女", "is_correct": true, "explanation": "正确：“子女”指孩子，与“都已经长大成人”相符。"}, {"text": "宠物", "is_correct": false, "explanation": "语义：宠物一般不说“长大成人”，与句中指人的语境不合。"}, {"text": "树", "is_correct": false, "explanation": "语义：树只能说“长大”，不能说“长大成人”。"}, {"text": "种子", "is_correct": false, "explanation": "搭配：“长大成人”只用于人，不能用于“种子”。"}], "explanations": {"子女": "正确：“子女”指孩子，与“都已经长大成人”相符。", "宠物": "语义：宠物一般不说“长大成人”，与句中指人的语境不合。", "树": "语义：树只能说“长大”，不能说“长大成人”。", "种子": "搭配：“长大成人”只用于人，不能用于“种子”。"}, "sentence_index": 6, "correct_answer": "子女"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师把班上的子女分成了三组。", "explanation": "这里应该用〈学生〉。子女指父母的孩子，班上的孩子对老师来说是学生。"}, {"text": "公司里有很多子女，都很努力工作。", "explanation": "这里应该用〈员工〉。子女指父母的孩子，不指公司里的同事或员工。"}, {"text": "我的子女把我养大，很辛苦。", "explanation": "这里应该用〈父母〉。子女指父母的孩子，不能指把孩子养大的父母。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90931, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸妈妈有三只子女，都很优秀。", "corrected_sentence": "爸爸妈妈有三个子女，都很优秀。", "error_description": "错误：“子女”指人，量词应用“个”，“只”一般用于动物。正确：“三个子女”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90931, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她有一子女，在上海工作。", "corrected_sentence": "她有一个子女，在上海工作。", "error_description": "错误：“子女”前面不能直接接数词“一”，要加量词“个”。正确：“一个子女”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
