INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90933, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "宝是很珍贵的好东西。", "primary_collocate": null, "pronunciation": "bǎo", "ipa": "paʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "对他来说，这支旧笔是个宝。", "target_word": "宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷留下的那块玉是宝。", "target_word": "宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书是他心里的宝。", "target_word": "宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把那个小盒子当成宝。", "target_word": "宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这棵老树是村子里的宝。", "target_word": "宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你捡到宝了，这个很值钱。", "target_word": "宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在孩子眼里，旧玩具就是宝。", "target_word": "宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个老师傅可是我们厂里的宝。", "target_word": "宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把那封信当宝一样放着。", "target_word": "宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对农民来说，水是宝。", "target_word": "宝", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "宝贝", "label": "复合"}, {"form": "国宝", "label": "复合"}, {"form": "寶", "label": "繁体"}], "register": "口语", "sense_fingerprint": "很珍贵的好东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f17da28-59f8-418f-b207-d6e528bd9ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90933, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "宝", "is_correct": true, "explanation": "宝（bǎo，第三声）：很珍贵的好东西。"}, {"text": "报", "is_correct": false, "explanation": "bào（第四声）与 bǎo（第三声）声调不同，意思是报纸。"}, {"text": "包", "is_correct": false, "explanation": "bāo（第一声）与 bǎo（第三声）声调不同，意思是包裹。"}, {"text": "抱", "is_correct": false, "explanation": "bào（第四声）与 bǎo（第三声）声调不同，意思是拥抱。"}, {"text": "跑", "is_correct": false, "explanation": "pǎo 与 bǎo 声母不同（p 与 b），意思是跑步。"}], "explanations": {"宝": "宝（bǎo，第三声）：很珍贵的好东西。", "报": "bào（第四声）与 bǎo（第三声）声调不同，意思是报纸。", "包": "bāo（第一声）与 bǎo（第三声）声调不同，意思是包裹。", "抱": "bào（第四声）与 bǎo（第三声）声调不同，意思是拥抱。", "跑": "pǎo 与 bǎo 声母不同（p 与 b），意思是跑步。"}, "sentence_index": null, "correct_answer": "宝"}, "level_3": {"options": [{"text": "宝", "is_correct": true, "explanation": "宝：很珍贵的好东西，符合“对他来说”的价值语境。"}, {"text": "老虎", "is_correct": false, "explanation": "语义：“老虎”是动物，不能说“这支旧笔是个老虎”。"}, {"text": "大楼", "is_correct": false, "explanation": "语义：“大楼”是建筑，与“这支旧笔”不相关，说不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材指人的体型，不能用来指一支笔。"}], "explanations": {"宝": "宝：很珍贵的好东西，符合“对他来说”的价值语境。", "老虎": "语义：“老虎”是动物，不能说“这支旧笔是个老虎”。", "大楼": "语义：“大楼”是建筑，与“这支旧笔”不相关，说不通。", "身材": "体貌：身材指人的体型，不能用来指一支笔。"}, "sentence_index": 0, "correct_answer": "宝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "宝总是出故障，很麻烦。", "explanation": "这里应该用〈机器〉。宝是很珍贵的好东西，不能说“出故障”。"}, {"text": "宝很臭，应该及时处理。", "explanation": "这里应该用〈垃圾〉。宝是很珍贵的好东西，不能用来形容“臭”。"}, {"text": "宝很吵，大家都受不了。", "explanation": "这里应该用〈噪音〉。宝是很珍贵的好东西，不能用来形容“吵”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90933, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "宝", "is_correct": true, "explanation": "宝（bǎo，第三声）：很珍贵的好东西。"}, {"text": "炮", "is_correct": false, "explanation": "pào（第四声）与 bǎo（第三声）声母和声调都不同，意思是炮或鞭炮。"}, {"text": "爆", "is_correct": false, "explanation": "bào（第四声）与 bǎo（第三声）声调不同，意思是爆炸。"}, {"text": "薄", "is_correct": false, "explanation": "báo（第二声）与 bǎo（第三声）声调不同，意思是薄厚的薄。"}, {"text": "暴", "is_correct": false, "explanation": "bào（第四声）与 bǎo（第三声）声调不同，意思是暴力。"}], "explanations": {"宝": "宝（bǎo，第三声）：很珍贵的好东西。", "炮": "pào（第四声）与 bǎo（第三声）声母和声调都不同，意思是炮或鞭炮。", "爆": "bào（第四声）与 bǎo（第三声）声调不同，意思是爆炸。", "薄": "báo（第二声）与 bǎo（第三声）声调不同，意思是薄厚的薄。", "暴": "bào（第四声）与 bǎo（第三声）声调不同，意思是暴力。"}, "sentence_index": null, "correct_answer": "宝"}, "level_3": {"options": [{"text": "宝", "is_correct": true, "explanation": "宝：在孩子眼里很珍贵的东西，符合“就是”的语境。"}, {"text": "老师", "is_correct": false, "explanation": "语义：旧玩具不是老师，与“在孩子眼里”的语境不合。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”是活动，不能是旧玩具，说不通。"}, {"text": "文件", "is_correct": false, "explanation": "语义：“文件”指公文资料，旧玩具不是文件，说不通。"}], "explanations": {"宝": "宝：在孩子眼里很珍贵的东西，符合“就是”的语境。", "老师": "语义：旧玩具不是老师，与“在孩子眼里”的语境不合。", "考试": "语义：“考试”是活动，不能是旧玩具，说不通。", "文件": "语义：“文件”指公文资料，旧玩具不是文件，说不通。"}, "sentence_index": 6, "correct_answer": "宝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "宝写完了，老师明天要检查。", "explanation": "这里应该用〈作业〉。宝是很珍贵的好东西，不能说“写完”。"}, {"text": "外面的宝很冷，我不想出门。", "explanation": "这里应该用〈天气〉。宝是很珍贵的好东西，不能用来形容“冷”。"}, {"text": "宝很厚，我读了整整一天。", "explanation": "这里应该用〈书〉。宝是很珍贵的好东西，不能用来形容“厚”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90933, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把那本书成当宝，每天都翻一翻。", "corrected_sentence": "他把那本书当成宝，每天都翻一翻。", "error_description": "错误：动词“当成”不能颠倒成“成当”。应说“把那本书当成宝”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90933, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是奶奶留给我宝。", "corrected_sentence": "这是奶奶留给我的宝。", "error_description": "错误：定语“奶奶留给我”和名词“宝”之间需要“的”。应说“留给我的宝”，漏掉“的”不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
