INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90934, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "珍贵的东西；也用于对孩子等的爱称。", "primary_collocate": null, "pronunciation": "bǎo", "ipa": "paʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "宝，该起床了，上学要迟到了。", "target_word": "宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说：“宝，过来吃饭。”", "target_word": "宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你是爸爸妈妈心里的宝。", "target_word": "宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块旧石头是爷爷留下的宝。", "target_word": "宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在他眼里，这本旧书就是宝。", "target_word": "宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝，别哭了，妈妈在这儿。", "target_word": "宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子是全家人的宝。", "target_word": "宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶把我当成宝一样爱着。", "target_word": "宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把那张旧照片当作宝，天天看。", "target_word": "宝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝，天黑了，我们回家吧。", "target_word": "宝", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "宝贝", "label": "复合"}, {"form": "宝宝", "label": "复合"}, {"form": "国宝", "label": "复合"}, {"form": "寶", "label": "繁体"}], "register": "口语", "sense_fingerprint": "珍贵之物，也是对孩子的爱称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f17da28-59f8-418f-b207-d6e528bd9ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90934, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "宝", "is_correct": true, "explanation": "宝（bǎo，第三声）：珍贵的东西，也是对孩子的爱称。"}, {"text": "报", "is_correct": false, "explanation": "bào（第四声）与 bǎo（第三声）声调不同，意思是报纸。"}, {"text": "包", "is_correct": false, "explanation": "bāo（第一声）与 bǎo（第三声）声调不同，意思是包裹。"}, {"text": "抱", "is_correct": false, "explanation": "bào（第四声）与 bǎo（第三声）声调不同，意思是拥抱。"}, {"text": "跑", "is_correct": false, "explanation": "pǎo 与 bǎo 声母不同（p 与 b），意思是跑步。"}, {"text": "豹", "is_correct": false, "explanation": "bào（第四声）与 bǎo（第三声）声调不同，意思是豹子。"}], "explanations": {"宝": "宝（bǎo，第三声）：珍贵的东西，也是对孩子的爱称。", "报": "bào（第四声）与 bǎo（第三声）声调不同，意思是报纸。", "包": "bāo（第一声）与 bǎo（第三声）声调不同，意思是包裹。", "抱": "bào（第四声）与 bǎo（第三声）声调不同，意思是拥抱。", "跑": "pǎo 与 bǎo 声母不同（p 与 b），意思是跑步。", "豹": "bào（第四声）与 bǎo（第三声）声调不同，意思是豹子。"}, "sentence_index": null, "correct_answer": "宝"}, "level_3": {"options": [{"text": "宝", "is_correct": true, "explanation": "宝：对孩子的爱称，符合“宝，该起床了”的呼唤语境。"}, {"text": "老板", "is_correct": false, "explanation": "语义：“老板”是成年人，不用上学，与“上学要迟到了”矛盾。"}, {"text": "钥匙", "is_correct": false, "explanation": "语义：“钥匙”是物件，不是可以被叫醒去上学的人，说不通。"}, {"text": "先生", "is_correct": false, "explanation": "语域：“先生”是正式礼貌的称呼，不用于对孩子的亲昵呼唤。"}], "explanations": {"宝": "宝：对孩子的爱称，符合“宝，该起床了”的呼唤语境。", "老板": "语义：“老板”是成年人，不用上学，与“上学要迟到了”矛盾。", "钥匙": "语义：“钥匙”是物件，不是可以被叫醒去上学的人，说不通。", "先生": "语域：“先生”是正式礼貌的称呼，不用于对孩子的亲昵呼唤。"}, "sentence_index": 0, "correct_answer": "宝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "宝很香，大家都在吃。", "explanation": "这里应该用〈饭菜〉。宝指珍贵的东西或爱称，不能用来形容“香”。"}, {"text": "宝坏了，我们换一个新的灯泡吧。", "explanation": "这里应该用〈灯〉。宝指珍贵的东西或爱称，不是坏了要换的灯泡。"}, {"text": "宝很长，可以拴住牛。", "explanation": "这里应该用〈绳子〉。宝指珍贵的东西或爱称，不是绳子，不能用来拴东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90934, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "宝", "is_correct": true, "explanation": "宝（bǎo，第三声）：珍贵的东西，也是对孩子的爱称。"}, {"text": "炮", "is_correct": false, "explanation": "pào（第四声）与 bǎo（第三声）声母和声调都不同，意思是炮或鞭炮。"}, {"text": "爆", "is_correct": false, "explanation": "bào（第四声）与 bǎo（第三声）声调不同，意思是爆炸。"}, {"text": "薄", "is_correct": false, "explanation": "báo（第二声）与 bǎo（第三声）声调不同，意思是薄厚的薄。"}, {"text": "暴", "is_correct": false, "explanation": "bào（第四声）与 bǎo（第三声）声调不同，意思是暴力。"}], "explanations": {"宝": "宝（bǎo，第三声）：珍贵的东西，也是对孩子的爱称。", "炮": "pào（第四声）与 bǎo（第三声）声母和声调都不同，意思是炮或鞭炮。", "爆": "bào（第四声）与 bǎo（第三声）声调不同，意思是爆炸。", "薄": "báo（第二声）与 bǎo（第三声）声调不同，意思是薄厚的薄。", "暴": "bào（第四声）与 bǎo（第三声）声调不同，意思是暴力。"}, "sentence_index": null, "correct_answer": "宝"}, "level_3": {"options": [{"text": "宝", "is_correct": true, "explanation": "宝：全家人最疼爱的孩子，符合“这个孩子是全家人的”语境。"}, {"text": "镜子", "is_correct": false, "explanation": "语义：孩子不是镜子，“全家人的镜子”说不通。"}, {"text": "房东", "is_correct": false, "explanation": "语义：房东指出租房屋的人，与“这个孩子”没有关系。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高指身材高矮，不能说“全家人的身高”。"}], "explanations": {"宝": "宝：全家人最疼爱的孩子，符合“这个孩子是全家人的”语境。", "镜子": "语义：孩子不是镜子，“全家人的镜子”说不通。", "房东": "语义：房东指出租房屋的人，与“这个孩子”没有关系。", "身高": "体貌：身高指身材高矮，不能说“全家人的身高”。"}, "sentence_index": 6, "correct_answer": "宝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "宝写完了，我去睡觉。", "explanation": "这里应该用〈作业〉。宝指珍贵的东西或爱称，不能说“写完”。"}, {"text": "今天宝很冷，大家都穿厚衣服。", "explanation": "这里应该用〈天气〉。宝指珍贵的东西或爱称，不能用来形容“冷”。"}, {"text": "宝很厚，我看了一个星期。", "explanation": "这里应该用〈书〉。宝指珍贵的东西或爱称，不能说“厚”，也不能用“看了一个星期”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90934, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把这封信成当宝，天天带着。", "corrected_sentence": "我把这封信当成宝，天天带着。", "error_description": "错误：动词“当成”是固定组合，不能颠倒成“成当”。应说“把这封信当成宝”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90934, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是我最珍贵宝。", "corrected_sentence": "这是我最珍贵的宝。", "error_description": "错误：修饰语“最珍贵”和名词“宝”之间需要“的”。应说“最珍贵的宝”，漏掉“的”不通顺。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
