INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90935, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "对不起是做错事以后说的话，是在说自己错了。", "primary_collocate": null, "pronunciation": "duì bu qǐ", "ipa": "twei̯˥˩ pu qʰi˨˩", "syllable_count": 3, "sentences": [{"text": "我打破了杯子，对不起。", "target_word": "对不起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对不起，我不该骂你。", "target_word": "对不起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他知道自己错了，对妈妈说对不起。", "target_word": "对不起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对不起，我把你的书弄脏了。", "target_word": "对不起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小弟说：“姐姐，对不起，我拿了你的笔。”", "target_word": "对不起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做错事要说对不起。", "target_word": "对不起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对不起，是我看错了时间。", "target_word": "对不起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我撞到了他，马上说对不起。", "target_word": "对不起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对不起，昨天我说错话了。", "target_word": "对不起", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师，对不起，我今天没写作业。", "target_word": "对不起", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "對不起", "label": "繁体"}], "register": "口语", "sense_fingerprint": "做错事后说的话，承认自己错了", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c1815bc1-456a-4f8f-953b-62c1483087d0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90935, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "对不起", "is_correct": true, "explanation": "对不起：承认自己打破了杯子，符合做错事后的语境。"}, {"text": "谢谢", "is_correct": false, "explanation": "语义：「谢谢」表示感谢，与“我打破了杯子”的过错不符。"}, {"text": "再见", "is_correct": false, "explanation": "语义：「再见」用于告别，不能用来承认过错。"}, {"text": "不客气", "is_correct": false, "explanation": "搭配：「不客气」是对感谢的回应，不能接在承认过错的陈述之后。"}], "explanations": {"对不起": "对不起：承认自己打破了杯子，符合做错事后的语境。", "谢谢": "语义：「谢谢」表示感谢，与“我打破了杯子”的过错不符。", "再见": "语义：「再见」用于告别，不能用来承认过错。", "不客气": "搭配：「不客气」是对感谢的回应，不能接在承认过错的陈述之后。"}, "sentence_index": 0, "correct_answer": "对不起"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "对不起你提醒我带伞，我很感动。", "explanation": "这里应该用〈谢谢〉。谢谢用于感谢别人的提醒；对不起是承认自己错了，不能用来表示感谢。"}, {"text": "妈妈笑着说：“对不起，生日快乐！”", "explanation": "语义：过生日是高兴的事，没有人做错事；对不起用于认错道歉，在这里说意思不通。"}, {"text": "同学道谢，我说：“对不起，这是我应该做的。”", "explanation": "这里应该用〈不客气〉来回应道谢；对不起是承认错误，不能用来回应感谢。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90935, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对不起", "is_correct": true, "explanation": "对不起：承认自己看错了时间，符合做错事后的语境。"}, {"text": "请问", "is_correct": false, "explanation": "语义：「请问」用于向别人提问，与承认过错的语境不符。"}, {"text": "你好", "is_correct": false, "explanation": "语义：「你好」用于打招呼，与承认自己看错时间的语境无关。"}, {"text": "加油", "is_correct": false, "explanation": "语义：「加油」用于鼓励，与“是我看错了时间”的承认过错不符。"}], "explanations": {"对不起": "对不起：承认自己看错了时间，符合做错事后的语境。", "请问": "语义：「请问」用于向别人提问，与承认过错的语境不符。", "你好": "语义：「你好」用于打招呼，与承认自己看错时间的语境无关。", "加油": "语义：「加油」用于鼓励，与“是我看错了时间”的承认过错不符。"}, "sentence_index": 6, "correct_answer": "对不起"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朋友拿了奖，我举杯说：“对不起，干一杯！”", "explanation": "这里应该用〈祝贺你〉。祝贺用于庆贺别人的喜事；对不起用于认错道歉，在庆祝的场合说它意思不通。"}, {"text": "他看了我的画，说：“对不起，你画得真好。”", "explanation": "语义：他是在称赞我的画，没有做错事；对不起用于认错道歉，在称赞时说意思不通。"}, {"text": "新同学来了，我笑着说：“对不起，欢迎你！”", "explanation": "这里应该用〈欢迎〉。欢迎用于迎接客人；对不起是承认错误，在迎接新人的场合说它意思不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90935, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我不小心弄坏了你的伞，对不起的。", "corrected_sentence": "我不小心弄坏了你的伞，对不起。", "error_description": "「对不起」是叹词，后面不能加「的」。正确说法是句末直接用「对不起」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90935, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "昨天我忘了还书，对不起着。", "corrected_sentence": "昨天我忘了还书，对不起。", "error_description": "「对不起」是叹词，后面不能加「着」。承认错误时直接说「对不起」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c2cf80d-887f-4ac7-a586-cf4a946dca85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
