INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90937, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "对手是和你比赛，想赢你的人。", "primary_collocate": null, "pronunciation": "duì shǒu", "ipa": "twei˥˩ ʂou˨˩˦", "syllable_count": 2, "sentences": [{"text": "我的对手想赢我，我也不想输。", "target_word": "对手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做生意时，对手常常会学你的办法。", "target_word": "对手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛开始前，我和对手握了手。", "target_word": "对手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的对手是一位年轻的女孩。", "target_word": "对手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步的时候，我看见对手跑在前面。", "target_word": "对手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了赢对手，他每天都练习三个小时。", "target_word": "对手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们是学校里的对手，可是也是好朋友。", "target_word": "对手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的对手很快，我们要小心。", "target_word": "对手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛结束后，他对对手说谢谢。", "target_word": "对手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不怕对手，只怕自己不努力。", "target_word": "对手", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个对手", "label": "量词"}, {"form": "竞争对手", "label": "复合"}], "register": "中性", "sense_fingerprint": "和你比赛、想赢你的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d2fa9c-e3fd-42ad-8411-015657f8b96c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90937, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "对手", "is_correct": true, "explanation": "对手：和你比赛、想赢你的人，即正确答案。"}, {"text": "对视", "is_correct": false, "explanation": "duì shì：第一个字读音相同，第二个字 shì 与 shǒu 不同，意思是互相看着。"}, {"text": "对数", "is_correct": false, "explanation": "duì shù：shù 与 shǒu 只差韵母，意思是数学里的对数。"}, {"text": "退守", "is_correct": false, "explanation": "tuì 与 duì 声调相同，声母 t 与 d 的送气不同，意思是撤退后守住。"}, {"text": "推手", "is_correct": false, "explanation": "tuī（第一声）与 duì（第四声）声母送气不同且声调不同，意思是推动事情的人。"}], "explanations": {"对手": "对手：和你比赛、想赢你的人，即正确答案。", "对视": "duì shì：第一个字读音相同，第二个字 shì 与 shǒu 不同，意思是互相看着。", "对数": "duì shù：shù 与 shǒu 只差韵母，意思是数学里的对数。", "退守": "tuì 与 duì 声调相同，声母 t 与 d 的送气不同，意思是撤退后守住。", "推手": "tuī（第一声）与 duì（第四声）声母送气不同且声调不同，意思是推动事情的人。"}, "sentence_index": null, "correct_answer": "对手"}, "level_3": {"options": [{"text": "对手", "is_correct": true, "explanation": "对手：和你比赛、想赢你的人，与“想赢我”的语境相符。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子没有意志，不会“想赢我”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是有意志的人，与“想赢我”矛盾。"}, {"text": "影子", "is_correct": false, "explanation": "搭配：“想赢我”要求有意志的人作主语，不说“影子想赢我”。"}], "explanations": {"对手": "对手：和你比赛、想赢你的人，与“想赢我”的语境相符。", "椅子": "语义：椅子没有意志，不会“想赢我”。", "天气": "语义：天气不是有意志的人，与“想赢我”矛盾。", "影子": "搭配：“想赢我”要求有意志的人作主语，不说“影子想赢我”。"}, "sentence_index": 0, "correct_answer": "对手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "昨天我在操场上遇到一位对手，他替我赢下了那场比赛。", "explanation": "这里应该用〈队友〉。对手是与你比赛、想赢你的人，不会替你赢下比赛。"}, {"text": "这盏台灯是我的对手，每天晚上替我做饭。", "explanation": "这里“对手”被用来指台灯，但它只指与你比赛、想赢你的人，意思不通。"}, {"text": "那位对手给病人检查身体。", "explanation": "这里应该用〈医生〉。对手是比赛中与你争胜的人，不会给病人检查身体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90937, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对手", "is_correct": true, "explanation": "对手：竞争中的对方，与“好朋友”形成“既是竞争对手又是朋友”的关系。"}, {"text": "货车", "is_correct": false, "explanation": "语义：货车是运输工具，与学校里的人际关系不符。"}, {"text": "天平", "is_correct": false, "explanation": "语义：天平是称量器具，不能指学校里的人。"}, {"text": "厂长", "is_correct": false, "explanation": "搭配：“学校里的”一般修饰学校中的人或物，“厂长”不在学校任职，搭配不当。"}], "explanations": {"对手": "对手：竞争中的对方，与“好朋友”形成“既是竞争对手又是朋友”的关系。", "货车": "语义：货车是运输工具，与学校里的人际关系不符。", "天平": "语义：天平是称量器具，不能指学校里的人。", "厂长": "搭配：“学校里的”一般修饰学校中的人或物，“厂长”不在学校任职，搭配不当。"}, "sentence_index": 6, "correct_answer": "对手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的对手是一份报纸，每天早上都送到我家门口。", "explanation": "这里“对手”被用来指报纸，但它只指与你比赛、想赢你的人，意思不通。"}, {"text": "那个对手替我把英文翻成中文。", "explanation": "这里应该用〈翻译〉。对手是比赛中的对方，不会替你做翻译。"}, {"text": "我遇到了一个对手，它每天在阳台上开花。", "explanation": "这里“对手”被用来指植物，但它只指与你比赛、想赢你的人，不能指花。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90937, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他是我遇到过的最强的一头对手。", "corrected_sentence": "他是我遇到过的最强的一个对手。", "error_description": "错误：“一头对手”。正确：“一个对手”。对手指人，量词用“个”或“位”，“头”用于牛、猪等动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90937, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我的这只对手很厉害。", "corrected_sentence": "我的这个对手很厉害。", "error_description": "错误：“这只对手”。正确：“这个对手”。对手指人，量词用“个”，不用“只”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
