INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90938, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "竞赛或较量中的对方；本领相当的人。", "primary_collocate": null, "pronunciation": "duì shǒu", "ipa": "twei˥˩ ʂou˨˩˦", "syllable_count": 2, "sentences": [{"text": "他是我多年的老对手，我们每次比赛都很紧张。", "target_word": "对手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场比赛，我的对手比我高很多。", "target_word": "对手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下棋时他总是找水平差不多的对手。", "target_word": "对手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对手太强了，我们输了。", "target_word": "对手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网球比赛里，她打败了最强的对手。", "target_word": "对手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小王和小李是乒乓球场上的对手。", "target_word": "对手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛前，教练仔细研究了对手的打法。", "target_word": "对手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在决赛中遇到了一个很厉害的对手。", "target_word": "对手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我跟他下棋，不是他的对手。", "target_word": "对手", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两队实力差不多，是真正的对手。", "target_word": "对手", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个对手", "label": "量词"}, {"form": "竞争对手", "label": "复合"}], "register": "中性", "sense_fingerprint": "竞赛较量中的对方，或本领相当的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '05d2fa9c-e3fd-42ad-8411-015657f8b96c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90938, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "对手", "is_correct": true, "explanation": "对手：竞赛或较量中的对方，即正确答案。"}, {"text": "对视", "is_correct": false, "explanation": "duì shì：第一个字读音相同，第二个字 shì 与 shǒu 不同，意思是互相看着。"}, {"text": "对数", "is_correct": false, "explanation": "duì shù：shù 与 shǒu 只差韵母，意思是数学里的对数。"}, {"text": "退守", "is_correct": false, "explanation": "tuì 与 duì 声调相同，声母 t 与 d 的送气不同，意思是撤退后守住。"}, {"text": "推手", "is_correct": false, "explanation": "tuī（第一声）与 duì（第四声）声母送气不同且声调不同，意思是推动事情的人。"}], "explanations": {"对手": "对手：竞赛或较量中的对方，即正确答案。", "对视": "duì shì：第一个字读音相同，第二个字 shì 与 shǒu 不同，意思是互相看着。", "对数": "duì shù：shù 与 shǒu 只差韵母，意思是数学里的对数。", "退守": "tuì 与 duì 声调相同，声母 t 与 d 的送气不同，意思是撤退后守住。", "推手": "tuī（第一声）与 duì（第四声）声母送气不同且声调不同，意思是推动事情的人。"}, "sentence_index": null, "correct_answer": "对手"}, "level_3": {"options": [{"text": "对手", "is_correct": true, "explanation": "对手：竞赛或较量中的对方，与“每次比赛都很紧张”的语境相符。"}, {"text": "牙刷", "is_correct": false, "explanation": "语义：“牙刷”是刷牙用品，与“每次比赛都很紧张”的人际关系不符，句子不通。"}, {"text": "房东", "is_correct": false, "explanation": "语义：“房东”指出租房屋的人，与比赛无关，“每次比赛都很紧张”说不通。"}, {"text": "孩子", "is_correct": false, "explanation": "搭配：“老”一般修饰年长的人或事物，不说“老孩子”。"}], "explanations": {"对手": "对手：竞赛或较量中的对方，与“每次比赛都很紧张”的语境相符。", "牙刷": "语义：“牙刷”是刷牙用品，与“每次比赛都很紧张”的人际关系不符，句子不通。", "房东": "语义：“房东”指出租房屋的人，与比赛无关，“每次比赛都很紧张”说不通。", "孩子": "搭配：“老”一般修饰年长的人或事物，不说“老孩子”。"}, "sentence_index": 0, "correct_answer": "对手"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "欢迎新对手加入我们的球队。", "explanation": "这里应该用〈队友〉。对手是比赛中与你对抗的一方，不会加入你的球队。"}, {"text": "妈妈是我的对手，每天帮我洗衣服。", "explanation": "这里应该用〈帮手〉。对手指比赛或较量中的对方，不会每天帮你洗衣服。"}, {"text": "这家公司的老板是我的对手，每个月都给我发奖金。", "explanation": "这里应该用〈上司〉。对手指竞争中与你争胜的一方，不会每月给你发奖金。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90938, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对手", "is_correct": true, "explanation": "对手：竞争中的对方，这里指对方球员的比赛风格。"}, {"text": "球迷", "is_correct": false, "explanation": "语义：球迷观看比赛，不参加比赛，没有“打法”可以研究。"}, {"text": "裁判", "is_correct": false, "explanation": "语义：裁判负责判罚，不参加比赛，没有“打法”可言。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“打法”指球员或队伍的比赛方式，不说“天气的打法”。"}], "explanations": {"对手": "对手：竞争中的对方，这里指对方球员的比赛风格。", "球迷": "语义：球迷观看比赛，不参加比赛，没有“打法”可以研究。", "裁判": "语义：裁判负责判罚，不参加比赛，没有“打法”可言。", "天气": "搭配：“打法”指球员或队伍的比赛方式，不说“天气的打法”。"}, "sentence_index": 6, "correct_answer": "对手"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的对手正在教我弹钢琴。", "explanation": "这里应该用〈老师〉。对手是竞争中与你争胜的一方，不会教你弹钢琴。"}, {"text": "我的对手每天早上给我做早饭。", "explanation": "这里应该用〈妈妈〉之类照顾你的人。对手指竞争中与你争胜的一方，不会每天给你做早饭。"}, {"text": "这把椅子是我的对手，每天陪我看书。", "explanation": "“对手”的意思是竞赛或较量中的对方，这里却用来指一把椅子，意思不通。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90938, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我找到了一只合适的对手，一起练习。", "corrected_sentence": "我找到了一个合适的对手，一起练习。", "error_description": "错误：“一只对手”。正确：“一个对手”。对手指人，量词用“个”，不用“只”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90938, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "比赛那天，他的一只对手生病了。", "corrected_sentence": "比赛那天，他的一个对手生病了。", "error_description": "错误：“他的一只对手”。正确：“他的一个对手”。对手指人，量词用“个”，不用“只”（“只”多用于动物等）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd176ca88-5e6f-462a-bc9f-e2165d5111e6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
