INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90940, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一个州的行政首长，负责管理全州的政务。", "primary_collocate": null, "pronunciation": "zhōu zhǎng", "ipa": "ʈʂoʊ˥ ʈʂɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "美国每个州都有一位州长。", "target_word": "州长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "州长是这个州最高的官员。", "target_word": "州长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新州长下个月会来我们的城市。", "target_word": "州长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "州长在电视上讲话了。", "target_word": "州长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "加州的州长是选出来的。", "target_word": "州长", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "州长今天参观了一所学校。", "target_word": "州长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位州长很关心教育问题。", "target_word": "州长", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他当过两年州长，后来去了华盛顿。", "target_word": "州长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "州长签字以后，这项法律才生效。", "target_word": "州长", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者问州长明年有什么计划。", "target_word": "州长", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "州長", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一州的行政首长，负责全州政务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3d48bf1a-fcce-4795-8810-0494f4f470de') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90940, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "州长", "is_correct": true, "explanation": "州长是一个州的行政首长，与“每个州都有一位”相符。"}, {"text": "市长", "is_correct": false, "explanation": "语义：市长管的是一座城市，不是每个州都有的首长。"}, {"text": "州政府", "is_correct": false, "explanation": "搭配：“一位”用于人，州政府是机构，不能用“位”计量。"}, {"text": "总统", "is_correct": false, "explanation": "语义：总统管全国，不是每个州都有一位。"}], "explanations": {"州长": "州长是一个州的行政首长，与“每个州都有一位”相符。", "市长": "语义：市长管的是一座城市，不是每个州都有的首长。", "州政府": "搭配：“一位”用于人，州政府是机构，不能用“位”计量。", "总统": "语义：总统管全国，不是每个州都有一位。"}, "sentence_index": 0, "correct_answer": "州长"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市的州长很年轻。", "explanation": "这里应该用〈市长〉。州长是州一级的首长，城市的首长要说市长。"}, {"text": "我们选出了一只州长。", "explanation": "这里应该用〈位〉。州长是人，量词用“位”，不用动物用的“只”。"}, {"text": "中国每个省都有一位州长。", "explanation": "这里应该用〈省长〉。州长是美国州一级的首长，中国省一级的首长要说省长。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90940, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "州长", "is_correct": true, "explanation": "州长是人，能够关心教育问题，与“这位”搭配。"}, {"text": "州议会", "is_correct": false, "explanation": "搭配：“这位”要接人，州议会是机构，不能用“位”计量。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有感情，不能关心教育问题。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户没有想法，无法关心教育问题。"}], "explanations": {"州长": "州长是人，能够关心教育问题，与“这位”搭配。", "州议会": "搭配：“这位”要接人，州议会是机构，不能用“位”计量。", "石头": "语义：石头没有感情，不能关心教育问题。", "窗户": "语义：窗户没有想法，无法关心教育问题。"}, "sentence_index": 6, "correct_answer": "州长"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "州长在法庭上判案。", "explanation": "这里应该用〈法官〉。州长管理州政务，不负责审理案件。"}, {"text": "我们下午在州长见面。", "explanation": "这里应该用〈州政府〉。州长是人，不是见面的地点，见面的地点可以说州政府。"}, {"text": "这个州长的价格很便宜。", "explanation": "这里应该用〈商品〉。州长是人，不是商品，不能说价格便宜；商品才有价格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90940, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "美国有五十只州长。", "corrected_sentence": "美国有五十位州长。", "error_description": "“只”用于动物或一般物件，不能用于人。州长是人，应用量词“位”，正确形式为“美国有五十位州长”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90940, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他当过一只州长。", "corrected_sentence": "他当过一任州长。", "error_description": "量词“只”用于动物或一般物件，不能用于人。州长是人，表示任期应用量词“任”，正确形式为“他当过一任州长”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2414c3c-d6d5-4334-9daf-042526ccddbe') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
