INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90941, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "屁股是人坐下时坐在椅子上的那个地方。", "primary_collocate": null, "pronunciation": "pì gu", "ipa": "pʰi˥˩ ku", "syllable_count": 2, "sentences": [{"text": "他屁股刚坐到椅子上，电话就响了。", "target_word": "屁股", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这把椅子太硬，坐久了屁股疼。", "target_word": "屁股", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子屁股坐不住，一会儿就跑了。", "target_word": "屁股", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把屁股往旁边挪一挪，让我坐下。", "target_word": "屁股", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一坐下，屁股就陷进了沙发里。", "target_word": "屁股", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在椅子上扭来扭去，屁股怎么也坐不稳。", "target_word": "屁股", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教室里的凳子很小，我的屁股只坐了一半。", "target_word": "屁股", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他起身时，屁股下面的椅子倒了。", "target_word": "屁股", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "坐了三个小时，我的屁股都麻了。", "target_word": "屁股", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "车座很软，坐上去屁股特别舒服。", "target_word": "屁股", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "屁股蛋", "label": "复合"}], "register": "口语", "sense_fingerprint": "人坐下时接触椅子、座位的部位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '336a0206-f607-4671-866d-44fb53eddaab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90941, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "屁股", "is_correct": true, "explanation": "正确答案。屁股（pì gu）指人坐下时坐在椅子上的那个部位，是口语说法。"}, {"text": "皮鼓", "is_correct": false, "explanation": "pí（第二声）与 pì（第四声）声调不同，皮鼓（pí gǔ）指用皮革蒙面的鼓。"}, {"text": "皮骨", "is_correct": false, "explanation": "pí（第二声）与 pì（第四声）声调不同，皮骨（pí gǔ）指皮和骨头，常见于“皮包骨”。"}, {"text": "皮箍", "is_correct": false, "explanation": "pí（第二声）与 pì（第四声）声调不同，皮箍（pí gū）指皮革做的箍。"}, {"text": "鼻骨", "is_correct": false, "explanation": "bí（第二声）与 pì 声母不同（b 与 p），声调也不同，鼻骨（bí gǔ）指鼻子的骨头。"}], "explanations": {"屁股": "正确答案。屁股（pì gu）指人坐下时坐在椅子上的那个部位，是口语说法。", "皮鼓": "pí（第二声）与 pì（第四声）声调不同，皮鼓（pí gǔ）指用皮革蒙面的鼓。", "皮骨": "pí（第二声）与 pì（第四声）声调不同，皮骨（pí gǔ）指皮和骨头，常见于“皮包骨”。", "皮箍": "pí（第二声）与 pì（第四声）声调不同，皮箍（pí gū）指皮革做的箍。", "鼻骨": "bí（第二声）与 pì 声母不同（b 与 p），声调也不同，鼻骨（bí gǔ）指鼻子的骨头。"}, "sentence_index": null, "correct_answer": "屁股"}, "level_3": {"options": [{"text": "屁股", "is_correct": true, "explanation": "屁股是人坐下时接触椅子的部位，符合语境。"}, {"text": "手", "is_correct": false, "explanation": "语义：坐到椅子上的是屁股，不是手，句子说不通。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子是家具，不会坐到椅子上。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包是物品，不能坐到椅子上。"}], "explanations": {"屁股": "屁股是人坐下时接触椅子的部位，符合语境。", "手": "语义：坐到椅子上的是屁股，不是手，句子说不通。", "桌子": "语义：桌子是家具，不会坐到椅子上。", "书包": "语义：书包是物品，不能坐到椅子上。"}, "sentence_index": 0, "correct_answer": "屁股"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他看了一下午书，屁股累得睁不开。", "explanation": "这里应该用〈眼睛〉。屁股是坐的部位，不能说睁不开，看书累了眼睛睁不开要说眼睛。"}, {"text": "客厅里多了一张屁股。", "explanation": "这里应该用〈个〉。量词“张”用于平面的东西，不能用来数“屁股”，屁股应搭配“个”。"}, {"text": "他伸出屁股，跟我握手。", "explanation": "这里应该用〈手〉。屁股是坐的部位，不能用来握手，握手要用手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c49f556-4b6a-4ac8-966b-a2069f0026a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90941, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "屁股", "is_correct": true, "explanation": "屁股是人坐在凳子上的部位，只坐了一半，与语境相符。"}, {"text": "脚", "is_correct": false, "explanation": "语义：脚踩在地上，不是坐在凳子上的部位，说“脚只坐了一半”不通。"}, {"text": "膝盖", "is_correct": false, "explanation": "语义：膝盖不是坐在凳子上的部位，说“膝盖只坐了一半”不通。"}, {"text": "皮包", "is_correct": false, "explanation": "语义：皮包是物品，不能坐一半，语义不通。"}], "explanations": {"屁股": "屁股是人坐在凳子上的部位，只坐了一半，与语境相符。", "脚": "语义：脚踩在地上，不是坐在凳子上的部位，说“脚只坐了一半”不通。", "膝盖": "语义：膝盖不是坐在凳子上的部位，说“膝盖只坐了一半”不通。", "皮包": "语义：皮包是物品，不能坐一半，语义不通。"}, "sentence_index": 6, "correct_answer": "屁股"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他饿了一天，屁股一直咕咕叫。", "explanation": "这里应该用〈肚子〉。屁股不会咕咕叫，饿了肚子叫要说肚子。"}, {"text": "车座上放着一根屁股。", "explanation": "这里应该用〈个〉。量词“根”用于细长的东西，不能用来数“屁股”。"}, {"text": "他用屁股敲着桌子。", "explanation": "这里应该用〈手指〉。屁股是坐的部位，不能用来敲击，敲桌子要用手指。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c49f556-4b6a-4ac8-966b-a2069f0026a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90941, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把一张屁股挪到了旁边。", "corrected_sentence": "他把屁股挪到了旁边。", "error_description": "“屁股”不能用量词“张”（“张”用于平面的东西），这里也不需要数量词；正确为“把屁股挪到了旁边”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c49f556-4b6a-4ac8-966b-a2069f0026a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90941, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他坐了个半屁股在椅子上。", "corrected_sentence": "他坐了半个屁股在椅子上。", "error_description": "“个半”前须有数词（如“一个半”），单独的“个半屁股”不成词；表示二分之一应说“半个”，正确为“坐了半个屁股”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c49f556-4b6a-4ac8-966b-a2069f0026a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
