INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90943, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "连书是把好几个字连在一起写的一种写法。", "primary_collocate": null, "pronunciation": "lián shū", "ipa": "li̯ɛn³⁵ ʂu⁵⁵", "syllable_count": 2, "sentences": [{"text": "他把三个字连在一起写，这就是连书。", "target_word": "连书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友刚学写字，还不会写连书。", "target_word": "连书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅书法作品里有不少连书。", "target_word": "连书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们怎么写连书。", "target_word": "连书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "连书的字不容易分清楚。", "target_word": "连书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想练习连书，但是总写不好。", "target_word": "连书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张卡片上的名字是用连书来写的。", "target_word": "连书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "写得太快的连书，别人看不懂。", "target_word": "连书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的签名是连书，看起来很漂亮。", "target_word": "连书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要用连书，每个字写清楚。", "target_word": "连书", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "連書", "label": "繁体"}], "register": "中性", "sense_fingerprint": "把好几个字连在一起写的写法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9bab8fe-0b72-43ae-8aa8-81542a01a1dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90943, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "连书", "is_correct": true, "explanation": "连书：把好几个字连在一起写的写法，是正确答案。"}, {"text": "脸书", "is_correct": false, "explanation": "liǎn（第三声）与 lián（第二声）声调不同，脸书意思是社交网站（台湾用语）。"}, {"text": "联署", "is_correct": false, "explanation": "shǔ（第三声）与 shū（第一声）声调不同，联署意思是几个人共同签名。"}, {"text": "良书", "is_correct": false, "explanation": "liáng 与 lián 的韵母不同（-ang 与 -an），良书意思是好书。"}], "explanations": {"连书": "连书：把好几个字连在一起写的写法，是正确答案。", "脸书": "liǎn（第三声）与 lián（第二声）声调不同，脸书意思是社交网站（台湾用语）。", "联署": "shǔ（第三声）与 shū（第一声）声调不同，联署意思是几个人共同签名。", "良书": "liáng 与 lián 的韵母不同（-ang 与 -an），良书意思是好书。"}, "sentence_index": null, "correct_answer": "连书"}, "level_3": {"options": [{"text": "连书", "is_correct": true, "explanation": "正确：连书就是把好几个字连在一起写的写法，与句子相符。"}, {"text": "楷书", "is_correct": false, "explanation": "语义：楷书的笔画要分开写，与“连在一起写”相反。"}, {"text": "篆书", "is_correct": false, "explanation": "语义：篆书是古代字体，并不是把字连在一起写的方式。"}, {"text": "标题", "is_correct": false, "explanation": "搭配：“这就是”后应接书写方式，标题不是写法。"}], "explanations": {"连书": "正确：连书就是把好几个字连在一起写的写法，与句子相符。", "楷书": "语义：楷书的笔画要分开写，与“连在一起写”相反。", "篆书": "语义：篆书是古代字体，并不是把字连在一起写的方式。", "标题": "搭配：“这就是”后应接书写方式，标题不是写法。"}, "sentence_index": 0, "correct_answer": "连书"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "连书的字母大小一样，每个字母都是单独的。", "explanation": "这里应该用〈印刷体〉。印刷体的字母各自独立，连书的字母要连在一起，两者不能互换。"}, {"text": "连书的笔画要一笔一笔分开写。", "explanation": "这里应该用〈楷书〉。楷书的笔画各自分开，连书是把字连在一起写的，这句话与连书的含义相反。"}, {"text": "碑文上的每个字都要单独刻清楚，所以多用连书。", "explanation": "这里应该用〈篆书〉。篆书的字各自独立，碑文要求每个字单独刻清楚；连书是把字连在一起写的，与这一要求相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90943, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "连书", "is_correct": true, "explanation": "正确：连书是一种书写方式，可以用来写名字。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不是用来书写名字的方式。"}, {"text": "乐谱", "is_correct": false, "explanation": "语义：乐谱是记录音乐的符号，不用来写名字。"}, {"text": "数学", "is_correct": false, "explanation": "搭配：“用……来写”的对象应是书写方式或工具，数学不是。"}], "explanations": {"连书": "正确：连书是一种书写方式，可以用来写名字。", "歌曲": "语义：歌曲不是用来书写名字的方式。", "乐谱": "语义：乐谱是记录音乐的符号，不用来写名字。", "数学": "搭配：“用……来写”的对象应是书写方式或工具，数学不是。"}, "sentence_index": 6, "correct_answer": "连书"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "印刷的书上全是连书，每个字都分得很开。", "explanation": "这里应该用〈印刷体〉。印刷的字是一个一个分开的，连书是把字连在一起写，两者相反。"}, {"text": "小学生写作业要用连书，一笔一画写清楚。", "explanation": "这里应该用〈楷书〉。一笔一画、字字分开的是楷书，连书是把字连在一起写的。"}, {"text": "这个连书很大，挂在商店门口。", "explanation": "这里应该用〈招牌〉。挂在门口的是招牌，连书是一种写法，不是可以挂起来的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90943, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想学这只连书。", "corrected_sentence": "我想学这种连书。", "error_description": "量词错误：“连书”是一种写法，应该用量词“种”。“只”多用于动物或成对的器官，不能用来量“连书”。应说“这种连书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90943, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是老师写连书。", "corrected_sentence": "这是老师写的连书。", "error_description": "“的”遗漏：“老师写的连书”中“的”把动词短语变成定语，缺了“的”，“这是老师写连书”不成句。应说“这是老师写的连书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
