INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90944, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指书写时把几个字或字母连成一体的写法，也指连在一起书写的字形。", "primary_collocate": null, "pronunciation": "lián shū", "ipa": "li̯ɛn³⁵ ʂu⁵⁵", "syllable_count": 2, "sentences": [{"text": "英文手写体常用连书，字母都连在一起。", "target_word": "连书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种连书的写法很难认。", "target_word": "连书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，写作业时不要用连书。", "target_word": "连书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他写字很快，所以常常用连书。", "target_word": "连书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草书里有很多连书的字形。", "target_word": "连书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，这两个字用了连书的写法。", "target_word": "连书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我读不懂这张便条，因为全是连书。", "target_word": "连书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "连书能让写字的速度快一点儿。", "target_word": "连书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个字母的连书字形像一个小圈。", "target_word": "连书", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古人写信时，常用连书的方法。", "target_word": "连书", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "連書", "label": "繁体"}], "register": "中性", "sense_fingerprint": "书写时把几个字或字母连成一体的写法或字形", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f9bab8fe-0b72-43ae-8aa8-81542a01a1dd') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90944, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "连书", "is_correct": true, "explanation": "连书：把几个字或字母连成一体的写法，是正确答案。"}, {"text": "脸书", "is_correct": false, "explanation": "liǎn（第三声）与 lián（第二声）声调不同，脸书意思是社交网站（台湾用语）。"}, {"text": "联署", "is_correct": false, "explanation": "shǔ（第三声）与 shū（第一声）声调不同，联署意思是几个人共同签名。"}, {"text": "良书", "is_correct": false, "explanation": "liáng 与 lián 的韵母不同（-ang 与 -an），良书意思是好书。"}], "explanations": {"连书": "连书：把几个字或字母连成一体的写法，是正确答案。", "脸书": "liǎn（第三声）与 lián（第二声）声调不同，脸书意思是社交网站（台湾用语）。", "联署": "shǔ（第三声）与 shū（第一声）声调不同，联署意思是几个人共同签名。", "良书": "liáng 与 lián 的韵母不同（-ang 与 -an），良书意思是好书。"}, "sentence_index": null, "correct_answer": "连书"}, "level_3": {"options": [{"text": "连书", "is_correct": true, "explanation": "正确：连书指把字母连成一体的写法，与“字母都连在一起”相符。"}, {"text": "印刷体", "is_correct": false, "explanation": "语义：印刷体的字母彼此分开，与“手写体”和“字母都连在一起”相矛盾。"}, {"text": "汉字", "is_correct": false, "explanation": "搭配：“英文手写体”指英文的手写字体，汉字不能用在这里。"}, {"text": "篆书", "is_correct": false, "explanation": "语义：篆书是古代汉字字体，不是英文字母的手写方式。"}], "explanations": {"连书": "正确：连书指把字母连成一体的写法，与“字母都连在一起”相符。", "印刷体": "语义：印刷体的字母彼此分开，与“手写体”和“字母都连在一起”相矛盾。", "汉字": "搭配：“英文手写体”指英文的手写字体，汉字不能用在这里。", "篆书": "语义：篆书是古代汉字字体，不是英文字母的手写方式。"}, "sentence_index": 0, "correct_answer": "连书"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本词典的例句用连书，字很清楚。", "explanation": "这里应该用〈印刷体〉。印刷字体的字母彼此分开，不是连在一起的写法，连书不能用来形容印刷字。"}, {"text": "连书的每个字都要分开写。", "explanation": "这里应该用〈楷书〉。楷书的字要分开写，连书是把字连在一起写，两者正好相反。"}, {"text": "古代印章上常刻连书。", "explanation": "这里应该用〈篆书〉。篆书用于刻在印章、碑石上，连书是连笔书写的方式，不用于刻印。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90944, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "连书", "is_correct": true, "explanation": "正确：连书的字连在一起，读者难以辨认，符合“读不懂”。"}, {"text": "宴会", "is_correct": false, "explanation": "语义：便条上不可能全是宴会，句意不通。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：便条不会全是歌曲，读不懂与此无关。"}, {"text": "汤圆", "is_correct": false, "explanation": "语义：便条上不会全是汤圆，句意不通。"}], "explanations": {"连书": "正确：连书的字连在一起，读者难以辨认，符合“读不懂”。", "宴会": "语义：便条上不可能全是宴会，句意不通。", "歌曲": "语义：便条不会全是歌曲，读不懂与此无关。", "汤圆": "语义：便条上不会全是汤圆，句意不通。"}, "sentence_index": 6, "correct_answer": "连书"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电脑打出来的字都是连书，字母一个一个分开。", "explanation": "这里应该用〈印刷体〉。电脑打出的字母彼此分开，是印刷体；连书是把字母连在一起写的。"}, {"text": "考试时要用连书，每个字都写得端端正正。", "explanation": "这里应该用〈楷书〉。端正、字字分开的是楷书，连书是把字连在一起写的。"}, {"text": "这块古老的石碑上刻着连书，是秦朝的字体。", "explanation": "这里应该用〈篆书〉。秦朝刻在石碑上的字体是篆书，连书是连笔书写的方式，不是一种刻在石头上的字体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90944, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只连书很有特点，我想学。", "corrected_sentence": "这种连书很有特点，我想学。", "error_description": "量词错误：“连书”是一种写法，应该用量词“种”。“只”多用于动物或成对的器官，不能用来量“连书”。应说“这种连书”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90944, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张卡片上的一只连书，我看得很清楚。", "corrected_sentence": "这张卡片上的一种连书，我看得很清楚。", "error_description": "量词错误：“连书”是一种写法，应该用量词“种”，不能用“只”。应说“这张卡片上的一种连书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3510f827-0343-4132-a211-b6281d80c3e4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
