INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90945, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "工作时间是大人每天去做事的那些时间。", "primary_collocate": null, "pronunciation": "gōng zuò shí jiān", "ipa": "kʊŋ˥ tswɔ˥˩ ʂɨ˧˥ tɕjɛn˥", "syllable_count": 4, "sentences": [{"text": "妈妈的工作时间是白天，她晚上在家。", "target_word": "工作时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸在工作时间不能回家玩。", "target_word": "工作时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作时间到了，爸爸就去公司了。", "target_word": "工作时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想在妈妈的工作时间里自己写作业。", "target_word": "工作时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作时间里，爸爸不能陪我玩。", "target_word": "工作时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作时间结束后，妈妈就回家做饭。", "target_word": "工作时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的工作时间每天从早上七点到下午四点。", "target_word": "工作时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸的工作时间很长，我很想他。", "target_word": "工作时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作时间里，大人都在忙。", "target_word": "工作时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道妈妈的工作时间是几点吗？", "target_word": "工作时间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "弹性工作时间", "label": "复合"}, {"form": "工作時間", "label": "繁体"}], "register": "中性", "sense_fingerprint": "大人每天做事的时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f17da28-59f8-418f-b207-d6e528bd9ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90945, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工作时间", "is_correct": true, "explanation": "工作时间：大人去做事的时段，与“是白天，她晚上在家”相符。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高指身材高矮，不是时段，不能说“身高是白天”。"}, {"text": "工资", "is_correct": false, "explanation": "语义：工资指报酬，不是时段，与“是白天”的说法矛盾。"}, {"text": "办公室", "is_correct": false, "explanation": "语义：办公室指地点，不是时段，不能说“办公室是白天”。"}], "explanations": {"工作时间": "工作时间：大人去做事的时段，与“是白天，她晚上在家”相符。", "身高": "体貌：身高指身材高矮，不是时段，不能说“身高是白天”。", "工资": "语义：工资指报酬，不是时段，与“是白天”的说法矛盾。", "办公室": "语义：办公室指地点，不是时段，不能说“办公室是白天”。"}, "sentence_index": 0, "correct_answer": "工作时间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈的工作时间很高，学校都很信任她。", "explanation": "这里应该用〈工作效率〉。〈高〉形容效率等程度，工作时间指时段，不能说“高”。"}, {"text": "妈妈的工作时间离家很近，每天走路就能到。", "explanation": "这里应该用〈工作单位〉。工作时间指时段，不能用来说离家多远。"}, {"text": "妈妈的工作时间很强，每天都很累。", "explanation": "这里应该用〈工作能力〉。〈强〉形容能力，不能用来形容时段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90945, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工作时间", "is_correct": true, "explanation": "工作时间：老师上班的时段，与“每天从早上七点到下午四点”相符。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄指岁数，不是时段，不能说“年龄每天从早上七点到下午四点”。"}, {"text": "外貌", "is_correct": false, "explanation": "体貌：外貌指人的样子，不是时段，与“从早上七点到下午四点”矛盾。"}, {"text": "工作单位", "is_correct": false, "explanation": "语义：工作单位指机构，不是时段，不能和具体钟点搭配。"}], "explanations": {"工作时间": "工作时间：老师上班的时段，与“每天从早上七点到下午四点”相符。", "年龄": "语义：年龄指岁数，不是时段，不能说“年龄每天从早上七点到下午四点”。", "外貌": "体貌：外貌指人的样子，不是时段，与“从早上七点到下午四点”矛盾。", "工作单位": "语义：工作单位指机构，不是时段，不能和具体钟点搭配。"}, "sentence_index": 6, "correct_answer": "工作时间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈的工作时间很大，晚上常常睡不好。", "explanation": "这里应该用〈工作压力〉。〈大〉可形容压力，工作时间指时段，不能用“大”形容。"}, {"text": "妈妈的工作时间是照顾病人，很辛苦。", "explanation": "这里应该用〈工作内容〉。工作时间指时段，不能用来说明做什么事。"}, {"text": "妈妈的工作时间很认真，大家都很尊敬她。", "explanation": "这里应该用〈工作态度〉。〈认真〉形容做事态度，工作时间是时段，不能用来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90945, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈的工作时间结束着，她回家做饭。", "corrected_sentence": "妈妈的工作时间结束了，她回家做饭。", "error_description": "错误：“结束”表示动作已经完成，应该用“了”，用“着”表示持续，不通顺。应说“工作时间结束了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90945, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "下午的工作时间到着，老师就去学校了。", "corrected_sentence": "下午的工作时间到了，老师就去学校了。", "error_description": "错误：“到”表示已经发生的变化，应该用“了”，不能用表示持续的“着”。应说“工作时间到了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
