INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90946, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "规定用于工作的时段。", "primary_collocate": null, "pronunciation": "gōng zuò shí jiān", "ipa": "kʊŋ˥ tswɔ˥˩ ʂɨ˧˥ tɕjɛn˥", "syllable_count": 4, "sentences": [{"text": "我们公司的工作时间是早上九点到下午六点。", "target_word": "工作时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作时间不能玩手机。", "target_word": "工作时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的工作时间很长，常常很晚才回家。", "target_word": "工作时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在工作时间，请不要大声说话。", "target_word": "工作时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院的工作时间每天都不一样。", "target_word": "工作时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家银行的工作时间是几点到几点？", "target_word": "工作时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸的工作时间在晚上，白天要睡觉。", "target_word": "工作时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作时间以外，老板也会给我打电话。", "target_word": "工作时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你们的工作时间一周有多少个小时？", "target_word": "工作时间", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作时间太长，对身体不好。", "target_word": "工作时间", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "弹性工作时间", "label": "复合"}, {"form": "工作時間", "label": "繁体"}], "register": "中性", "sense_fingerprint": "规定的上班时段", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f17da28-59f8-418f-b207-d6e528bd9ac3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90946, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工作时间", "is_correct": true, "explanation": "工作时间：规定用于工作的时段，与“早上九点到下午六点”相符，能完整填入空格。"}, {"text": "寒假", "is_correct": false, "explanation": "语义：寒假是学校的假期，不是每天的上班时段，与“早上九点到下午六点”矛盾。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高指人的身材高矮，不能用来说明公司的上班时段。"}, {"text": "办公室", "is_correct": false, "explanation": "语义：办公室指地点，不是时段，不能说“是早上九点到下午六点”。"}], "explanations": {"工作时间": "工作时间：规定用于工作的时段，与“早上九点到下午六点”相符，能完整填入空格。", "寒假": "语义：寒假是学校的假期，不是每天的上班时段，与“早上九点到下午六点”矛盾。", "身高": "体貌：身高指人的身材高矮，不能用来说明公司的上班时段。", "办公室": "语义：办公室指地点，不是时段，不能说“是早上九点到下午六点”。"}, "sentence_index": 0, "correct_answer": "工作时间"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司的工作时间在市中心，很方便。", "explanation": "这里应该用〈工作地点〉。工作时间指时段，不能用来表示地点。"}, {"text": "他的工作时间很高，老板很满意。", "explanation": "这里应该用〈工作效率〉。〈高〉形容效率等程度，工作时间指时段，不能说“高”。"}, {"text": "他的工作时间很大，每天要做很多事。", "explanation": "这里应该用〈工作量〉。〈大〉形容的是量，描述时段要用〈长〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90946, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工作时间", "is_correct": true, "explanation": "工作时间：爸爸上班的时段，与“在晚上，白天要睡觉”相符。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重是身体的重量，不是可以“在晚上”的时段，说不通。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄指岁数，不是时段，不能说“年龄在晚上”。"}, {"text": "工作单位", "is_correct": false, "explanation": "语义：工作单位指机构，不是时段，与“在晚上”的说法不合。"}], "explanations": {"工作时间": "工作时间：爸爸上班的时段，与“在晚上，白天要睡觉”相符。", "体重": "体貌：体重是身体的重量，不是可以“在晚上”的时段，说不通。", "年龄": "语义：年龄指岁数，不是时段，不能说“年龄在晚上”。", "工作单位": "语义：工作单位指机构，不是时段，与“在晚上”的说法不合。"}, "sentence_index": 6, "correct_answer": "工作时间"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的工作时间很突出，被评为优秀员工。", "explanation": "这里应该用〈工作成绩〉。〈突出〉形容成绩等，工作时间指时段，不能说“突出”。"}, {"text": "他的工作时间是设计海报。", "explanation": "这里应该用〈工作内容〉。工作时间指时段，不能用来说明做什么事。"}, {"text": "他的工作时间很认真。", "explanation": "这里应该用〈工作态度〉。〈认真〉形容人做事的态度，不能用来形容时段。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90946, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工作时间结束着，大家都回家了。", "corrected_sentence": "工作时间结束了，大家都回家了。", "error_description": "错误：“结束”表示动作已经完成，应该用“了”，用“着”表示持续，不通顺。应说“工作时间结束了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90946, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工作时间到着，我们开始上班吧。", "corrected_sentence": "工作时间到了，我们开始上班吧。", "error_description": "错误：“到”表示已经发生的变化，应该用“了”，不能用“着”。应说“工作时间到了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a790e2b-b94b-42db-90c7-ee92a1c6b709') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
