INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90948, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "机关、单位或个人向上级或群众汇报工作情况和成果的正式文件或讲话。", "primary_collocate": null, "pronunciation": "gōng zuò bào gào", "ipa": "kʊŋ˥ tsuɔ˥˩ pɑʊ˥˩ kɑʊ˥˩", "syllable_count": 4, "sentences": [{"text": "市长在大会上做了政府工作报告。", "target_word": "工作报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份工作报告是给上级看的。", "target_word": "工作报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长的工作报告讲了一个小时。", "target_word": "工作报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "代表们认真听着工作报告。", "target_word": "工作报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司今年的工作报告已经发给大家了。", "target_word": "工作报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作报告里有很多数字。", "target_word": "工作报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在大会上读完了工作报告。", "target_word": "工作报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里开会，村长先做工作报告。", "target_word": "工作报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家对这份工作报告很满意。", "target_word": "工作报告", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总经理把年度工作报告交给了董事会。", "target_word": "工作报告", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "年度工作报告", "label": "复合"}], "register": "正式", "sense_fingerprint": "向上级或群众汇报工作的正式文件或讲话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4236ccb-40e1-4dd6-9f6f-04c3557493d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90948, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工作报告", "is_correct": true, "explanation": "正确。“政府工作报告”是市长在大会上发表的正式文件，符合句意。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园是地方，不是市长在大会上做的正式汇报。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是电子设备，不是汇报工作的正式文件。"}, {"text": "饭菜", "is_correct": false, "explanation": "搭配：“政府”通常修饰文件、会议，不修饰饭菜，“政府饭菜”不成词。"}], "explanations": {"工作报告": "正确。“政府工作报告”是市长在大会上发表的正式文件，符合句意。", "花园": "语义：花园是地方，不是市长在大会上做的正式汇报。", "手机": "语义：手机是电子设备，不是汇报工作的正式文件。", "饭菜": "搭配：“政府”通常修饰文件、会议，不修饰饭菜，“政府饭菜”不成词。"}, "sentence_index": 0, "correct_answer": "工作报告"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校贴出一份工作报告：明天上午九点开会，请准时参加。", "explanation": "这里应该用〈通知〉。通知用于告知时间、要求，工作报告用于汇报工作情况和成果。"}, {"text": "她给远方的朋友写了一份工作报告。", "explanation": "这里应该用〈信〉。信用于私人问候，工作报告是机关、单位向上级汇报工作的正式文件，不能用来写给朋友。"}, {"text": "服务员递给我一份工作报告。", "explanation": "这里应该用〈菜单〉。菜单用于点菜，工作报告是汇报工作的正式文件，不能在餐厅里递给顾客。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90948, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "工作报告", "is_correct": true, "explanation": "正确。“读完了”的对象是正式的工作报告，符合句意。"}, {"text": "早饭", "is_correct": false, "explanation": "搭配：“读完了”不能接“早饭”，早饭不是可以读的东西。"}, {"text": "猫", "is_correct": false, "explanation": "语义：猫是动物，不是可以读完的内容，与大会上的汇报不合。"}, {"text": "眼镜", "is_correct": false, "explanation": "语义：眼镜是物品，不能读完，与“在大会上”的语境不合。"}], "explanations": {"工作报告": "正确。“读完了”的对象是正式的工作报告，符合句意。", "早饭": "搭配：“读完了”不能接“早饭”，早饭不是可以读的东西。", "猫": "语义：猫是动物，不是可以读完的内容，与大会上的汇报不合。", "眼镜": "语义：眼镜是物品，不能读完，与“在大会上”的语境不合。"}, "sentence_index": 6, "correct_answer": "工作报告"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈照着工作报告做饭。", "explanation": "这里应该用〈食谱〉。食谱用于做菜，工作报告是汇报工作的正式文件，不能用来照着做饭。"}, {"text": "她看着工作报告弹了一首钢琴曲。", "explanation": "这里应该用〈乐谱〉。乐谱用于演奏，工作报告是汇报工作的正式文件，不能照着弹琴。"}, {"text": "街上贴着一张工作报告，宣传新产品。", "explanation": "这里应该用〈海报〉。海报用于宣传，工作报告用于汇报工作，不能用来做宣传。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90948, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "市长在大会上发表了一只政府工作报告。", "corrected_sentence": "市长在大会上发表了一份政府工作报告。", "error_description": "量词错误：“只”用于动物等，工作报告应用量词“份”，应说“一份政府工作报告”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90948, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司的这只年度工作报告很重要。", "corrected_sentence": "公司的这份年度工作报告很重要。", "error_description": "量词错误：“只”用于动物等，工作报告应用量词“份”，应说“这份年度工作报告”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
