INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90949, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "游戏设备是玩游戏时要用的东西，像手柄和屏幕。", "primary_collocate": null, "pronunciation": "yóu xì shè bèi", "ipa": "jou̯˧˥ ɕi˥˩ ʂɤ˥˩ pei̯˥˩", "syllable_count": 4, "sentences": [{"text": "这套游戏设备有手柄和屏幕。", "target_word": "游戏设备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他买了一台新的游戏设备。", "target_word": "游戏设备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我的游戏设备放在客厅的电视旁边。", "target_word": "游戏设备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "没有游戏设备，我们就没法玩游戏。", "target_word": "游戏设备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟把游戏设备带到了奶奶家。", "target_word": "游戏设备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些游戏设备的屏幕很大。", "target_word": "游戏设备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他最喜欢的游戏设备是红色的。", "target_word": "游戏设备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店里有很多游戏设备，价格都不一样。", "target_word": "游戏设备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "生日那天，爸爸送给我一套游戏设备。", "target_word": "游戏设备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们围着游戏设备玩了一下午。", "target_word": "游戏设备", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "套", "label": "量词"}, {"form": "台", "label": "量词"}, {"form": "遊戲設備", "label": "繁体"}], "register": "中性", "sense_fingerprint": "玩游戏时用的手柄、屏幕等日常用品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eec25974-71fd-4a3e-aa7f-4714ae3f80b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90949, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "游戏设备", "is_correct": true, "explanation": "正确：“游戏设备”指玩游戏用的手柄、屏幕等，句中说的正是这套器材有手柄和屏幕。"}, {"text": "家具", "is_correct": false, "explanation": "语义：家具是家里摆放的器物，没有屏幕，与“屏幕”不合。"}, {"text": "文具", "is_correct": false, "explanation": "语义：文具指笔、本子等学习用品，不说有屏幕。"}, {"text": "乐器", "is_correct": false, "explanation": "搭配：“乐器”一般不说带“屏幕”这类部件，“有手柄和屏幕”不通。"}], "explanations": {"游戏设备": "正确：“游戏设备”指玩游戏用的手柄、屏幕等，句中说的正是这套器材有手柄和屏幕。", "家具": "语义：家具是家里摆放的器物，没有屏幕，与“屏幕”不合。", "文具": "语义：文具指笔、本子等学习用品，不说有屏幕。", "乐器": "搭配：“乐器”一般不说带“屏幕”这类部件，“有手柄和屏幕”不通。"}, "sentence_index": 0, "correct_answer": "游戏设备"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只游戏设备。", "explanation": "量词错误：“只”多用于动物或成对的小物件，“游戏设备”应用“套”或“台”。"}, {"text": "这条游戏设备的屏幕很大。", "explanation": "量词错误：“条”用于细长的东西，“游戏设备”不能说“这条”，应说“这套”或“这台”。"}, {"text": "他买了一朵新的游戏设备。", "explanation": "量词错误：“朵”用于花朵，“游戏设备”不能用“朵”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90949, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "游戏设备", "is_correct": true, "explanation": "正确：“游戏设备”是有颜色的器材，说它“是红色的”，句意通顺。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“是红色的”一般修饰有颜色的物品，“天气”不能说是红色的。"}, {"text": "音乐", "is_correct": false, "explanation": "语义：音乐是声音，没有颜色，与“红色的”不合。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气无色，不能说“最喜欢的空气是红色的”。"}], "explanations": {"游戏设备": "正确：“游戏设备”是有颜色的器材，说它“是红色的”，句意通顺。", "天气": "搭配：“是红色的”一般修饰有颜色的物品，“天气”不能说是红色的。", "音乐": "语义：音乐是声音，没有颜色，与“红色的”不合。", "空气": "语义：空气无色，不能说“最喜欢的空气是红色的”。"}, "sentence_index": 6, "correct_answer": "游戏设备"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这一页游戏设备的屏幕很大。", "explanation": "量词错误：“页”用于纸张，“游戏设备”不能说“这一页”。"}, {"text": "他买了一棵新的游戏设备。", "explanation": "量词错误：“棵”用于树木等植物，“游戏设备”不能用“棵”。"}, {"text": "孩子们围着一顶游戏设备玩了一下午。", "explanation": "量词错误：“顶”用于帽子等物品，“游戏设备”不能用“顶”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90949, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "哥哥昨天买了一只游戏设备。", "corrected_sentence": "哥哥昨天买了一套游戏设备。", "error_description": "量词错误：“游戏设备”应用量词“套”或“台”，不能用“只”。应说“一套游戏设备”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90949, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我买了一新套的游戏设备。", "corrected_sentence": "我买了一套新的游戏设备。", "error_description": "语序错误：修饰语“新”应放在量词“套”之后，应说“一套新的游戏设备”，不能说“一新套的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
