INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90950, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供人进行电子游戏或娱乐游戏所用的机器、器材的统称。", "primary_collocate": null, "pronunciation": "yóu xì shè bèi", "ipa": "jou̯˧˥ ɕi˥˩ ʂɤ˥˩ pei̯˥˩", "syllable_count": 4, "sentences": [{"text": "这家店专门修理游戏设备。", "target_word": "游戏设备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商场里的游戏设备供孩子们免费玩。", "target_word": "游戏设备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "游戏厅里摆着很多游戏设备。", "target_word": "游戏设备", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司生产各种游戏设备。", "target_word": "游戏设备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新的游戏设备比旧的更快，声音也更好。", "target_word": "游戏设备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公园里新装了一批供娱乐用的游戏设备。", "target_word": "游戏设备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "游戏设备坏了，工人正在修理。", "target_word": "游戏设备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们公司去年卖出了几万台游戏设备。", "target_word": "游戏设备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "玩家们都想试试这台最新的游戏设备。", "target_word": "游戏设备", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "展会上展出了许多新型游戏设备。", "target_word": "游戏设备", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "套", "label": "量词"}, {"form": "台", "label": "量词"}, {"form": "遊戲設備", "label": "繁体"}], "register": "中性", "sense_fingerprint": "电子游戏和娱乐游戏所用机器、器材的统称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eec25974-71fd-4a3e-aa7f-4714ae3f80b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90950, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "游戏设备", "is_correct": true, "explanation": "正确：“游戏设备”是电子游戏用的器材，店里可以修理，句意通顺。"}, {"text": "食品", "is_correct": false, "explanation": "语义：食品是吃的东西，不能修理，与“修理”不合。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料是喝的东西，不能修理。"}, {"text": "糕点", "is_correct": false, "explanation": "搭配：糕点是食物，不能说“修理糕点”。"}], "explanations": {"游戏设备": "正确：“游戏设备”是电子游戏用的器材，店里可以修理，句意通顺。", "食品": "语义：食品是吃的东西，不能修理，与“修理”不合。", "饮料": "语义：饮料是喝的东西，不能修理。", "糕点": "搭配：糕点是食物，不能说“修理糕点”。"}, "sentence_index": 0, "correct_answer": "游戏设备"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家公司生产了一棵游戏设备。", "explanation": "量词错误：“棵”用于树木等植物，“游戏设备”不能用“棵”。"}, {"text": "商场里摆着一朵游戏设备，很多人来看。", "explanation": "量词错误：“朵”用于花朵，“游戏设备”不能用“朵”。"}, {"text": "我们买了一条游戏设备。", "explanation": "量词错误：“条”用于细长的东西，“游戏设备”不能用“条”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90950, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "游戏设备", "is_correct": true, "explanation": "正确：“游戏设备”指供电子游戏使用的器材，坏了需要修理。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，坏了不需要工人修理。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是器物，不能由工人修理。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“坏了”一般用于器物或设施，“作业”不能说坏了。"}], "explanations": {"游戏设备": "正确：“游戏设备”指供电子游戏使用的器材，坏了需要修理。", "蛋糕": "语义：蛋糕是食物，坏了不需要工人修理。", "天气": "语义：天气不是器物，不能由工人修理。", "作业": "搭配：“坏了”一般用于器物或设施，“作业”不能说坏了。"}, "sentence_index": 6, "correct_answer": "游戏设备"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "展会上展出了一页新型游戏设备。", "explanation": "量词错误：“页”用于纸张，“游戏设备”不能用“页”。"}, {"text": "展会上她抱着一顶新型游戏设备。", "explanation": "量词错误：“顶”用于帽子等物品，“游戏设备”不能用“顶”。"}, {"text": "展会上展出了一张新型游戏设备。", "explanation": "量词错误：“张”用于平面的东西，“游戏设备”不能用“张”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90950, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家商店进了一只新的游戏设备。", "corrected_sentence": "这家商店进了一套新的游戏设备。", "error_description": "量词错误：“游戏设备”应用量词“套”或“台”，不能用“只”。应说“一套新的游戏设备”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90950, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们公司买了一新台的游戏设备。", "corrected_sentence": "我们公司买了一台新的游戏设备。", "error_description": "语序错误：修饰语“新”应放在量词“台”之后，应说“一台新的游戏设备”，不能说“一新台的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
