INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90952, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "春节之前的一段时间。", "primary_collocate": null, "pronunciation": "nián qián", "ipa": "niɛn˧˥ tɕʰiɛn˧˥", "syllable_count": 2, "sentences": [{"text": "年前我要回老家看爸爸妈妈。", "target_word": "年前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司年前很忙，过年后才休息。", "target_word": "年前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年前的火车票很难买。", "target_word": "年前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们年前把房子打扫干净了。", "target_word": "年前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年前商店里的人特别多。", "target_word": "年前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说年前一定把钱还给我。", "target_word": "年前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年前下了一场大雪，路上很冷。", "target_word": "年前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工作要在年前做完，不然没法安心过年。", "target_word": "年前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈年前就开始准备年货了。", "target_word": "年前", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年前的几天，街上到处是红灯笼。", "target_word": "年前", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "春节之前的一段时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4256b07-2d2b-4db1-830f-e6bafd30f388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90952, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "年前", "is_correct": true, "explanation": "年前指春节之前的一段时间，与“回老家看爸爸妈妈”的计划相合。"}, {"text": "去年", "is_correct": false, "explanation": "语义：“去年”指过去，与句中“要”表示的将来计划相冲突。"}, {"text": "前年", "is_correct": false, "explanation": "语义：“前年”指过去的时间，与句中“要”表示的将来计划相冲突。"}, {"text": "昨天", "is_correct": false, "explanation": "搭配：“要”表示将来，不能与表示过去的“昨天”搭配。"}], "explanations": {"年前": "年前指春节之前的一段时间，与“回老家看爸爸妈妈”的计划相合。", "去年": "语义：“去年”指过去，与句中“要”表示的将来计划相冲突。", "前年": "语义：“前年”指过去的时间，与句中“要”表示的将来计划相冲突。", "昨天": "搭配：“要”表示将来，不能与表示过去的“昨天”搭配。"}, "sentence_index": 0, "correct_answer": "年前"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "过了年，我们年前才回公司上班。", "explanation": "这里应该用〈年后〉。“年前”指春节之前，与“过了年”矛盾。"}, {"text": "今年三月，公司年前开了一次员工大会。", "explanation": "这里应该用〈年后〉。今年三月已在春节之后，“年前”指春节之前，二者矛盾。"}, {"text": "春节假期结束后，他年前才开始写论文。", "explanation": "这里应该用〈春节后〉。“假期结束后”发生在春节之后，与“年前”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcda1516-089b-43a9-89fd-53dfeb9462c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90952, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年前", "is_correct": true, "explanation": "年前指春节之前，与“下了一场大雪”的已发生语境相合。"}, {"text": "明天", "is_correct": false, "explanation": "体貌：“了”表示已完成，不能与表示将来的“明天”搭配。"}, {"text": "明年", "is_correct": false, "explanation": "语义：“明年”指将来，与“下了一场大雪”已经发生的叙述冲突。"}, {"text": "夏天", "is_correct": false, "explanation": "语义：夏天不会下大雪，与“路上很冷”也互相矛盾。"}], "explanations": {"年前": "年前指春节之前，与“下了一场大雪”的已发生语境相合。", "明天": "体貌：“了”表示已完成，不能与表示将来的“明天”搭配。", "明年": "语义：“明年”指将来，与“下了一场大雪”已经发生的叙述冲突。", "夏天": "语义：夏天不会下大雪，与“路上很冷”也互相矛盾。"}, "sentence_index": 6, "correct_answer": "年前"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "元宵节过后，她年前才开始上班。", "explanation": "这里应该用〈春节后〉。元宵节在春节之后，“年前”指春节之前，二者矛盾。"}, {"text": "大年初一，我们年前就放了鞭炮。", "explanation": "这里应该用〈春节当天〉。大年初一本身是春节当天，“年前”指春节之前，二者时间矛盾。"}, {"text": "开学后的第一天，我们年前就开始考试。", "explanation": "这里应该用〈春节后〉。开学在春节之后，“年前”指春节之前，二者矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcda1516-089b-43a9-89fd-53dfeb9462c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90952, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们年前的把账算清楚。", "corrected_sentence": "我们年前把账算清楚。", "error_description": "时间词“年前”后不能加“的”再接动词短语，“的”应去掉。写成“我们年前的把账算清楚”是误用，应为“我们年前把账算清楚”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcda1516-089b-43a9-89fd-53dfeb9462c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90952, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "年前以前我们买了很多年货。", "corrected_sentence": "年前我们买了很多年货。", "error_description": "“年前”已表示春节之前，后面再加“以前”属于重复，应去掉“以前”，写成“年前我们买了很多年货”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcda1516-089b-43a9-89fd-53dfeb9462c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
