INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90953, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "很会做事、本事很大的人。", "primary_collocate": null, "pronunciation": "gàn cái", "ipa": "kan˥˩ tsʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "他是个干才，遇到难题总能想出办法。", "target_word": "干才", "complexity_tier": "T3", "furigana": "tā shì ge gàncái, yùdào nántí zǒng néng xiǎng chū bànfǎ.", "sentence_source": "generated"}, {"text": "王经理是公司里有名的干才。", "target_word": "干才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店请了一位干才来管事。", "target_word": "干才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说小李是个干才，什么事都难不倒他。", "target_word": "干才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位干才一个人就能做三个人的事。", "target_word": "干才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司需要干才，不要只会说话的人。", "target_word": "干才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里出了一个干才，大家都很高兴。", "target_word": "干才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板很喜欢干才，因为他们做事快。", "target_word": "干才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别看她年纪小，却是个干才。", "target_word": "干才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个干才一来，问题很快就解决了。", "target_word": "干才", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "位", "label": "量词"}, {"form": "幹才", "label": "繁体"}], "register": "书面", "sense_fingerprint": "做事能力很强、本事很大的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fc88ea3-cc81-44ee-a2a6-03befb6fb706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90953, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "干才", "is_correct": true, "explanation": "正确。“干才”指很会做事、本事很大的人，与“总能想出办法”相符。"}, {"text": "庸才", "is_correct": false, "explanation": "语义：“庸才”指平庸、能力低的人，与“总能想出办法”矛盾。"}, {"text": "懒汉", "is_correct": false, "explanation": "语义：“懒汉”不肯做事，与“遇到难题总能想出办法”矛盾。"}, {"text": "草包", "is_correct": false, "explanation": "语域：“草包”是口语中的贬义词，与书面叙述不合，且与“总能想出办法”矛盾。"}], "explanations": {"干才": "正确。“干才”指很会做事、本事很大的人，与“总能想出办法”相符。", "庸才": "语义：“庸才”指平庸、能力低的人，与“总能想出办法”矛盾。", "懒汉": "语义：“懒汉”不肯做事，与“遇到难题总能想出办法”矛盾。", "草包": "语域：“草包”是口语中的贬义词，与书面叙述不合，且与“总能想出办法”矛盾。"}, "sentence_index": 0, "correct_answer": "干才"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是个干才，画画一学就会。", "explanation": "这里应该用〈天才〉。干才指办事能干、善于处理事务；画画一学就会说明的是天赋，应说天才。"}, {"text": "这位干才的歌声很动听。", "explanation": "这里应该用〈歌手〉。干才指办事能干的人，唱歌动听的人应称歌手。"}, {"text": "这位干才研究了二十年的历史。", "explanation": "这里应该用〈学者〉。干才指善于办事的人，研究历史、做学问的人应称学者。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11e86a06-4236-491b-bd68-3cf176847259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90953, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "干才", "is_correct": true, "explanation": "正确。“干才”指办事能干的人，与“大家都很高兴”相符。"}, {"text": "小偷", "is_correct": false, "explanation": "语义：村里出了小偷，大家不会高兴，与“大家都很高兴”矛盾。"}, {"text": "病人", "is_correct": false, "explanation": "语义：村里出了一个病人，大家不会因此高兴，与“大家都很高兴”矛盾。"}, {"text": "饭桶", "is_correct": false, "explanation": "语域：“饭桶”是口语贬义词，与书面叙述不合，且与“大家都很高兴”矛盾。"}], "explanations": {"干才": "正确。“干才”指办事能干的人，与“大家都很高兴”相符。", "小偷": "语义：村里出了小偷，大家不会高兴，与“大家都很高兴”矛盾。", "病人": "语义：村里出了一个病人，大家不会因此高兴，与“大家都很高兴”矛盾。", "饭桶": "语域：“饭桶”是口语贬义词，与书面叙述不合，且与“大家都很高兴”矛盾。"}, "sentence_index": 6, "correct_answer": "干才"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是个干才，冲进火场救出了三个孩子。", "explanation": "这里应该用〈英雄〉。干才指办事能干，冲进火场救人的勇敢之人要用英雄。"}, {"text": "这位干才为病人开了一张药方。", "explanation": "这里应该用〈医生〉。干才指办事能干的人，为病人开药方的人应称医生。"}, {"text": "这位干才写了三本小说。", "explanation": "这里应该用〈作家〉。干才指善于办事的人，写小说的人应称作家。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11e86a06-4236-491b-bd68-3cf176847259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90953, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他很干才，做事从来不拖拉。", "corrected_sentence": "他是个干才，做事从来不拖拉。", "error_description": "错误：“很干才”。“干才”是名词，指能干的人，不能受“很”修饰作谓语；应说“是个干才”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11e86a06-4236-491b-bd68-3cf176847259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90953, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只干才来了以后，工厂的产量翻了一番。", "corrected_sentence": "这位干才来了以后，工厂的产量翻了一番。", "error_description": "错误：量词“只”。“干才”指人，应用“位”或“个”；“只”多用于动物或小件物品。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11e86a06-4236-491b-bd68-3cf176847259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90955, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90955, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90955, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "运动会是很多人在一起比赛跑步、跳远的日子。", "primary_collocate": null, "pronunciation": "yùn dòng huì", "ipa": "yn˥˩ tʊŋ˥˩ xweɪ̯˥˩", "syllable_count": 3, "sentences": [{"text": "今天是学校的运动会，我们要比赛跑步。", "target_word": "运动会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动会上，小王跳远跳得最远。", "target_word": "运动会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "明天开运动会，大家都穿了运动鞋。", "target_word": "运动会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们班在运动会上跑步得了第一名。", "target_word": "运动会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动会那天，操场上有很多人。", "target_word": "运动会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友们都想参加今年的运动会。", "target_word": "运动会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动会开始了，同学们一起喊加油。", "target_word": "运动会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，明天的运动会可能要换时间。", "target_word": "运动会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸妈妈也来看我的运动会。", "target_word": "运动会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动会上，每个人都要跑一百米。", "target_word": "运动会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "届", "label": "量词"}, {"form": "场", "label": "量词"}], "register": "口语", "sense_fingerprint": "很多人聚在一起比赛跑步、跳远的日子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa66c51-d2c5-4935-9b03-31cebe5b34a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90955, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "运动会", "is_correct": true, "explanation": "正确：指学校组织的、多人比赛跑步的集会，与句中“比赛跑步”相符。"}, {"text": "考试", "is_correct": false, "explanation": "语义：“考试”是笔试或测验，不是比赛跑步的活动。"}, {"text": "音乐会", "is_correct": false, "explanation": "语义：“音乐会”是欣赏演出的场合，不是比赛跑步的活动。"}, {"text": "演讲", "is_correct": false, "explanation": "搭配：“演讲”不能与“比赛跑步”搭配，句中的活动是体育比赛。"}], "explanations": {"运动会": "正确：指学校组织的、多人比赛跑步的集会，与句中“比赛跑步”相符。", "考试": "语义：“考试”是笔试或测验，不是比赛跑步的活动。", "音乐会": "语义：“音乐会”是欣赏演出的场合，不是比赛跑步的活动。", "演讲": "搭配：“演讲”不能与“比赛跑步”搭配，句中的活动是体育比赛。"}, "sentence_index": 0, "correct_answer": "运动会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们每周末都去运动会跑步。", "explanation": "这里应该用〈体育馆〉或〈操场〉。运动会是学校组织的一次集会，不是固定的运动场地，不能说“去运动会跑步”。"}, {"text": "我们学校的一位运动会很热闹。", "explanation": "这里应该用〈届〉或〈场〉。运动会按届或场计数，“位”是用于人的量词，不能说“一位运动会”。"}, {"text": "我们班每周二上运动会。", "explanation": "这里应该用〈体育课〉。运动会只在特定日子举办，不是每周的课程，不能说“上运动会”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90955, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "运动会", "is_correct": true, "explanation": "正确：指一项集体活动的开始，同学们在这里一起喊加油。"}, {"text": "婚礼", "is_correct": false, "explanation": "语义：“婚礼”是新人结婚的仪式，学生不会在婚礼上一起喊加油。"}, {"text": "小说", "is_correct": false, "explanation": "搭配：“小说”不能说“开始了”来指一项集体活动，句中的开始指活动。"}, {"text": "面试", "is_correct": false, "explanation": "语义：“面试”是个人应聘的考核，不是同学们一起喊加油的场合。"}], "explanations": {"运动会": "正确：指一项集体活动的开始，同学们在这里一起喊加油。", "婚礼": "语义：“婚礼”是新人结婚的仪式，学生不会在婚礼上一起喊加油。", "小说": "搭配：“小说”不能说“开始了”来指一项集体活动，句中的开始指活动。", "面试": "语义：“面试”是个人应聘的考核，不是同学们一起喊加油的场合。"}, "sentence_index": 6, "correct_answer": "运动会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "运动会每天训练两个小时。", "explanation": "这里应该用〈运动员〉。运动会是活动，不能进行训练，每天训练的应是运动员。"}, {"text": "我每天晚上都去运动会看书。", "explanation": "这里应该用〈图书馆〉。运动会是体育集会，不是看书的地方。"}, {"text": "爸爸每天去运动会上班。", "explanation": "这里应该用〈公司〉。运动会是偶尔举行的活动，不是每天上班的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90955, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校明天要上运动会，大家都很激动。", "corrected_sentence": "学校明天要开运动会，大家都很激动。", "error_description": "搭配错误：运动会要说“开运动会”或“举办运动会”，不能说“上运动会”（“上”用于“上课”等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90955, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校下个月要开一位运动会，大家都很兴奋。", "corrected_sentence": "学校下个月要开一场运动会，大家都很兴奋。", "error_description": "量词错误：“运动会”的量词应用“届”或“场”，“位”只用于人，不能说“一位运动会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
