INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90956, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "学校或单位组织的、包含多个体育项目的比赛集会。", "primary_collocate": null, "pronunciation": "yùn dòng huì", "ipa": "yn˥˩ tʊŋ˥˩ xweɪ̯˥˩", "syllable_count": 3, "sentences": [{"text": "学校每年秋天都举办一次运动会。", "target_word": "运动会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司下个月组织运动会，有跑步和拔河。", "target_word": "运动会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次运动会包括篮球、跳高和游泳等项目。", "target_word": "运动会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动会的报名表要在周五前交给老师。", "target_word": "运动会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们单位的运动会从周六开始，一共两天。", "target_word": "运动会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校运动会设有很多比赛项目。", "target_word": "运动会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在运动会开幕式上讲了话。", "target_word": "运动会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了准备运动会，各班都排练了入场式。", "target_word": "运动会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动会设了奖牌，前三名都能得到。", "target_word": "运动会", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这所学校的运动会有二十多个体育项目。", "target_word": "运动会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "届", "label": "量词"}, {"form": "场", "label": "量词"}], "register": "中性", "sense_fingerprint": "学校或单位组织的、设多个体育项目的比赛集会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa66c51-d2c5-4935-9b03-31cebe5b34a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90956, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "运动会", "is_correct": true, "explanation": "正确：指学校每年秋天举办的体育比赛集会，“举办”的对象是运动会。"}, {"text": "晚饭", "is_correct": false, "explanation": "搭配：“举办”后面不能接“晚饭”，“晚饭”不是可以举办的活动。"}, {"text": "奖状", "is_correct": false, "explanation": "搭配：“举办”后面不能接“奖状”，奖状是颁发的东西。"}, {"text": "春节", "is_correct": false, "explanation": "语义：“春节”是节日，不是学校在秋天组织的集会。"}], "explanations": {"运动会": "正确：指学校每年秋天举办的体育比赛集会，“举办”的对象是运动会。", "晚饭": "搭配：“举办”后面不能接“晚饭”，“晚饭”不是可以举办的活动。", "奖状": "搭配：“举办”后面不能接“奖状”，奖状是颁发的东西。", "春节": "语义：“春节”是节日，不是学校在秋天组织的集会。"}, "sentence_index": 0, "correct_answer": "运动会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天都去运动会锻炼身体。", "explanation": "这里应该用〈健身房〉。运动会是学校或单位组织的比赛集会，不是日常锻炼的场所。"}, {"text": "我们学校举办了一本运动会。", "explanation": "这里应该用〈届〉或〈次〉。运动会用“届”或“次”计数，“本”是书的量词，不能用。"}, {"text": "我们每周三都去礼堂听运动会。", "explanation": "这里应该用〈讲座〉。运动会是比赛集会，不是可以“听”的内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90956, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "运动会", "is_correct": true, "explanation": "正确：“开幕式”是运动会的环节，老师在运动会开幕式上讲话。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：“食堂”是吃饭的地方，不能举行开幕式。"}, {"text": "病房", "is_correct": false, "explanation": "语义：“病房”是住院病人的地方，不能举行开幕式。"}, {"text": "教材", "is_correct": false, "explanation": "搭配：“教材”不能用来指开幕式的场合，“开幕式”需要活动或会议作为主体。"}], "explanations": {"运动会": "正确：“开幕式”是运动会的环节，老师在运动会开幕式上讲话。", "食堂": "语义：“食堂”是吃饭的地方，不能举行开幕式。", "病房": "语义：“病房”是住院病人的地方，不能举行开幕式。", "教材": "搭配：“教材”不能用来指开幕式的场合，“开幕式”需要活动或会议作为主体。"}, "sentence_index": 6, "correct_answer": "运动会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "运动会里每天都有很多病人。", "explanation": "这里应该用〈医院〉。运动会是活动，不是每天都有病人的场所。"}, {"text": "这所学校的运动会有很多锅。", "explanation": "这里应该用〈厨房〉。运动会不是存放器具的地方，不能说“有很多锅”。"}, {"text": "运动会里的书是免费借阅的。", "explanation": "这里应该用〈图书馆〉。运动会不是藏书的地方，不能说“里的书是免费借阅的”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90956, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校下个月要办一位运动会。", "corrected_sentence": "学校下个月要办一届运动会。", "error_description": "错误：“运动会”的量词应用“届”或“场”，“位”只用于人，不能说“一位运动会”。正确形式是“一届运动会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90956, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学校在一位运动会上发了奖牌。", "corrected_sentence": "学校在一届运动会上发了奖牌。", "error_description": "错误：“运动会”的量词应用“届”或“场”，“位”只用于人，不能说“一位运动会”。正确形式是“在一届运动会上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
