INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90957, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "做东西来卖的工厂或公司。", "primary_collocate": null, "pronunciation": "chǎng shāng", "ipa": "tʂʰɑŋ²¹⁴ ʂɑŋ⁵⁵", "syllable_count": 2, "sentences": [{"text": "买家电的时候，我会先看厂商的名字。", "target_word": "厂商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厂商说，新产品下个月就能买到。", "target_word": "厂商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家厂商做的鞋子又好看又便宜。", "target_word": "厂商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有些厂商为了赚钱，用很差的材料。", "target_word": "厂商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机厂商每年都会开发布会。", "target_word": "厂商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给厂商打电话，问什么时候能修好。", "target_word": "厂商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在一家饮料厂商工作。", "target_word": "厂商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的厂商会认真听客人的意见。", "target_word": "厂商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厂商把东西送到商店，我们就可以买了。", "target_word": "厂商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个厂商做的牛奶很安全。", "target_word": "厂商", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "手机厂商", "label": "复合"}, {"form": "饮料厂商", "label": "复合"}], "register": "中性", "sense_fingerprint": "厂商：做东西来卖的工厂或公司", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d0a3031-66ae-43d8-9fb5-fe85694236c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90957, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厂商", "is_correct": true, "explanation": "厂商：做东西来卖的工厂或公司，有名字可以看，符合句意。"}, {"text": "歌", "is_correct": false, "explanation": "语义：买家电时看的是生产家电的单位，歌不是卖家电的，句意不通。"}, {"text": "云", "is_correct": false, "explanation": "语义：云没有可以“看名字”的生产者，与买家电的语境不符。"}, {"text": "学生", "is_correct": false, "explanation": "配价：“看……的名字”的对象应是卖家电的单位，学生不符合。"}], "explanations": {"厂商": "厂商：做东西来卖的工厂或公司，有名字可以看，符合句意。", "歌": "语义：买家电时看的是生产家电的单位，歌不是卖家电的，句意不通。", "云": "语义：云没有可以“看名字”的生产者，与买家电的语境不符。", "学生": "配价：“看……的名字”的对象应是卖家电的单位，学生不符合。"}, "sentence_index": 0, "correct_answer": "厂商"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天去厂商买菜。", "explanation": "这里应该用〈菜市场〉。厂商指做东西来卖的工厂或公司，不是买菜的地方。"}, {"text": "妹妹生病了，我们去厂商看病。", "explanation": "这里应该用〈医院〉。厂商指做东西来卖的工厂或公司，不是看病的地方。"}, {"text": "他每天用厂商写作业。", "explanation": "这里应该用〈电脑〉。厂商指做东西来卖的工厂或公司，不能当作写作业的工具。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90957, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厂商", "is_correct": true, "explanation": "厂商：做东西来卖的公司，“饮料厂商”指生产饮料的企业，符合句意。"}, {"text": "学校", "is_correct": false, "explanation": "语义：“饮料”修饰的应是生产饮料的企业，学校不生产饮料，“饮料学校”搭配不通。"}, {"text": "医院", "is_correct": false, "explanation": "语义：“饮料医院”与饮料生产无关，句意不通。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：“饮料”只能修饰生产饮料的企业，不能修饰花园。"}], "explanations": {"厂商": "厂商：做东西来卖的公司，“饮料厂商”指生产饮料的企业，符合句意。", "学校": "语义：“饮料”修饰的应是生产饮料的企业，学校不生产饮料，“饮料学校”搭配不通。", "医院": "语义：“饮料医院”与饮料生产无关，句意不通。", "花园": "搭配：“饮料”只能修饰生产饮料的企业，不能修饰花园。"}, "sentence_index": 6, "correct_answer": "厂商"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我和朋友去厂商看电影。", "explanation": "这里应该用〈电影院〉。厂商指做东西来卖的工厂或公司，不是看电影的地方。"}, {"text": "厂商每天给病人打针。", "explanation": "这里应该用〈护士〉。厂商指做东西来卖的工厂或公司，不能指打针的人。"}, {"text": "我周末去厂商游泳。", "explanation": "这里应该用〈游泳池〉。厂商指做东西来卖的工厂或公司，不是游泳的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90957, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只厂商做的鞋子又好看又结实。", "corrected_sentence": "这家厂商做的鞋子又好看又结实。", "error_description": "量词错误：“厂商”是公司，量词应用“家”，不能用“只”，应说“这家厂商”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90957, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "厂商的把东西送到店里，我们就可以买了。", "corrected_sentence": "厂商把东西送到店里，我们就可以买了。", "error_description": "结构错误：“厂商”作主语时后面不加“的”，应说“厂商把东西送到店里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
