INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90958, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "生产并销售商品的工厂或企业。", "primary_collocate": null, "pronunciation": "chǎng shāng", "ipa": "tʂʰɑŋ²¹⁴ ʂɑŋ⁵⁵", "syllable_count": 2, "sentences": [{"text": "这家厂商生产的手机很受欢迎。", "target_word": "厂商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多厂商都想把产品卖到国外。", "target_word": "厂商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厂商要对自己生产的东西负责。", "target_word": "厂商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "如果产品有问题，请你联系厂商。", "target_word": "厂商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "汽车厂商今年推出了三种新车。", "target_word": "厂商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这几家厂商的价格差不多。", "target_word": "厂商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厂商给我们送来了一批新电脑。", "target_word": "厂商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了卖得更多，厂商常常打折。", "target_word": "厂商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个厂商只做儿童玩具。", "target_word": "厂商", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经销商从厂商那里买东西，再卖给商店。", "target_word": "厂商", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "手机厂商", "label": "复合"}, {"form": "汽车厂商", "label": "复合"}], "register": "中性", "sense_fingerprint": "厂商：生产并销售商品的工厂或企业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d0a3031-66ae-43d8-9fb5-fe85694236c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90958, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厂商", "is_correct": true, "explanation": "厂商：生产并销售商品的工厂或企业，符合“生产的手机”的句意。"}, {"text": "农场", "is_correct": false, "explanation": "语义：农场不生产手机，句中说的是生产手机的企业。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校不生产手机，与“生产的手机”矛盾。"}, {"text": "餐厅", "is_correct": false, "explanation": "搭配：“生产”的主体是工厂或企业，不能用于餐厅。"}], "explanations": {"厂商": "厂商：生产并销售商品的工厂或企业，符合“生产的手机”的句意。", "农场": "语义：农场不生产手机，句中说的是生产手机的企业。", "学校": "语义：学校不生产手机，与“生产的手机”矛盾。", "餐厅": "搭配：“生产”的主体是工厂或企业，不能用于餐厅。"}, "sentence_index": 0, "correct_answer": "厂商"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天去厂商理发。", "explanation": "这里应该用〈理发店〉。厂商指生产或销售商品的工厂或企业，不是理发的地方。"}, {"text": "我每天在厂商上课。", "explanation": "这里应该用〈学校〉。厂商指生产或销售商品的工厂或企业，不是上课的地方。"}, {"text": "我每天打开厂商看新闻。", "explanation": "这里应该用〈电视〉。厂商指生产或销售商品的工厂或企业，不能打开来看新闻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90958, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "厂商", "is_correct": true, "explanation": "厂商：能够生产并供应商品的企业，可以给我们送来电脑。"}, {"text": "月亮", "is_correct": false, "explanation": "语义：月亮不能给人送来电脑，句意荒谬。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会送东西，与“给我们送来”矛盾。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：“送来一批新电脑”需要能供货的单位，花园不能供货。"}], "explanations": {"厂商": "厂商：能够生产并供应商品的企业，可以给我们送来电脑。", "月亮": "语义：月亮不能给人送来电脑，句意荒谬。", "石头": "语义：石头不会送东西，与“给我们送来”矛盾。", "花园": "搭配：“送来一批新电脑”需要能供货的单位，花园不能供货。"}, "sentence_index": 6, "correct_answer": "厂商"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我周末去厂商散步。", "explanation": "这里应该用〈公园〉。厂商指生产或销售商品的工厂或企业，不是散步的地方。"}, {"text": "厂商每天给我们讲课。", "explanation": "这里应该用〈老师〉。厂商指生产或销售商品的工厂或企业，不能指讲课的人。"}, {"text": "我经常去厂商看书。", "explanation": "这里应该用〈图书馆〉。厂商指生产或销售商品的工厂或企业，不是看书的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90958, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本厂商生产的手机质量很好。", "corrected_sentence": "这家厂商生产的手机质量很好。", "error_description": "量词错误：“厂商”作为公司或企业应用量词“家”，不能用“本”，应说“这家厂商”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90958, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家厂商的给我们送来了一批新电脑。", "corrected_sentence": "这家厂商给我们送来了一批新电脑。", "error_description": "结构错误：“厂商”作主语后面不能加“的”，应说“这家厂商给我们送来”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
