INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90959, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "道具是演戏时手里拿的东西，像假的刀和帽子。", "primary_collocate": null, "pronunciation": "dào jù", "ipa": "taʊ̯˥˩ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "演员手里的道具刀是假的，不会伤人。", "target_word": "道具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他演海盗，头上戴着一顶道具帽子。", "target_word": "道具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员拿着道具枪，在台上大声说话。", "target_word": "道具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这把道具剑看起来很真，其实很轻。", "target_word": "道具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演出前，他把道具放在桌子上了。", "target_word": "道具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员忘了拿道具，只好空着手上台。", "target_word": "道具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师用一把道具伞，演下雨天的戏。", "target_word": "道具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个道具杯子是纸做的，不能喝水。", "target_word": "道具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明在话剧里拿着一个道具包。", "target_word": "道具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演员手里的道具很小，观众看不清。", "target_word": "道具", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "件", "label": "量词"}, {"form": "道具师", "label": "复合"}], "register": "中性", "sense_fingerprint": "演员在台上手里拿的或身上戴的假东西，如假刀、假帽子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa66c51-d2c5-4935-9b03-31cebe5b34a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90959, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "道具", "is_correct": true, "explanation": "正确答案。道具指演戏时用的假器物，“道具刀”是假的，不会伤人。"}, {"text": "电话", "is_correct": false, "explanation": "语义：电话不是刀具，“电话刀”说不通。"}, {"text": "树叶", "is_correct": false, "explanation": "语义：树叶不是刀具，“树叶刀”不成立。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不是刀具，“椅子刀”说不通。"}], "explanations": {"道具": "正确答案。道具指演戏时用的假器物，“道具刀”是假的，不会伤人。", "电话": "语义：电话不是刀具，“电话刀”说不通。", "树叶": "语义：树叶不是刀具，“树叶刀”不成立。", "椅子": "语义：椅子不是刀具，“椅子刀”说不通。"}, "sentence_index": 0, "correct_answer": "道具"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子们抱着道具睡觉了。", "explanation": "这里应该用〈玩具〉。道具是演出时用的东西，不是给孩子玩的，不能说“抱着道具睡觉”。"}, {"text": "木匠用道具修好了椅子。", "explanation": "这里应该用〈工具〉。道具只用于戏剧、电影，修椅子要用工具。"}, {"text": "我用道具吃饭。", "explanation": "这里应该用〈餐具〉。道具不是吃饭用的器具，不能说“用道具吃饭”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90959, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "道具", "is_correct": true, "explanation": "正确答案。道具是演戏用的物件，“道具伞”用于下雨天的戏，正合句意。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑不是伞，“电脑伞”说不通，也与演下雨天的戏无关。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干不是伞，“饼干伞”不成立。"}, {"text": "教室", "is_correct": false, "explanation": "搭配：“一把”用于有柄的物件，不能修饰“教室”。"}], "explanations": {"道具": "正确答案。道具是演戏用的物件，“道具伞”用于下雨天的戏，正合句意。", "电脑": "语义：电脑不是伞，“电脑伞”说不通，也与演下雨天的戏无关。", "饼干": "语义：饼干不是伞，“饼干伞”不成立。", "教室": "搭配：“一把”用于有柄的物件，不能修饰“教室”。"}, "sentence_index": 6, "correct_answer": "道具"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一辆道具。", "explanation": "这里应该用〈件〉。“辆”用于车，道具要用“件”。"}, {"text": "他借了一头道具。", "explanation": "这里应该用〈件〉。“头”用于牛、猪等大牲畜，道具要用“件”。"}, {"text": "舞台上放着一条道具。", "explanation": "这里应该用〈件〉。“条”用于细长的东西，道具要用“件”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90959, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "演员手里拿着一条道具刀，在台上大声说话。", "corrected_sentence": "演员手里拿着一把道具刀，在台上大声说话。", "error_description": "量词错误：刀的量词是“把”，不能说“一条道具刀”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90959, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "演员把一艘道具搬上了台。", "corrected_sentence": "演员把一件道具搬上了台。", "error_description": "量词错误：“艘”用于船只，道具的量词是“件”，不能说“一艘道具”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
