INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90960, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "戏剧、电影演出中所用的各种器物的统称。", "primary_collocate": null, "pronunciation": "dào jù", "ipa": "taʊ̯˥˩ tɕy˥˩", "syllable_count": 2, "sentences": [{"text": "这部电影的道具都是工作人员做的。", "target_word": "道具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "剧组买了很多新道具，准备拍戏。", "target_word": "道具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "舞台上的道具要在演出前摆好。", "target_word": "道具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在剧院工作，负责管理所有道具。", "target_word": "道具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里的古代道具，看起来很真。", "target_word": "道具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个剧团的道具放在后台的大箱子里。", "target_word": "道具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "拍这场戏要用很多道具，比如桌椅和灯。", "target_word": "道具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "导演说这件道具太新，不像古代的东西。", "target_word": "道具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影结束后，工作人员收好了所有道具。", "target_word": "道具", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校话剧社要自己做演出用的道具。", "target_word": "道具", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "件", "label": "量词"}, {"form": "道具师", "label": "复合"}], "register": "中性", "sense_fingerprint": "戏剧、电影演出所用各种器物的统称，由剧组准备、管理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa66c51-d2c5-4935-9b03-31cebe5b34a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90960, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "道具", "is_correct": true, "explanation": "正确答案。道具是电影里用的器物，由工作人员做，句子说的正是它。"}, {"text": "演员", "is_correct": false, "explanation": "语义：演员是人，不是工作人员“做”出来的东西。"}, {"text": "观众", "is_correct": false, "explanation": "语义：观众是看电影的人，不是可以被做出来的东西。"}, {"text": "观点", "is_correct": false, "explanation": "搭配：“做”与“观点”不搭配，观点应说“提出”或“有”。"}], "explanations": {"道具": "正确答案。道具是电影里用的器物，由工作人员做，句子说的正是它。", "演员": "语义：演员是人，不是工作人员“做”出来的东西。", "观众": "语义：观众是看电影的人，不是可以被做出来的东西。", "观点": "搭配：“做”与“观点”不搭配，观点应说“提出”或“有”。"}, "sentence_index": 0, "correct_answer": "道具"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用道具修好了灯。", "explanation": "这里应该用〈工具〉。道具只用于戏剧、电影，修灯要用工具。"}, {"text": "小狗在地上玩道具。", "explanation": "这里应该用〈玩具〉。道具是演出用的器物，不是给小狗玩的。"}, {"text": "饭馆的道具都洗干净了。", "explanation": "这里应该用〈餐具〉。道具不是吃饭用的器具，不能说“饭馆的道具”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90960, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "道具", "is_correct": true, "explanation": "正确答案。拍戏要用的道具可以包括桌椅和灯，句子说的正是它。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生是人，不是拍戏要用的器物，与“比如桌椅和灯”不符。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料不是拍戏用的器物，与“比如桌椅和灯”不符。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“要用很多”的宾语应是具体的物件，“感情”不能这样使用。"}], "explanations": {"道具": "正确答案。拍戏要用的道具可以包括桌椅和灯，句子说的正是它。", "学生": "语义：学生是人，不是拍戏要用的器物，与“比如桌椅和灯”不符。", "饮料": "语义：饮料不是拍戏用的器物，与“比如桌椅和灯”不符。", "感情": "搭配：“要用很多”的宾语应是具体的物件，“感情”不能这样使用。"}, "sentence_index": 6, "correct_answer": "道具"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "舞台上搬来了一艘道具。", "explanation": "这里应该用〈件〉。“艘”用于船只，道具要用“件”。"}, {"text": "我们借了一封道具。", "explanation": "这里应该用〈件〉。“封”用于信件，道具要用“件”。"}, {"text": "导演挑了一首道具。", "explanation": "这里应该用〈件〉。“首”用于诗歌、歌曲，道具要用“件”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90960, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工作人员把一本道具搬进了后台。", "corrected_sentence": "工作人员把一件道具搬进了后台。", "error_description": "量词错误：“本”用于书册，道具的量词是“件”，不能说“一本道具”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90960, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "剧组新买了一辆道具。", "corrected_sentence": "剧组新买了一套道具。", "error_description": "量词错误：“辆”用于车辆，道具应说“套”或“件”，不能说“一辆道具”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
