INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90964, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "不再使用或失去作用；废弃，废除。", "primary_collocate": null, "pronunciation": "fèi", "ipa": "fei˥˩", "syllable_count": 1, "sentences": [{"text": "这条旧规定早就废了，没人再用。", "target_word": "废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校把这个老办法废了。", "target_word": "废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个旧制度已经不合适，该废了。", "target_word": "废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司把那条不合理的规矩废掉了。", "target_word": "废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个旧的审批流程早就废了，现在大家都不用了。", "target_word": "废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王下令废掉了这条老法律。", "target_word": "废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个旧方法不好用，大家都说该废了。", "target_word": "废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条旧的收费标准太不合理，已经废了很多年。", "target_word": "废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划没有用，经理决定废掉它。", "target_word": "废", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧的考试办法废了以后，学生轻松多了。", "target_word": "废", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "废了", "label": "体标"}, {"form": "废除", "label": "复合"}, {"form": "废弃", "label": "复合"}, {"form": "廢", "label": "繁体"}], "register": "中性", "sense_fingerprint": "废：规定、制度、办法等不再使用，被废除或废弃", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d4986a0-230f-4048-a49e-666580b97150') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90964, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "废", "is_correct": true, "explanation": "正确。废指规定、制度等不再使用，被废除。"}, {"text": "非", "is_correct": false, "explanation": "fēi（第一声）与 fèi（第四声）声调不同，意思是不是、非。"}, {"text": "肥", "is_correct": false, "explanation": "féi（第二声）与 fèi（第四声）声调不同，意思是肥胖、肥料。"}, {"text": "佩", "is_correct": false, "explanation": "pèi 与 fèi 声母不同（p/f），意思是佩带。"}, {"text": "份", "is_correct": false, "explanation": "fèn 与 fèi 韵母不同（n/i），意思是份额、一份。"}], "explanations": {"废": "正确。废指规定、制度等不再使用，被废除。", "非": "fēi（第一声）与 fèi（第四声）声调不同，意思是不是、非。", "肥": "féi（第二声）与 fèi（第四声）声调不同，意思是肥胖、肥料。", "佩": "pèi 与 fèi 声母不同（p/f），意思是佩带。", "份": "fèn 与 fèi 韵母不同（n/i），意思是份额、一份。"}, "sentence_index": null, "correct_answer": "废"}, "level_3": {"options": [{"text": "废", "is_correct": true, "explanation": "正确。“早就废了”表示规定已经被取消，没人再用。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”不能用于规定，“早就吃了”句意不通。"}, {"text": "买", "is_correct": false, "explanation": "语义：规定不能购买，“买了”在这里句意不通。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”需要接受者（送给某人），单说“早就送了”不完整，句意不通。"}], "explanations": {"废": "正确。“早就废了”表示规定已经被取消，没人再用。", "吃": "语义：“吃”不能用于规定，“早就吃了”句意不通。", "买": "语义：规定不能购买，“买了”在这里句意不通。", "送": "配价：“送”需要接受者（送给某人），单说“早就送了”不完整，句意不通。"}, "sentence_index": 0, "correct_answer": "废"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们每天都废这台电脑。", "explanation": "这里应该用〈用〉。废表示不再使用或失去作用，不能说每天都在废掉仍然使用的电脑。"}, {"text": "他把一整天都废在了游戏里。", "explanation": "这里的〈废〉指荒废、白白耗费时间，与本句需要的“不再使用、废除”的义项不同。"}, {"text": "这片森林是我们的骄傲，我们要废它。", "explanation": "这里应该用〈保护〉。废表示不再使用、废弃，与“是我们的骄傲”、需要保护的意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ea2e41-fe4c-4e22-b114-3834ebfb0285') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90964, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "废", "is_correct": true, "explanation": "正确。废指规定、制度等不再使用，被废除。"}, {"text": "飞", "is_correct": false, "explanation": "fēi（第一声）与 fèi（第四声）声调不同，意思是飞。"}, {"text": "匪", "is_correct": false, "explanation": "fěi（第三声）与 fèi（第四声）声调不同，意思是土匪。"}, {"text": "配", "is_correct": false, "explanation": "pèi 与 fèi 声母不同（p/f），意思是配合、搭配。"}, {"text": "奋", "is_correct": false, "explanation": "fèn 与 fèi 韵母不同（n/i），意思是奋力、奋斗。"}], "explanations": {"废": "正确。废指规定、制度等不再使用，被废除。", "飞": "fēi（第一声）与 fèi（第四声）声调不同，意思是飞。", "匪": "fěi（第三声）与 fèi（第四声）声调不同，意思是土匪。", "配": "pèi 与 fèi 声母不同（p/f），意思是配合、搭配。", "奋": "fèn 与 fèi 韵母不同（n/i），意思是奋力、奋斗。"}, "sentence_index": null, "correct_answer": "废"}, "level_3": {"options": [{"text": "废", "is_correct": true, "explanation": "正确。“大家都说该废了”表示这个方法应被取消。"}, {"text": "洗", "is_correct": false, "explanation": "语义：“洗”不能用于方法，“该洗了”与“不好用”的语境不合。"}, {"text": "穿", "is_correct": false, "explanation": "搭配：“穿”的对象是衣物等，不说“穿方法”。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”与方法无关，“该唱了”与“不好用”的语境不合，句意不通。"}], "explanations": {"废": "正确。“大家都说该废了”表示这个方法应被取消。", "洗": "语义：“洗”不能用于方法，“该洗了”与“不好用”的语境不合。", "穿": "搭配：“穿”的对象是衣物等，不说“穿方法”。", "唱": "语义：“唱”与方法无关，“该唱了”与“不好用”的语境不合，句意不通。"}, "sentence_index": 6, "correct_answer": "废"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些老照片很珍贵，我想废了它们。", "explanation": "这里应该用〈收藏〉。废表示不再使用、废弃，与“很珍贵、想留着”的意思相反。"}, {"text": "这台旧收音机坏了，我找人废好了它。", "explanation": "这里应该用〈修〉。废表示不再使用、废除，不能说把东西“废好”让它恢复使用。"}, {"text": "学校把图书馆废到了新楼。", "explanation": "这里应该用〈搬〉。废表示不再使用、废除，不能表示把东西搬到某处。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ea2e41-fe4c-4e22-b114-3834ebfb0285') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90964, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这项规定太旧了，政府已经它把废了。", "corrected_sentence": "这项规定太旧了，政府已经把它废了。", "error_description": "“把”字句的“把”应放在处置对象之前，应说“已经把它废了”，不能说“已经它把废了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ea2e41-fe4c-4e22-b114-3834ebfb0285') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90964, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个老办法太落后了，我们决定把它了废。", "corrected_sentence": "这个老办法太落后了，我们决定把它废了。", "error_description": "“了”应放在动词“废”之后，应说“废了”，“了废”的语序不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ea2e41-fe4c-4e22-b114-3834ebfb0285') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
