INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90967, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "怀孕是妈妈的肚子里有了小宝宝。", "primary_collocate": null, "pronunciation": "huái yùn", "ipa": "xwai̯˧˥ yn˥˩", "syllable_count": 2, "sentences": [{"text": "我姐姐怀孕了，家里人都很高兴。", "target_word": "怀孕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她怀孕五个月了，肚子越来越大。", "target_word": "怀孕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈怀孕的时候，不能喝酒。", "target_word": "怀孕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说你太太怀孕了，恭喜你们！", "target_word": "怀孕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说她已经怀孕两个月了。", "target_word": "怀孕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "怀孕以后，她不再穿高跟鞋了。", "target_word": "怀孕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她怀孕了，所以每天都早点睡觉。", "target_word": "怀孕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹刚结婚就怀孕了，全家都很开心。", "target_word": "怀孕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "怀孕的妈妈要多吃水果和蔬菜。", "target_word": "怀孕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我怀孕那年，丈夫天天陪我散步。", "target_word": "怀孕", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "怀孕了", "label": "体标（了）"}, {"form": "怀过孕", "label": "体标（过）"}, {"form": "懷孕", "label": "繁体"}], "register": "中性", "sense_fingerprint": "女人肚子里有了小宝宝", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940b2af-c4cb-48b8-9d0b-57e75b82fbed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90967, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "怀孕", "is_correct": true, "explanation": "正确：“怀孕”指女性肚子里有了胎儿，与“家里人都很高兴”相符。"}, {"text": "生病", "is_correct": false, "explanation": "语义：“生病”是身体不适，与“家里人都很高兴”相矛盾。"}, {"text": "失业", "is_correct": false, "explanation": "语义：“失业”是不利的事情，与“家里人都很高兴”相矛盾。"}, {"text": "感冒", "is_correct": false, "explanation": "语义：“感冒”是生病，与“家里人都很高兴”相矛盾。"}], "explanations": {"怀孕": "正确：“怀孕”指女性肚子里有了胎儿，与“家里人都很高兴”相符。", "生病": "语义：“生病”是身体不适，与“家里人都很高兴”相矛盾。", "失业": "语义：“失业”是不利的事情，与“家里人都很高兴”相矛盾。", "感冒": "语义：“感冒”是生病，与“家里人都很高兴”相矛盾。"}, "sentence_index": 0, "correct_answer": "怀孕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位母亲在产房里怀孕了，婴儿哭声很响。", "explanation": "这里应该用〈生〉。怀孕指胎儿还在肚子里，在产房里发生的是分娩，要用“生”。"}, {"text": "我爸爸去年怀孕了，全家都很高兴。", "explanation": "这里误用了〈怀孕〉：它指女性体内有胎儿，男性没有这种情况，不能用于“爸爸”。"}, {"text": "小宝宝昨天怀孕了，医生说他很健康。", "explanation": "这里应该用〈出生〉。怀孕的主语必须是能怀胎的女性或雌性动物，已经出生的宝宝不能“怀孕”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90967, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "怀孕", "is_correct": true, "explanation": "正确：“怀孕”与“所以每天都早点睡觉”之间的因果关系合理。"}, {"text": "熬夜", "is_correct": false, "explanation": "语义：“熬夜”是晚睡，与“每天都早点睡觉”相矛盾。"}, {"text": "加班", "is_correct": false, "explanation": "语义：“加班”是工作到很晚，与“每天都早点睡觉”相矛盾。"}, {"text": "上夜班", "is_correct": false, "explanation": "语义：“上夜班”与“每天都早点睡觉”相矛盾。"}], "explanations": {"怀孕": "正确：“怀孕”与“所以每天都早点睡觉”之间的因果关系合理。", "熬夜": "语义：“熬夜”是晚睡，与“每天都早点睡觉”相矛盾。", "加班": "语义：“加班”是工作到很晚，与“每天都早点睡觉”相矛盾。", "上夜班": "语义：“上夜班”与“每天都早点睡觉”相矛盾。"}, "sentence_index": 6, "correct_answer": "怀孕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她每天都怀孕，所以很累。", "explanation": "这里误用了〈怀孕〉的时间义：它指已经处于妊娠状态，不是每天重复发生的动作，不能和“每天都”搭配。"}, {"text": "他昨天怀孕了，今天好多了。", "explanation": "这里误用了〈怀孕〉：它只指女性体内有胎儿，男性不能怀孕。"}, {"text": "这块石头怀孕了，形状很奇怪。", "explanation": "这里误用了〈怀孕〉：它只指有生命的雌性体内有胎儿，石头没有这种情况。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90967, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她怀孕了宝宝，我们都很开心。", "corrected_sentence": "她怀孕了，我们都很开心。", "error_description": "错误：“怀孕”是不及物动词，后面不能直接带宾语“宝宝”。正确：去掉“宝宝”，说“她怀孕了”；如果要说明胎儿，可以说“怀上宝宝”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90967, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她两年多前被怀孕了，现在孩子已经两岁了。", "corrected_sentence": "她两年多前怀孕了，现在孩子已经两岁了。", "error_description": "错误：“怀孕”是不及物动词，不能用“被”字句表示被动。正确：去掉“被”，说“她两年多前怀孕了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
