INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90968, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90968, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "女子或雌性动物体内有了胎儿。", "primary_collocate": null, "pronunciation": "huái yùn", "ipa": "xwai̯˧˥ yn˥˩", "syllable_count": 2, "sentences": [{"text": "这只母猫怀孕了，肚子鼓鼓的。", "target_word": "怀孕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母牛怀孕要九个月左右。", "target_word": "怀孕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生检查后，说她确实怀孕了。", "target_word": "怀孕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兔子怀孕以后，会自己做窝。", "target_word": "怀孕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她怀孕时身体不舒服，常常想吐。", "target_word": "怀孕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农场里的母羊怀孕了，要小心照顾。", "target_word": "怀孕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们结婚三年，妻子终于怀孕了。", "target_word": "怀孕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "母狗怀孕的时候，不要让它跑太多。", "target_word": "怀孕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "怀孕期间，女人需要多休息。", "target_word": "怀孕", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怀孕了吗？别搬这么重的东西。", "target_word": "怀孕", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "怀孕了", "label": "体标（了）"}, {"form": "怀过孕", "label": "体标（过）"}, {"form": "懷孕", "label": "繁体"}], "register": "中性", "sense_fingerprint": "女子或雌性动物体内有了胎儿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940b2af-c4cb-48b8-9d0b-57e75b82fbed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90968, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "怀孕", "is_correct": true, "explanation": "正确：“怀孕”指雌性动物体内有了胎儿，与“肚子鼓鼓的”相符。"}, {"text": "消瘦", "is_correct": false, "explanation": "语义：“消瘦”是身体变瘦，与“肚子鼓鼓的”相矛盾。"}, {"text": "下蛋", "is_correct": false, "explanation": "搭配：“下蛋”只用于禽类，不能用于猫。"}, {"text": "出生", "is_correct": false, "explanation": "语义：“出生”指刚来到世界，与这只母猫肚子鼓起的状况不符。"}], "explanations": {"怀孕": "正确：“怀孕”指雌性动物体内有了胎儿，与“肚子鼓鼓的”相符。", "消瘦": "语义：“消瘦”是身体变瘦，与“肚子鼓鼓的”相矛盾。", "下蛋": "搭配：“下蛋”只用于禽类，不能用于猫。", "出生": "语义：“出生”指刚来到世界，与这只母猫肚子鼓起的状况不符。"}, "sentence_index": 0, "correct_answer": "怀孕"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "母羊昨天怀孕了，三只小羊都很健康。", "explanation": "这里应该用〈生〉。怀孕指胎儿还在母体内，“三只小羊都很健康”说明已经出生，要用“生”。"}, {"text": "公猫怀孕了，肚子鼓鼓的。", "explanation": "这里误用了〈怀孕〉：它只指雌性体内有胎儿，公猫没有这种情况。"}, {"text": "这台电脑怀孕了，所以开始发热。", "explanation": "这里误用了〈怀孕〉：它只指雌性生物体内有胎儿，电脑这类物品不能怀孕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90968, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "怀孕", "is_correct": true, "explanation": "正确：“怀孕”与“他们结婚三年”之后的变化相符。"}, {"text": "结婚", "is_correct": false, "explanation": "语义：他们已经结婚三年，不能说“终于结婚了”。"}, {"text": "下雨", "is_correct": false, "explanation": "语义：“下雨”是天气现象，主语不能是“妻子”，句子不通。"}, {"text": "打", "is_correct": false, "explanation": "配价：“打”需要宾语，“妻子终于打了”不完整。"}], "explanations": {"怀孕": "正确：“怀孕”与“他们结婚三年”之后的变化相符。", "结婚": "语义：他们已经结婚三年，不能说“终于结婚了”。", "下雨": "语义：“下雨”是天气现象，主语不能是“妻子”，句子不通。", "打": "配价：“打”需要宾语，“妻子终于打了”不完整。"}, "sentence_index": 6, "correct_answer": "怀孕"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这只母猫每天都怀孕，真让人担心。", "explanation": "这里误用了〈怀孕〉的时间义：它指已经处于妊娠状态，不是每天重复发生的动作，不能和“每天都”搭配。"}, {"text": "这只猫上周怀孕，现在已经痊愈了。", "explanation": "这里应该用〈生病〉。怀孕不会“痊愈”，“痊愈”说的是病好了，要用疾病词。"}, {"text": "这只小猫刚出生，就已经怀孕了。", "explanation": "这里误用了〈怀孕〉：它只指成年雌性体内有胎儿，刚出生的小猫不能怀孕。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90968, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只母狗被怀孕了，主人很担心。", "corrected_sentence": "那只母狗怀孕了，主人很担心。", "error_description": "错误：“怀孕”是不及物动词，不能用“被”构成被动句。正确：直接说“那只母狗怀孕了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90968, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只母猫很怀孕以后，食量变大了。", "corrected_sentence": "这只母猫怀孕以后，食量变大了。", "error_description": "错误：“怀孕”是动词，前面不能加程度副词“很”。正确：去掉“很”，说“怀孕以后”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
