INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90969, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这次考试你拿了第一，恭喜的你！", "corrected_sentence": "这次考试你拿了第一，恭喜你！", "error_description": "“恭喜”是动词，后面直接接宾语“你”，中间不能插入“的”，应说“恭喜你！”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ea2e41-fe4c-4e22-b114-3834ebfb0285') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90969, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你们结婚了，我真心地把恭喜你们。", "corrected_sentence": "你们结婚了，我真心地恭喜你们。", "error_description": "“恭喜”是动词，其宾语应直接放在动词后，前面不能加“把”字。应说“恭喜你们”，“把恭喜你们”不成立。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ea2e41-fe4c-4e22-b114-3834ebfb0285') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
