INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90971, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "酒精是一种无色、看起来像水的液体，能杀死细菌，也能让人喝醉。", "primary_collocate": null, "pronunciation": "jiǔ jīng", "ipa": "tɕiou̯˨˩˦ tɕiŋ˥", "syllable_count": 2, "sentences": [{"text": "酒精是没有颜色的，看起来像水。", "target_word": "酒精", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "酒精能杀死很多细菌。", "target_word": "酒精", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他喝了太多酒，酒精已经让他醉了。", "target_word": "酒精", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "酒精让他说话越来越大声。", "target_word": "酒精", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "酒精进到身体里，人就会喝醉。", "target_word": "酒精", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这种酒的酒精含量很高，我一喝就醉了。", "target_word": "酒精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "酒精让他的脸变得红红的。", "target_word": "酒精", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用酒精擦一擦手，手上的细菌就少了。", "target_word": "酒精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸喝了酒，满身都是酒精的味道。", "target_word": "酒精", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "酒精很容易变成气体，所以要盖好瓶子。", "target_word": "酒精", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "瓶", "label": "量词"}, {"form": "酒精灯", "label": "复合"}, {"form": "酒精度", "label": "复合"}], "register": "中性", "sense_fingerprint": "无色像水的液体，能消毒杀菌，让人喝醉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eec25974-71fd-4a3e-aa7f-4714ae3f80b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90971, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "酒精", "is_correct": true, "explanation": "酒精（jiǔ jīng）：无色、像水的液体，能杀虫，也能让人喝醉，是本条的目标词。"}, {"text": "救星", "is_correct": false, "explanation": "救星（jiù xīng）：jiù 与 jiǔ 声调不同（第四声），xīng 与 jīng 声母不同（x 与 j），意思是救命的人或事物。"}, {"text": "九斤", "is_correct": false, "explanation": "九斤（jiǔ jīn）：jīn 与 jīng 韵尾不同（in 与 ing），意思是九斤重的分量。"}, {"text": "旧情", "is_correct": false, "explanation": "旧情（jiù qíng）：jiù 声调不同（第四声），qíng 与 jīng 声母不同（q 与 j），意思是过去的感情。"}, {"text": "酒劲", "is_correct": false, "explanation": "酒劲（jiǔ jìn）：jìn 与 jīng 韵尾不同（n 与 ng），声调也不同（第四声），意思是酒的醉人作用。"}], "explanations": {"酒精": "酒精（jiǔ jīng）：无色、像水的液体，能杀虫，也能让人喝醉，是本条的目标词。", "救星": "救星（jiù xīng）：jiù 与 jiǔ 声调不同（第四声），xīng 与 jīng 声母不同（x 与 j），意思是救命的人或事物。", "九斤": "九斤（jiǔ jīn）：jīn 与 jīng 韵尾不同（in 与 ing），意思是九斤重的分量。", "旧情": "旧情（jiù qíng）：jiù 声调不同（第四声），qíng 与 jīng 声母不同（q 与 j），意思是过去的感情。", "酒劲": "酒劲（jiǔ jìn）：jìn 与 jīng 韵尾不同（n 与 ng），声调也不同（第四声），意思是酒的醉人作用。"}, "sentence_index": null, "correct_answer": "酒精"}, "level_3": {"options": [{"text": "酒精", "is_correct": true, "explanation": "酒精无色、看起来像水，符合“没有颜色，看起来像水”的描述。"}, {"text": "牛奶", "is_correct": false, "explanation": "体貌：牛奶是白色的，不是没有颜色的。"}, {"text": "墨水", "is_correct": false, "explanation": "体貌：墨水是有颜色的，不符合“没有颜色”。"}, {"text": "石油", "is_correct": false, "explanation": "语义：石油通常是深色的油，不是无色的液体，看起来不像水。"}], "explanations": {"酒精": "酒精无色、看起来像水，符合“没有颜色，看起来像水”的描述。", "牛奶": "体貌：牛奶是白色的，不是没有颜色的。", "墨水": "体貌：墨水是有颜色的，不符合“没有颜色”。", "石油": "语义：石油通常是深色的油，不是无色的液体，看起来不像水。"}, "sentence_index": 0, "correct_answer": "酒精"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈用酒精给孩子洗澡。", "explanation": "这里应该用〈沐浴露〉。给孩子洗澡要用沐浴露，酒精刺激皮肤，不能用来洗澡。"}, {"text": "我买了一条酒精。", "explanation": "这里应该用〈瓶〉。“条”用于细长的东西，液体酒精要用“瓶”计量。"}, {"text": "我买了一只酒精。", "explanation": "这里应该用〈瓶〉。液体不能用“只”计量，应说“一瓶酒精”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90971, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "酒精", "is_correct": true, "explanation": "酒精（jiǔ jīng）：无色、像水的液体，能杀虫，也能让人喝醉，是本条的目标词。"}, {"text": "酒兴", "is_correct": false, "explanation": "酒兴（jiǔ xìng）：xìng 与 jīng 声母不同（x 与 j），声调也不同（第四声），意思是饮酒时的兴致。"}, {"text": "就近", "is_correct": false, "explanation": "就近（jiù jìn）：jiù 声调不同（第四声），jìn 与 jīng 韵尾不同（n 与 ng），意思是离得近。"}, {"text": "鸡精", "is_correct": false, "explanation": "鸡精（jī jīng）：jī 与 jiǔ 声调不同，且没有 u 韵母，意思是鸡精调味料。"}, {"text": "九星", "is_correct": false, "explanation": "九星（jiǔ xīng）：xīng 与 jīng 声母不同（x 与 j），意思是九颗星星。"}], "explanations": {"酒精": "酒精（jiǔ jīng）：无色、像水的液体，能杀虫，也能让人喝醉，是本条的目标词。", "酒兴": "酒兴（jiǔ xìng）：xìng 与 jīng 声母不同（x 与 j），声调也不同（第四声），意思是饮酒时的兴致。", "就近": "就近（jiù jìn）：jiù 声调不同（第四声），jìn 与 jīng 韵尾不同（n 与 ng），意思是离得近。", "鸡精": "鸡精（jī jīng）：jī 与 jiǔ 声调不同，且没有 u 韵母，意思是鸡精调味料。", "九星": "九星（jiǔ xīng）：xīng 与 jīng 声母不同（x 与 j），意思是九颗星星。"}, "sentence_index": null, "correct_answer": "酒精"}, "level_3": {"options": [{"text": "酒精", "is_correct": true, "explanation": "酒精能让人的脸变红，符合“让他的脸变得红红的”的语境。"}, {"text": "醋", "is_correct": false, "explanation": "语义：醋是调味品，不会让人的脸变红。"}, {"text": "面粉", "is_correct": false, "explanation": "语义：面粉是食材，不会让人的脸变红。"}, {"text": "酱油", "is_correct": false, "explanation": "语义：酱油是调味品，吃了不会让人的脸变红。"}], "explanations": {"酒精": "酒精能让人的脸变红，符合“让他的脸变得红红的”的语境。", "醋": "语义：醋是调味品，不会让人的脸变红。", "面粉": "语义：面粉是食材，不会让人的脸变红。", "酱油": "语义：酱油是调味品，吃了不会让人的脸变红。"}, "sentence_index": 6, "correct_answer": "酒精"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生让我每天往眼睛里滴一次酒精。", "explanation": "这里应该用〈眼药水〉。滴眼睛要用眼药水，酒精刺激性强，不能滴进眼睛。"}, {"text": "我买了一根酒精。", "explanation": "这里应该用〈瓶〉。液体酒精装在瓶子里，计量用“瓶”，不用“根”。"}, {"text": "我买了一片酒精。", "explanation": "这里应该用〈瓶〉。“片”用于薄片状的东西，液体酒精要用“瓶”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90971, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把一只酒精倒进了碗里。", "corrected_sentence": "我把一瓶酒精倒进了碗里。", "error_description": "量词错误：酒精是液体，计量要用“瓶”，不能用“只”。应说“一瓶酒精”，不说“一只酒精”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90971, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈酒精放在柜子里。", "corrected_sentence": "妈妈把酒精放在柜子里。", "error_description": "“把”字缺失：要表示把“酒精”放到某处，需用“把”引出宾语，应说“妈妈把酒精放在柜子里”，不能说“妈妈酒精放在柜子里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
