INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90972, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由粮食等发酵或化学方法制成的无色透明液体，可燃，用于消毒、做溶剂或制酒。", "primary_collocate": null, "pronunciation": "jiǔ jīng", "ipa": "tɕiou̯˨˩˦ tɕiŋ˥", "syllable_count": 2, "sentences": [{"text": "医生用酒精给伤口消毒。", "target_word": "酒精", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈用酒精把桌子擦干净了。", "target_word": "酒精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打针以前，护士先用酒精擦皮肤。", "target_word": "酒精", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "酒精可以用来消毒。", "target_word": "酒精", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这种油漆要用酒精才能洗掉。", "target_word": "酒精", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "粮食发酵以后，可以做出酒精。", "target_word": "酒精", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这瓶酒精是无色透明的。", "target_word": "酒精", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "酒精很容易着火，要放远一点。", "target_word": "酒精", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家药箱里有一瓶酒精和一些棉花。", "target_word": "酒精", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用酒精擦手，可以杀死手上的细菌。", "target_word": "酒精", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "瓶", "label": "量词"}, {"form": "酒精灯", "label": "复合"}, {"form": "酒精度", "label": "复合"}], "register": "中性", "sense_fingerprint": "无色透明可燃液体，用于消毒、溶剂和制酒", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eec25974-71fd-4a3e-aa7f-4714ae3f80b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90972, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "酒精", "is_correct": true, "explanation": "酒精（jiǔ jīng）：无色透明、可燃的液体，用于消毒、做溶剂，是本条的目标词。"}, {"text": "救星", "is_correct": false, "explanation": "救星（jiù xīng）：jiù 与 jiǔ 声调不同（第四声），xīng 与 jīng 声母不同（x 与 j），意思是救命的人或事物。"}, {"text": "酒兴", "is_correct": false, "explanation": "酒兴（jiǔ xìng）：xìng 与 jīng 声母不同（x 与 j），声调也不同（第四声），意思是饮酒时的兴致。"}, {"text": "就近", "is_correct": false, "explanation": "就近（jiù jìn）：jiù 声调不同（第四声），jìn 与 jīng 韵尾不同（n 与 ng），意思是离得近。"}, {"text": "旧情", "is_correct": false, "explanation": "旧情（jiù qíng）：jiù 声调不同（第四声），qíng 与 jīng 声母不同（q 与 j），意思是过去的感情。"}], "explanations": {"酒精": "酒精（jiǔ jīng）：无色透明、可燃的液体，用于消毒、做溶剂，是本条的目标词。", "救星": "救星（jiù xīng）：jiù 与 jiǔ 声调不同（第四声），xīng 与 jīng 声母不同（x 与 j），意思是救命的人或事物。", "酒兴": "酒兴（jiǔ xìng）：xìng 与 jīng 声母不同（x 与 j），声调也不同（第四声），意思是饮酒时的兴致。", "就近": "就近（jiù jìn）：jiù 声调不同（第四声），jìn 与 jīng 韵尾不同（n 与 ng），意思是离得近。", "旧情": "旧情（jiù qíng）：jiù 声调不同（第四声），qíng 与 jīng 声母不同（q 与 j），意思是过去的感情。"}, "sentence_index": null, "correct_answer": "酒精"}, "level_3": {"options": [{"text": "酒精", "is_correct": true, "explanation": "酒精可以用来给伤口消毒，符合“用……给伤口消毒”的语境。"}, {"text": "牛奶", "is_correct": false, "explanation": "语义：牛奶是食品，不能用来消毒伤口。"}, {"text": "汽油", "is_correct": false, "explanation": "语义：汽油易燃且有毒，不能涂在伤口上消毒。"}, {"text": "米饭", "is_correct": false, "explanation": "搭配：“用……消毒”需要消毒剂作工具，米饭不能用来消毒。"}], "explanations": {"酒精": "酒精可以用来给伤口消毒，符合“用……给伤口消毒”的语境。", "牛奶": "语义：牛奶是食品，不能用来消毒伤口。", "汽油": "语义：汽油易燃且有毒，不能涂在伤口上消毒。", "米饭": "搭配：“用……消毒”需要消毒剂作工具，米饭不能用来消毒。"}, "sentence_index": 0, "correct_answer": "酒精"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈做饭时直接用酒精调味。", "explanation": "这里应该用〈酱油〉。调味要用酱油等食用调料，消毒用的酒精不能入口，不能用来调味。"}, {"text": "失火时可以用酒精灭火。", "explanation": "这里应该用〈灭火器〉。酒精本身可燃，不能用来灭火，灭火要用灭火器。"}, {"text": "我买了一朵酒精。", "explanation": "这里应该用〈瓶〉。“朵”用于花朵，液体酒精要用“瓶”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90972, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "酒精", "is_correct": true, "explanation": "酒精（jiǔ jīng）：无色透明、可燃的液体，用于消毒、做溶剂，是本条的目标词。"}, {"text": "酒劲", "is_correct": false, "explanation": "酒劲（jiǔ jìn）：jìn 与 jīng 韵尾不同（n 与 ng），声调也不同（第四声），意思是酒的醉人作用。"}, {"text": "九斤", "is_correct": false, "explanation": "九斤（jiǔ jīn）：jīn 与 jīng 韵尾不同（in 与 ing），意思是九斤重的分量。"}, {"text": "鸡精", "is_correct": false, "explanation": "鸡精（jī jīng）：jī 与 jiǔ 声调不同，且没有 u 韵母，意思是鸡精调味料。"}, {"text": "九星", "is_correct": false, "explanation": "九星（jiǔ xīng）：xīng 与 jīng 声母不同（x 与 j），意思是九颗星星。"}], "explanations": {"酒精": "酒精（jiǔ jīng）：无色透明、可燃的液体，用于消毒、做溶剂，是本条的目标词。", "酒劲": "酒劲（jiǔ jìn）：jìn 与 jīng 韵尾不同（n 与 ng），声调也不同（第四声），意思是酒的醉人作用。", "九斤": "九斤（jiǔ jīn）：jīn 与 jīng 韵尾不同（in 与 ing），意思是九斤重的分量。", "鸡精": "鸡精（jī jīng）：jī 与 jiǔ 声调不同，且没有 u 韵母，意思是鸡精调味料。", "九星": "九星（jiǔ xīng）：xīng 与 jīng 声母不同（x 与 j），意思是九颗星星。"}, "sentence_index": null, "correct_answer": "酒精"}, "level_3": {"options": [{"text": "酒精", "is_correct": true, "explanation": "酒精是无色透明的液体，符合“无色透明”的描述。"}, {"text": "酱油", "is_correct": false, "explanation": "体貌：酱油是深褐色的，与“无色透明”矛盾。"}, {"text": "墨水", "is_correct": false, "explanation": "体貌：墨水是有颜色的，不可能无色透明。"}, {"text": "面粉", "is_correct": false, "explanation": "语义：面粉是白色粉末，不是液体，与“无色透明的”不符。"}], "explanations": {"酒精": "酒精是无色透明的液体，符合“无色透明”的描述。", "酱油": "体貌：酱油是深褐色的，与“无色透明”矛盾。", "墨水": "体貌：墨水是有颜色的，不可能无色透明。", "面粉": "语义：面粉是白色粉末，不是液体，与“无色透明的”不符。"}, "sentence_index": 6, "correct_answer": "酒精"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位叔叔每天晚上都要喝一杯酒精。", "explanation": "这里应该用〈白酒〉。白酒可以喝，酒精不能当饮料喝。"}, {"text": "孩子嗓子疼，妈妈用酒精给他漱口。", "explanation": "这里应该用〈盐水〉。给孩子漱口要用温和的盐水；酒精刺激强，孩子容易误吞。"}, {"text": "我买了一棵酒精。", "explanation": "这里应该用〈瓶〉。“棵”用于树木，液体酒精要用“瓶”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90972, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "护士拿来一只酒精，给我擦手。", "corrected_sentence": "护士拿来一瓶酒精，给我擦手。", "error_description": "量词错误：酒精是液体，计量要用“瓶”，不能用“只”。应说“一瓶酒精”，不说“一只酒精”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90972, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "小明酒精擦干净了手机屏幕。", "corrected_sentence": "小明用酒精擦干净了手机屏幕。", "error_description": "介词缺失：“酒精”作工具要用“用”引出，应说“用酒精擦”，不能省略“用”直接说“酒精擦”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90973, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拆", "is_correct": true, "explanation": "正确：拆表示拆除，与“搭建高架子”构成反义。"}, {"text": "写", "is_correct": false, "explanation": "写表示写字，与“搭”没有反义关系。"}, {"text": "跑", "is_correct": false, "explanation": "跑表示快速移动，与“搭”没有反义关系。"}, {"text": "洗", "is_correct": false, "explanation": "洗表示清洗，与“搭”没有反义关系。"}], "correct_answer": "拆", "explanations": {"拆": "正确：拆表示拆除，与“搭建高架子”构成反义。", "写": "写表示写字，与“搭”没有反义关系。", "跑": "跑表示快速移动，与“搭”没有反义关系。", "洗": "洗表示清洗，与“搭”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26836a31-7f2a-42f4-8e16-0e87522ee9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90973, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拆", "is_correct": true, "explanation": "正确：拆表示拆除，与“用纸盒搭小城堡”的搭建义构成反义。"}, {"text": "卖", "is_correct": false, "explanation": "卖表示出售，与“搭”没有反义关系。"}, {"text": "喝", "is_correct": false, "explanation": "喝表示饮用，与“搭”没有反义关系。"}, {"text": "摘", "is_correct": false, "explanation": "摘表示采下，与“搭”没有反义关系。"}], "correct_answer": "拆", "explanations": {"拆": "正确：拆表示拆除，与“用纸盒搭小城堡”的搭建义构成反义。", "卖": "卖表示出售，与“搭”没有反义关系。", "喝": "喝表示饮用，与“搭”没有反义关系。", "摘": "摘表示采下，与“搭”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26836a31-7f2a-42f4-8e16-0e87522ee9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90973, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "搭是把东西放在一起，做成一个架子或房子。", "primary_collocate": null, "pronunciation": "dā", "ipa": "ta˥", "syllable_count": 1, "sentences": [{"text": "爸爸在院子里搭了一个小棚子。", "target_word": "搭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在山上搭帐篷过夜。", "target_word": "搭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们用积木搭了一座房子。", "target_word": "搭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人正在搭一个高架子。", "target_word": "搭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想搭一间小木屋。", "target_word": "搭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨前，大家把帐篷搭好了。", "target_word": "搭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷用竹子搭了个架子，让黄瓜往上长。", "target_word": "搭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个台子是谁搭的？", "target_word": "搭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正在海边搭一个大帐篷。", "target_word": "搭", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用纸盒搭了一个小城堡。", "target_word": "搭", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "搭了", "label": "体标"}, {"form": "搭着", "label": "体标"}, {"form": "搭过", "label": "体标"}, {"form": "搭建", "label": "复合"}, {"form": "搭好", "label": "复合"}], "register": "通用", "sense_fingerprint": "搭：把东西拼起来做成架子或房子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '126c1563-16f3-4d23-b8d9-2411ca5ce2db') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90973, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "搭", "is_correct": true, "explanation": "正确：搭（dā）表示把东西拼起来做成架子或房子。"}, {"text": "打", "is_correct": false, "explanation": "dǎ（第三声）与 dā（第一声）声调不同，意思是“打”，指击打。"}, {"text": "大", "is_correct": false, "explanation": "dà（第四声）与 dā（第一声）声调不同，意思是“大”。"}, {"text": "答", "is_correct": false, "explanation": "dá（第二声）与 dā（第一声）声调不同，意思是“回答”。"}, {"text": "他", "is_correct": false, "explanation": "tā 与 dā 声母不同（t 与 d），意思是“他”。"}], "explanations": {"搭": "正确：搭（dā）表示把东西拼起来做成架子或房子。", "打": "dǎ（第三声）与 dā（第一声）声调不同，意思是“打”，指击打。", "大": "dà（第四声）与 dā（第一声）声调不同，意思是“大”。", "答": "dá（第二声）与 dā（第一声）声调不同，意思是“回答”。", "他": "tā 与 dā 声母不同（t 与 d），意思是“他”。"}, "sentence_index": null, "correct_answer": "搭"}, "level_3": {"options": [{"text": "挖", "is_correct": false, "explanation": "语义：挖是掘土，不能挖出一个小棚子。"}, {"text": "唱", "is_correct": false, "explanation": "语义：唱是唱歌，不能用来做小棚子。"}, {"text": "搭", "is_correct": true, "explanation": "正确：搭表示架设、搭建，“爸爸在院子里搭了一个小棚子”成立。"}, {"text": "骑", "is_correct": false, "explanation": "搭配：“骑”用于能骑的东西，不能说“骑一个小棚子”。"}], "explanations": {"挖": "语义：挖是掘土，不能挖出一个小棚子。", "唱": "语义：唱是唱歌，不能用来做小棚子。", "搭": "正确：搭表示架设、搭建，“爸爸在院子里搭了一个小棚子”成立。", "骑": "搭配：“骑”用于能骑的东西，不能说“骑一个小棚子”。"}, "sentence_index": 0, "correct_answer": "搭"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座摩天大楼是他们搭的。", "explanation": "这里应该用〈建〉。搭指搭建简单的架子或棚子，摩天大楼这样的大型建筑要用“建”。"}, {"text": "他在纸上搭了一只猫。", "explanation": "这里应该用〈画〉。搭不表示在纸上画画。"}, {"text": "孩子们在教室里搭了一首歌。", "explanation": "这里应该用〈唱〉。搭不表示唱歌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26836a31-7f2a-42f4-8e16-0e87522ee9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90973, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "搭", "is_correct": true, "explanation": "正确：搭（dā）表示把东西拼起来做成架子或房子。"}, {"text": "八", "is_correct": false, "explanation": "bā 与 dā 声母不同（b 与 d），意思是“八”。"}, {"text": "哈", "is_correct": false, "explanation": "hā 与 dā 声母不同（h 与 d），意思是“哈”。"}, {"text": "当", "is_correct": false, "explanation": "dāng 与 dā 韵母不同（ang 与 a），意思是“当”。"}, {"text": "都", "is_correct": false, "explanation": "dōu 与 dā 韵母不同（ou 与 a），意思是“都”。"}, {"text": "低", "is_correct": false, "explanation": "dī 与 dā 韵母不同（i 与 a），意思是“低”。"}, {"text": "达", "is_correct": false, "explanation": "dá（第二声）与 dā（第一声）声调不同，意思是“到达”。"}], "explanations": {"搭": "正确：搭（dā）表示把东西拼起来做成架子或房子。", "八": "bā 与 dā 声母不同（b 与 d），意思是“八”。", "哈": "hā 与 dā 声母不同（h 与 d），意思是“哈”。", "当": "dāng 与 dā 韵母不同（ang 与 a），意思是“当”。", "都": "dōu 与 dā 韵母不同（ou 与 a），意思是“都”。", "低": "dī 与 dā 韵母不同（i 与 a），意思是“低”。", "达": "dá（第二声）与 dā（第一声）声调不同，意思是“到达”。"}, "sentence_index": null, "correct_answer": "搭"}, "level_3": {"options": [{"text": "烧", "is_correct": false, "explanation": "语义：烧是使东西燃烧，竹子烧了就做不成架子。"}, {"text": "搭", "is_correct": true, "explanation": "正确：搭表示用材料做成架子，“爷爷用竹子搭了个架子”成立。"}, {"text": "吃", "is_correct": false, "explanation": "语义：吃是吃东西，竹子不能吃，也做不成架子。"}, {"text": "敲", "is_correct": false, "explanation": "搭配：“敲”是打击动作，不能说“敲了个架子”。"}], "explanations": {"烧": "语义：烧是使东西燃烧，竹子烧了就做不成架子。", "搭": "正确：搭表示用材料做成架子，“爷爷用竹子搭了个架子”成立。", "吃": "语义：吃是吃东西，竹子不能吃，也做不成架子。", "敲": "搭配：“敲”是打击动作，不能说“敲了个架子”。"}, "sentence_index": 6, "correct_answer": "搭"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农民在地里搭了一排白菜。", "explanation": "这里应该用〈种〉。搭表示架设或搭建，不表示种植。"}, {"text": "他每天搭一个苹果当早饭。", "explanation": "这里应该用〈吃〉。搭不表示吃东西。"}, {"text": "她用笔搭字。", "explanation": "这里应该用〈写〉。搭不表示写字。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26836a31-7f2a-42f4-8e16-0e87522ee9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90973, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们把木架搭了好。", "corrected_sentence": "我们把木架搭好了。", "error_description": "结果补语“好”要紧跟动词，动态助词“了”放在“好”之后，应说“搭好了”，不能说“搭了好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26836a31-7f2a-42f4-8e16-0e87522ee9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90973, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "工人把帐篷搭很结实。", "corrected_sentence": "工人把帐篷搭得很结实。", "error_description": "“搭”后面的程度补语要用“得”，应说“搭得很结实”，这里漏了“得”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '26836a31-7f2a-42f4-8e16-0e87522ee9ea') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
