INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90977, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "医是帮生病的人把病治好。", "primary_collocate": null, "pronunciation": "yī", "ipa": "i˥", "syllable_count": 1, "sentences": [{"text": "这种病很难医好，要花很长时间。", "target_word": "医", "complexity_tier": "T3", "furigana": "zhè zhǒng bìng hěn nán yī hǎo, yào huā hěn cháng shí jiān.", "sentence_source": "generated"}, {"text": "听说那位老人能医好这个病。", "target_word": "医", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的腿伤花了半年才医好。", "target_word": "医", "complexity_tier": "T3", "furigana": "tā de tuǐ shāng huā le bàn nián cái yī hǎo.", "sentence_source": "generated"}, {"text": "这种病现在还医不好。", "target_word": "医", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "妈妈想把我的咳嗽医好。", "target_word": "医", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "只要你听话，我就能医好你的病。", "target_word": "医", "complexity_tier": "T3", "furigana": "zhǐ yào nǐ tīng huà, wǒ jiù néng yī hǎo nǐ de bìng.", "sentence_source": "generated"}, {"text": "小狗的脚受伤了，我们想办法医好它。", "target_word": "医", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个药很好，能医好你的头疼。", "target_word": "医", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个病他看了很多年，还是没医好。", "target_word": "医", "complexity_tier": "T3", "furigana": "zhè ge bìng tā kàn le hěn duō nián, hái shì méi yī hǎo.", "sentence_source": "generated"}, {"text": "只有这位老人能把我的病医好。", "target_word": "医", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "医了", "label": "体标"}, {"form": "医过", "label": "体标"}, {"form": "医治", "label": "复合"}, {"form": "醫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "动词，给病人治病，使病好起来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eec25974-71fd-4a3e-aa7f-4714ae3f80b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90977, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "医", "is_correct": true, "explanation": "正确：医（yī，第一声）指治病，是本词。"}, {"text": "椅", "is_correct": false, "explanation": "yǐ（第三声）与 yī（第一声）声调不同，意思是椅子。"}, {"text": "以", "is_correct": false, "explanation": "yǐ（第三声）与 yī（第一声）声调不同，意思是用、凭借。"}, {"text": "亿", "is_correct": false, "explanation": "yì（第四声）与 yī（第一声）声调不同，意思是数量单位亿。"}, {"text": "姨", "is_correct": false, "explanation": "yí（第二声）与 yī（第一声）声调不同，意思是阿姨。"}], "explanations": {"医": "正确：医（yī，第一声）指治病，是本词。", "椅": "yǐ（第三声）与 yī（第一声）声调不同，意思是椅子。", "以": "yǐ（第三声）与 yī（第一声）声调不同，意思是用、凭借。", "亿": "yì（第四声）与 yī（第一声）声调不同，意思是数量单位亿。", "姨": "yí（第二声）与 yī（第一声）声调不同，意思是阿姨。"}, "sentence_index": null, "correct_answer": "医"}, "level_3": {"options": [{"text": "医", "is_correct": true, "explanation": "正确：“医好”指治病使病好起来，句中说这种病很难治好。"}, {"text": "修", "is_correct": false, "explanation": "搭配：“修好”多用于器物，不用于疾病。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃好”指吃得好，与疾病无关，句意不通。"}, {"text": "织", "is_correct": false, "explanation": "语义：“织好”指编织完成，与疾病无关，句意不通。"}], "explanations": {"医": "正确：“医好”指治病使病好起来，句中说这种病很难治好。", "修": "搭配：“修好”多用于器物，不用于疾病。", "吃": "语义：“吃好”指吃得好，与疾病无关，句意不通。", "织": "语义：“织好”指编织完成，与疾病无关，句意不通。"}, "sentence_index": 0, "correct_answer": "医"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把那条旧裤子医成了短裤。", "explanation": "这里应该用〈改〉。医指治病，把旧裤子改成短裤要用改，不能说医成。"}, {"text": "爸爸把这辆旧汽车医好了。", "explanation": "这里应该用〈修〉。医只用于治病，汽车等机器坏了应说修好，不能说医好。"}, {"text": "医生医了病人的命。", "explanation": "这里应该用〈救〉。医指治病，不能和“命”搭配，救命应说救。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90977, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "医", "is_correct": true, "explanation": "正确：医（yī，第一声）指治病，是本词。"}, {"text": "移", "is_correct": false, "explanation": "yí（第二声）与 yī（第一声）声调不同，意思是移动。"}, {"text": "意", "is_correct": false, "explanation": "yì（第四声）与 yī（第一声）声调不同，意思是意思、心意。"}, {"text": "议", "is_correct": false, "explanation": "yì（第四声）与 yī（第一声）声调不同，意思是讨论。"}, {"text": "已", "is_correct": false, "explanation": "yǐ（第三声）与 yī（第一声）声调不同，意思是已经。"}], "explanations": {"医": "正确：医（yī，第一声）指治病，是本词。", "移": "yí（第二声）与 yī（第一声）声调不同，意思是移动。", "意": "yì（第四声）与 yī（第一声）声调不同，意思是意思、心意。", "议": "yì（第四声）与 yī（第一声）声调不同，意思是讨论。", "已": "yǐ（第三声）与 yī（第一声）声调不同，意思是已经。"}, "sentence_index": null, "correct_answer": "医"}, "level_3": {"options": [{"text": "医", "is_correct": true, "explanation": "正确：“医好它”指治好小狗的伤，与“想办法”搭配，句意通顺。"}, {"text": "装", "is_correct": false, "explanation": "搭配：“装好”指安装或包装，不用于给动物治伤。"}, {"text": "找", "is_correct": false, "explanation": "语义：“找好”不是治伤的意思，与“受伤”不合。"}, {"text": "叫", "is_correct": false, "explanation": "语义：“叫好”指喝彩，句中说想办法叫好它，意思不通。"}], "explanations": {"医": "正确：“医好它”指治好小狗的伤，与“想办法”搭配，句意通顺。", "装": "搭配：“装好”指安装或包装，不用于给动物治伤。", "找": "语义：“找好”不是治伤的意思，与“受伤”不合。", "叫": "语义：“叫好”指喝彩，句中说想办法叫好它，意思不通。"}, "sentence_index": 6, "correct_answer": "医"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把破袜子医好了。", "explanation": "这里应该用〈补〉。医只用于治疗人或动物的疾病，袜子破了应说补好。"}, {"text": "妈妈把脏衣服医干净了。", "explanation": "这里应该用〈洗〉。医指治病，衣服脏了要用洗，不能说医干净。"}, {"text": "工人把空调医好了。", "explanation": "这里应该用〈修〉。医用于治病，坏了的空调要修好，不能说医好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90977, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的咳嗽终于医了好。", "corrected_sentence": "我的咳嗽终于医好了。", "error_description": "补语位置错误：结果补语“好”应紧接动词“医”，之后再加“了”，应说“医好了”，不能说“医了好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90977, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个病我吃了很多药，还是医没好。", "corrected_sentence": "这个病我吃了很多药，还是没医好。", "error_description": "否定位置错误：否定词“没”应放在动词“医”之前，应说“没医好”，不能说“医没好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
