INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90978, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "医学，指学习或从事医学这一行。", "primary_collocate": null, "pronunciation": "yī", "ipa": "i˥", "syllable_count": 1, "sentences": [{"text": "哥哥在大学学医，以后想帮助病人。", "target_word": "医", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她家几代都有人学医，很受大家尊敬。", "target_word": "医", "complexity_tier": "T3", "furigana": "tā jiā jǐ dài dōu yǒu rén xué yī, hěn shòu dà jiā zūn jìng.", "sentence_source": "generated"}, {"text": "他爷爷学了一辈子医，治病四十年了。", "target_word": "医", "complexity_tier": "T3", "furigana": "tā yé ye xué le yí bèi zi yī, zhì bìng sì shí nián le.", "sentence_source": "generated"}, {"text": "我姐姐学过医，会看简单的病。", "target_word": "医", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就想学医。", "target_word": "医", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她懂医，朋友生病都来问她。", "target_word": "医", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位老先生不但学医，还写了不少书。", "target_word": "医", "complexity_tier": "T3", "furigana": "zhè wèi lǎo xiān sheng bú dàn xué yī, hái xiě le bù shǎo shū.", "sentence_source": "generated"}, {"text": "他放弃了做生意，改行学医了。", "target_word": "医", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他对医很感兴趣，常常看医书。", "target_word": "医", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他放弃文学改学医，一直没后悔过。", "target_word": "医", "complexity_tier": "T3", "furigana": "tā fàng qì wén xué gǎi xué yī, yì zhí méi hòu huǐ guo.", "sentence_source": "generated"}], "morphological_forms": [{"form": "医生", "label": "复合"}, {"form": "医学", "label": "复合"}, {"form": "醫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "学习或从事医学这一行", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eec25974-71fd-4a3e-aa7f-4714ae3f80b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90978, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "医", "is_correct": true, "explanation": "正确：医（yī，第一声）指医学，是本词。"}, {"text": "椅", "is_correct": false, "explanation": "yǐ（第三声）与 yī（第一声）声调不同，意思是椅子。"}, {"text": "以", "is_correct": false, "explanation": "yǐ（第三声）与 yī（第一声）声调不同，意思是用、凭借。"}, {"text": "亿", "is_correct": false, "explanation": "yì（第四声）与 yī（第一声）声调不同，意思是数量单位亿。"}, {"text": "姨", "is_correct": false, "explanation": "yí（第二声）与 yī（第一声）声调不同，意思是阿姨。"}], "explanations": {"医": "正确：医（yī，第一声）指医学，是本词。", "椅": "yǐ（第三声）与 yī（第一声）声调不同，意思是椅子。", "以": "yǐ（第三声）与 yī（第一声）声调不同，意思是用、凭借。", "亿": "yì（第四声）与 yī（第一声）声调不同，意思是数量单位亿。", "姨": "yí（第二声）与 yī（第一声）声调不同，意思是阿姨。"}, "sentence_index": null, "correct_answer": "医"}, "level_3": {"options": [{"text": "医", "is_correct": true, "explanation": "正确：“学医”指学习医学，句中说哥哥在大学学医。"}, {"text": "唱", "is_correct": false, "explanation": "语义：学唱歌与“以后想帮助病人”不相关，句意不合。"}, {"text": "演", "is_correct": false, "explanation": "语义：学表演与“帮助病人”无关，句意不通。"}, {"text": "跳", "is_correct": false, "explanation": "搭配：“学”后接“跳”一般要接“舞”，单独“学跳”不成搭配。"}], "explanations": {"医": "正确：“学医”指学习医学，句中说哥哥在大学学医。", "唱": "语义：学唱歌与“以后想帮助病人”不相关，句意不合。", "演": "语义：学表演与“帮助病人”无关，句意不通。", "跳": "搭配：“学”后接“跳”一般要接“舞”，单独“学跳”不成搭配。"}, "sentence_index": 0, "correct_answer": "医"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "孩子总是医爸爸说话的样子。", "explanation": "这里应该用〈模仿〉。医指治病或学医，照着别人的样子做要用模仿，不能用医。"}, {"text": "他长大后想当医。", "explanation": "这里应该用〈医生〉。“医”单独不表示职业，说职业要用医生，不能说当医。"}, {"text": "她在大学医过心理学。", "explanation": "这里应该用〈教〉。医指治病或学医，在课堂上讲授课程要用教，不能说医心理学。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90978, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "医", "is_correct": true, "explanation": "正确：医（yī，第一声）指医学，是本词。"}, {"text": "移", "is_correct": false, "explanation": "yí（第二声）与 yī（第一声）声调不同，意思是移动。"}, {"text": "意", "is_correct": false, "explanation": "yì（第四声）与 yī（第一声）声调不同，意思是意思、心意。"}, {"text": "议", "is_correct": false, "explanation": "yì（第四声）与 yī（第一声）声调不同，意思是讨论。"}, {"text": "已", "is_correct": false, "explanation": "yǐ（第三声）与 yī（第一声）声调不同，意思是已经。"}], "explanations": {"医": "正确：医（yī，第一声）指医学，是本词。", "移": "yí（第二声）与 yī（第一声）声调不同，意思是移动。", "意": "yì（第四声）与 yī（第一声）声调不同，意思是意思、心意。", "议": "yì（第四声）与 yī（第一声）声调不同，意思是讨论。", "已": "yǐ（第三声）与 yī（第一声）声调不同，意思是已经。"}, "sentence_index": null, "correct_answer": "医"}, "level_3": {"options": [{"text": "医", "is_correct": true, "explanation": "正确：“学医”指学习医学，句中“不但……，还写了不少书”承接学业。"}, {"text": "跑", "is_correct": false, "explanation": "语义：学跑步与“写了不少书”不合，句意不通。"}, {"text": "睡", "is_correct": false, "explanation": "语义：“学睡”不成词，与“写了不少书”不合，句意不通。"}, {"text": "哭", "is_correct": false, "explanation": "语义：“学哭”不成词，句意不通。"}], "explanations": {"医": "正确：“学医”指学习医学，句中“不但……，还写了不少书”承接学业。", "跑": "语义：学跑步与“写了不少书”不合，句意不通。", "睡": "语义：“学睡”不成词，与“写了不少书”不合，句意不通。", "哭": "语义：“学哭”不成词，句意不通。"}, "sentence_index": 6, "correct_answer": "医"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他每天医三顿饭，很辛苦。", "explanation": "这里应该用〈做〉。医指治病或学医，做饭要用做，不能说医三顿饭。"}, {"text": "他医了一本关于历史的书。", "explanation": "这里应该用〈写〉。医不能表示写作，写书要用写，不能说医了一本书。"}, {"text": "他每天医车上班。", "explanation": "这里应该用〈开〉。医指治病或学医，驾驶汽车要用开，不能说医车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90978, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我哥哥学医过，后来当了医生。", "corrected_sentence": "我哥哥学过医，后来当了医生。", "error_description": "“过”的位置错误：“过”应紧接动词“学”，表示经历，应说“学过医”，不能说“学医过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90978, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他学了两年医生，现在是医生。", "corrected_sentence": "他学了两年医，现在是医生。", "error_description": "宾语错误：“学”后面的宾语应是学科“医”（医学），不能用职业名词“医生”。应说“学了两年医”，不说“学了两年医生”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
