INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90979, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "杯是喝水用的东西，一般是圆的，上面是开口的。", "primary_collocate": null, "pronunciation": "bēi", "ipa": "peɪ˥", "syllable_count": 1, "sentences": [{"text": "杯里有热茶。", "target_word": "杯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上的杯是我的。", "target_word": "杯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把杯洗干净了。", "target_word": "杯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把杯放进了柜子。", "target_word": "杯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只杯是红色的。", "target_word": "杯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杯里没有水了，再倒一点吧。", "target_word": "杯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看着杯里的茶，没有说话。", "target_word": "杯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杯里的牛奶已经凉了。", "target_word": "杯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的杯在包里，你看见了吗？", "target_word": "杯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只杯很大，能装很多水。", "target_word": "杯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "杯子", "label": "复合"}, {"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "喝水用的圆形开口器具", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1bdeefd-92f9-4e14-bb18-a5d8568bc61c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90979, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "杯", "is_correct": true, "explanation": "杯是喝水用的器具，与听到的读音一致。"}, {"text": "北", "is_correct": false, "explanation": "běi（第三声）与 bēi（第一声）声调不同，北指北方。"}, {"text": "被", "is_correct": false, "explanation": "bèi（第四声）与 bēi（第一声）声调不同，被是被动的标记。"}, {"text": "倍", "is_correct": false, "explanation": "bèi（第四声）与 bēi（第一声）声调不同，倍指数量的倍数。"}], "explanations": {"杯": "杯是喝水用的器具，与听到的读音一致。", "北": "běi（第三声）与 bēi（第一声）声调不同，北指北方。", "被": "bèi（第四声）与 bēi（第一声）声调不同，被是被动的标记。", "倍": "bèi（第四声）与 bēi（第一声）声调不同，倍指数量的倍数。"}, "sentence_index": null, "correct_answer": "杯"}, "level_3": {"options": [{"text": "窗户", "is_correct": false, "explanation": "语义：窗户不能用来盛热茶，句子说不通。"}, {"text": "杯", "is_correct": true, "explanation": "杯是盛饮料的器具，“杯里”可以装热茶，句子通顺。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板不能装东西，热茶放不进去。"}, {"text": "天空", "is_correct": false, "explanation": "搭配：“里”要求能装东西的地方，天空不能说“天空里有热茶”。"}], "explanations": {"窗户": "语义：窗户不能用来盛热茶，句子说不通。", "杯": "杯是盛饮料的器具，“杯里”可以装热茶，句子通顺。", "黑板": "语义：黑板不能装东西，热茶放不进去。", "天空": "搭配：“里”要求能装东西的地方，天空不能说“天空里有热茶”。"}, "sentence_index": 0, "correct_answer": "杯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他晚上枕着杯睡觉。", "explanation": "这里应该用〈枕头〉。杯子是盛饮料的，不能枕着睡觉，睡觉要用枕头。"}, {"text": "吃饭要用杯和筷子。", "explanation": "这里应该用〈碗〉。杯只用来盛饮料，吃饭盛饭菜要用碗。"}, {"text": "请把菜放进杯里。", "explanation": "这里应该用〈盘子〉。杯只盛饮料，菜要放在盘子里。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c224d9-282f-454c-a3fa-811ceaaad6bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90979, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "杯", "is_correct": true, "explanation": "杯是喝水用的器具，与听到的读音一致。"}, {"text": "备", "is_correct": false, "explanation": "bèi（第四声）与 bēi（第一声）声调不同，备指准备。"}, {"text": "贝", "is_correct": false, "explanation": "bèi（第四声）与 bēi（第一声）声调不同，贝指贝壳。"}, {"text": "辈", "is_correct": false, "explanation": "bèi（第四声）与 bēi（第一声）声调不同，辈指世代或同类的人。"}], "explanations": {"杯": "杯是喝水用的器具，与听到的读音一致。", "备": "bèi（第四声）与 bēi（第一声）声调不同，备指准备。", "贝": "bèi（第四声）与 bēi（第一声）声调不同，贝指贝壳。", "辈": "bèi（第四声）与 bēi（第一声）声调不同，辈指世代或同类的人。"}, "sentence_index": null, "correct_answer": "杯"}, "level_3": {"options": [{"text": "脸", "is_correct": false, "explanation": "语义：脸不能盛茶，句子说不通。"}, {"text": "杯", "is_correct": true, "explanation": "杯是盛茶的器具，“杯里的茶”指杯中的茶，句子通顺。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气是无形的，不能盛茶，句子说不通。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“里”要求能装东西的地方，时间不能说“时间里的茶”。"}], "explanations": {"脸": "语义：脸不能盛茶，句子说不通。", "杯": "杯是盛茶的器具，“杯里的茶”指杯中的茶，句子通顺。", "空气": "语义：空气是无形的，不能盛茶，句子说不通。", "时间": "搭配：“里”要求能装东西的地方，时间不能说“时间里的茶”。"}, "sentence_index": 6, "correct_answer": "杯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用杯炒菜。", "explanation": "这里应该用〈锅〉。炒菜要用锅，杯子不能用来炒菜。"}, {"text": "他用杯砍树。", "explanation": "这里应该用〈斧头〉。砍树要用斧头，杯子只用来盛饮料。"}, {"text": "他用杯擦桌子。", "explanation": "这里应该用〈抹布〉。擦桌子要用抹布，杯子只用来盛饮料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c224d9-282f-454c-a3fa-811ceaaad6bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90979, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那张杯是蓝色的。", "corrected_sentence": "那只杯是蓝色的。", "error_description": "量词错误：“杯”应用“只”或“个”，不能用“张”。正确：“那只杯是蓝色的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c224d9-282f-454c-a3fa-811ceaaad6bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90979, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条杯太小了，装不下牛奶。", "corrected_sentence": "这只杯太小了，装不下牛奶。", "error_description": "量词错误：“杯”应该用“只”或“个”，不能用“条”（“条”多用于细长的东西）。正确：“这只杯太小了，装不下牛奶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c224d9-282f-454c-a3fa-811ceaaad6bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
