INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90980, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "盛饮料的器皿，多为圆柱形或圆锥形。", "primary_collocate": null, "pronunciation": "bēi", "ipa": "peɪ˥", "syllable_count": 1, "sentences": [{"text": "杯中的果汁是橙色的。", "target_word": "杯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杯里有一片柠檬。", "target_word": "杯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只杯是圆的，上面开口。", "target_word": "杯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务员把杯放在客人面前。", "target_word": "杯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友的杯里是热牛奶。", "target_word": "杯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一口喝完了杯中的饮料。", "target_word": "杯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杯里的可乐有很多冰。", "target_word": "杯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把杯拿过来，我给你倒果汁。", "target_word": "杯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只带花的杯是她的。", "target_word": "杯", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "杯中的茶水还冒着热气。", "target_word": "杯", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "杯子", "label": "复合"}, {"form": "个", "label": "量词"}], "register": "口语", "sense_fingerprint": "盛饮料的圆柱形或圆锥形器皿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a1bdeefd-92f9-4e14-bb18-a5d8568bc61c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90980, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "杯", "is_correct": true, "explanation": "杯是盛饮料的器皿，与听到的读音一致。"}, {"text": "北", "is_correct": false, "explanation": "běi（第三声）与 bēi（第一声）声调不同，北指北方。"}, {"text": "被", "is_correct": false, "explanation": "bèi（第四声）与 bēi（第一声）声调不同，被是被动的标记。"}, {"text": "倍", "is_correct": false, "explanation": "bèi（第四声）与 bēi（第一声）声调不同，倍指数量的倍数。"}], "explanations": {"杯": "杯是盛饮料的器皿，与听到的读音一致。", "北": "běi（第三声）与 bēi（第一声）声调不同，北指北方。", "被": "bèi（第四声）与 bēi（第一声）声调不同，被是被动的标记。", "倍": "bèi（第四声）与 bēi（第一声）声调不同，倍指数量的倍数。"}, "sentence_index": null, "correct_answer": "杯"}, "level_3": {"options": [{"text": "课本", "is_correct": false, "explanation": "语义：课本不能盛果汁，句子说不通。"}, {"text": "杯", "is_correct": true, "explanation": "杯是盛饮料的器皿，“杯中的果汁”指杯里的果汁，与“橙色”相符。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄不是盛东西的地方，果汁无法放进去。"}, {"text": "发型", "is_correct": false, "explanation": "语义：发型是人的头发样式，不能用来盛果汁。"}], "explanations": {"课本": "语义：课本不能盛果汁，句子说不通。", "杯": "杯是盛饮料的器皿，“杯中的果汁”指杯里的果汁，与“橙色”相符。", "年龄": "语义：年龄不是盛东西的地方，果汁无法放进去。", "发型": "语义：发型是人的头发样式，不能用来盛果汁。"}, "sentence_index": 0, "correct_answer": "杯"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用杯梳头。", "explanation": "这里应该用〈梳子〉。梳头要用梳子，杯子不能用来梳头。"}, {"text": "他用杯写字。", "explanation": "这里应该用〈笔〉。写字要用笔，杯子不能用来写字。"}, {"text": "他戴着一个杯出门。", "explanation": "这里应该用〈帽子〉。杯子不能戴在头上，出门戴的东西要说帽子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c224d9-282f-454c-a3fa-811ceaaad6bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90980, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "杯", "is_correct": true, "explanation": "杯是盛饮料的器皿，与听到的读音一致。"}, {"text": "备", "is_correct": false, "explanation": "bèi（第四声）与 bēi（第一声）声调不同，备指准备。"}, {"text": "贝", "is_correct": false, "explanation": "bèi（第四声）与 bēi（第一声）声调不同，贝指贝壳。"}, {"text": "辈", "is_correct": false, "explanation": "bèi（第四声）与 bēi（第一声）声调不同，辈指世代或同类的人。"}], "explanations": {"杯": "杯是盛饮料的器皿，与听到的读音一致。", "备": "bèi（第四声）与 bēi（第一声）声调不同，备指准备。", "贝": "bèi（第四声）与 bēi（第一声）声调不同，贝指贝壳。", "辈": "bèi（第四声）与 bēi（第一声）声调不同，辈指世代或同类的人。"}, "sentence_index": null, "correct_answer": "杯"}, "level_3": {"options": [{"text": "天空", "is_correct": false, "explanation": "语义：天空不能装可乐，句子说不通。"}, {"text": "杯", "is_correct": true, "explanation": "杯是盛饮料的器皿，“杯里的可乐”指装在杯子里的可乐，句子通顺。"}, {"text": "手指", "is_correct": false, "explanation": "语义：手指不能盛可乐，句子说不通。"}, {"text": "时间", "is_correct": false, "explanation": "搭配：“里”要求能装东西的地方，时间不能说“时间里的可乐”。"}], "explanations": {"天空": "语义：天空不能装可乐，句子说不通。", "杯": "杯是盛饮料的器皿，“杯里的可乐”指装在杯子里的可乐，句子通顺。", "手指": "语义：手指不能盛可乐，句子说不通。", "时间": "搭配：“里”要求能装东西的地方，时间不能说“时间里的可乐”。"}, "sentence_index": 6, "correct_answer": "杯"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "天黑了，他打开杯照亮房间。", "explanation": "这里应该用〈灯〉。照明要用灯，杯子不能用来照亮。"}, {"text": "妈妈用杯切菜。", "explanation": "这里应该用〈刀〉。切菜要用刀，杯子不能用来切东西。"}, {"text": "他用杯剪指甲。", "explanation": "这里应该用〈指甲刀〉。剪指甲要用指甲刀，杯子不能用来剪东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c224d9-282f-454c-a3fa-811ceaaad6bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90980, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张杯是圆柱形的。", "corrected_sentence": "这只杯是圆柱形的。", "error_description": "量词错误：“杯”应用“只”，不能用“张”。正确：“这只杯是圆柱形的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c224d9-282f-454c-a3fa-811ceaaad6bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90980, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "服务员把一片杯端到桌上了。", "corrected_sentence": "服务员把一只杯端到桌上了。", "error_description": "量词错误：“杯”前不能用“片”（片多用于薄而平的东西），应说“一只杯”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '57c224d9-282f-454c-a3fa-811ceaaad6bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
