INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90981, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "天刚亮的那一段时间。", "primary_collocate": null, "pronunciation": "zǎo chén", "ipa": "tsɑʊ˨˩˦ ʈʂʰən˧˥", "syllable_count": 2, "sentences": [{"text": "早晨一到，鸟儿就开始叫了。", "target_word": "早晨", "complexity_tier": "T3", "furigana": "zǎo chen", "sentence_source": "generated"}, {"text": "夏天的早晨，天亮得很早。", "target_word": "早晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里的早晨，空气又凉又新鲜。", "target_word": "早晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早晨的太阳慢慢从东边出来。", "target_word": "早晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢在早晨出去走走，那时候空气特别清新。", "target_word": "早晨", "complexity_tier": "T3", "furigana": "zǎo chen", "sentence_source": "generated"}, {"text": "清冷的早晨，街上还没有人。", "target_word": "早晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在一个下雪的早晨，他离开了家。", "target_word": "早晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民们在早晨的薄雾里就下地干活。", "target_word": "早晨", "complexity_tier": "T3", "furigana": "zǎo chen", "sentence_source": "generated"}, {"text": "早晨的海边很安静，只有风声。", "target_word": "早晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早晨草上有一层白白的霜。", "target_word": "早晨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个早晨", "label": "量词"}], "register": "中性", "sense_fingerprint": "天刚亮时的清早，强调日出前后的景象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ce09844-0065-49c3-b8ad-6ca918984161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90981, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "太阳", "is_correct": false, "explanation": "语义：“太阳”指天体，不指一段时间，与“一到”所表达的时段含义不合。"}, {"text": "午饭", "is_correct": false, "explanation": "语义：“午饭”是一顿饭，不是天刚亮的时段，与“鸟儿就开始叫”不合。"}, {"text": "早晨", "is_correct": true, "explanation": "正确：“早晨”指天刚亮的那一段时间，可以说“早晨一到”。"}, {"text": "深夜", "is_correct": false, "explanation": "语义：“深夜”指夜深人静之时，与“鸟儿就开始叫”的清晨情境不合。"}], "explanations": {"太阳": "语义：“太阳”指天体，不指一段时间，与“一到”所表达的时段含义不合。", "午饭": "语义：“午饭”是一顿饭，不是天刚亮的时段，与“鸟儿就开始叫”不合。", "早晨": "正确：“早晨”指天刚亮的那一段时间，可以说“早晨一到”。", "深夜": "语义：“深夜”指夜深人静之时，与“鸟儿就开始叫”的清晨情境不合。"}, "sentence_index": 0, "correct_answer": "早晨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在山上住了一只早晨。", "explanation": "这里应该用〈个〉。“早晨”是时段，不用“只”，“只”用于动物。"}, {"text": "他在窗边坐了一张早晨。", "explanation": "这里应该用〈个〉。“张”用于纸、床等平面物，不能用来数时段。"}, {"text": "我们在湖边走了一条早晨。", "explanation": "这里应该用〈个〉。“条”用于长形物品，不能用来数“早晨”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90981, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "暑假", "is_correct": false, "explanation": "语义：“暑假”在夏季，与“下雪”矛盾。"}, {"text": "炎夏", "is_correct": false, "explanation": "语域：“炎夏”偏书面，且指炎热的夏季，与“下雪”矛盾。"}, {"text": "烈日", "is_correct": false, "explanation": "语义：“烈日”指炎热的太阳，与“下雪”矛盾。"}, {"text": "早晨", "is_correct": true, "explanation": "正确：“早晨”可以与“一个下雪的”搭配，符合句意。"}], "explanations": {"暑假": "语义：“暑假”在夏季，与“下雪”矛盾。", "炎夏": "语域：“炎夏”偏书面，且指炎热的夏季，与“下雪”矛盾。", "烈日": "语义：“烈日”指炎热的太阳，与“下雪”矛盾。", "早晨": "正确：“早晨”可以与“一个下雪的”搭配，符合句意。"}, "sentence_index": 6, "correct_answer": "早晨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们早晨十二点到家。", "explanation": "这里应该用〈中午〉。“早晨”指天刚亮的时段，十二点不是早晨。"}, {"text": "他早晨下午三点还在工作。", "explanation": "这里应该用〈下午〉。“早晨”指天刚亮的时段，与“下午三点”冲突，应只说“下午三点”。"}, {"text": "早晨晚上九点，我们去散步。", "explanation": "这里应该用〈晚上〉。“早晨”与“晚上九点”冲突，应只说“晚上九点”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90981, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在公园里等了一把早晨，然后回家了。", "corrected_sentence": "我在公园里等了一个早晨，然后回家了。", "error_description": "错误：量词“把”用于有柄的器具，不能用来数“早晨”。正确应为“一个早晨”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90981, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在院子里站了一场早晨，然后走了。", "corrected_sentence": "他在院子里站了一个早晨，然后走了。", "error_description": "错误：量词“场”用于雨、比赛等事件，不能用来数“早晨”。正确应为“一个早晨”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
