INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90982, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "从天亮到上午八九点钟的一段时间。", "primary_collocate": null, "pronunciation": "zǎo chén", "ipa": "tsɑʊ˨˩˦ ʈʂʰən˧˥", "syllable_count": 2, "sentences": [{"text": "每天早晨我都喝一杯牛奶。", "target_word": "早晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早晨八点，孩子们已经到学校了。", "target_word": "早晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天早晨我坐公共汽车去上班。", "target_word": "早晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他早晨要先吃饭，然后去工作。", "target_word": "早晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末的早晨，爸爸在家做饭。", "target_word": "早晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们明天早晨九点见面。", "target_word": "早晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她每个早晨都去公园走路。", "target_word": "早晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早晨的公园里有很多老人。", "target_word": "早晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天早晨下了一场小雨。", "target_word": "早晨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我早晨一般吃面包，不吃米饭。", "target_word": "早晨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个早晨", "label": "量词"}], "register": "中性", "sense_fingerprint": "从天亮到上午八九点的整段早上时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ce09844-0065-49c3-b8ad-6ca918984161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90982, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "去年", "is_correct": false, "explanation": "语义：“去年”是一个确定的年份，不能与“每天”搭配。"}, {"text": "早晨", "is_correct": true, "explanation": "正确：“早晨”是每天都有的一段时间，符合“每天……我都”。"}, {"text": "星期一", "is_correct": false, "explanation": "搭配：“每天”指每一天，不与“星期一”这类具体日期搭配。"}, {"text": "晨曦", "is_correct": false, "explanation": "语域：“晨曦”偏书面，指曙光，不指一段时间。"}], "explanations": {"去年": "语义：“去年”是一个确定的年份，不能与“每天”搭配。", "早晨": "正确：“早晨”是每天都有的一段时间，符合“每天……我都”。", "星期一": "搭配：“每天”指每一天，不与“星期一”这类具体日期搭配。", "晨曦": "语域：“晨曦”偏书面，指曙光，不指一段时间。"}, "sentence_index": 0, "correct_answer": "早晨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "天很晚了，你早晨睡吧，明天还要上班。", "explanation": "这里应该用〈早点〉。“早点”表示提前、早一些，“早晨”指天亮到上午八九点的时段，不能表示“提前”。"}, {"text": "我们早晨十二点吃午饭。", "explanation": "这里应该用〈中午〉。“早晨”指天刚亮到上午八九点的时段，十二点是中午。"}, {"text": "街上早晨下午一点还很热闹。", "explanation": "这里应该用〈下午〉。“早晨”指天亮到上午八九点的时段，与“下午一点”冲突，应只说“下午一点”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90982, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "烟雾", "is_correct": false, "explanation": "语义：“烟雾”是空气中的颗粒，不是时段，与“每个……都去公园”不合。"}, {"text": "早饭", "is_correct": false, "explanation": "搭配：“每个”不与“早饭”组合，应说“每顿早饭”。"}, {"text": "早晨", "is_correct": true, "explanation": "正确：“每个早晨”指每一个清早，符合句意。"}, {"text": "晨光", "is_correct": false, "explanation": "语域：“晨光”偏书面，指光线，不指时段。"}], "explanations": {"烟雾": "语义：“烟雾”是空气中的颗粒，不是时段，与“每个……都去公园”不合。", "早饭": "搭配：“每个”不与“早饭”组合，应说“每顿早饭”。", "早晨": "正确：“每个早晨”指每一个清早，符合句意。", "晨光": "语域：“晨光”偏书面，指光线，不指时段。"}, "sentence_index": 6, "correct_answer": "早晨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们昨天在公园里待了一只早晨。", "explanation": "这里应该用〈个〉。“早晨”是时段，量词用“个”，“只”一般用于动物。"}, {"text": "他睡了一张早晨，中午才起床。", "explanation": "这里应该用〈个〉。“张”用于纸、床等平面物，不能用来数时段。"}, {"text": "我们在这里度过了一条早晨。", "explanation": "这里应该用〈个〉。“条”用于长形物品，不能用来数“早晨”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90982, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在公园里等了一场早晨，然后回家了。", "corrected_sentence": "我在公园里等了一个早晨，然后回家了。", "error_description": "错误：量词“场”用于雨、比赛等事件，不能用来数“早晨”。正确应为“一个早晨”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90982, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在家里休息了一只早晨。", "corrected_sentence": "他在家里休息了一个早晨。", "error_description": "错误：量词“只”用于动物，不能用来数“早晨”。正确应为“一个早晨”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
