INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90983, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "钓鱼是用鱼竿和鱼钩把水里的鱼拉上来。", "primary_collocate": null, "pronunciation": "diào yú", "ipa": "tjaʊ̯˥˩ y˧˥", "syllable_count": 2, "sentences": [{"text": "他用鱼竿钓鱼，一下就拉上来一条大鱼。", "target_word": "钓鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钓鱼时，鱼一咬钩就要马上拉起来。", "target_word": "钓鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明坐在水边钓鱼，已经三个小时了。", "target_word": "钓鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹第一次钓鱼，高兴得大叫起来。", "target_word": "钓鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拿着鱼竿去池塘钓鱼。", "target_word": "钓鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水里的鱼很多，我们在桥下钓鱼。", "target_word": "钓鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钓鱼的人慢慢把鱼竿往上提。", "target_word": "钓鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他钓鱼很有耐心，一动不动地等着。", "target_word": "钓鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我们在河里钓鱼，鱼很大。", "target_word": "钓鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "叔叔会钓鱼，总能把鱼从水里拉上来。", "target_word": "钓鱼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "钓过鱼", "label": "体标"}, {"form": "钓鱼竿", "label": "复合"}], "register": "口语", "sense_fingerprint": "用鱼竿和鱼钩把水里的鱼拉上来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa66c51-d2c5-4935-9b03-31cebe5b34a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90983, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "钓鱼", "is_correct": true, "explanation": "正确：用鱼竿和鱼钩把水里的鱼拉上来，与“一下就拉上来一条大鱼”相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”不用鱼竿，“用鱼竿”与“游泳”的动作不合。"}, {"text": "打鼓", "is_correct": false, "explanation": "语义：“打鼓”不用鱼竿，句中“拉上来一条大鱼”说明是钓鱼。"}, {"text": "切菜", "is_correct": false, "explanation": "搭配：“用鱼竿”不能用来切菜，“切菜”与句中的工具不搭配。"}], "explanations": {"钓鱼": "正确：用鱼竿和鱼钩把水里的鱼拉上来，与“一下就拉上来一条大鱼”相符。", "游泳": "语义：“游泳”不用鱼竿，“用鱼竿”与“游泳”的动作不合。", "打鼓": "语义：“打鼓”不用鱼竿，句中“拉上来一条大鱼”说明是钓鱼。", "切菜": "搭配：“用鱼竿”不能用来切菜，“切菜”与句中的工具不搭配。"}, "sentence_index": 0, "correct_answer": "钓鱼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "渔船在海上用大网钓鱼，一次能拉上来好几吨。", "explanation": "这里应该用〈捕捞〉。钓鱼用鱼竿和鱼钩，成批地用大网拉鱼要说〈捕捞〉。"}, {"text": "孩子们在小溪里用手钓鱼，抓到了好几条。", "explanation": "这里应该用〈摸鱼〉。钓鱼要用鱼竿，用手在水里摸鱼要说〈摸鱼〉。"}, {"text": "他潜水用鱼叉钓鱼，抓到了一条大鱼。", "explanation": "这里应该用〈叉鱼〉。钓鱼不用鱼叉，潜水用鱼叉捕鱼要说〈叉鱼〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90983, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "钓鱼", "is_correct": true, "explanation": "正确：钓鱼的人用鱼竿把鱼拉上来，与“慢慢把鱼竿往上提”相符。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：“跳舞”与“慢慢把鱼竿往上提”的动作不合，句中的人是在钓鱼。"}, {"text": "写字", "is_correct": false, "explanation": "搭配：“写字”与“把鱼竿往上提”不搭配，句中的动作是垂钓。"}, {"text": "跑步", "is_correct": false, "explanation": "语义：“跑步”与“慢慢把鱼竿往上提”的动作不合，句中的人是在钓鱼。"}], "explanations": {"钓鱼": "正确：钓鱼的人用鱼竿把鱼拉上来，与“慢慢把鱼竿往上提”相符。", "跳舞": "语义：“跳舞”与“慢慢把鱼竿往上提”的动作不合，句中的人是在钓鱼。", "写字": "搭配：“写字”与“把鱼竿往上提”不搭配，句中的动作是垂钓。", "跑步": "语义：“跑步”与“慢慢把鱼竿往上提”的动作不合，句中的人是在钓鱼。"}, "sentence_index": 6, "correct_answer": "钓鱼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈在厨房里钓鱼，准备晚上的饭菜。", "explanation": "这里应该用〈做饭〉。钓鱼是在水边用鱼竿捕鱼，在厨房里准备饭菜要说〈做饭〉。"}, {"text": "猎人在山上钓鱼，带回了一只野兔。", "explanation": "这里应该用〈打猎〉。钓鱼是在水中捕鱼，猎人在山上捕获野兔要说〈打猎〉。"}, {"text": "农民在池塘里钓鱼，每年能卖好几吨。", "explanation": "这里应该用〈养鱼〉。钓鱼是一条一条地钓，成吨地养殖并出售要说〈养鱼〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90983, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "爸爸年轻时过钓鱼。", "corrected_sentence": "爸爸年轻时钓过鱼。", "error_description": "错误：体标“过”不能放在动词之前，“过钓鱼”不成立；应说“钓过鱼”，“过”紧跟动词“钓”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90983, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "叔叔钓鱼钓很得好。", "corrected_sentence": "叔叔钓鱼钓得很好。", "error_description": "语序错误：程度补语的“得”应紧跟动词，应说“钓鱼钓得很好”，不能说“钓鱼钓很得好”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
