INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90984, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用钓竿、鱼钩和饵诱捕鱼类。", "primary_collocate": null, "pronunciation": "diào yú", "ipa": "tjaʊ̯˥˩ y˧˥", "syllable_count": 2, "sentences": [{"text": "他在河边钓鱼，用面包当鱼饵。", "target_word": "钓鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末爸爸带我去湖边钓鱼。", "target_word": "钓鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钓鱼要先把饵挂在鱼钩上。", "target_word": "钓鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢钓鱼，每个星期都去河边。", "target_word": "钓鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天没带鱼竿，我们没法钓鱼。", "target_word": "钓鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钓鱼的时候要安静，不能大声说话。", "target_word": "钓鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷坐在小船上钓鱼，一坐就是半天。", "target_word": "钓鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想钓鱼，所以买了鱼钩和鱼饵。", "target_word": "钓鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天他们在冰上钓鱼，穿得很厚。", "target_word": "钓鱼", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我第一次钓鱼，等了一个小时没有鱼上钩。", "target_word": "钓鱼", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "钓过鱼", "label": "体标"}, {"form": "钓鱼竿", "label": "复合"}], "register": "中性", "sense_fingerprint": "用钓竿、鱼钩和鱼饵诱捕鱼类", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8fa66c51-d2c5-4935-9b03-31cebe5b34a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90984, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "钓鱼", "is_correct": true, "explanation": "正确：钓鱼是用鱼竿和鱼钩诱捕鱼，与“用面包当鱼饵”相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：“游泳”是在水里运动身体，不需要用面包当鱼饵，与句意不合。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“散步”不需要鱼饵，“用面包当鱼饵”说明句中的活动是钓鱼。"}, {"text": "烤肉", "is_correct": false, "explanation": "搭配：“烤肉”与“用面包当鱼饵”不搭配，句中的活动是垂钓。"}], "explanations": {"钓鱼": "正确：钓鱼是用鱼竿和鱼钩诱捕鱼，与“用面包当鱼饵”相符。", "游泳": "语义：“游泳”是在水里运动身体，不需要用面包当鱼饵，与句意不合。", "散步": "语义：“散步”不需要鱼饵，“用面包当鱼饵”说明句中的活动是钓鱼。", "烤肉": "搭配：“烤肉”与“用面包当鱼饵”不搭配，句中的活动是垂钓。"}, "sentence_index": 0, "correct_answer": "钓鱼"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人在河里钓鱼，一早上清理了很多垃圾。", "explanation": "这里应该用〈打捞〉。钓鱼是用鱼竿和鱼钩把鱼拉上来，把水里的垃圾捞起来要说〈打捞〉。"}, {"text": "他用手在河边钓鱼，抓到了好几条。", "explanation": "这里应该用〈摸鱼〉。钓鱼必须用鱼竿和鱼钩，用手在水里抓鱼要说〈摸鱼〉。"}, {"text": "这家农场在池塘里钓鱼，每年卖几百斤。", "explanation": "这里应该用〈养鱼〉。钓鱼是捕鱼，不是养殖，成批养殖并出售要说〈养鱼〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90984, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "钓鱼", "is_correct": true, "explanation": "正确：“坐在小船上钓鱼”，一坐就是半天，符合句意。"}, {"text": "跳舞", "is_correct": false, "explanation": "语义：“跳舞”不能坐在小船上进行，与“一坐就是半天”的描述不合。"}, {"text": "跑步", "is_correct": false, "explanation": "语义：“跑步”需要站立移动，不能坐在小船上一坐半天。"}, {"text": "跳高", "is_correct": false, "explanation": "语义：跳高要起跳，不能坐在小船上一坐半天。"}], "explanations": {"钓鱼": "正确：“坐在小船上钓鱼”，一坐就是半天，符合句意。", "跳舞": "语义：“跳舞”不能坐在小船上进行，与“一坐就是半天”的描述不合。", "跑步": "语义：“跑步”需要站立移动，不能坐在小船上一坐半天。", "跳高": "语义：跳高要起跳，不能坐在小船上一坐半天。"}, "sentence_index": 6, "correct_answer": "钓鱼"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "渔夫用网在池塘里钓鱼，一次能捞上来很多。", "explanation": "这里应该用〈捞鱼〉。钓鱼用鱼竿和鱼钩，用网在水里捞鱼要说〈捞鱼〉。"}, {"text": "潜水员用鱼叉钓鱼，叉到了一条大鱼。", "explanation": "这里应该用〈叉鱼〉。钓鱼不用鱼叉，用鱼叉捕鱼要说〈叉鱼〉。"}, {"text": "妈妈在厨房里钓鱼，准备做晚饭。", "explanation": "这里应该用〈烹饪〉。钓鱼是在水边用鱼竿捕鱼，不能用于厨房里的烹饪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90984, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我以前过钓鱼。", "corrected_sentence": "我以前钓过鱼。", "error_description": "错误：体标“过”不能放在动词之前，“过钓鱼”不成立；应说“钓过鱼”，“过”紧跟动词“钓”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90984, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他一早就去湖边钓鱼了鱼。", "corrected_sentence": "他一早就去湖边钓了鱼。", "error_description": "离合词错误：“钓鱼”的宾语“鱼”只能出现一次，应说“钓了鱼”；这里在“钓鱼”之后又多出一个“鱼”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f28db1bd-e4f7-4a6e-88bc-6b66dd49ced6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
