INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90986, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "故意致人死亡。", "primary_collocate": null, "pronunciation": "shā rén", "ipa": "ʂa˥ ʐən˧˥", "syllable_count": 2, "sentences": [{"text": "法律规定，故意杀人要受到严厉的处罚。", "target_word": "杀人", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他故意杀人，法院判了他二十年。", "target_word": "杀人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "警察查清了他杀人的原因。", "target_word": "杀人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "杀人要负法律责任。", "target_word": "杀人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他说自己没有杀人。", "target_word": "杀人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "证人说，他亲眼看见那个人杀人。", "target_word": "杀人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "电影里常有杀人的情节。", "target_word": "杀人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他杀人后很害怕，不敢回家。", "target_word": "杀人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法官问他为什么要杀人。", "target_word": "杀人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了钱杀人，是不能原谅的。", "target_word": "杀人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "杀人犯", "label": "复合"}, {"form": "杀人案", "label": "复合"}], "register": "中性", "sense_fingerprint": "故意使他人死亡，法律意义上的行为", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '336a0206-f607-4671-866d-44fb53eddaab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
