INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90986, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "杀人", "is_correct": true, "explanation": "杀人：致人死亡，是常见的犯罪题材，与“情节”相符。"}, {"text": "缴费", "is_correct": false, "explanation": "语义：缴费是日常生活事务，不构成影视剧中的常见情节，句子意思不通。"}, {"text": "打印", "is_correct": false, "explanation": "语义：打印是办公操作，与“电影里常有……的情节”的语境不符。"}, {"text": "杀", "is_correct": false, "explanation": "配价：“杀”必须带宾语（如“杀人”），单独作“的情节”的定语时宾语缺失，句子不成立。"}], "explanations": {"杀人": "杀人：致人死亡，是常见的犯罪题材，与“情节”相符。", "缴费": "语义：缴费是日常生活事务，不构成影视剧中的常见情节，句子意思不通。", "打印": "语义：打印是办公操作，与“电影里常有……的情节”的语境不符。", "杀": "配价：“杀”必须带宾语（如“杀人”），单独作“的情节”的定语时宾语缺失，句子不成立。"}, "sentence_index": 6, "correct_answer": "杀人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "工人在山上杀人，把大树一棵棵砍倒了。", "explanation": "这里应该用〈砍伐〉。杀人指害死人，砍树要说“砍伐”，不能用“杀人”。"}, {"text": "护士用酒精给针头杀人。", "explanation": "这里应该用〈杀菌〉。用酒精消灭细菌要说“杀菌”，杀人是致人死亡。"}, {"text": "这件衣服我跟老板杀人，便宜了十块。", "explanation": "这里应该用〈杀价〉。杀价指讨价还价压低价格，杀人是致人死亡，与讨价无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c49f556-4b6a-4ac8-966b-a2069f0026a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90986, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他被杀人了，案件正在调查。", "corrected_sentence": "他被人杀了，案件正在调查。", "error_description": "错误：“被杀人了”；正确：“被人杀了”。“杀人”是动宾结构，用在“被”字句中，施事“人”要放到动词前，应说“被人杀了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c49f556-4b6a-4ac8-966b-a2069f0026a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90986, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把杀人了，然后去自首了。", "corrected_sentence": "他把人杀了，然后去自首了。", "error_description": "错误：“把杀人了”；正确：“把人杀了”。“把”字句中，宾语“人”要放在“把”后、动词前，不能把“杀人”整体放在“把”后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c49f556-4b6a-4ac8-966b-a2069f0026a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90987, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "亮", "is_correct": true, "explanation": "正确。“亮”与“暗”在光线义上相反，是反义词。"}, {"text": "热", "is_correct": false, "explanation": "“热”与“冷”相对，与“暗”（光线不足）无反义关系。"}, {"text": "深", "is_correct": false, "explanation": "“深”与“浅”相对，与“暗”无反义关系。"}, {"text": "快", "is_correct": false, "explanation": "“快”与“慢”相对，与“暗”无反义关系。"}], "correct_answer": "亮", "explanations": {"亮": "正确。“亮”与“暗”在光线义上相反，是反义词。", "热": "“热”与“冷”相对，与“暗”（光线不足）无反义关系。", "深": "“深”与“浅”相对，与“暗”无反义关系。", "快": "“快”与“慢”相对，与“暗”无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11e86a06-4236-491b-bd68-3cf176847259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90987, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "亮", "is_correct": true, "explanation": "正确。“亮”与“暗”在光线义上相反，是反义词。"}, {"text": "远", "is_correct": false, "explanation": "“远”与“近”相对，与“暗”无反义关系。"}, {"text": "硬", "is_correct": false, "explanation": "“硬”与“软”相对，与“暗”无反义关系。"}, {"text": "矮", "is_correct": false, "explanation": "“矮”与“高”相对，与“暗”无反义关系。"}], "correct_answer": "亮", "explanations": {"亮": "正确。“亮”与“暗”在光线义上相反，是反义词。", "远": "“远”与“近”相对，与“暗”无反义关系。", "硬": "“硬”与“软”相对，与“暗”无反义关系。", "矮": "“矮”与“高”相对，与“暗”无反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11e86a06-4236-491b-bd68-3cf176847259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90987, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有光，看不清楚。", "primary_collocate": null, "pronunciation": "àn", "ipa": "an˥˩", "syllable_count": 1, "sentences": [{"text": "屋里没有灯，太暗了，我看不清。", "target_word": "暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上路很暗，你要小心。", "target_word": "暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "房间里很暗，我什么都看不见。", "target_word": "暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天暗了，我们快回家吧。", "target_word": "暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "停电以后，家里一下子暗了。", "target_word": "暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条小路又窄又暗，我不敢走。", "target_word": "暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山洞里很暗，我们要带着手电筒。", "target_word": "暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里太暗，我找不到钥匙。", "target_word": "暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他关了灯，屋子马上暗下来。", "target_word": "暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下室很暗，看不清楚墙上的字。", "target_word": "暗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "暗了", "label": "体标"}, {"form": "黑暗", "label": "复合"}, {"form": "昏暗", "label": "复合"}], "register": "中性", "sense_fingerprint": "没有光线，以致看不清东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fc88ea3-cc81-44ee-a2a6-03befb6fb706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90987, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "暗", "is_correct": true, "explanation": "正确。àn 表示没有光、看不清楚。"}, {"text": "安", "is_correct": false, "explanation": "ān（第一声）与 àn（第四声）只有声调不同，意思是平安。"}, {"text": "俺", "is_correct": false, "explanation": "ǎn（第三声）与 àn（第四声）只有声调不同，意思是“我”（北方方言）。"}, {"text": "盎", "is_correct": false, "explanation": "àng（第四声）与 àn 只差韵尾（ng／n），声调相同，意思是充溢，如“盎然”。"}, {"text": "爱", "is_correct": false, "explanation": "ài（第四声）与 àn 韵尾不同（i／n），声调相同，意思是喜爱。"}], "explanations": {"暗": "正确。àn 表示没有光、看不清楚。", "安": "ān（第一声）与 àn（第四声）只有声调不同，意思是平安。", "俺": "ǎn（第三声）与 àn（第四声）只有声调不同，意思是“我”（北方方言）。", "盎": "àng（第四声）与 àn 只差韵尾（ng／n），声调相同，意思是充溢，如“盎然”。", "爱": "ài（第四声）与 àn 韵尾不同（i／n），声调相同，意思是喜爱。"}, "sentence_index": null, "correct_answer": "暗"}, "level_3": {"options": [{"text": "暗", "is_correct": true, "explanation": "正确。“暗”表示没有光、看不清，与“太暗了，我看不清”相符。"}, {"text": "宽", "is_correct": false, "explanation": "搭配：“宽”说空间的大小，与光线无关，“屋里太宽”与“看不清”不相符。"}, {"text": "咸", "is_correct": false, "explanation": "搭配：“咸”形容味道，不能用来形容屋里的光线。"}, {"text": "清楚", "is_correct": false, "explanation": "语义：“清楚”与“我看不清”直接矛盾，且与“没有灯”的语境不符。"}], "explanations": {"暗": "正确。“暗”表示没有光、看不清，与“太暗了，我看不清”相符。", "宽": "搭配：“宽”说空间的大小，与光线无关，“屋里太宽”与“看不清”不相符。", "咸": "搭配：“咸”形容味道，不能用来形容屋里的光线。", "清楚": "语义：“清楚”与“我看不清”直接矛盾，且与“没有灯”的语境不符。"}, "sentence_index": 0, "correct_answer": "暗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他暗中帮了我很多忙，我一直不知道。", "explanation": "这里“暗”表示“暗中、不公开”，与“没有光、看不清楚”的意思不同。"}, {"text": "他的话暗示我们该早点回家。", "explanation": "这里“暗”表示“含蓄地示意”，与“没有光”的意思不同。"}, {"text": "他暗恋班里的一个女生，一直没有告诉她。", "explanation": "这里“暗”表示“心里偷偷地喜欢”，与“光线不足”无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11e86a06-4236-491b-bd68-3cf176847259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90987, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "暗", "is_correct": true, "explanation": "正确。“暗”表示光线不足，与“山洞里很暗，要带着手电筒”相符。"}, {"text": "明亮", "is_correct": false, "explanation": "语义：“明亮”与“很暗”相反，且与“要带着手电筒”的理由相矛盾。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”形容水，不用来形容山洞里的光线。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不用来形容山洞或光线。"}], "explanations": {"暗": "正确。“暗”表示光线不足，与“山洞里很暗，要带着手电筒”相符。", "明亮": "语义：“明亮”与“很暗”相反，且与“要带着手电筒”的理由相矛盾。", "清澈": "搭配：“清澈”形容水，不用来形容山洞里的光线。", "甜": "搭配：“甜”形容味道，不用来形容山洞或光线。"}, "sentence_index": 6, "correct_answer": "暗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她暗暗下定了决心，要努力学习。", "explanation": "这里“暗暗”表示“在心里偷偷地”，与“光线不足”的意思不同。"}, {"text": "他听了我的话，暗笑了一下。", "explanation": "这里“暗”表示“偷偷地”，与“没有光、看不清楚”的意思不同。"}, {"text": "这家公司的前途很暗，大家都在找新工作。", "explanation": "这里“暗”表示“没有希望、前景不好”（暗淡），不是“光线不足”的意思。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11e86a06-4236-491b-bd68-3cf176847259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90987, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "太阳落山了，院子里渐渐暗出来。", "corrected_sentence": "太阳落山了，院子里渐渐暗下来。", "error_description": "错误：补语“出来”。表示光线逐渐变暗的趋向应说“暗下来”，“暗出来”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11e86a06-4236-491b-bd68-3cf176847259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90987, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个很暗角落没人愿意去。", "corrected_sentence": "这个很暗的角落没人愿意去。", "error_description": "错误：漏掉“的”。“很暗”修饰名词“角落”时中间要加“的”，应说“很暗的角落”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11e86a06-4236-491b-bd68-3cf176847259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
