INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90988, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "光线不足，不明亮。", "primary_collocate": null, "pronunciation": "àn", "ipa": "an˥˩", "syllable_count": 1, "sentences": [{"text": "这盏灯太暗，不能看书。", "target_word": "暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的房间朝北，光线有点暗。", "target_word": "暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屏幕太暗，我调亮一点。", "target_word": "暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家餐厅的灯很暗，很有气氛。", "target_word": "暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "阴天的时候，教室里比平时暗。", "target_word": "暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张照片拍得太暗了。", "target_word": "暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗户太小，客厅里有点暗。", "target_word": "暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯泡旧了，光越来越暗。", "target_word": "暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你把灯调亮一点，这里有点暗。", "target_word": "暗", "complexity_tier": "T3", "furigana": "nǐ bǎ dēng tiáoliàng yìdiǎn, zhèlǐ yǒudiǎn àn.", "sentence_source": "generated"}, {"text": "电影院里比较暗，大家都很安静。", "target_word": "暗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "暗了", "label": "体标"}, {"form": "黑暗", "label": "复合"}, {"form": "昏暗", "label": "复合"}], "register": "中性", "sense_fingerprint": "光线不够强，不明亮", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1fc88ea3-cc81-44ee-a2a6-03befb6fb706') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90988, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "暗", "is_correct": true, "explanation": "正确。àn 表示光线不足、不明亮。"}, {"text": "安", "is_correct": false, "explanation": "ān（第一声）与 àn（第四声）只有声调不同，意思是平安。"}, {"text": "俺", "is_correct": false, "explanation": "ǎn（第三声）与 àn（第四声）只有声调不同，意思是“我”（北方方言）。"}, {"text": "盎", "is_correct": false, "explanation": "àng（第四声）与 àn 只差韵尾（ng／n），声调相同，意思是充溢，如“盎然”。"}, {"text": "爱", "is_correct": false, "explanation": "ài（第四声）与 àn 韵尾不同（i／n），声调相同，意思是喜爱。"}], "explanations": {"暗": "正确。àn 表示光线不足、不明亮。", "安": "ān（第一声）与 àn（第四声）只有声调不同，意思是平安。", "俺": "ǎn（第三声）与 àn（第四声）只有声调不同，意思是“我”（北方方言）。", "盎": "àng（第四声）与 àn 只差韵尾（ng／n），声调相同，意思是充溢，如“盎然”。", "爱": "ài（第四声）与 àn 韵尾不同（i／n），声调相同，意思是喜爱。"}, "sentence_index": null, "correct_answer": "暗"}, "level_3": {"options": [{"text": "暗", "is_correct": true, "explanation": "正确。“暗”表示光线不足，与“这盏灯太暗，不能看书”相符。"}, {"text": "吵", "is_correct": false, "explanation": "语义：灯不会发出声音，“吵”与“不能看书”的理由不通。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不用来形容灯的亮度。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”形容人或动物的身材，不用来形容灯。"}], "explanations": {"暗": "正确。“暗”表示光线不足，与“这盏灯太暗，不能看书”相符。", "吵": "语义：灯不会发出声音，“吵”与“不能看书”的理由不通。", "甜": "搭配：“甜”形容味道，不用来形容灯的亮度。", "瘦": "体貌：“瘦”形容人或动物的身材，不用来形容灯。"}, "sentence_index": 0, "correct_answer": "暗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他暗自高兴，却没有告诉别人。", "explanation": "这里“暗自”表示“私下、不让人知道”，与“光线不足”的意思不同。"}, {"text": "他暗暗记住了这个地址。", "explanation": "这里“暗暗”表示“私下、不让人知道”，与“光线不足”的意思不同。"}, {"text": "他在心里暗骂了一句，但没有说出来。", "explanation": "这里“暗骂”表示“在心里偷偷地骂”，与“光线不足”无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11e86a06-4236-491b-bd68-3cf176847259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXC