INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90988, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "暗", "is_correct": true, "explanation": "正确。“暗”表示光线不足，与“窗户太小，客厅里有点暗”相符。"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”形容人或动物的身材，不用来形容客厅。"}, {"text": "饿", "is_correct": false, "explanation": "搭配：“饿”形容人的饥饱，不用来形容房间。"}, {"text": "软", "is_correct": false, "explanation": "搭配：“软”形容质地，不用来形容房间的光线。"}], "explanations": {"暗": "正确。“暗”表示光线不足，与“窗户太小，客厅里有点暗”相符。", "胖": "体貌：“胖”形容人或动物的身材，不用来形容客厅。", "饿": "搭配：“饿”形容人的饥饱，不用来形容房间。", "软": "搭配：“软”形容质地，不用来形容房间的光线。"}, "sentence_index": 6, "correct_answer": "暗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他看着我，暗笑着摇了摇头。", "explanation": "这里“暗笑”表示“偷偷地笑”，“暗”不表示光线不足。"}, {"text": "他暗中帮我联系了一份工作。", "explanation": "这里“暗”表示“暗中、不公开”，与“不明亮”的意思不同。"}, {"text": "他暗地里托人打听消息。", "explanation": "这里“暗”表示“私下、不公开”，与“光线不足”无关。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11e86a06-4236-491b-bd68-3cf176847259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90988, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条走廊朝北，光线比客厅很暗。", "corrected_sentence": "这条走廊朝北，光线比客厅暗。", "error_description": "错误：“比客厅很暗”。“比”字句中形容词“暗”前不能加“很”，应说“比客厅暗”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '11e86a06-4236-491b-bd68-3cf176847259') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
