INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90989, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "防卫是保护自己，不让坏人伤害。", "primary_collocate": null, "pronunciation": "fáng wèi", "ipa": "faŋ˧˥ weɪ˥˩", "syllable_count": 2, "sentences": [{"text": "他为了防卫自己，拿起了一根木棍。", "target_word": "防卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里走路，她随身带着防狼喷雾来防卫自己。", "target_word": "防卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面对坏人，小李只能防卫，不能先动手。", "target_word": "防卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教女孩们怎么防卫自己。", "target_word": "防卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是为了防卫才打了对方。", "target_word": "防卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到坏人时，他先防卫自己，再大声喊人。", "target_word": "防卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她学过一点功夫，可以防卫自己。", "target_word": "防卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到危险时，要学会防卫自己。", "target_word": "防卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他只是为了防卫，并不想伤人。", "target_word": "防卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她用伞防卫自己，不让坏人靠近。", "target_word": "防卫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "防卫了", "label": "体标"}, {"form": "防卫着", "label": "体标"}, {"form": "防卫过", "label": "体标"}], "register": "中性", "sense_fingerprint": "遇到坏人时保护自己、不被伤害（自卫）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b342a05-3699-4607-9d19-13216e1ae00e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90989, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "防卫", "is_correct": true, "explanation": "正确：“防卫”读作 fáng wèi，指保护自己，不让坏人伤害。"}, {"text": "方位", "is_correct": false, "explanation": "fāng（第一声）与 fáng（第二声）声调不同，意思是方向和位置。"}, {"text": "防伪", "is_correct": false, "explanation": "wěi（第三声）与 wèi（第四声）声调不同，意思是防止假冒。"}, {"text": "防务", "is_correct": false, "explanation": "wù 与 wèi 韵母不同（u／ei），声调相同，意思是国防方面的事务。"}], "explanations": {"防卫": "正确：“防卫”读作 fáng wèi，指保护自己，不让坏人伤害。", "方位": "fāng（第一声）与 fáng（第二声）声调不同，意思是方向和位置。", "防伪": "wěi（第三声）与 wèi（第四声）声调不同，意思是防止假冒。", "防务": "wù 与 wèi 韵母不同（u／ei），声调相同，意思是国防方面的事务。"}, "sentence_index": null, "correct_answer": "防卫"}, "level_3": {"options": [{"text": "防卫", "is_correct": true, "explanation": "正确：“为了防卫自己”符合句意，拿木棍是为了保护自己。"}, {"text": "逃避", "is_correct": false, "explanation": "搭配：“逃避”的对象是责任、困难等，不能说“逃避自己”。"}, {"text": "打扮", "is_correct": false, "explanation": "语义：“打扮”指装扮外貌，与“拿起一根木棍”的动作无关，句子不通。"}, {"text": "介绍", "is_correct": false, "explanation": "语义：“介绍自己”指自我介绍，与拿木棍的动作无关，句子不通。"}], "explanations": {"防卫": "正确：“为了防卫自己”符合句意，拿木棍是为了保护自己。", "逃避": "搭配：“逃避”的对象是责任、困难等，不能说“逃避自己”。", "打扮": "语义：“打扮”指装扮外貌，与“拿起一根木棍”的动作无关，句子不通。", "介绍": "语义：“介绍自己”指自我介绍，与拿木棍的动作无关，句子不通。"}, "sentence_index": 0, "correct_answer": "防卫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天防卫生病的爸爸。", "explanation": "这里应该用〈照顾〉。防卫专指抵挡来犯的坏人或伤害，不用于照料生病的人。"}, {"text": "看到车来了，他赶紧防卫。", "explanation": "这里应该用〈躲避〉。防卫是抵挡坏人的伤害，不用于躲开车辆这类意外。"}, {"text": "他每天在桌边防卫家里的花瓶。", "explanation": "这里应该用〈保护〉。防卫指抵挡来犯的人或伤害，用于人身或国土，不用于看管物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90989, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "防卫", "is_correct": true, "explanation": "正确：“防卫”读作 fáng wèi，指保护自己，不让坏人伤害。"}, {"text": "范围", "is_correct": false, "explanation": "fàn wéi：fàn 与 fáng 韵尾不同（n／ng），wéi 与 wèi 声调不同，意思是周围的界限。"}, {"text": "王位", "is_correct": false, "explanation": "wáng 与 fáng 声母不同（w／f），声调相同，意思是君主的宝座。"}, {"text": "访问", "is_correct": false, "explanation": "fǎng wèn：fǎng 与 fáng 声调不同，wèn 与 wèi 韵母不同，意思是去看望、拜访。"}], "explanations": {"防卫": "正确：“防卫”读作 fáng wèi，指保护自己，不让坏人伤害。", "范围": "fàn wéi：fàn 与 fáng 韵尾不同（n／ng），wéi 与 wèi 声调不同，意思是周围的界限。", "王位": "wáng 与 fáng 声母不同（w／f），声调相同，意思是君主的宝座。", "访问": "fǎng wèn：fǎng 与 fáng 声调不同，wèn 与 wèi 韵母不同，意思是去看望、拜访。"}, "sentence_index": null, "correct_answer": "防卫"}, "level_3": {"options": [{"text": "防卫", "is_correct": true, "explanation": "正确：“可以防卫自己”符合句意，学过功夫就能保护自己。"}, {"text": "讨论", "is_correct": false, "explanation": "搭配：“讨论”的对象是问题或事情，不能说“讨论自己”。"}, {"text": "烹饪", "is_correct": false, "explanation": "语义：“烹饪”针对食物，不能用于人自身，句子不通。"}, {"text": "操作", "is_correct": false, "explanation": "语义：“操作”针对机器或设备，不能说“操作自己”，句子不通。"}], "explanations": {"防卫": "正确：“可以防卫自己”符合句意，学过功夫就能保护自己。", "讨论": "搭配：“讨论”的对象是问题或事情，不能说“讨论自己”。", "烹饪": "语义：“烹饪”针对食物，不能用于人自身，句子不通。", "操作": "语义：“操作”针对机器或设备，不能说“操作自己”，句子不通。"}, "sentence_index": 6, "correct_answer": "防卫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把钱包紧紧防卫在怀里。", "explanation": "这里应该用〈保护〉。防卫要抵挡来犯的伤害，护住随身的东西不用“防卫”。"}, {"text": "爷爷每天防卫小孙子散步。", "explanation": "这里应该用〈陪伴〉。防卫指抵挡坏人的伤害，不用于陪家人散步。"}, {"text": "医生正在防卫病人。", "explanation": "这里应该用〈抢救〉。防卫指抵挡伤害，不用于救治病人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDE