INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90989, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从小练拳，很防卫自己。", "corrected_sentence": "他从小练拳，很会防卫自己。", "error_description": "“防卫”是动词，前面不能直接加程度副词“很”。表示能力要说“很会防卫自己”，漏掉“会”就是错误。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90989, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她为了防卫了自己，把门锁上了。", "corrected_sentence": "她为了防卫自己，把门锁上了。", "error_description": "“为了”后面的动词“防卫”不能再加“了”。“了”应放在句末，如“把门锁上了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90990, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "进攻", "is_correct": true, "explanation": "正确：“进攻”与军事上的“防卫”相对，是反义词。"}, {"text": "运输", "is_correct": false, "explanation": "运输指把物资从一地运到另一地，与“防卫”没有相反的意义，不是反义词。"}, {"text": "装饰", "is_correct": false, "explanation": "装饰指美化物品，与“防卫”没有相反的意义，不是反义词。"}, {"text": "翻译", "is_correct": false, "explanation": "翻译指转换语言，与“防卫”没有相反的意义，不是反义词。"}], "correct_answer": "进攻", "explanations": {"进攻": "正确：“进攻”与军事上的“防卫”相对，是反义词。", "运输": "运输指把物资从一地运到另一地，与“防卫”没有相反的意义，不是反义词。", "装饰": "装饰指美化物品，与“防卫”没有相反的意义，不是反义词。", "翻译": "翻译指转换语言，与“防卫”没有相反的意义，不是反义词。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
