INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90990, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "防备并保卫，抵御外来的侵犯。", "primary_collocate": null, "pronunciation": "fáng wèi", "ipa": "faŋ˧˥ weɪ˥˩", "syllable_count": 2, "sentences": [{"text": "士兵们日夜防卫着边境。", "target_word": "防卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市由军队防卫。", "target_word": "防卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们修了高高的城墙来防卫。", "target_word": "防卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小岛上只有几个士兵防卫。", "target_word": "防卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "海军负责防卫我们的海岸。", "target_word": "防卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "敌人来了，大家一起防卫村子。", "target_word": "防卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家要有力量防卫自己的土地。", "target_word": "防卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在山口防卫了三天。", "target_word": "防卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，人们用城墙防卫城市。", "target_word": "防卫", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支小队负责防卫机场。", "target_word": "防卫", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "防卫了", "label": "体标"}, {"form": "防卫着", "label": "体标"}, {"form": "防卫过", "label": "体标"}], "register": "书面语", "sense_fingerprint": "军队或人群防备并保卫地方，抵御外敌侵犯", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b342a05-3699-4607-9d19-13216e1ae00e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90990, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "防卫", "is_correct": true, "explanation": "正确：“防卫”读作 fáng wèi，指守卫并抵御外来侵犯。"}, {"text": "方位", "is_correct": false, "explanation": "fāng（第一声）与 fáng（第二声）声调不同，意思是方向和位置。"}, {"text": "防伪", "is_correct": false, "explanation": "wěi（第三声）与 wèi（第四声）声调不同，意思是防止假冒。"}, {"text": "防务", "is_correct": false, "explanation": "wù 与 wèi 韵母不同（u／ei），声调相同，意思是国防方面的事务。"}], "explanations": {"防卫": "正确：“防卫”读作 fáng wèi，指守卫并抵御外来侵犯。", "方位": "fāng（第一声）与 fáng（第二声）声调不同，意思是方向和位置。", "防伪": "wěi（第三声）与 wèi（第四声）声调不同，意思是防止假冒。", "防务": "wù 与 wèi 韵母不同（u／ei），声调相同，意思是国防方面的事务。"}, "sentence_index": null, "correct_answer": "防卫"}, "level_3": {"options": [{"text": "防卫", "is_correct": true, "explanation": "正确：“日夜防卫着边境”符合句意，士兵守卫国境。"}, {"text": "游览", "is_correct": false, "explanation": "语义：“游览”指参观景点，不能用于守卫边境，句子不通。"}, {"text": "宣传", "is_correct": false, "explanation": "搭配：“宣传”的对象是政策、思想等，不能说“宣传边境”。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：“装饰”指美化，与守卫边境无关，句子不通。"}], "explanations": {"防卫": "正确：“日夜防卫着边境”符合句意，士兵守卫国境。", "游览": "语义：“游览”指参观景点，不能用于守卫边境，句子不通。", "宣传": "搭配：“宣传”的对象是政策、思想等，不能说“宣传边境”。", "装饰": "语义：“装饰”指美化，与守卫边境无关，句子不通。"}, "sentence_index": 0, "correct_answer": "防卫"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "敌军连夜防卫我方的阵地。", "explanation": "这里应该用〈进攻〉。防卫是守卫己方、抵挡来犯的敌人；敌军要攻取我方阵地，应说“进攻”，不能说“防卫”。"}, {"text": "老师在教室里防卫学生做作业。", "explanation": "这里应该用〈辅导〉。防卫是抵御外来侵犯，不用于帮助学生学习。"}, {"text": "工人们花了三个月防卫旧城墙，把破损的墙体都修好了。", "explanation": "这里应该用〈修缮〉。防卫是抵挡侵犯、守卫领土，不用于维修或保养建筑。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90990, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "防卫", "is_correct": true, "explanation": "正确：“防卫”读作 fáng wèi，指守卫并抵御外来侵犯。"}, {"text": "范围", "is_correct": false, "explanation": "fàn wéi：fàn 与 fáng 韵尾不同（n／ng），wéi 与 wèi 声调不同，意思是周围的界限。"}, {"text": "王位", "is_correct": false, "explanation": "wáng 与 fáng 声母不同（w／f），声调相同，意思是君主的宝座。"}, {"text": "访问", "is_correct": false, "explanation": "fǎng wèn：fǎng 与 fáng 声调不同，wèn 与 wèi 韵母不同，意思是去看望、拜访。"}], "explanations": {"防卫": "正确：“防卫”读作 fáng wèi，指守卫并抵御外来侵犯。", "范围": "fàn wéi：fàn 与 fáng 韵尾不同（n／ng），wéi 与 wèi 声调不同，意思是周围的界限。", "王位": "wáng 与 fáng 声母不同（w／f），声调相同，意思是君主的宝座。", "访问": "fǎng wèn：fǎng 与 fáng 声调不同，wèn 与 wèi 韵母不同，意思是去看望、拜访。"}, "sentence_index": null, "correct_answer": "防卫"}, "level_3": {"options": [{"text": "防卫", "is_correct": true, "explanation": "正确：“国家要有力量防卫自己的土地”符合句意。"}, {"text": "拍卖", "is_correct": false, "explanation": "语义：“拍卖”是卖出物品，与“要有力量”的语境相悖，句子不通。"}, {"text": "欣赏", "is_correct": false, "explanation": "搭配：“欣赏”的对象是景色或作品，不能说“欣赏自己的土地”。"}, {"text": "品尝", "is_correct": false, "explanation": "搭配：“品尝”的对象是食物，不能说“品尝自己的土地”。"}], "explanations": {"防卫": "正确：“国家要有力量防卫自己的土地”符合句意。", "拍卖": "语义：“拍卖”是卖出物品，与“要有力量”的语境相悖，句子不通。", "欣赏": "搭配：“欣赏”的对象是景色或作品，不能说“欣赏自己的土地”。", "品尝": "搭配：“品尝”的对象是食物，不能说“品尝自己的土地”。"}, "sentence_index": 6, "correct_answer": "防卫"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "消防员冲进火场防卫被困的人。", "explanation": "这里应该用〈救援〉。防卫指抵挡侵犯，不用于救出被困的人。"}, {"text": "工人们防卫了一座新桥。", "explanation": "这里应该用〈修建〉。防卫是守卫、抵挡伤害，不用于建造东西。"}, {"text": "大家热烈防卫远方的客人。", "explanation": "这里应该用〈欢迎〉。防卫指抵挡侵犯，不用于接待客人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90990, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "士兵们把边境防卫很严密。", "corrected_sentence": "士兵们把边境防卫得很严密。", "error_description": "补语要用“得”连接。“防卫很严密”漏了“得”，应说“防卫得很严密”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90990, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "边防连队的战士很防卫山口。", "corrected_sentence": "边防连队的战士很会防卫山口。", "error_description": "“防卫”是动词，不能直接被“很”修饰。表示能力要说“很会防卫山口”，漏掉“会”就是错误。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
