INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90993, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "可以唱出来或用乐器弹出来的好听的声音。", "primary_collocate": null, "pronunciation": "qǔ", "ipa": "tɕʰy²¹⁴", "syllable_count": 1, "sentences": [{"text": "这首歌的词和曲都是他写的。", "target_word": "曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她坐在钢琴前，为我们弹了一曲。", "target_word": "曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拉着小提琴，为大家拉了一曲。", "target_word": "曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支曲很好听，我听了三遍。", "target_word": "曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上，他坐在河边吹了一曲。", "target_word": "曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她轻轻地唱了一曲，大家都鼓掌。", "target_word": "曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支曲没有歌词，只用钢琴弹。", "target_word": "曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他弹的这一曲让我想起了家乡。", "target_word": "曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想学一支曲，在朋友生日时弹给他听。", "target_word": "曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷爱听戏，也会唱几支曲。", "target_word": "曲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "曲子", "label": "复合"}, {"form": "歌曲", "label": "复合"}], "register": "中性", "sense_fingerprint": "曲：能唱、能弹奏的好听的声音（弹一曲、一支曲）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d0a3031-66ae-43d8-9fb5-fe85694236c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90993, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "曲", "is_correct": true, "explanation": "曲（qǔ，第三声）：可以唱出来或弹出来的好听的声音。"}, {"text": "许", "is_correct": false, "explanation": "许（xǔ）与曲（qǔ）声母不同，x 与 q 不同，意思是允许。"}, {"text": "去", "is_correct": false, "explanation": "去（qù）与曲（qǔ）声调不同，第四声与第三声不同，意思是去。"}, {"text": "雨", "is_correct": false, "explanation": "雨（yǔ）与曲（qǔ）声母不同，q 与 y 不同，意思是雨。"}, {"text": "区", "is_correct": false, "explanation": "区（qū）与曲（qǔ）声调不同，第一声与第三声不同，意思是地区。"}], "explanations": {"曲": "曲（qǔ，第三声）：可以唱出来或弹出来的好听的声音。", "许": "许（xǔ）与曲（qǔ）声母不同，x 与 q 不同，意思是允许。", "去": "去（qù）与曲（qǔ）声调不同，第四声与第三声不同，意思是去。", "雨": "雨（yǔ）与曲（qǔ）声母不同，q 与 y 不同，意思是雨。", "区": "区（qū）与曲（qǔ）声调不同，第一声与第三声不同，意思是地区。"}, "sentence_index": null, "correct_answer": "曲"}, "level_3": {"options": [{"text": "曲", "is_correct": true, "explanation": "曲：这里指乐曲，与“词”相对，是歌的旋律部分，句意通顺。"}, {"text": "画", "is_correct": false, "explanation": "语义：歌的组成部分是词和曲，画不属于歌，与“这首歌的”不符。"}, {"text": "饭", "is_correct": false, "explanation": "搭配：“写”的对象是词、曲等作品，不能写饭。"}, {"text": "镜", "is_correct": false, "explanation": "语义：镜子不是歌的一部分，也不能由他写出，句意不通。"}], "explanations": {"曲": "曲：这里指乐曲，与“词”相对，是歌的旋律部分，句意通顺。", "画": "语义：歌的组成部分是词和曲，画不属于歌，与“这首歌的”不符。", "饭": "搭配：“写”的对象是词、曲等作品，不能写饭。", "镜": "语义：镜子不是歌的一部分，也不能由他写出，句意不通。"}, "sentence_index": 0, "correct_answer": "曲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老人给孩子讲了一曲。", "explanation": "这里应该用〈故事〉。讲的是故事，曲指可以唱或演奏的乐调，不能用“讲”。"}, {"text": "他在墙上挂了一曲。", "explanation": "这里应该用〈幅画〉。曲指乐曲，是听的，不能挂在墙上。"}, {"text": "他拍了一曲，大家都很感动。", "explanation": "这里应该用〈电影〉。曲指乐曲，不能用“拍”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90993, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "曲", "is_correct": true, "explanation": "曲（qǔ，第三声）：可以唱出来或弹出来的好听的声音。"}, {"text": "女", "is_correct": false, "explanation": "女（nǚ）与曲（qǔ）声母不同，n 与 q 不同，意思是女性。"}, {"text": "屈", "is_correct": false, "explanation": "屈（qū）与曲（qǔ）声调不同，第一声与第三声不同，意思是弯曲或委屈。"}, {"text": "趣", "is_correct": false, "explanation": "趣（qù）与曲（qǔ）声调不同，第四声与第三声不同，意思是趣味。"}, {"text": "吐", "is_correct": false, "explanation": "吐（tǔ）与曲（qǔ）声母不同，t 与 q 不同，意思是吐出。"}], "explanations": {"曲": "曲（qǔ，第三声）：可以唱出来或弹出来的好听的声音。", "女": "女（nǚ）与曲（qǔ）声母不同，n 与 q 不同，意思是女性。", "屈": "屈（qū）与曲（qǔ）声调不同，第一声与第三声不同，意思是弯曲或委屈。", "趣": "趣（qù）与曲（qǔ）声调不同，第四声与第三声不同，意思是趣味。", "吐": "吐（tǔ）与曲（qǔ）声母不同，t 与 q 不同，意思是吐出。"}, "sentence_index": null, "correct_answer": "曲"}, "level_3": {"options": [{"text": "曲", "is_correct": true, "explanation": "曲：这里指乐曲，“没有歌词，只用钢琴弹”说的正是乐曲。"}, {"text": "笔", "is_correct": false, "explanation": "语义：笔不能用钢琴弹，句中说的是可以弹奏的乐曲。"}, {"text": "箫", "is_correct": false, "explanation": "搭配：箫是用嘴吹的乐器，不能说“用钢琴弹”。"}, {"text": "枪", "is_correct": false, "explanation": "语义：枪不能用钢琴弹，也谈不上“没有歌词”，句意荒谬。"}], "explanations": {"曲": "曲：这里指乐曲，“没有歌词，只用钢琴弹”说的正是乐曲。", "笔": "语义：笔不能用钢琴弹，句中说的是可以弹奏的乐曲。", "箫": "搭配：箫是用嘴吹的乐器，不能说“用钢琴弹”。", "枪": "语义：枪不能用钢琴弹，也谈不上“没有歌词”，句意荒谬。"}, "sentence_index": 6, "correct_answer": "曲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在院子里摘了一曲。", "explanation": "这里应该用〈花〉。曲指乐曲，不能用“摘”。"}, {"text": "他把曲脱了，然后躺下睡觉。", "explanation": "这里应该用〈鞋子〉。曲指乐曲，不能用“脱”。"}, {"text": "奶奶给我吃了一曲。", "explanation": "这里应该用〈糖〉。曲指乐曲，不能用“吃”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90993, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在河边吹了一张曲，很好听。", "corrected_sentence": "他在河边吹了一支曲，很好听。", "error_description": "量词错误：“曲”作乐曲时用“支”，“张”只用于纸张、桌子等，不能用于乐曲。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90993, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把这支曲弹得一遍。", "corrected_sentence": "他把这支曲弹了一遍。", "error_description": "助词错误：表示动作完成并带动量补语时应用“了”，不能用“得”，应说“弹了一遍”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
