INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90994, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "可以歌唱或演奏的乐调；歌曲，乐曲。", "primary_collocate": null, "pronunciation": "qǔ", "ipa": "tɕʰy²¹⁴", "syllable_count": 1, "sentences": [{"text": "他为这首诗谱了曲。", "target_word": "曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌是他作的曲，不是别人写的。", "target_word": "曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影的曲是谁作的？", "target_word": "曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这支曲，大家都安静下来。", "target_word": "曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支曲的节奏很慢，适合晚上听。", "target_word": "曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师教我们唱一支新曲。", "target_word": "曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支曲是专门为婚礼写的。", "target_word": "曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "乐队演奏了最后一曲，音乐会就结束了。", "target_word": "曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支曲有三分钟，歌词只有两句。", "target_word": "曲", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想写一支曲送给妈妈。", "target_word": "曲", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "曲子", "label": "复合"}, {"form": "乐曲", "label": "复合"}], "register": "中性", "sense_fingerprint": "曲：乐调；歌曲、乐曲（谱曲、一支曲）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1d0a3031-66ae-43d8-9fb5-fe85694236c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90994, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "曲", "is_correct": true, "explanation": "曲（qǔ，第三声）：可以歌唱或演奏的乐调，歌曲或乐曲。"}, {"text": "苦", "is_correct": false, "explanation": "苦（kǔ）与曲（qǔ）声母不同，k 与 q 不同，意思是苦。"}, {"text": "古", "is_correct": false, "explanation": "古（gǔ）与曲（qǔ）声母不同，g 与 q 不同，意思是古代。"}, {"text": "区", "is_correct": false, "explanation": "区（qū）与曲（qǔ）声调不同，第一声与第三声不同，意思是地区。"}, {"text": "去", "is_correct": false, "explanation": "去（qù）与曲（qǔ）声调不同，第四声与第三声不同，意思是离开、前往。"}], "explanations": {"曲": "曲（qǔ，第三声）：可以歌唱或演奏的乐调，歌曲或乐曲。", "苦": "苦（kǔ）与曲（qǔ）声母不同，k 与 q 不同，意思是苦。", "古": "古（gǔ）与曲（qǔ）声母不同，g 与 q 不同，意思是古代。", "区": "区（qū）与曲（qǔ）声调不同，第一声与第三声不同，意思是地区。", "去": "去（qù）与曲（qǔ）声调不同，第四声与第三声不同，意思是离开、前往。"}, "sentence_index": null, "correct_answer": "曲"}, "level_3": {"options": [{"text": "曲", "is_correct": true, "explanation": "曲：这里指乐曲，“谱曲”就是为诗配上旋律，句意通顺。"}, {"text": "诗", "is_correct": false, "explanation": "语义：句中已有“这首诗”，又说谱成“诗”，意思矛盾。"}, {"text": "雨", "is_correct": false, "explanation": "搭配：“谱”的对象是乐曲或歌词，不能谱雨。"}, {"text": "灯", "is_correct": false, "explanation": "搭配：“谱”只能用于乐曲，不能说谱灯。"}], "explanations": {"曲": "曲：这里指乐曲，“谱曲”就是为诗配上旋律，句意通顺。", "诗": "语义：句中已有“这首诗”，又说谱成“诗”，意思矛盾。", "雨": "搭配：“谱”的对象是乐曲或歌词，不能谱雨。", "灯": "搭配：“谱”只能用于乐曲，不能说谱灯。"}, "sentence_index": 0, "correct_answer": "曲"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我妈妈是一支曲。", "explanation": "这里应该用〈医生〉。曲指乐调或歌曲，不能指人。"}, {"text": "他煮了一曲，老师很满意。", "explanation": "这里应该用〈饭〉。曲指乐曲，不能用“煮”。"}, {"text": "我坐曲去北京。", "explanation": "这里应该用〈火车〉。曲指乐曲，不是交通工具，不能用“坐”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90994, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "曲", "is_correct": true, "explanation": "曲（qǔ，第三声）：可以歌唱或演奏的乐调，歌曲或乐曲。"}, {"text": "虎", "is_correct": false, "explanation": "虎（hǔ）与曲（qǔ）声母不同，h 与 q 不同，意思是老虎。"}, {"text": "趣", "is_correct": false, "explanation": "趣（qù）与曲（qǔ）声调不同，第四声与第三声不同，意思是趣味。"}, {"text": "渠", "is_correct": false, "explanation": "渠（qú）与曲（qǔ）声调不同，第二声与第三声不同，意思是水渠。"}], "explanations": {"曲": "曲（qǔ，第三声）：可以歌唱或演奏的乐调，歌曲或乐曲。", "虎": "虎（hǔ）与曲（qǔ）声母不同，h 与 q 不同，意思是老虎。", "趣": "趣（qù）与曲（qǔ）声调不同，第四声与第三声不同，意思是趣味。", "渠": "渠（qú）与曲（qǔ）声调不同，第二声与第三声不同，意思是水渠。"}, "sentence_index": null, "correct_answer": "曲"}, "level_3": {"options": [{"text": "曲", "is_correct": true, "explanation": "曲：这里指乐曲，“专门为婚礼写的”说的是乐曲，句意通顺。"}, {"text": "枪", "is_correct": false, "explanation": "语义：枪不是为婚礼写的，句意荒谬。"}, {"text": "烟", "is_correct": false, "explanation": "搭配：“写”不能用于烟，不说“写烟”。"}, {"text": "花", "is_correct": false, "explanation": "语义：花不能为婚礼写出来，句意不通。"}], "explanations": {"曲": "曲：这里指乐曲，“专门为婚礼写的”说的是乐曲，句意通顺。", "枪": "语义：枪不是为婚礼写的，句意荒谬。", "烟": "搭配：“写”不能用于烟，不说“写烟”。", "花": "语义：花不能为婚礼写出来，句意不通。"}, "sentence_index": 6, "correct_answer": "曲"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在山上种了一曲。", "explanation": "这里应该用〈树〉。曲指乐曲，不能用“种”。"}, {"text": "妈妈炒了一曲。", "explanation": "这里应该用〈菜〉。曲指乐曲，不能用“炒”。"}, {"text": "他穿上了一曲。", "explanation": "这里应该用〈鞋子〉。曲指乐曲，不能用“穿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90994, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张曲是他为母亲作的。", "corrected_sentence": "这首曲是他为母亲作的。", "error_description": "量词错误：这里的“曲”指乐曲，应该用“首”，“张”只用于纸张、桌子等，不能用于乐曲。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90994, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他写了一支的曲送给妈妈。", "corrected_sentence": "他写了一支曲送给妈妈。", "error_description": "结构错误：量词短语“一支”后面不能加“的”，应说“一支曲”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '85fbacaf-e141-44b7-8e73-30886be46082') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
