INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90995, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "电影节是很多电影一起放给大家看的节日。", "primary_collocate": null, "pronunciation": "diàn yǐng jié", "ipa": "tiɛn⁵¹ iŋ²¹⁴ tɕiɛ³⁵", "syllable_count": 3, "sentences": [{"text": "这个周末城里有电影节，我们一起去看电影吧。", "target_word": "电影节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影节期间，电影院每天都放不同的电影。", "target_word": "电影节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我和朋友买了电影节的票，晚上去看。", "target_word": "电影节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影节那几天，电影院里总是坐满了人。", "target_word": "电影节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小城的电影节让大家免费看好电影。", "target_word": "电影节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈带着孩子去参加电影节。", "target_word": "电影节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电影节有很多国家的电影，我最喜欢那部。", "target_word": "电影节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影节开始了，大家都在门口排队看电影。", "target_word": "电影节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "去年的电影节很热闹，今年我还想去。", "target_word": "电影节", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们学校每年秋天都办一次电影节。", "target_word": "电影节", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "届", "label": "量词"}, {"form": "電影節", "label": "繁体"}], "register": "中性", "sense_fingerprint": "很多电影集中放映、大家一起看的节日", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2c571f81-6489-4741-8a61-f863fc462a95') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90995, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "电影节", "is_correct": true, "explanation": "正确答案：电影节（diàn yǐng jié），指集中放映影片的节日活动。"}, {"text": "电影界", "is_correct": false, "explanation": "jiè（第四声）与 jié（第二声）声调不同，意思是电影行业、影视圈。"}, {"text": "电影街", "is_correct": false, "explanation": "jiē（第一声）与 jié（第二声）声调不同，意思是放映或售卖电影的街道。"}, {"text": "电音节", "is_correct": false, "explanation": "yīn（第一声）与 yǐng（第三声）读音不同，电音节指电子音乐节，不是电影活动。"}], "explanations": {"电影节": "正确答案：电影节（diàn yǐng jié），指集中放映影片的节日活动。", "电影界": "jiè（第四声）与 jié（第二声）声调不同，意思是电影行业、影视圈。", "电影街": "jiē（第一声）与 jié（第二声）声调不同，意思是放映或售卖电影的街道。", "电音节": "yīn（第一声）与 yǐng（第三声）读音不同，电音节指电子音乐节，不是电影活动。"}, "sentence_index": null, "correct_answer": "电影节"}, "level_3": {"options": [{"text": "体育馆", "is_correct": false, "explanation": "语义：体育馆是固定场所，“这个周末城里有”指的是会发生的活动，不能指建筑。"}, {"text": "电影节", "is_correct": true, "explanation": "正确：“这个周末城里有电影节”指周末举办的电影活动，与后面“一起去看电影”相符。"}, {"text": "葬礼", "is_correct": false, "explanation": "语义：葬礼是哀悼活动，不能和后面“一起去看电影吧”的轻松邀约搭配。"}, {"text": "地震", "is_correct": false, "explanation": "语义：地震是自然灾害，不能和后面“一起去看电影吧”的邀约相连。"}], "explanations": {"体育馆": "语义：体育馆是固定场所，“这个周末城里有”指的是会发生的活动，不能指建筑。", "电影节": "正确：“这个周末城里有电影节”指周末举办的电影活动，与后面“一起去看电影”相符。", "葬礼": "语义：葬礼是哀悼活动，不能和后面“一起去看电影吧”的轻松邀约搭配。", "地震": "语义：地震是自然灾害，不能和后面“一起去看电影吧”的邀约相连。"}, "sentence_index": 0, "correct_answer": "电影节"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们参加了一本电影节。", "explanation": "这里量词用错了。电影节应该用〈届〉（或〈个〉），“本”只用来数书册，不能用来数电影节。"}, {"text": "我昨天看了一部很好的电影节。", "explanation": "这里应该用〈电影〉。电影节是一项持续数日的活动，不是一部可以看完的影片，不能说“看一部电影节”。"}, {"text": "城里新开了一家电影节，里面有很多座位。", "explanation": "这里应该用〈电影院〉。电影节是定期举办的活动，没有固定的场所，不能说“新开了一家电影节”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a00b61e-0302-4d46-b4c4-f79c7f8764d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90995, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "食堂", "is_correct": false, "explanation": "语义：食堂不放映电影，“这个食堂有很多国家的电影”与常识不符。"}, {"text": "电影节", "is_correct": true, "explanation": "正确：“这个电影节有很多国家的电影”指这届电影节放映了多国影片，与后文“我最喜欢那部”呼应。"}, {"text": "停车场", "is_correct": false, "explanation": "语义：停车场是停车的地方，不会放映影片。"}, {"text": "花店", "is_correct": false, "explanation": "搭配：“有很多国家的电影”的主语应是能放映影片的场所或活动，花店不搭。"}], "explanations": {"食堂": "语义：食堂不放映电影，“这个食堂有很多国家的电影”与常识不符。", "电影节": "正确：“这个电影节有很多国家的电影”指这届电影节放映了多国影片，与后文“我最喜欢那部”呼应。", "停车场": "语义：停车场是停车的地方，不会放映影片。", "花店": "搭配：“有很多国家的电影”的主语应是能放映影片的场所或活动，花店不搭。"}, "sentence_index": 6, "correct_answer": "电影节"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这场电影节的比分是三比二。", "explanation": "这里应该用〈比赛〉。比分只属于比赛、球赛，电影节不计比分。"}, {"text": "这次电影节有很多古代的陶器。", "explanation": "这里应该用〈展览〉。展览陈列实物，电影节放映影片，古代陶器不属于它的内容。"}, {"text": "这次电影节一共有二十集。", "explanation": "这里应该用〈电视剧〉。“集”用于分集的作品，电影节没有分集，不能说“一共有二十集”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a00b61e-0302-4d46-b4c4-f79c7f8764d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90995, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座城市去年新办了一部电影节。", "corrected_sentence": "这座城市去年新办了一届电影节。", "error_description": "“电影节”的量词应为“届”（或“个”）。“部”用来数电影、书等，说“一部电影节”是量词用错，应改为“一届电影节”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a00b61e-0302-4d46-b4c4-f79c7f8764d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90995, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个电影节每年都有很多人来吃。", "corrected_sentence": "这个电影节每年都有很多人来参加。", "error_description": "「吃」不能搭配活动类名词「电影节」，应改为「参加」，说「来参加电影节」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a00b61e-0302-4d46-b4c4-f79c7f8764d6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
