INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90999, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一群人在一起，用乐器弹出好听的音乐。", "primary_collocate": null, "pronunciation": "yuè duì", "ipa": "ɥe˥˩ tweɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "我哥哥在一个小乐队里弹吉他。", "target_word": "乐队", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "周末公园里有一支乐队在演奏。", "target_word": "乐队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个乐队的歌，我天天都听。", "target_word": "乐队", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们几个朋友一起组了一个乐队。", "target_word": "乐队", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想参加学校的乐队，学吹小号。", "target_word": "乐队", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "乐队里有三个男孩和一个女孩。", "target_word": "乐队", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小乐队在街上唱着好听的歌。", "target_word": "乐队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个乐队的鼓手是我的同学。", "target_word": "乐队", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的乐队下个月要去北京开音乐会。", "target_word": "乐队", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "乐队来了，孩子们都围过来看。", "target_word": "乐队", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "支", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "樂隊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "一群人一起弹奏乐器的小团体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b16ac64-fa49-4be4-b4f1-b3825b46d122') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90999, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乐队", "is_correct": true, "explanation": "正确答案。乐队是几个人一起演奏的团体，可以在里面弹吉他。"}, {"text": "球队", "is_correct": false, "explanation": "语义：球队指体育竞赛的团队，与弹吉他的场景不符。"}, {"text": "字典", "is_correct": false, "explanation": "语义：字典是工具书，不是人可以待在里面弹吉他的地方。"}, {"text": "名片", "is_correct": false, "explanation": "语义：名片是印有个人信息的小卡片，不能在里面弹吉他。"}], "explanations": {"乐队": "正确答案。乐队是几个人一起演奏的团体，可以在里面弹吉他。", "球队": "语义：球队指体育竞赛的团队，与弹吉他的场景不符。", "字典": "语义：字典是工具书，不是人可以待在里面弹吉他的地方。", "名片": "语义：名片是印有个人信息的小卡片，不能在里面弹吉他。"}, "sentence_index": 0, "correct_answer": "乐队"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们班来了一张乐队，大家都很兴奋。", "explanation": "这里应该用〈支〉。〈张〉用于纸、桌子等平面物件，不用于乐队。"}, {"text": "学校门口停着一台乐队。", "explanation": "这里应该用〈支〉。〈台〉用于机器、车辆等，不用于乐队。"}, {"text": "舞台上站着一棵乐队。", "explanation": "这里应该用〈支〉。〈棵〉用于树木、植物，不用于乐队。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90999, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乐队", "is_correct": true, "explanation": "正确答案。小乐队是街头演唱的团体，可以在街上唱歌。"}, {"text": "商店", "is_correct": false, "explanation": "语义：商店是卖东西的地方，不会在街上唱歌。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院是看病的地方，与在街上唱歌的场景不符。"}, {"text": "车站", "is_correct": false, "explanation": "语义：车站是交通场所，它本身不能在街上唱歌。"}], "explanations": {"乐队": "正确答案。小乐队是街头演唱的团体，可以在街上唱歌。", "商店": "语义：商店是卖东西的地方，不会在街上唱歌。", "医院": "语义：医院是看病的地方，与在街上唱歌的场景不符。", "车站": "语义：车站是交通场所，它本身不能在街上唱歌。"}, "sentence_index": 6, "correct_answer": "乐队"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我想先学会用乐队。", "explanation": "这里应该用〈乐器〉。乐队是由人组成的团体，不能被“用”来演奏。"}, {"text": "这个乐队下个月要在剧院演出一部话剧。", "explanation": "这里应该用〈剧团〉。乐队演奏音乐，不演出话剧。"}, {"text": "他是很厉害的乐队。", "explanation": "这里应该用〈乐手〉。指一个人时要说乐手，乐队是团体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90999, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们学校新组了一只乐队。", "corrected_sentence": "我们学校新组了一支乐队。", "error_description": "量词错误：乐队应该用量词〈支〉。〈只〉用于动物等，不能用来数乐队。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (90999, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我哥哥今年加入了一座乐队。", "corrected_sentence": "我哥哥今年加入了一支乐队。", "error_description": "量词错误：乐队应该用量词〈支〉。〈座〉用于山、楼房等大型固定物，不能用来数乐队。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
