INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91000, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "由多人组成、使用多种乐器合奏音乐的演奏团体。", "primary_collocate": null, "pronunciation": "yuè duì", "ipa": "ɥe˥˩ tweɪ̯˥˩", "syllable_count": 2, "sentences": [{"text": "这支乐队由四十个人组成。", "target_word": "乐队", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这支乐队有小提琴、钢琴和大鼓。", "target_word": "乐队", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "乐队的指挥站在舞台中间。", "target_word": "乐队", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个乐队每年都去很多城市演出。", "target_word": "乐队", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "音乐会开始前，乐队先调好了乐器。", "target_word": "乐队", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这支乐队合奏了一首有名的曲子。", "target_word": "乐队", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "乐队里的每个人都要听指挥。", "target_word": "乐队", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市政府请了一支乐队来演奏。", "target_word": "乐队", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "乐队正在台上演奏着一首老歌。", "target_word": "乐队", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校乐队参加了全市的比赛。", "target_word": "乐队", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "支", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "樂隊", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有指挥、多种乐器合奏的演奏团体", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6b16ac64-fa49-4be4-b4f1-b3825b46d122') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91000, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "乐队", "is_correct": true, "explanation": "正确答案。乐队是由四十人组成的合奏团体，符合“由四十个人组成”。"}, {"text": "蜡烛", "is_correct": false, "explanation": "语义：蜡烛是物件，不能由四十个人组成。"}, {"text": "铅笔", "is_correct": false, "explanation": "语义：铅笔是文具，与“由四十个人组成”的主语不符。"}, {"text": "钢笔", "is_correct": false, "explanation": "搭配：“由……组成”搭配团体、组织，“钢笔”不能与之搭配。"}], "explanations": {"乐队": "正确答案。乐队是由四十人组成的合奏团体，符合“由四十个人组成”。", "蜡烛": "语义：蜡烛是物件，不能由四十个人组成。", "铅笔": "语义：铅笔是文具，与“由四十个人组成”的主语不符。", "钢笔": "搭配：“由……组成”搭配团体、组织，“钢笔”不能与之搭配。"}, "sentence_index": 0, "correct_answer": "乐队"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张乐队有四十个人。", "explanation": "这里应该用〈支〉。〈张〉用于纸、桌子等平面物件，不用于乐队。"}, {"text": "市政府请了一座乐队来演奏。", "explanation": "这里应该用〈支〉。〈座〉用于山、建筑等，不用于乐队。"}, {"text": "舞台上站着一片乐队。", "explanation": "这里应该用〈支〉。〈片〉用于大片区域或树叶等，不用于乐队。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91000, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "乐队", "is_correct": true, "explanation": "正确答案。乐队里的每个人都要服从指挥，符合语境。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不是需要服从指挥的群体，句子不通。"}, {"text": "田野", "is_correct": false, "explanation": "语义：田野不是有指挥的团队，与“听指挥”的语境不符。"}, {"text": "海洋", "is_correct": false, "explanation": "语义：海洋不是需要听指挥的群体，句子不通。"}], "explanations": {"乐队": "正确答案。乐队里的每个人都要服从指挥，符合语境。", "花园": "语义：花园不是需要服从指挥的群体，句子不通。", "田野": "语义：田野不是有指挥的团队，与“听指挥”的语境不符。", "海洋": "语义：海洋不是需要听指挥的群体，句子不通。"}, "sentence_index": 6, "correct_answer": "乐队"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他弹了一下这支乐队。", "explanation": "这里应该用〈乐器〉。弹的是乐器，乐队是演奏音乐的团体，不能被弹。"}, {"text": "他是很出色的乐队，弹得一手好琴。", "explanation": "这里应该用〈乐手〉。指一个人时要说乐手，乐队是团体。"}, {"text": "这支乐队在比赛中踢进了两个球。", "explanation": "这里应该用〈球队〉。乐队演奏音乐，不踢球；踢球的团体是球队。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91000, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校请了一只乐队来演出。", "corrected_sentence": "学校请了一支乐队来演出。", "error_description": "量词错误：乐队应该用量词〈支〉。〈只〉用于动物等，不能用来数乐队。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91000, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她带着一块乐队在城里演出。", "corrected_sentence": "她带着一支乐队在城里演出。", "error_description": "量词错误：乐队应该用量词〈支〉。〈块〉用于块状的东西，不能用来数乐队。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5169cc0b-4b5b-4418-a9cc-aff8c883c291') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
