INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91002, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用砖、石等砌成的、围住或间隔空间的建筑物，如院墙、城墙。", "primary_collocate": null, "pronunciation": "qiáng", "ipa": "tɕʰiɑŋ˧˥", "syllable_count": 1, "sentences": [{"text": "院子四周有一堵很高的墙。", "target_word": "墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老城的墙已经有几百年了。", "target_word": "墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫跳上墙，走到了别人家的院子。", "target_word": "墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的墙外面是一条小河。", "target_word": "墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们用石头砌了一堵墙。", "target_word": "墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们在两个房间中间砌了一堵墙。", "target_word": "墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古时候，人们修墙来保护村子。", "target_word": "墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "花园的墙边种着很多红花。", "target_word": "墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那堵墙是用砖砌的，很结实。", "target_word": "墙", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩翻过墙去捡球。", "target_word": "墙", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "面", "label": "量词"}, {"form": "堵", "label": "量词"}, {"form": "围墙", "label": "复合词"}, {"form": "城墙", "label": "复合词"}, {"form": "牆", "label": "繁体"}], "register": "中性", "sense_fingerprint": "砖石砌成的院墙、城墙等建筑物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b4256b07-2d2b-4db1-830f-e6bafd30f388') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91002, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "墙", "is_correct": true, "explanation": "墙是用砖石砌成的围墙、城墙之类建筑，正是听到的词。"}, {"text": "钱", "is_correct": false, "explanation": "qián（第二声）与 qiáng 韵母不同（an 与 ang），意思是钱。"}, {"text": "枪", "is_correct": false, "explanation": "qiāng（第一声）与 qiáng 声调不同，意思是枪。"}, {"text": "抢", "is_correct": false, "explanation": "qiǎng（第三声）与 qiáng 声调不同，意思是抢夺。"}], "explanations": {"墙": "墙是用砖石砌成的围墙、城墙之类建筑，正是听到的词。", "钱": "qián（第二声）与 qiáng 韵母不同（an 与 ang），意思是钱。", "枪": "qiāng（第一声）与 qiáng 声调不同，意思是枪。", "抢": "qiǎng（第三声）与 qiáng 声调不同，意思是抢夺。"}, "sentence_index": null, "correct_answer": "墙"}, "level_3": {"options": [{"text": "墙", "is_correct": true, "explanation": "墙指砖石砌成的围墙，可以量词“堵”计量，围在院子四周。"}, {"text": "树", "is_correct": false, "explanation": "搭配：树用「棵」计量，不说「一堵树」，树也不是砌成的。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不能围在院子四周，「一堵很高的桌子」不成立。"}, {"text": "河", "is_correct": false, "explanation": "语义：河是水流，不能围在院子四周。"}], "explanations": {"墙": "墙指砖石砌成的围墙，可以量词“堵”计量，围在院子四周。", "树": "搭配：树用「棵」计量，不说「一堵树」，树也不是砌成的。", "桌子": "语义：桌子不能围在院子四周，「一堵很高的桌子」不成立。", "河": "语义：河是水流，不能围在院子四周。"}, "sentence_index": 0, "correct_answer": "墙"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校门口有一只墙。", "explanation": "这里应该用〈堵〉。墙用“堵”或“面”计量，“只”用于动物，不用于墙。"}, {"text": "他把墙挂在客厅里，当作装饰。", "explanation": "这里应该用〈画〉。墙是砌成的建筑物，不能挂起来；挂在客厅里当装饰的是画。"}, {"text": "学校旁边立着一扇墙。", "explanation": "这里应该用〈堵〉。“扇”用于门窗，墙不说“一扇墙”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcda1516-089b-43a9-89fd-53dfeb9462c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91002, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "墙", "is_correct": true, "explanation": "墙是用砖石砌成的围墙、城墙之类建筑，正是听到的词。"}, {"text": "前", "is_correct": false, "explanation": "qián（第二声）与 qiáng 韵母不同（an 与 ang），意思是前面。"}, {"text": "呛", "is_correct": false, "explanation": "qiàng（第四声）与 qiáng 声调不同，意思是呛住。"}, {"text": "腔", "is_correct": false, "explanation": "qiāng（第一声）与 qiáng 声调不同，意思是腔调。"}], "explanations": {"墙": "墙是用砖石砌成的围墙、城墙之类建筑，正是听到的词。", "前": "qián（第二声）与 qiáng 韵母不同（an 与 ang），意思是前面。", "呛": "qiàng（第四声）与 qiáng 声调不同，意思是呛住。", "腔": "qiāng（第一声）与 qiáng 声调不同，意思是腔调。"}, "sentence_index": null, "correct_answer": "墙"}, "level_3": {"options": [{"text": "墙", "is_correct": true, "explanation": "古人修墙是为了防御、保护村子，“墙”指砖石建造的围墙。"}, {"text": "公路", "is_correct": false, "explanation": "语义：公路供交通往来，不能起到保护村子的作用。"}, {"text": "游乐场", "is_correct": false, "explanation": "语义：游乐场供人玩耍，不具备防护功能。"}, {"text": "唱片", "is_correct": false, "explanation": "搭配：“修”用于建造或修复的器物，“唱片”不这样搭配，与“保护村子”也无关。"}], "explanations": {"墙": "古人修墙是为了防御、保护村子，“墙”指砖石建造的围墙。", "公路": "语义：公路供交通往来，不能起到保护村子的作用。", "游乐场": "语义：游乐场供人玩耍，不具备防护功能。", "唱片": "搭配：“修”用于建造或修复的器物，“唱片”不这样搭配，与“保护村子”也无关。"}, "sentence_index": 6, "correct_answer": "墙"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校门口立着一根墙。", "explanation": "这里应该用〈堵〉。“根”用于细长的东西，墙不用“根”计量。"}, {"text": "我家门口有一张墙。", "explanation": "这里应该用〈堵〉。“张”用于纸、桌子等平面的东西，墙不说“一张墙”。"}, {"text": "院子里有一把墙，挡着风。", "explanation": "这里应该用〈堵〉。“把”用于有柄的器具，墙不用“把”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcda1516-089b-43a9-89fd-53dfeb9462c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91002, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "村里有一根墙被大水冲倒了。", "corrected_sentence": "村里有一段墙被大水冲倒了。", "error_description": "墙的量词应为「段」「堵」或「面」。「根」用于细长的东西，「一根墙」属量词误用，应改为「一段墙」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcda1516-089b-43a9-89fd-53dfeb9462c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91002, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们在院子四周砌了一块墙。", "corrected_sentence": "他们在院子四周砌了一堵墙。", "error_description": "墙的量词应为「堵」或「面」。「块」用于砖、石头等块状物，不说「一块墙」，应改为「一堵墙」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bcda1516-089b-43a9-89fd-53dfeb9462c7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
