INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91003, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "鞋子是穿在脚上走路的东西。", "primary_collocate": null, "pronunciation": "xié zi", "ipa": "ɕje˧˥ tsɨ", "syllable_count": 2, "sentences": [{"text": "他穿着新鞋子去上学。", "target_word": "鞋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的鞋子在床下面。", "target_word": "鞋子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟找不到另一只鞋子。", "target_word": "鞋子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这双鞋子太大了，我穿不了。", "target_word": "鞋子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈每天晚上洗孩子的鞋子。", "target_word": "鞋子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我穿着这双鞋子走了一天路。", "target_word": "鞋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的鞋子是红色的，很漂亮。", "target_word": "鞋子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天冷了，要穿厚一点的鞋子。", "target_word": "鞋子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小狗咬坏了我的鞋子。", "target_word": "鞋子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "客人来了，门口放着很多鞋子。", "target_word": "鞋子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "双", "label": "量词"}, {"form": "运动鞋", "label": "复合"}], "register": "中性", "sense_fingerprint": "穿在脚上走路用的东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7a2fbd5-9221-419f-9b73-a6b85fe461a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91003, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "鞋子", "is_correct": true, "explanation": "正确答案：鞋子，指穿在脚上走路用的东西。"}, {"text": "茄子", "is_correct": false, "explanation": "声母：茄子 qié zi 与 鞋子 xié zi 只有第一个字的声母不同（q 与 x），茄子指一种蔬菜。"}, {"text": "席子", "is_correct": false, "explanation": "韵母：席子 xí zi 与 鞋子 xié zi 只有第一个字的韵母不同（i 与 ie），席子指睡觉时铺的草编物。"}, {"text": "结子", "is_correct": false, "explanation": "声母：结子 jié zi 与 鞋子 xié zi 只有第一个字的声母不同（j 与 x），结子指绳子等打成的结。"}], "explanations": {"鞋子": "正确答案：鞋子，指穿在脚上走路用的东西。", "茄子": "声母：茄子 qié zi 与 鞋子 xié zi 只有第一个字的声母不同（q 与 x），茄子指一种蔬菜。", "席子": "韵母：席子 xí zi 与 鞋子 xié zi 只有第一个字的韵母不同（i 与 ie），席子指睡觉时铺的草编物。", "结子": "声母：结子 jié zi 与 鞋子 xié zi 只有第一个字的声母不同（j 与 x），结子指绳子等打成的结。"}, "sentence_index": null, "correct_answer": "鞋子"}, "level_3": {"options": [{"text": "鞋子", "is_correct": true, "explanation": "正确：穿在脚上的鞋子，与「穿着新……去上学」相合。"}, {"text": "眼镜", "is_correct": false, "explanation": "搭配：眼镜是戴在脸上的，不说穿，「穿着新眼镜」不成立。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：书包是背在身上的，不说穿，「穿着新书包」不成立。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机不能穿在身上，与「穿着」的动作相抵触。"}], "explanations": {"鞋子": "正确：穿在脚上的鞋子，与「穿着新……去上学」相合。", "眼镜": "搭配：眼镜是戴在脸上的，不说穿，「穿着新眼镜」不成立。", "书包": "搭配：书包是背在身上的，不说穿，「穿着新书包」不成立。", "手机": "语义：手机不能穿在身上，与「穿着」的动作相抵触。"}, "sentence_index": 0, "correct_answer": "鞋子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他捧着这双鞋子喝汤。", "explanation": "这里应该用〈碗〉。鞋子穿在脚上，不能用来盛汤。"}, {"text": "她用鞋子给花浇水。", "explanation": "这里应该用〈水壶〉。鞋子穿在脚上，不能用来浇水。"}, {"text": "他把鞋子塞进耳朵里，当耳机听歌。", "explanation": "这里应该用〈耳机〉。鞋子穿在脚上，不能塞进耳朵里当耳机使用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91003, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鞋子", "is_correct": true, "explanation": "正确：鞋子可以是红色的，与「很漂亮」相合。"}, {"text": "皮肤", "is_correct": false, "explanation": "体貌：一般不说皮肤是红色的，与「她的……是红色的，很漂亮」的描写不合。"}, {"text": "眼睛", "is_correct": false, "explanation": "体貌：一般不说眼睛是红色的，与「她的……是红色的，很漂亮」的描写不合。"}, {"text": "歌", "is_correct": false, "explanation": "语义：歌曲没有颜色，不能说歌是红色的。"}], "explanations": {"鞋子": "正确：鞋子可以是红色的，与「很漂亮」相合。", "皮肤": "体貌：一般不说皮肤是红色的，与「她的……是红色的，很漂亮」的描写不合。", "眼睛": "体貌：一般不说眼睛是红色的，与「她的……是红色的，很漂亮」的描写不合。", "歌": "语义：歌曲没有颜色，不能说歌是红色的。"}, "sentence_index": 6, "correct_answer": "鞋子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把鞋子当成杯子，倒了一杯水。", "explanation": "这里应该用〈杯子〉。鞋子穿在脚上，不能当杯子盛水。"}, {"text": "他把鞋子系在脖子上当项链。", "explanation": "这里应该用〈项链〉。鞋子穿在脚上，不能系在脖子上做装饰。"}, {"text": "他把鞋子当作书本，读了起来。", "explanation": "这里应该用〈书〉。鞋子穿在脚上，不能用来阅读。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91003, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了一台新鞋子。", "corrected_sentence": "他买了一双新鞋子。", "error_description": "错误：「鞋子」的量词用了「台」。正确：成对穿的鞋子要用量词「双」，应说「一双新鞋子」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
