INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91004, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "穿在脚上、保护脚并便于行走的物品。", "primary_collocate": null, "pronunciation": "xié zi", "ipa": "ɕje˧˥ tsɨ", "syllable_count": 2, "sentences": [{"text": "这双鞋子很舒服，走很远也不累。", "target_word": "鞋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，我的鞋子都湿了。", "target_word": "鞋子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把鞋子放在门口的架子上。", "target_word": "鞋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的脚长得快，鞋子很快就小了。", "target_word": "鞋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她买了一双黑色的鞋子。", "target_word": "鞋子", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爬山要穿一双结实的鞋子，才能保护脚。", "target_word": "鞋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋子的底很软，走路一点也不疼。", "target_word": "鞋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "进屋以前，请先脱下鞋子。", "target_word": "鞋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的鞋子坏了，得去修一修。", "target_word": "鞋子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里的鞋子又好看又便宜。", "target_word": "鞋子", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "双", "label": "量词"}, {"form": "运动鞋", "label": "复合"}], "register": "中性", "sense_fingerprint": "穿在脚上、保护脚、便于行走的物品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b7a2fbd5-9221-419f-9b73-a6b85fe461a4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
