model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91004, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "鞋子", "is_correct": true, "explanation": "正确：鞋子的底很软，与「走路一点也不疼」相合。"}, {"text": "翅膀", "is_correct": false, "explanation": "语义：翅膀不长底，不能用「底很软，走路不疼」来形容。"}, {"text": "枕头", "is_correct": false, "explanation": "语义：枕头不穿在脚上，没有「底」，也不能用来走路，与「走路一点也不疼」相抵触。"}, {"text": "手掌", "is_correct": false, "explanation": "配价：「走路」要求能行走的主体，手掌不能走路，这里的搭配不成立。"}], "explanations": {"鞋子": "正确：鞋子的底很软，与「走路一点也不疼」相合。", "翅膀": "语义：翅膀不长底，不能用「底很软，走路不疼」来形容。", "枕头": "语义：枕头不穿在脚上，没有「底」，也不能用来走路，与「走路一点也不疼」相抵触。", "手掌": "配价：「走路」要求能行走的主体，手掌不能走路，这里的搭配不成立。"}, "sentence_index": 6, "correct_answer": "鞋子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这双鞋子戴在了手上。", "explanation": "这里应该用〈手套〉。鞋子穿在脚上，不能戴在手上保暖。"}, {"text": "她把这双鞋子挂在耳朵上，上学去了。", "explanation": "这里应该用〈耳环〉。鞋子穿在脚上，不能挂在耳朵上当装饰。"}, {"text": "他把这双鞋子盖在身上睡觉。", "explanation": "这里应该用〈被子〉。鞋子穿在脚上，不能用来盖在身上取暖。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91004, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我买了三本鞋子。", "corrected_sentence": "我买了三双鞋子。", "error_description": "错误：「鞋子」的量词用了「本」。正确：成对穿的鞋子要用量词「双」，应说「三双鞋子」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91004, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈给我买了两鞋子。", "corrected_sentence": "妈妈给我买了两双鞋子。", "error_description": "错误：数词「两」后面缺少量词「双」。正确：应说「两双鞋子」，数词与名词之间要加上量词。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '71ea201e-b9c6-4019-8044-8f002f70eed7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91005, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "悲伤", "is_correct": true, "explanation": "反义：“欢乐”表示心里高兴、想笑，“悲伤”表示心里难过，二者情绪相反，词典中成对。"}, {"text": "精致", "is_correct": false, "explanation": "无关：精致形容物品或做工细致，与情绪无关。"}, {"text": "坚硬", "is_correct": false, "explanation": "无关：坚硬形容质地，与情绪无关。"}, {"text": "迅速", "is_correct": false, "explanation": "无关：迅速形容速度快，与情绪无关。"}], "correct_answer": "悲伤", "explanations": {"悲伤": "反义：“欢乐”表示心里高兴、想笑，“悲伤”表示心里难过，二者情绪相反，词典中成对。", "精致": "无关：精致形容物品或做工细致，与情绪无关。", "坚硬": "无关：坚硬形容质地，与情绪无关。", "迅速": "无关：迅速形容速度快，与情绪无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91005, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "悲伤", "is_correct": true, "explanation": "反义：“欢乐”表示心里高兴、想笑，“悲伤”表示心里难过，二者情绪相反，词典中成对。"}, {"text": "清楚", "is_correct": false, "explanation": "无关：清楚形容明白易懂，与情绪无关。"}, {"text": "猛烈", "is_correct": false, "explanation": "无关：猛烈形容力量强大或剧烈，与情绪无关。"}, {"text": "丰富", "is_correct": false, "explanation": "无关：丰富形容数量多或种类多，与情绪无关。"}], "correct_answer": "悲伤", "explanations": {"悲伤": "反义：“欢乐”表示心里高兴、想笑，“悲伤”表示心里难过，二者情绪相反，词典中成对。", "清楚": "无关：清楚形容明白易懂，与情绪无关。", "猛烈": "无关：猛烈形容力量强大或剧烈，与情绪无关。", "丰富": "无关：丰富形容数量多或种类多，与情绪无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91005, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "心里很高兴，一直想笑。", "primary_collocate": null, "pronunciation": "huān lè", "ipa": "xwan˥ lɤ˥˩", "syllable_count": 2, "sentences": [{"text": "孩子们玩得很欢乐。", "target_word": "欢乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她笑得很欢乐。", "target_word": "欢乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到好消息，大家都很欢乐。", "target_word": "欢乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的脸上带着欢乐的笑容。", "target_word": "欢乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗跑来跑去，样子很欢乐。", "target_word": "欢乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们欢乐地唱着歌。", "target_word": "欢乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到妈妈回来，弟弟欢乐极了。", "target_word": "欢乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她今天特别欢乐，一直在笑。", "target_word": "欢乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "欢乐的孩子最爱笑。", "target_word": "欢乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过生日的时候，我心里很欢乐。", "target_word": "欢乐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "欢欢乐乐", "label": "重叠"}, {"form": "歡樂", "label": "繁体"}], "register": "中性", "sense_fingerprint": "人心里高兴、总想笑的感觉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4236ccb-40e1-4dd6-9f6f-04c3557493d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91005, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欢乐", "is_correct": true, "explanation": "正确。“玩得很欢乐”形容孩子们玩得高兴、开心，符合句意。"}, {"text": "严肃", "is_correct": false, "explanation": "语义：严肃表示态度郑重、不轻松，与“玩”的轻松快乐相反。"}, {"text": "冷清", "is_correct": false, "explanation": "搭配：冷清形容场所没有人气，不能用来形容玩耍的状态。"}, {"text": "精致", "is_correct": false, "explanation": "搭配：精致多形容物品或做工细致，不能用来形容“玩”的样子。"}], "explanations": {"欢乐": "正确。“玩得很欢乐”形容孩子们玩得高兴、开心，符合句意。", "严肃": "语义：严肃表示态度郑重、不轻松，与“玩”的轻松快乐相反。", "冷清": "搭配：冷清形容场所没有人气，不能用来形容玩耍的状态。", "精致": "搭配：精致多形容物品或做工细致，不能用来形容“玩”的样子。"}, "sentence_index": 0, "correct_answer": "欢乐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听到地震的消息，大家的脸上都带着欢乐的表情。", "explanation": "这里应该用〈惊恐〉。欢乐表示心里高兴、想笑，听到地震的消息应当用惊恐，不能用欢乐。"}, {"text": "听到噩耗后，他欢乐地哭了起来。", "explanation": "这里应该用〈悲伤〉。欢乐表示心里高兴，听到噩耗后应当用悲伤，不能用欢乐。"}, {"text": "他听说比赛输了，欢乐地低下了头。", "explanation": "这里应该用〈难过〉。欢乐表示高兴、想笑，比赛输了应当用难过，不能用欢乐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91005, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欢乐", "is_correct": true, "explanation": "正确。“看到妈妈回来，弟弟欢乐极了”表示弟弟非常高兴，符合句意。"}, {"text": "忧愁", "is_correct": false, "explanation": "语义：忧愁表示心里发愁，与看到妈妈回来的高兴心情相反。"}, {"text": "陌生", "is_correct": false, "explanation": "语义：陌生表示不熟悉，与看到亲人回来的情境不合。"}, {"text": "严重", "is_correct": false, "explanation": "搭配：严重修饰病情或问题，不能用来形容心情到了极点。"}], "explanations": {"欢乐": "正确。“看到妈妈回来，弟弟欢乐极了”表示弟弟非常高兴，符合句意。", "忧愁": "语义：忧愁表示心里发愁，与看到妈妈回来的高兴心情相反。", "陌生": "语义：陌生表示不熟悉，与看到亲人回来的情境不合。", "严重": "搭配：严重修饰病情或问题，不能用来形容心情到了极点。"}, "sentence_index": 6, "correct_answer": "欢乐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他欢乐地告诉我，爸爸病危了。", "explanation": "这里应该用〈悲伤〉。欢乐表示心里高兴，告诉别人病危的消息应当用悲伤，不能用欢乐。"}, {"text": "我用欢乐的手，把书打开。", "explanation": "这里应该用〈灵巧〉。欢乐形容心情，不能修饰手的动作，形容手的灵活应当说灵巧。"}, {"text": "他因为失恋，哭了一整夜，心里却十分欢乐。", "explanation": "这里应该用〈悲伤〉。欢乐表示心里高兴，失恋后整夜哭泣应当用悲伤，不能用欢乐。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91005, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妹妹玩很欢乐。", "corrected_sentence": "妹妹玩得很欢乐。", "error_description": "补语标记错误：“欢乐”作“玩”的补语，中间要用“得”，应说“玩得很欢乐”，不能省略“得”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91005, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "看到哥哥回来，妹妹欢乐地极了。", "corrected_sentence": "看到哥哥回来，妹妹欢乐极了。", "error_description": "结构助词错误：“极了”前不能加“地”，应说“欢乐极了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
