INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91006, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "快乐而热闹；高兴。", "primary_collocate": null, "pronunciation": "huān lè", "ipa": "xwan˥ lɤ˥˩", "syllable_count": 2, "sentences": [{"text": "过年的时候，家里很欢乐。", "target_word": "欢乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "街上是一片欢乐的景象。", "target_word": "欢乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚会上的气氛非常欢乐。", "target_word": "欢乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们唱起欢乐的歌。", "target_word": "欢乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们度过了一个欢乐的周末。", "target_word": "欢乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公园里充满了欢乐的笑声。", "target_word": "欢乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "欢乐的音乐响了起来。", "target_word": "欢乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家在欢乐的气氛中吃着饭。", "target_word": "欢乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "节日的广场上热闹又欢乐。", "target_word": "欢乐", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个欢乐的晚上，我永远忘不了。", "target_word": "欢乐", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "欢欢乐乐", "label": "重叠"}, {"form": "歡樂", "label": "繁体"}], "register": "中性", "sense_fingerprint": "场面、气氛快乐而热闹", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4236ccb-40e1-4dd6-9f6f-04c3557493d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91006, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "欢乐", "is_correct": true, "explanation": "正确。“过年的时候，家里很欢乐”形容家里热闹快乐的气氛，符合句意。"}, {"text": "迅速", "is_correct": false, "explanation": "语义：迅速形容速度快，不能用来形容家里的气氛。"}, {"text": "粗糙", "is_correct": false, "explanation": "语义：粗糙形容质地不平滑，不能用来形容家里的气氛。"}, {"text": "陡峭", "is_correct": false, "explanation": "搭配：陡峭形容地形，不能用来形容家里的气氛。"}], "explanations": {"欢乐": "正确。“过年的时候，家里很欢乐”形容家里热闹快乐的气氛，符合句意。", "迅速": "语义：迅速形容速度快，不能用来形容家里的气氛。", "粗糙": "语义：粗糙形容质地不平滑，不能用来形容家里的气氛。", "陡峭": "搭配：陡峭形容地形，不能用来形容家里的气氛。"}, "sentence_index": 0, "correct_answer": "欢乐"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座空无一人的小镇，街上很欢乐。", "explanation": "这里应该用〈凄凉〉。欢乐形容热闹快乐的气氛，空无一人的小镇不能用欢乐，应当说凄凉。"}, {"text": "这个欢乐的水杯很大。", "explanation": "这里应该用〈漂亮〉。欢乐形容热闹快乐的场面或气氛，不能修饰水杯这样的物品。"}, {"text": "墓地里很欢乐。", "explanation": "这里应该用〈肃穆〉。墓地应当用肃穆形容，欢乐形容热闹快乐的气氛，不能用来形容墓地。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91006, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欢乐", "is_correct": true, "explanation": "正确。“欢乐的音乐响了起来”形容热闹快乐的音乐，符合句意。"}, {"text": "潮湿", "is_correct": false, "explanation": "搭配：潮湿形容空气或环境，不能用来修饰音乐。"}, {"text": "狭窄", "is_correct": false, "explanation": "搭配：狭窄形容空间，不能用来修饰音乐。"}, {"text": "饥饿", "is_correct": false, "explanation": "语义：饥饿形容人想吃东西的感觉，不能用来形容音乐。"}], "explanations": {"欢乐": "正确。“欢乐的音乐响了起来”形容热闹快乐的音乐，符合句意。", "潮湿": "搭配：潮湿形容空气或环境，不能用来修饰音乐。", "狭窄": "搭配：狭窄形容空间，不能用来修饰音乐。", "饥饿": "语义：饥饿形容人想吃东西的感觉，不能用来形容音乐。"}, "sentence_index": 6, "correct_answer": "欢乐"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "空荡荡的车站里很欢乐。", "explanation": "这里应该用〈冷清〉。欢乐形容热闹快乐的场面，空荡荡的车站应当说冷清，不能用欢乐。"}, {"text": "我们在监狱里度过了一个欢乐的周末。", "explanation": "这里应该用〈难熬〉。欢乐形容热闹快乐，监狱里的日子应当说难熬，不能用欢乐。"}, {"text": "他把欢乐的钱包弄丢了。", "explanation": "这里应该用〈新〉。欢乐形容热闹快乐的场面或气氛，不能修饰钱包这样的物品，应当说新钱包。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
