INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91007, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "首届是第一次办的那一回。", "primary_collocate": null, "pronunciation": "shǒu jiè", "ipa": "ʂou˨˩˦ tɕjɛ˥˩", "syllable_count": 2, "sentences": [{"text": "首届运动会在我们学校举行。", "target_word": "首届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是首届中文歌唱比赛，很多人来看。", "target_word": "首届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我哥哥参加了首届读书节。", "target_word": "首届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首届画展的票很快就卖完了。", "target_word": "首届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是首届比赛的第一名。", "target_word": "首届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首届音乐节在春天开始，一共三天。", "target_word": "首届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸说首届校友会特别热闹。", "target_word": "首届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首届足球赛那年，我还是个孩子。", "target_word": "首届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首届电影节吸引了很多年轻人。", "target_word": "首届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们公司明天开首届交流会。", "target_word": "首届", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "首届：放在名词前，表示某活动办的第一回", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '422192c1-2427-4ec1-9369-3724e9165a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91007, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "首届", "is_correct": true, "explanation": "首届：第一次举办的运动会，符合句意。"}, {"text": "深红", "is_correct": false, "explanation": "搭配：“深红”形容颜色，不能修饰“运动会”。"}, {"text": "寂静", "is_correct": false, "explanation": "语义：“寂静”与运动会的热闹相反，句意不通。"}, {"text": "透明", "is_correct": false, "explanation": "搭配：“透明”说物体的质地，不能修饰活动。"}], "explanations": {"首届": "首届：第一次举办的运动会，符合句意。", "深红": "搭配：“深红”形容颜色，不能修饰“运动会”。", "寂静": "语义：“寂静”与运动会的热闹相反，句意不通。", "透明": "搭配：“透明”说物体的质地，不能修饰活动。"}, "sentence_index": 0, "correct_answer": "首届"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家的首届空调是去年买的。", "explanation": "这里应该用〈首台〉。届用于定期举办的活动，空调按台计算，应该用台。"}, {"text": "这家工厂的首届产品下个月上市。", "explanation": "这里应该用〈首批〉。届用于定期举办的会议、赛事，产品按批次投放，应该用批。"}, {"text": "两国的首届协议下周签署。", "explanation": "这里应该用〈首份〉。届用于定期举办的会议、赛事，协议按份计算，应该用份。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91007, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "首届", "is_correct": true, "explanation": "首届：第一次举办的校友会，与“特别热闹”的句意相符。"}, {"text": "冷清", "is_correct": false, "explanation": "语义：“冷清”与后面的“特别热闹”正好相反。"}, {"text": "狭小", "is_correct": false, "explanation": "搭配：“狭小”形容空间，不能修饰校友会。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：“陈旧”指东西老旧，与聚会热闹的气氛不合。"}], "explanations": {"首届": "首届：第一次举办的校友会，与“特别热闹”的句意相符。", "冷清": "语义：“冷清”与后面的“特别热闹”正好相反。", "狭小": "搭配：“狭小”形容空间，不能修饰校友会。", "陈旧": "语义：“陈旧”指东西老旧，与聚会热闹的气氛不合。"}, "sentence_index": 6, "correct_answer": "首届"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是国内首届器官移植手术。", "explanation": "这里应该用〈首例〉。届用于定期举办的会议、赛事，手术是按例计算的，应该用例。"}, {"text": "这场只办过一次的私人婚礼，他们却称之为首届婚礼。", "explanation": "届指定期举办的活动的届次。只办过一次的婚礼没有届次，不能说首届。"}, {"text": "他昨天收到了首届来信。", "explanation": "这里应该用〈第一封〉。届用于定期举办的活动，信是按封计算的，不能说首届。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91007, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们学校今年举办了第首届运动会。", "corrected_sentence": "我们学校今年举办了首届运动会。", "error_description": "错误：“第首届”。“首届”本身已经表示第一届，前面不能再加“第”。正确说法是“首届运动会”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91007, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "公司的首届的交流会下周在上海举行。", "corrected_sentence": "公司的首届交流会下周在上海举行。", "error_description": "错误：“首届的”。“首届”是区别词，直接修饰名词，后面不能加“的”。正确说法是“首届交流会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
