INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91008, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "定期举行的会议或活动的第一次。", "primary_collocate": null, "pronunciation": "shǒu jiè", "ipa": "ʂou˨˩˦ tɕjɛ˥˩", "syllable_count": 2, "sentences": [{"text": "首届世界杯是在一九三零年举行的。", "target_word": "首届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首届奥运会在希腊开幕。", "target_word": "首届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首届进博会吸引了很多国家的公司。", "target_word": "首届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电影节每年一次，今年是首届电影节。", "target_word": "首届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首届亚运会在印度举办。", "target_word": "首届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首届冬季运动会去年在我们城市开幕了。", "target_word": "首届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他当年拿过首届金奖。", "target_word": "首届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首届大会选出了十位代表。", "target_word": "首届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首届论坛来了五百多位专家。", "target_word": "首届", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报纸上说，首届艺术节下月开幕。", "target_word": "首届", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "首届：定期举办的会议、赛事、活动的第一次", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '422192c1-2427-4ec1-9369-3724e9165a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91008, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "首届", "is_correct": true, "explanation": "首届：第一次举办的世界杯，与“一九三零年举行”的句意相符。"}, {"text": "清脆", "is_correct": false, "explanation": "搭配：“清脆”形容声音，不能修饰比赛。"}, {"text": "微型", "is_correct": false, "explanation": "语义：“微型”指体积很小，与世界杯的规模不符。"}, {"text": "轻薄", "is_correct": false, "explanation": "搭配：“轻薄”说质地，不能修饰比赛。"}], "explanations": {"首届": "首届：第一次举办的世界杯，与“一九三零年举行”的句意相符。", "清脆": "搭配：“清脆”形容声音，不能修饰比赛。", "微型": "语义：“微型”指体积很小，与世界杯的规模不符。", "轻薄": "搭配：“轻薄”说质地，不能修饰比赛。"}, "sentence_index": 0, "correct_answer": "首届"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的首届小说下个月出版。", "explanation": "这里应该用〈首部〉。届用于定期举办的活动，小说按部计算，应该用部。"}, {"text": "这家工厂的首届机床今天下线。", "explanation": "这里应该用〈首台〉。届用于定期举办的活动，机床按台计算，应该用台。"}, {"text": "这条线路的首届公交车今天投入运营。", "explanation": "这里应该用〈首辆〉。届用于定期举办的活动，车辆按辆计算，应该用辆。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91008, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "首届", "is_correct": true, "explanation": "首届：某项定期赛事的第一届，与“拿过”的句意相符。"}, {"text": "无效", "is_correct": false, "explanation": "语义：“无效”与“拿过金奖”所表示的荣誉相矛盾。"}, {"text": "木质", "is_correct": false, "explanation": "搭配：“木质”说材料，金奖不用材料来修饰。"}, {"text": "廉价", "is_correct": false, "explanation": "语义：“廉价”与金奖所代表的荣誉相矛盾。"}], "explanations": {"首届": "首届：某项定期赛事的第一届，与“拿过”的句意相符。", "无效": "语义：“无效”与“拿过金奖”所表示的荣誉相矛盾。", "木质": "搭配：“木质”说材料，金奖不用材料来修饰。", "廉价": "语义：“廉价”与金奖所代表的荣誉相矛盾。"}, "sentence_index": 6, "correct_answer": "首届"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是我们家的首届乔迁宴。", "explanation": "这里应该用〈首次〉。届用于定期举办的活动，乔迁宴一家只办一次，应该用首次。"}, {"text": "这次同学聚会只办了一次，却被叫作首届同学聚会。", "explanation": "届指定期举办活动的届次。只办一次的同学聚会没有届次，不能说首届。"}, {"text": "这是这家汽车厂的首届新车。", "explanation": "这里应该用〈首款〉。届用于定期举办的活动，车型按款式计算，应该用款。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91008, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "第首届世界杯于一九三零年在乌拉圭举行。", "corrected_sentence": "首届世界杯于一九三零年在乌拉圭举行。", "error_description": "错误：“第首届”。“首届”本身已经表示第一届，前面不能再加“第”。正确说法是“首届世界杯”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91008, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是我们学校的第首届运动会。", "corrected_sentence": "这是我们学校的首届运动会。", "error_description": "错误：“第首届”。“首届”本身已经表示第一届，前面不能再加“第”。正确说法是“首届运动会”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
