INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91009, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "生日是你来到这个世界的那一天。每年这一天，大家会吃蛋糕。", "primary_collocate": null, "pronunciation": "shēng rì", "ipa": "ʂɤŋ˥ ɻʅ˥˩", "syllable_count": 2, "sentences": [{"text": "小明过生日，家人给他买了大蛋糕。", "target_word": "生日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生日那天，大家一起唱歌，吃蛋糕。", "target_word": "生日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友请我去她家过生日。", "target_word": "生日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天我过生日，妈妈做了很多好吃的菜。", "target_word": "生日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他过生日的时候，收到了很多礼物。", "target_word": "生日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟的生日快到了，他想要一辆新车。", "target_word": "生日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过生日时，我们会吹蜡烛，许愿。", "target_word": "生日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你生日那天想吃什么？", "target_word": "生日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在我生日那天做了一个蛋糕。", "target_word": "生日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想在生日那天请同学来我家。", "target_word": "生日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个生日", "label": "量词"}, {"form": "生日蛋糕", "label": "复合"}, {"form": "生日礼物", "label": "复合"}], "register": "中性", "sense_fingerprint": "每年庆祝的、吃蛋糕收礼物的那一天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '336a0206-f607-4671-866d-44fb53eddaab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91009, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "生日", "is_correct": true, "explanation": "生日（shēng rì）：一个人出生的日子，每年这一天大家庆祝。"}, {"text": "生意", "is_correct": false, "explanation": "rì 与 yì 声母不同（r 与零声母），意思是做买卖。"}, {"text": "圣日", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）声调不同，圣日指神圣的日子。"}, {"text": "胜日", "is_correct": false, "explanation": "shèng（第四声）与 shēng（第一声）声调不同，胜日是书面语，指美好的日子。"}], "explanations": {"生日": "生日（shēng rì）：一个人出生的日子，每年这一天大家庆祝。", "生意": "rì 与 yì 声母不同（r 与零声母），意思是做买卖。", "圣日": "shèng（第四声）与 shēng（第一声）声调不同，圣日指神圣的日子。", "胜日": "shèng（第四声）与 shēng（第一声）声调不同，胜日是书面语，指美好的日子。"}, "sentence_index": null, "correct_answer": "生日"}, "level_3": {"options": [{"text": "生日", "is_correct": true, "explanation": "生日：每年庆祝的那一天，与“过……”搭配，句子通顺。"}, {"text": "数学", "is_correct": false, "explanation": "语义：“过数学”说不通，数学是学科，不能庆祝。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：“过电脑”说不通，电脑不是可以庆祝的日子。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“过”后接的是节日或生日一类的日子，“作业”不能与“过”搭配。"}], "explanations": {"生日": "生日：每年庆祝的那一天，与“过……”搭配，句子通顺。", "数学": "语义：“过数学”说不通，数学是学科，不能庆祝。", "电脑": "语义：“过电脑”说不通，电脑不是可以庆祝的日子。", "作业": "搭配：“过”后接的是节日或生日一类的日子，“作业”不能与“过”搭配。"}, "sentence_index": 0, "correct_answer": "生日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "春节是一家人团圆的生日。", "explanation": "这里应该用〈节日〉。生日指个人出生的日子，春节是全民节日，不能说“生日”。"}, {"text": "报名的生日是下周五，别忘了报名。", "explanation": "这里应该用〈截止日期〉。生日指个人出生的日子，报名的最后期限要说“截止日期”，不能用“生日”。"}, {"text": "我妹妹的生日已经有十二岁了。", "explanation": "这里应该用〈年龄〉。生日指个人出生的日子，人的岁数要说“年龄”，不能用“生日”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c49f556-4b6a-4ac8-966b-a2069f0026a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91009, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "生日", "is_correct": true, "explanation": "生日：每年庆祝的那一天，与“过……时”相符，句子通顺。"}, {"text": "电影", "is_correct": false, "explanation": "语义：“过电影时，我们会吹蜡烛、许愿”说不通，电影不是庆祝的日子。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：游戏不是庆祝的场合，“过游戏时”与后文的吹蜡烛、许愿不协调。"}, {"text": "星期", "is_correct": false, "explanation": "语义：“过星期时，我们会吹蜡烛、许愿”说不通，星期是时间单位，不是庆祝的日子。"}], "explanations": {"生日": "生日：每年庆祝的那一天，与“过……时”相符，句子通顺。", "电影": "语义：“过电影时，我们会吹蜡烛、许愿”说不通，电影不是庆祝的日子。", "游戏": "语义：游戏不是庆祝的场合，“过游戏时”与后文的吹蜡烛、许愿不协调。", "星期": "语义：“过星期时，我们会吹蜡烛、许愿”说不通，星期是时间单位，不是庆祝的日子。"}, "sentence_index": 6, "correct_answer": "生日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "寒假是学生最喜欢的生日。", "explanation": "这里应该用〈假期〉。生日指出生的日子，不能指一段放假的时间。"}, {"text": "会议的生日定在十号。", "explanation": "这里应该用〈日期〉。生日是某人出生的日子，会议的时间安排要说“日期”。"}, {"text": "比赛的生日改到明天下午，大家别忘了。", "explanation": "这里应该用〈时间〉。生日指个人出生的日子，比赛的时间安排要说“时间”，不能用“生日”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c49f556-4b6a-4ac8-966b-a2069f0026a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91009, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈给我过了一块很热闹的生日。", "corrected_sentence": "妈妈给我过了一个很热闹的生日。", "error_description": "错误：“一块……生日”；正确：“一个……生日”。“生日”作名词，量词用“个”，“块”用于成块的东西，不能用于“生日”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c49f556-4b6a-4ac8-966b-a2069f0026a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91009, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在家里生日。", "corrected_sentence": "我们在家里过生日。", "error_description": "错误：“在家里生日”漏掉了“过”；正确：“在家里过生日”。“过生日”是动宾结构，“过”是必需的动词，不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c49f556-4b6a-4ac8-966b-a2069f0026a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
