INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91011, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "数学里的一个记号，样子像一个小十字。", "primary_collocate": null, "pronunciation": "zhèng hào", "ipa": "ʈʂəŋ˥˩ xɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "黑板上写着一个大大的正号。", "target_word": "正号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个正号像一个小十字。", "target_word": "正号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在这张纸上画一个正号。", "target_word": "正号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在本子上画了三个正号。", "target_word": "正号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "正号的样子很简单，就是一横一竖。", "target_word": "正号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子用两根小棍摆出了一个正号。", "target_word": "正号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你看，这里有一个很小的正号。", "target_word": "正号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个正号是用一横和一竖交叉画成的。", "target_word": "正号", "complexity_tier": "T3", "furigana": "zhèng hào", "sentence_source": "generated"}, {"text": "她用红笔把正号写得很大。", "target_word": "正号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个正号太小，我看不清楚。", "target_word": "正号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个正号", "label": "量词"}], "register": "中性", "sense_fingerprint": "数学记号“+”的外形，像一个小十字", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ce09844-0065-49c3-b8ad-6ca918984161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91011, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "椅子", "is_correct": false, "explanation": "搭配：“写着”的对象应是字或符号，不能写椅子。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“写着”不能用于窗户这类实物。"}, {"text": "正号", "is_correct": true, "explanation": "正确：“正号”是符号，可以写在黑板上，“一个大大的”修饰它很自然。"}, {"text": "石头", "is_correct": false, "explanation": "语义：“石头”是实物，不是可写的符号，与“写着”不合。"}], "explanations": {"椅子": "搭配：“写着”的对象应是字或符号，不能写椅子。", "窗户": "搭配：“写着”不能用于窗户这类实物。", "正号": "正确：“正号”是符号，可以写在黑板上，“一个大大的”修饰它很自然。", "石头": "语义：“石头”是实物，不是可写的符号，与“写着”不合。"}, "sentence_index": 0, "correct_answer": "正号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师在错的题目旁边画了一个正号。", "explanation": "这里应该用〈叉号〉。“正号”是加号的形状，不表示错误，标记错误要用叉号。"}, {"text": "老师在对的题目旁边画了一个正号。", "explanation": "这里应该用〈对号〉。“正号”表示加号或正数，不表示正确，标记正确要用对号。"}, {"text": "这个词的旁边要加一个正号，标注解释。", "explanation": "这里应该用〈星号〉。“正号”是数学符号，不用来标注解释，标注要用星号。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91011, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "大山", "is_correct": false, "explanation": "语义：“大山”很大，与“很小的”矛盾。"}, {"text": "正号", "is_correct": true, "explanation": "正确：“正号”形体很小，可以用“一个很小的”修饰。"}, {"text": "大海", "is_correct": false, "explanation": "语义：“大海”极大，与“很小的”矛盾。"}, {"text": "大厦", "is_correct": false, "explanation": "语义：“大厦”体积很大，与“很小的”矛盾。"}], "explanations": {"大山": "语义：“大山”很大，与“很小的”矛盾。", "正号": "正确：“正号”形体很小，可以用“一个很小的”修饰。", "大海": "语义：“大海”极大，与“很小的”矛盾。", "大厦": "语义：“大厦”体积很大，与“很小的”矛盾。"}, "sentence_index": 6, "correct_answer": "正号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我在纸上找到了一只正号。", "explanation": "这里应该用〈个〉。“正号”是符号，不是动物，不能用“只”。"}, {"text": "黑板上还留着一条正号。", "explanation": "这里应该用〈个〉。“条”用于长条形的东西，“正号”不用“条”。"}, {"text": "他拿出一把正号给我看。", "explanation": "这里应该用〈个〉。“把”用于有柄的东西，“正号”不用“把”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91011, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在纸上画了一张正号，然后就走了。", "corrected_sentence": "他在纸上画了一个正号，然后就走了。", "error_description": "错误：量词“张”用于纸、床等平面物，“正号”是符号，应用“个”。正确应为“一个正号”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91011, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在纸的角落里画了一块很小的正号。", "corrected_sentence": "他在纸的角落里画了一个很小的正号。", "error_description": "错误：量词“块”用于块状物，画出的符号应用“个”。正确应为“一个很小的正号”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
