INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91012, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "数学中表示正数或加法的符号“+”。", "primary_collocate": null, "pronunciation": "zhèng hào", "ipa": "ʈʂəŋ˥˩ xɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "数字前面有正号，说明它是正数。", "target_word": "正号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "算式里的正号表示加法。", "target_word": "正号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "五前面的正号可以不写。", "target_word": "正号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "正号后面的数是正数。", "target_word": "正号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，这里要用正号，不能用负号。", "target_word": "正号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他忘了写正号，所以题做错了。", "target_word": "正号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "零度以上的温度前面可以写正号。", "target_word": "正号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "正号和负号是相反的记号。", "target_word": "正号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题里的正号表示两个数相加。", "target_word": "正号", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明看见正号，就知道要做加法。", "target_word": "正号", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个正号", "label": "量词"}], "register": "中性", "sense_fingerprint": "数学符号“+”，表示正数或加法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6ce09844-0065-49c3-b8ad-6ca918984161') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91012, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "负号", "is_correct": false, "explanation": "语义：“负号”表示负数，与“说明它是正数”矛盾。"}, {"text": "小数点", "is_correct": false, "explanation": "搭配：小数点位于数字中间，不放在数字前面。"}, {"text": "正号", "is_correct": true, "explanation": "正确：“正号”放在数字前面，表示这个数是正数。"}, {"text": "问号", "is_correct": false, "explanation": "语义：“问号”表示疑问，不能说明数的正负。"}], "explanations": {"负号": "语义：“负号”表示负数，与“说明它是正数”矛盾。", "小数点": "搭配：小数点位于数字中间，不放在数字前面。", "正号": "正确：“正号”放在数字前面，表示这个数是正数。", "问号": "语义：“问号”表示疑问，不能说明数的正负。"}, "sentence_index": 0, "correct_answer": "正号"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "正号后面的数是负数。", "explanation": "这里应该用〈负号〉。“正号”表示正数或加法，不表示负数，负数要用负号。"}, {"text": "正号表示减法。", "explanation": "这里应该用〈减号〉。“正号”表示加号或正数，不表示减法，减法要用减号。"}, {"text": "正号表示开平方运算。", "explanation": "这里应该用〈根号〉。“正号”不表示开平方，开平方要用根号。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91012, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "冒号", "is_correct": false, "explanation": "语义：“冒号”用于分隔，不表示温度的正负。"}, {"text": "句号", "is_correct": false, "explanation": "搭配：“句号”用在句末，不写在温度或数字前面。"}, {"text": "星号", "is_correct": false, "explanation": "语义：“星号”用于标注，与温度的正负无关。"}, {"text": "正号", "is_correct": true, "explanation": "正确：零度以上为正数，所以温度前面可以写“正号”。"}], "explanations": {"冒号": "语义：“冒号”用于分隔，不表示温度的正负。", "句号": "搭配：“句号”用在句末，不写在温度或数字前面。", "星号": "语义：“星号”用于标注，与温度的正负无关。", "正号": "正确：零度以上为正数，所以温度前面可以写“正号”。"}, "sentence_index": 6, "correct_answer": "正号"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师在黑板上写了一只正号。", "explanation": "这里应该用〈个〉。“正号”是符号，“只”用于动物，不能用来数“正号”。"}, {"text": "题目里有一条正号，我没注意。", "explanation": "这里应该用〈个〉。“条”用于长形的东西，“正号”不用“条”。"}, {"text": "他从书包里拿出一把正号。", "explanation": "这里应该用〈个〉。“把”用于有柄的东西，“正号”不用“把”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91012, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "算式里有一张正号。", "corrected_sentence": "算式里有一个正号。", "error_description": "错误：量词“张”用于纸、床等平面物，“正号”是符号，应用“个”。正确应为“一个正号”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91012, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "数字前面写正号，就表示它是负数。", "corrected_sentence": "数字前面写正号，就表示它是正数。", "error_description": "错误：“正号”放在数字前面表示该数为正数，不能说成负数。正确应为“表示它是正数”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd64713a8-b09d-44b3-85a0-8bf06f2f1ccc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
