INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91014, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在政府机关或团体中设立的、由党员组成并起领导作用的组织。", "primary_collocate": null, "pronunciation": "dǎng zǔ", "ipa": "tɑŋ˨˩ tsu˨˩", "syllable_count": 2, "sentences": [{"text": "政府机关里一般都设有党组。", "target_word": "党组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "党组在这家协会里起领导作用。", "target_word": "党组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个协会的党组由几位党员组成。", "target_word": "党组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "党组负责讨论单位的重大事情。", "target_word": "党组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学会成立以后，也设立了党组。", "target_word": "党组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "党组不直接管理日常工作，只管大事。", "target_word": "党组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市政府的党组每周开一次会。", "target_word": "党组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "党组领导整个单位的工作。", "target_word": "党组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "报社的党组决定了新的方案。", "target_word": "党组", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多团体里都有党组这个组织。", "target_word": "党组", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个党组", "label": "量词"}, {"form": "党组书记", "label": "复合"}, {"form": "党组会议", "label": "复合"}], "register": "正式", "sense_fingerprint": "政府机关或团体中设立的党员领导组织", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '62e3c067-3c4e-4854-b164-7c1afd2d112c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91014, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "党组", "is_correct": true, "explanation": "正确。政府机关里设有的党员领导组织就是党组，符合句意。"}, {"text": "海浪", "is_correct": false, "explanation": "语义：海浪是自然现象，不是机关中设立的组织，句意不通。"}, {"text": "空气", "is_correct": false, "explanation": "搭配：“设有”用于机构或设施，空气不能被“设有”。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "语义：鸡蛋是食物，不是机关里设立的组织，句意冲突。"}], "explanations": {"党组": "正确。政府机关里设有的党员领导组织就是党组，符合句意。", "海浪": "语义：海浪是自然现象，不是机关中设立的组织，句意不通。", "空气": "搭配：“设有”用于机构或设施，空气不能被“设有”。", "鸡蛋": "语义：鸡蛋是食物，不是机关里设立的组织，句意冲突。"}, "sentence_index": 0, "correct_answer": "党组"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈在党组里买了一些水果和蔬菜。", "explanation": "这里应该用〈超市〉。党组是机关或团体中由党员组成的领导组织，不是买东西的地方，应用超市。"}, {"text": "我们厂的党组每周都为职工体检。", "explanation": "这里应该用〈医务室〉。党组是领导组织，不负责为职工体检，应用医务室。"}, {"text": "班里成立了一个党组，负责组织学习。", "explanation": "这里应该用〈学习小组〉。党组只在政府机关或团体中设立，班级里的学习小组不能叫党组。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91014, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "党组", "is_correct": true, "explanation": "正确。市政府设立的党员领导组织每周开会，符合句意。"}, {"text": "花园", "is_correct": false, "explanation": "搭配：“开会”的主体应是机构或人群，花园不能“开一次会”。"}, {"text": "电影", "is_correct": false, "explanation": "语义：电影是影视作品，不是机构，不能每周召开会议。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头没有开会的能力，与“市政府的……每周开一次会”不符。"}], "explanations": {"党组": "正确。市政府设立的党员领导组织每周开会，符合句意。", "花园": "搭配：“开会”的主体应是机构或人群，花园不能“开一次会”。", "电影": "语义：电影是影视作品，不是机构，不能每周召开会议。", "石头": "语义：石头没有开会的能力，与“市政府的……每周开一次会”不符。"}, "sentence_index": 6, "correct_answer": "党组"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周末我们全家去党组郊游。", "explanation": "这里应该用〈公园〉。党组是团体中的领导组织，不是郊游的地方，应用公园。"}, {"text": "这个团体的党组专门负责出售门票。", "explanation": "这里应该用〈售票处〉。党组是领导组织，不负责售票，应用售票处。"}, {"text": "放学后，学生们在党组里踢足球。", "explanation": "这里应该用〈操场〉。党组是团体中的领导组织，不能用来踢足球，应用操场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91014, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个协会新设了一座党组。", "corrected_sentence": "这个协会新设了一个党组。", "error_description": "量词错误：党组是组织，应用量词“个”，不能用“座”。应说“新设了一个党组”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91014, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "党组们每周都在三楼开会。", "corrected_sentence": "党组每周都在三楼开会。", "error_description": "错误形式：“党组们”；正确形式：“党组”。“党组”指组织，不是人，不能加“们”表示复数。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fa685ae0-ba87-44e1-be57-b9072e9dcd3c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
