INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91015, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "神秘是让人觉得很奇怪，不知道里面是什么。", "primary_collocate": null, "pronunciation": "shén mì", "ipa": "ʂən˧˥ mi˥˩", "syllable_count": 2, "sentences": [{"text": "桌上有一个神秘的盒子。", "target_word": "神秘", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "门后面有一间神秘的小屋。", "target_word": "神秘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他给了我一个神秘的包裹，不让我打开。", "target_word": "神秘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座老房子看起来很神秘。", "target_word": "神秘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地下室里有个神秘的房间，没人进去过。", "target_word": "神秘", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个神秘的箱子里到底是什么？", "target_word": "神秘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山里有一个神秘的洞，里面很黑。", "target_word": "神秘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她手里拿着一个神秘的小袋子。", "target_word": "神秘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "抽屉里有一个神秘的铁盒，谁也不知道里面装着什么。", "target_word": "神秘", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师带来的盒子看起来很神秘，大家都想打开看看。", "target_word": "神秘", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "神秘感", "label": "复合"}, {"form": "神秘兮兮", "label": "复合"}], "register": "中性", "sense_fingerprint": "东西或地方让人好奇，不知道里面有什么", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '336a0206-f607-4671-866d-44fb53eddaab') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91015, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "神秘", "is_correct": true, "explanation": "神秘指东西让人好奇、不知道里面是什么，与“盒子”相符。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：“温柔”形容人的性格或态度，不能用来形容盒子。"}, {"text": "饿", "is_correct": false, "explanation": "语义：“饿”形容人或动物需要吃东西，盒子不会饿，说不通。"}, {"text": "嫩", "is_correct": false, "explanation": "搭配：“嫩”多形容食物或植物，不用来形容盒子。"}], "explanations": {"神秘": "神秘指东西让人好奇、不知道里面是什么，与“盒子”相符。", "温柔": "语义：“温柔”形容人的性格或态度，不能用来形容盒子。", "饿": "语义：“饿”形容人或动物需要吃东西，盒子不会饿，说不通。", "嫩": "搭配：“嫩”多形容食物或植物，不用来形容盒子。"}, "sentence_index": 0, "correct_answer": "神秘"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间屋子打扫得很神秘，地板亮得能照人。", "explanation": "这里应该用〈干净〉。神秘指让人好奇、不知里面有什么，不能用来形容屋子打扫得清洁。"}, {"text": "书架上的书摆得很神秘。", "explanation": "这里应该用〈整齐〉。神秘用于让人好奇的事物，不能形容书摆放得有序。"}, {"text": "这碗汤很神秘，我一口就喝光了。", "explanation": "这里应该用〈美味〉。神秘不描述味道，汤好喝要用美味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c49f556-4b6a-4ac8-966b-a2069f0026a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91015, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "神秘", "is_correct": true, "explanation": "神秘指让人好奇、不知里面有什么，与“里面很黑”的语境相符。"}, {"text": "胖", "is_correct": false, "explanation": "语义：“胖”形容人或动物的体型，不能用来形容山洞，句子说不通。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”一般形容味道，不用来形容山洞。"}, {"text": "乖巧", "is_correct": false, "explanation": "语义：“乖巧”形容人或动物的性情，山洞不会乖巧。"}], "explanations": {"神秘": "神秘指让人好奇、不知里面有什么，与“里面很黑”的语境相符。", "胖": "语义：“胖”形容人或动物的体型，不能用来形容山洞，句子说不通。", "甜": "搭配：“甜”一般形容味道，不用来形容山洞。", "乖巧": "语义：“乖巧”形容人或动物的性情，山洞不会乖巧。"}, "sentence_index": 6, "correct_answer": "神秘"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "集市上很神秘，人来人往。", "explanation": "这里应该用〈热闹〉。神秘指让人好奇、不知里面有什么，不能形容集市人来人往的场面。"}, {"text": "这件衣服洗得很神秘，穿起来很舒服。", "explanation": "这里应该用〈干净〉。神秘用于让人好奇的东西，不能形容衣服洗得清洁。"}, {"text": "这块蛋糕很神秘，大家都抢着吃。", "explanation": "这里应该用〈好吃〉。神秘不描述味道，蛋糕好吃要用好吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c49f556-4b6a-4ac8-966b-a2069f0026a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91015, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个箱子很神秘地，谁也不知道里面装着什么。", "corrected_sentence": "这个箱子很神秘，谁也不知道里面装着什么。", "error_description": "作谓语的形容词后多加了“地”，“神秘地”是副词形式，只能修饰动词，“很神秘地”不能作谓语；正确为“很神秘”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c49f556-4b6a-4ac8-966b-a2069f0026a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91015, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那片森林里有一条神秘地小路。", "corrected_sentence": "那片森林里有一条神秘的小路。", "error_description": "修饰名词的形容词要用“的”，不用“地”；“地”是状语的标志，“神秘地小路”不通，正确为“神秘的小路”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8c49f556-4b6a-4ac8-966b-a2069f0026a0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
