INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91018, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "国家机关颁布的具有法律效力的命令、规章的总称。", "primary_collocate": null, "pronunciation": "fǎ lìng", "ipa": "fa˨˩˦ liŋ˥˩", "syllable_count": 2, "sentences": [{"text": "国务院颁布了新的法令。", "target_word": "法令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新法令自下月起施行。", "target_word": "法令", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "政府依照法令处理这件事。", "target_word": "法令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "各级机关都必须执行国家法令。", "target_word": "法令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "违反法令的企业会受到处罚。", "target_word": "法令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这项法令对环境保护作了明确规定。", "target_word": "法令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "公民应当遵守国家的法律和法令。", "target_word": "法令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "法令发布以后，全国各地都要执行。", "target_word": "法令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他是研究古代法令的学者。", "target_word": "法令", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "国务院公布了有关交通的法令。", "target_word": "法令", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一项法令", "label": "量词"}, {"form": "一条法令", "label": "量词"}], "register": "书面", "sense_fingerprint": "国家机关颁布的有法律效力的命令和规章的统称", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7d4986a0-230f-4048-a49e-666580b97150') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91018, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "饼干", "is_correct": false, "explanation": "搭配：“颁布”用于法令、规章，不能用于食品。"}, {"text": "法令", "is_correct": true, "explanation": "“法令”是国家机关颁布的规范，与“国务院颁布了新的”相符。"}, {"text": "小说", "is_correct": false, "explanation": "搭配：小说是出版或发表的，不能说颁布小说。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不是国家机关颁布的东西，句子说不通。"}], "explanations": {"饼干": "搭配：“颁布”用于法令、规章，不能用于食品。", "法令": "“法令”是国家机关颁布的规范，与“国务院颁布了新的”相符。", "小说": "搭配：小说是出版或发表的，不能说颁布小说。", "花园": "语义：花园不是国家机关颁布的东西，句子说不通。"}, "sentence_index": 0, "correct_answer": "法令"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "学校制定了一项法令，要求学生按时到校。", "explanation": "这里应该用〈章程〉。法令由国家机关颁布，学校或社团的规章要用章程。"}, {"text": "老师布置的法令，学生要认真完成。", "explanation": "这里应该用〈作业〉。法令是颁布的规定，不能布置或完成，应说作业。"}, {"text": "牛顿发现了一项法令，解释了物体运动。", "explanation": "这里应该用〈定律〉。法令是国家机关颁布的规章，自然界的规律要用定律。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ea2e41-fe4c-4e22-b114-3834ebfb0285') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91018, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "歌曲", "is_correct": false, "explanation": "搭配：“遵守”的宾语应是法律、规定，不能说遵守歌曲。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气是自然现象，不能要求人遵守。"}, {"text": "法令", "is_correct": true, "explanation": "“法令”是国家颁布、公民应当遵守的规范，与“遵守国家的法律和”相符。"}, {"text": "笑话", "is_correct": false, "explanation": "语义：笑话不是需要遵守的规范，“遵守笑话”说不通。"}], "explanations": {"歌曲": "搭配：“遵守”的宾语应是法律、规定，不能说遵守歌曲。", "天气": "语义：天气是自然现象，不能要求人遵守。", "法令": "“法令”是国家颁布、公民应当遵守的规范，与“遵守国家的法律和”相符。", "笑话": "语义：笑话不是需要遵守的规范，“遵守笑话”说不通。"}, "sentence_index": 6, "correct_answer": "法令"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "歌手发布了新法令，大家都在听。", "explanation": "这里应该用〈新歌〉。歌手发布的是歌曲，不是国家机关颁布的法令。"}, {"text": "校长做了一项法令，全校都要听。", "explanation": "这里应该用〈报告〉。法令是颁布的，不是做出来的；做出来的汇报要用报告。"}, {"text": "居委会发出了一项法令，告诉居民下午停水。", "explanation": "这里应该用〈通知〉。法令由国家机关颁布、有法律效力，居委会告知停水这类事项要用通知。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ea2e41-fe4c-4e22-b114-3834ebfb0285') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91018, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "国务院这次颁布了一把法令。", "corrected_sentence": "国务院这次颁布了一项法令。", "error_description": "“法令”的量词应为“项”或“条”。“把”用于有柄的东西，不能用于法令，应说“一项法令”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ea2e41-fe4c-4e22-b114-3834ebfb0285') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91018, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "国务院发布了一幅法令。", "corrected_sentence": "国务院发布了一项法令。", "error_description": "“法令”的量词应为“项”或“条”。“幅”用于字画、图片，不能用于法令，应说“一项法令”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c9ea2e41-fe4c-4e22-b114-3834ebfb0285') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91020, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上车", "is_correct": true, "explanation": "上车指从车外进到车里，与“下车”（从车上下来）构成反义。"}, {"text": "启动", "is_correct": false, "explanation": "启动指车辆开始运行，与“下车”没有反义关系。"}, {"text": "停靠", "is_correct": false, "explanation": "停靠指车辆在站点停下，与“下车”没有反义关系。"}, {"text": "追赶", "is_correct": false, "explanation": "追赶指快步赶上，与“下车”没有反义关系。"}], "correct_answer": "上车", "explanations": {"上车": "上车指从车外进到车里，与“下车”（从车上下来）构成反义。", "启动": "启动指车辆开始运行，与“下车”没有反义关系。", "停靠": "停靠指车辆在站点停下，与“下车”没有反义关系。", "追赶": "追赶指快步赶上，与“下车”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91020, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "上车", "is_correct": true, "explanation": "上车指从车外进到车里，与“下车”（从车上下来）构成反义。"}, {"text": "买票", "is_correct": false, "explanation": "买票指购买车票，与“下车”没有反义关系。"}, {"text": "发动", "is_correct": false, "explanation": "发动指使车辆或机器开始运转，与“下车”没有反义关系。"}, {"text": "进站", "is_correct": false, "explanation": "进站指进入车站，与“下车”没有反义关系。"}], "correct_answer": "上车", "explanations": {"上车": "上车指从车外进到车里，与“下车”（从车上下来）构成反义。", "买票": "买票指购买车票，与“下车”没有反义关系。", "发动": "发动指使车辆或机器开始运转，与“下车”没有反义关系。", "进站": "进站指进入车站，与“下车”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91020, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从车辆上下来。", "primary_collocate": null, "pronunciation": "xià chē", "ipa": "ɕjɑ˥˩ ʈʂʰɤ˥", "syllable_count": 2, "sentences": [{"text": "公共汽车到站了，请从后门下车。", "target_word": "下车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在下一站下车，你呢？", "target_word": "下车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地铁门一开，大家都下车了。", "target_word": "下车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车一停，很多人急着下车。", "target_word": "下车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人要下车，司机把公交车停稳了。", "target_word": "下车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在人民公园下车，然后走路回家。", "target_word": "下车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请带好行李，在终点站下车。", "target_word": "下车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在北京站下车，朋友来接我们。", "target_word": "下车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下车时请注意脚下。", "target_word": "下车", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他睡着了，坐过站才下车。", "target_word": "下车", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "下了车", "label": "体标"}, {"form": "下过车", "label": "体标"}, {"form": "下車", "label": "繁体"}], "register": "中性", "sense_fingerprint": "从公共汽车、地铁、火车等车辆上下来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'eec25974-71fd-4a3e-aa7f-4714ae3f80b2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91020, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "下车", "is_correct": true, "explanation": "下车（xià chē）：从公共汽车、地铁、火车等车辆上下来，是本条的目标词。"}, {"text": "下策", "is_correct": false, "explanation": "下策（xià cè）：cè 与 chē 声母不同（c 与 ch），声调也不同，意思是最差的办法。"}, {"text": "现车", "is_correct": false, "explanation": "现车（xiàn chē）：xiàn 比 xià 多了鼻音韵尾 n，意思是现成可以提走的车。"}, {"text": "下撤", "is_correct": false, "explanation": "下撤（xià chè）：chè 与 chē 只有声调不同（第四声），意思是向下撤退。"}], "explanations": {"下车": "下车（xià chē）：从公共汽车、地铁、火车等车辆上下来，是本条的目标词。", "下策": "下策（xià cè）：cè 与 chē 声母不同（c 与 ch），声调也不同，意思是最差的办法。", "现车": "现车（xiàn chē）：xiàn 比 xià 多了鼻音韵尾 n，意思是现成可以提走的车。", "下撤": "下撤（xià chè）：chè 与 chē 只有声调不同（第四声），意思是向下撤退。"}, "sentence_index": null, "correct_answer": "下车"}, "level_3": {"options": [{"text": "下车", "is_correct": true, "explanation": "下车表示从车上下来，符合“公共汽车到站了，请从后门下车”的语境。"}, {"text": "下班", "is_correct": false, "explanation": "语义：公共汽车到站后，乘客是下车，不是下班。"}, {"text": "下船", "is_correct": false, "explanation": "搭配：公共汽车不能说下船，“船”与“车”不搭配。"}, {"text": "出海", "is_correct": false, "explanation": "语义：公共汽车到站后，乘客不会出海。"}], "explanations": {"下车": "下车表示从车上下来，符合“公共汽车到站了，请从后门下车”的语境。", "下班": "语义：公共汽车到站后，乘客是下车，不是下班。", "下船": "搭配：公共汽车不能说下船，“船”与“车”不搭配。", "出海": "语义：公共汽车到站后，乘客不会出海。"}, "sentence_index": 0, "correct_answer": "下车"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们走到山顶看了看，又走路下车了。", "explanation": "这里应该用〈下山〉。下车用于车辆，从山上走下来要说下山。"}, {"text": "校长讲完话，就从讲台上下车了。", "explanation": "这里应该用〈下台〉。下车用于车辆，人从讲台上离开要说下台。"}, {"text": "他在楼上喊了一声，就下车来了。", "explanation": "这里应该用〈下楼〉。下车用于车辆，从楼上下来要说下楼。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91020, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "下车", "is_correct": true, "explanation": "下车（xià chē）：从公共汽车、地铁、火车等车辆上下来，是本条的目标词。"}, {"text": "下设", "is_correct": false, "explanation": "下设（xià shè）：shè 与 chē 声母不同（sh 与 ch），声调也不同，意思是下级机构的设立。"}, {"text": "下撤", "is_correct": false, "explanation": "下撤（xià chè）：chè 与 chē 声调不同（第四声），意思是向下撤退。"}, {"text": "闲车", "is_correct": false, "explanation": "闲车（xián chē）：xián 比 xià 多了鼻音韵尾 n，且为第二声，意思是闲置的车。"}], "explanations": {"下车": "下车（xià chē）：从公共汽车、地铁、火车等车辆上下来，是本条的目标词。", "下设": "下设（xià shè）：shè 与 chē 声母不同（sh 与 ch），声调也不同，意思是下级机构的设立。", "下撤": "下撤（xià chè）：chè 与 chē 声调不同（第四声），意思是向下撤退。", "闲车": "闲车（xián chē）：xián 比 xià 多了鼻音韵尾 n，且为第二声，意思是闲置的车。"}, "sentence_index": null, "correct_answer": "下车"}, "level_3": {"options": [{"text": "下车", "is_correct": true, "explanation": "下车表示从车上下来，符合“请带好行李，在终点站下车”的语境。"}, {"text": "开会", "is_correct": false, "explanation": "语义：终点站不是开会的地方，与“带好行李”的语境不合。"}, {"text": "下棋", "is_correct": false, "explanation": "语义：在终点站下棋，不符合“带好行李”的语境。"}, {"text": "下机", "is_correct": false, "explanation": "搭配：“下机”指从飞机上下来，不能用于公共汽车或火车的终点站。"}], "explanations": {"下车": "下车表示从车上下来，符合“请带好行李，在终点站下车”的语境。", "开会": "语义：终点站不是开会的地方，与“带好行李”的语境不合。", "下棋": "语义：在终点站下棋，不符合“带好行李”的语境。", "下机": "搭配：“下机”指从飞机上下来，不能用于公共汽车或火车的终点站。"}, "sentence_index": 6, "correct_answer": "下车"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他刚从家里出来，马上就下车去上班。", "explanation": "这里应该用〈上车〉。他刚离开家，应该先上车再去上班，不能说下车。"}, {"text": "他从楼上下车，去厨房倒水。", "explanation": "这里应该用〈走下来〉。下车用于车辆，从楼上下来要说走下来。"}, {"text": "船靠岸了，大家陆续下车。", "explanation": "这里应该用〈下船〉。下车用于公共汽车、地铁、火车等车辆，船上的人要说下船。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91020, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在前门下车了公交车，直接去了医院。", "corrected_sentence": "他在前门下了公交车，直接去了医院。", "error_description": "离合词错误：“下车”是离合词，不能直接带宾语。应说“下了公交车”，“了”要放在“下”和“车”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91020, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "车到站了，可是他昨天没下车了。", "corrected_sentence": "车到站了，可是他昨天没下车。", "error_description": "体标错误：用“没”否定已发生的动作时不能再带“了”，应说“没下车”，不说“没下车了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5cadf0c0-3068-4fcc-aaac-86dcf141d198') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
