INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91022, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "做事或说话走到极端，不留余地。", "primary_collocate": null, "pronunciation": "jué", "ipa": "tɕyɛ˧˥", "syllable_count": 1, "sentences": [{"text": "你别把话说绝，以后还要见面。", "target_word": "绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他做得太绝，朋友都不理他了。", "target_word": "绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事你做得太绝了。", "target_word": "绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别把路走绝了，给自己留条后路。", "target_word": "绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她说话太绝，一点面子也不给。", "target_word": "绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板把话说绝了，我们没法再谈。", "target_word": "绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把事情做绝，大家都很生气。", "target_word": "绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "话不要说得太绝，也许还有办法。", "target_word": "绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对朋友不能做得这么绝。", "target_word": "绝", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说得很绝，一点商量的余地也没有。", "target_word": "绝", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "絕", "label": "繁体"}, {"form": "断绝", "label": "复合词"}, {"form": "绝对", "label": "复合词"}], "register": "口语", "sense_fingerprint": "绝：说话或做事走到极端，不留余地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53db9dd3-8e45-4d0b-b8b6-d4711d195280') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91022, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "绝", "is_correct": true, "explanation": "正确：“绝”读 jué，这里指做事说话走到极端、不留余地。"}, {"text": "学", "is_correct": false, "explanation": "xué（第二声）与 jué 声母不同，意思是学习。"}, {"text": "节", "is_correct": false, "explanation": "jié（第二声）与 jué 韵母不同，意思是节日。"}, {"text": "结", "is_correct": false, "explanation": "jié（第二声）与 jué 韵母不同，意思是结束、打结。"}, {"text": "穴", "is_correct": false, "explanation": "xué（第二声）与 jué 声母不同，意思是洞穴。"}], "explanations": {"绝": "正确：“绝”读 jué，这里指做事说话走到极端、不留余地。", "学": "xué（第二声）与 jué 声母不同，意思是学习。", "节": "jié（第二声）与 jué 韵母不同，意思是节日。", "结": "jié（第二声）与 jué 韵母不同，意思是结束、打结。", "穴": "xué（第二声）与 jué 声母不同，意思是洞穴。"}, "sentence_index": null, "correct_answer": "绝"}, "level_3": {"options": [{"text": "绝", "is_correct": true, "explanation": "正确：“把话说绝”指说话不留余地，与后文“以后还要见面”形成对照。"}, {"text": "饱", "is_correct": false, "explanation": "搭配：“把话说”后不能接“饱”作结果，“把话说饱”不成立。"}, {"text": "碎", "is_correct": false, "explanation": "搭配：“把话说”后不能接“碎”作结果，“把话说碎”不成立。"}, {"text": "好", "is_correct": false, "explanation": "语义：“把话说好”指事先约定好，与“别……以后还要见面”的劝阻语境不符。"}], "explanations": {"绝": "正确：“把话说绝”指说话不留余地，与后文“以后还要见面”形成对照。", "饱": "搭配：“把话说”后不能接“饱”作结果，“把话说饱”不成立。", "碎": "搭配：“把话说”后不能接“碎”作结果，“把话说碎”不成立。", "好": "语义：“把话说好”指事先约定好，与“别……以后还要见面”的劝阻语境不符。"}, "sentence_index": 0, "correct_answer": "绝"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个笑话真绝，大家都笑了。", "explanation": "这里〈绝〉用的是“绝妙、非常好”的意思，与“走到极端、不留余地”的意思不同。"}, {"text": "这件事我绝不会告诉别人。", "explanation": "这里〈绝〉用作副词，表示“一定不”的语气，与本义的形容词用法不同。"}, {"text": "他把和朋友的关系绝了。", "explanation": "这里应该用〈断〉。〈断〉可带“关系”等宾语表示断开；〈绝〉作形容词，不能这样带宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91022, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "绝", "is_correct": true, "explanation": "正确：“绝”读 jué，这里指做事说话走到极端、不留余地。"}, {"text": "截", "is_correct": false, "explanation": "jié（第二声）与 jué 韵母不同，意思是截断。"}, {"text": "洁", "is_correct": false, "explanation": "jié（第二声）与 jué 韵母不同，意思是干净。"}, {"text": "劫", "is_correct": false, "explanation": "jié（第二声）与 jué 韵母不同，意思是抢劫。"}, {"text": "杰", "is_correct": false, "explanation": "jié（第二声）与 jué 韵母不同，意思是杰出。"}], "explanations": {"绝": "正确：“绝”读 jué，这里指做事说话走到极端、不留余地。", "截": "jié（第二声）与 jué 韵母不同，意思是截断。", "洁": "jié（第二声）与 jué 韵母不同，意思是干净。", "劫": "jié（第二声）与 jué 韵母不同，意思是抢劫。", "杰": "jié（第二声）与 jué 韵母不同，意思是杰出。"}, "sentence_index": null, "correct_answer": "绝"}, "level_3": {"options": [{"text": "绝", "is_correct": true, "explanation": "正确：“做绝”指做事不留余地，与“大家都很生气”相符。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“做事情”不能搭配“甜”，“把事情做甜”不成立。"}, {"text": "厚", "is_correct": false, "explanation": "搭配：“做”后不能接“厚”来描述事情，“把事情做厚”不成立。"}, {"text": "蓝", "is_correct": false, "explanation": "搭配：“做事情”不能搭配“蓝”，“把事情做蓝”不成立。"}], "explanations": {"绝": "正确：“做绝”指做事不留余地，与“大家都很生气”相符。", "甜": "搭配：“做事情”不能搭配“甜”，“把事情做甜”不成立。", "厚": "搭配：“做”后不能接“厚”来描述事情，“把事情做厚”不成立。", "蓝": "搭配：“做事情”不能搭配“蓝”，“把事情做蓝”不成立。"}, "sentence_index": 6, "correct_answer": "绝"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这道菜的味道真绝，大家都说好吃。", "explanation": "这里〈绝〉是“绝妙、好到极点”的意思，是称赞，与“做事说话走到极端、不留余地”的意思不同。"}, {"text": "他绝了所有的朋友。", "explanation": "这里应该用〈失去〉。〈绝〉作形容词，不能作动词带宾语“朋友”来表示失去。"}, {"text": "我们绝常见面。", "explanation": "这里应该用〈经常〉。〈绝〉表示走到极端，不表示频率，不能修饰“常”这类频率副词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91022, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把话绝说了，谁也劝不了他。", "corrected_sentence": "他把话说绝了，谁也劝不了他。", "error_description": "错误：“绝说”，应为“说绝”。“绝”在此作结果补语，要放在动词“说”之后，不能放在动词前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91022, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把事情绝做了，大家都很生气。", "corrected_sentence": "他把事情做绝了，大家都很生气。", "error_description": "错误：“绝做”，应为“做绝”。“绝”在此作结果补语，要放在动词“做”之后，不能放在动词前面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b2c40768-3295-45fa-9fbc-623a0ac594e8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
