INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91023, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "叫一个人去做事，或者去别的地方。", "primary_collocate": null, "pronunciation": "pài chū", "ipa": "pʰaɪ˥˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "老师派出一个学生去拿书。", "target_word": "派出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板派出小王去买午饭。", "target_word": "派出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理派出了小李去机场接客人。", "target_word": "派出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师派出两个同学去办公室。", "target_word": "派出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "队长派出一个人先去看看。", "target_word": "派出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经理派出员工去仓库取货。", "target_word": "派出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他派出自己的朋友去找你。", "target_word": "派出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王经理派出秘书去送东西。", "target_word": "派出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "部长派出小张去北京办事。", "target_word": "派出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班长派出了三个人去搬桌子。", "target_word": "派出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "派出了", "label": "体标"}, {"form": "派出过", "label": "体标"}], "register": "中性", "sense_fingerprint": "叫某个人去办一件具体的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4236ccb-40e1-4dd6-9f6f-04c3557493d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91023, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "派出", "is_correct": true, "explanation": "派出（pàichū）：叫某个人去办一件具体的事。这里是正确答案。"}, {"text": "排出", "is_correct": false, "explanation": "排出（páichū）第一音节为第二声，与派出的第四声不同，意思是排放出去。"}, {"text": "拍出", "is_correct": false, "explanation": "拍出（pāichū）第一音节为第一声，与派出的第四声不同，意思是拍摄或拍打而得到。"}, {"text": "卖出", "is_correct": false, "explanation": "卖出（màichū）声母为 m，与派出的 p 不同，声调相同，意思是售卖。"}, {"text": "泡出", "is_correct": false, "explanation": "泡出（pàochū）韵母为 ao，与派出的 ai 不同，声调相同，意思是用水浸泡出来。"}], "explanations": {"派出": "派出（pàichū）：叫某个人去办一件具体的事。这里是正确答案。", "排出": "排出（páichū）第一音节为第二声，与派出的第四声不同，意思是排放出去。", "拍出": "拍出（pāichū）第一音节为第一声，与派出的第四声不同，意思是拍摄或拍打而得到。", "卖出": "卖出（màichū）声母为 m，与派出的 p 不同，声调相同，意思是售卖。", "泡出": "泡出（pàochū）韵母为 ao，与派出的 ai 不同，声调相同，意思是用水浸泡出来。"}, "sentence_index": null, "correct_answer": "派出"}, "level_3": {"options": [{"text": "派出", "is_correct": true, "explanation": "符合语境：老师叫一个学生去拿书，正是派出的用法。"}, {"text": "批评", "is_correct": false, "explanation": "语义：“批评”是指出错误，与“去拿书”的派遣意思不合。"}, {"text": "表扬", "is_correct": false, "explanation": "搭配：“表扬”用于赞许人或行为，不能表示指派学生去做事。"}, {"text": "宣布", "is_correct": false, "explanation": "配价：“宣布”要接内容或决定，不能直接带人再接“去拿书”。"}], "explanations": {"派出": "符合语境：老师叫一个学生去拿书，正是派出的用法。", "批评": "语义：“批评”是指出错误，与“去拿书”的派遣意思不合。", "表扬": "搭配：“表扬”用于赞许人或行为，不能表示指派学生去做事。", "宣布": "配价：“宣布”要接内容或决定，不能直接带人再接“去拿书”。"}, "sentence_index": 0, "correct_answer": "派出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师派出试卷给同学们。", "explanation": "这里应该用〈分发〉。派出指叫人去做事，分发试卷要用分发。"}, {"text": "我派出自己去买菜。", "explanation": "这里应该用〈亲自〉，或直接说“我去买菜”。派出是叫别人去做事，不能用来指自己去做。"}, {"text": "老师派出一把尺子去办公室。", "explanation": "这里应该用〈带〉。派出只用于叫人或派车去做事，把尺子拿去办公室要用带。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91023, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "派出", "is_correct": true, "explanation": "派出（pàichū）：叫某个人去办一件具体的事。这里是正确答案。"}, {"text": "排除", "is_correct": false, "explanation": "排除（páichú）两个音节的声调都与派出（pàichū）不同，意思是消除或去掉。"}, {"text": "配出", "is_correct": false, "explanation": "配出（pèichū）韵母为 ei，与派出的 ai 不同，声调相同，意思是按要求配制出来，如“配出钥匙”。"}, {"text": "跑出", "is_correct": false, "explanation": "跑出（pǎochū）韵母为 ao、第三声，与派出的 ai、第四声不同，意思是快速移动到外面。"}], "explanations": {"派出": "派出（pàichū）：叫某个人去办一件具体的事。这里是正确答案。", "排除": "排除（páichú）两个音节的声调都与派出（pàichū）不同，意思是消除或去掉。", "配出": "配出（pèichū）韵母为 ei，与派出的 ai 不同，声调相同，意思是按要求配制出来，如“配出钥匙”。", "跑出": "跑出（pǎochū）韵母为 ao、第三声，与派出的 ai、第四声不同，意思是快速移动到外面。"}, "sentence_index": null, "correct_answer": "派出"}, "level_3": {"options": [{"text": "派出", "is_correct": true, "explanation": "符合语境：他叫自己的朋友去找你，正是派出的用法。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：“嘲笑”是取笑，与“去找你”的派遣意思不合。"}, {"text": "感谢", "is_correct": false, "explanation": "语义：“感谢”表示谢意，与“派遣朋友去找你”的意思不合。"}, {"text": "打听", "is_correct": false, "explanation": "搭配：“打听”是询问信息，不能用来指派朋友去找人。"}], "explanations": {"派出": "符合语境：他叫自己的朋友去找你，正是派出的用法。", "嘲笑": "语义：“嘲笑”是取笑，与“去找你”的派遣意思不合。", "感谢": "语义：“感谢”表示谢意，与“派遣朋友去找你”的意思不合。", "打听": "搭配：“打听”是询问信息，不能用来指派朋友去找人。"}, "sentence_index": 6, "correct_answer": "派出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "系统派出了一条通知给大家。", "explanation": "这里应该用〈发送〉。派出指叫人去做事，传递消息要用发送。"}, {"text": "他派出一封信给朋友。", "explanation": "这里应该用〈寄〉。派出只用于叫人去做事或去别处，寄信要用寄。"}, {"text": "我派出朋友去家里做客。", "explanation": "这里应该用〈邀请〉。派出指叫人去做事，请朋友来做客要用邀请。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91023, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "班长派出着一个同学去借书。", "corrected_sentence": "班长派出了一个同学去借书。", "error_description": "体标错误：“派出”表示一次完成的指派，应用“了”，不能用“着”，应说“派出了一个同学”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91023, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他派出着自己的朋友去找你。", "corrected_sentence": "他派出了自己的朋友去找你。", "error_description": "体标错误：“派出”是一次完成的指派，应用“了”，不能用“着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
