INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91024, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "指派人员前往某处执行任务。", "primary_collocate": null, "pronunciation": "pài chū", "ipa": "pʰaɪ˥˩ ʈʂʰu˥", "syllable_count": 2, "sentences": [{"text": "公司派出两名工人去外地修路。", "target_word": "派出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察局派出了十个人去找他。", "target_word": "派出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校今年派出老师去国外学习。", "target_word": "派出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医院马上派出医生去山里。", "target_word": "派出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家派出了很多人去帮助灾区。", "target_word": "派出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们队派出最好的球员去比赛。", "target_word": "派出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市里派出过一个小组去那里工作。", "target_word": "派出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司准备派出三个人参加会议。", "target_word": "派出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "消防队派出了两辆车去那里。", "target_word": "派出", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们派出代表去开会。", "target_word": "派出", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "派出了", "label": "体标"}, {"form": "派出过", "label": "体标"}], "register": "正式", "sense_fingerprint": "单位正式指派人员去某地执行任务", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f4236ccb-40e1-4dd6-9f6f-04c3557493d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91024, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "派出", "is_correct": true, "explanation": "派出（pàichū）：指派人员前往某处执行任务。这里是正确答案。"}, {"text": "排出", "is_correct": false, "explanation": "排出（páichū）第一音节为第二声，与派出的第四声不同，意思是排放出去，不指派人员。"}, {"text": "拍出", "is_correct": false, "explanation": "拍出（pāichū）第一音节为第一声，与派出的第四声不同，意思是拍摄或拍卖出去。"}, {"text": "泡出", "is_correct": false, "explanation": "泡出（pàochū）韵母为 ao，与派出的 ai 不同，声调相同，意思是用水浸泡出来，如“泡出茶色”。"}, {"text": "配出", "is_correct": false, "explanation": "配出（pèichū）韵母为 ei，与派出的 ai 不同，声调相同，意思是按要求配制出来，如“配出钥匙”。"}], "explanations": {"派出": "派出（pàichū）：指派人员前往某处执行任务。这里是正确答案。", "排出": "排出（páichū）第一音节为第二声，与派出的第四声不同，意思是排放出去，不指派人员。", "拍出": "拍出（pāichū）第一音节为第一声，与派出的第四声不同，意思是拍摄或拍卖出去。", "泡出": "泡出（pàochū）韵母为 ao，与派出的 ai 不同，声调相同，意思是用水浸泡出来，如“泡出茶色”。", "配出": "配出（pèichū）韵母为 ei，与派出的 ai 不同，声调相同，意思是按要求配制出来，如“配出钥匙”。"}, "sentence_index": null, "correct_answer": "派出"}, "level_3": {"options": [{"text": "派出", "is_correct": true, "explanation": "符合语境：公司指派两名工人去外地，正是派出的用法。"}, {"text": "辞退", "is_correct": false, "explanation": "语义：“辞退”是解雇，与后面的“去外地修路”矛盾。"}, {"text": "押送", "is_correct": false, "explanation": "搭配：“押送”多用于人犯或货物，不用于派遣工人去工作。"}, {"text": "派发", "is_correct": false, "explanation": "搭配：“派发”指分发物品，不说派发人员去外地修路。"}], "explanations": {"派出": "符合语境：公司指派两名工人去外地，正是派出的用法。", "辞退": "语义：“辞退”是解雇，与后面的“去外地修路”矛盾。", "押送": "搭配：“押送”多用于人犯或货物，不用于派遣工人去工作。", "派发": "搭配：“派发”指分发物品，不说派发人员去外地修路。"}, "sentence_index": 0, "correct_answer": "派出"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "班长派出练习本给每个同学。", "explanation": "这里应该用〈派发〉。派出指派人员去某处执行任务，分发练习本要用派发。"}, {"text": "他朝我派出一个眼神，示意我先走。", "explanation": "这里应该用〈使眼色〉。派出指派人员或车辆去某处，不用于表示眼神示意。"}, {"text": "快递员派出包裹送到我家。", "explanation": "这里应该用〈派送〉。派出用于派遣人员或车辆，递送包裹要用派送。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91024, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "派出", "is_correct": true, "explanation": "派出（pàichū）：指派人员前往某处执行任务。这里是正确答案。"}, {"text": "拍出", "is_correct": false, "explanation": "拍出（pāichū）第一音节为第一声，与派出的第四声不同，意思是拍摄或拍打而得到。"}, {"text": "卖出", "is_correct": false, "explanation": "卖出（màichū）声母为 m，与派出的 p 不同，声调相同，意思是售卖。"}, {"text": "跑出", "is_correct": false, "explanation": "跑出（pǎochū）韵母与声调都与派出不同（ao 与 ai，第三声与第四声），意思是快速移动到外面。"}, {"text": "排除", "is_correct": false, "explanation": "排除（páichú）两个音节声调都与派出不同，意思是消除或去掉。"}], "explanations": {"派出": "派出（pàichū）：指派人员前往某处执行任务。这里是正确答案。", "拍出": "拍出（pāichū）第一音节为第一声，与派出的第四声不同，意思是拍摄或拍打而得到。", "卖出": "卖出（màichū）声母为 m，与派出的 p 不同，声调相同，意思是售卖。", "跑出": "跑出（pǎochū）韵母与声调都与派出不同（ao 与 ai，第三声与第四声），意思是快速移动到外面。", "排除": "排除（páichú）两个音节声调都与派出不同，意思是消除或去掉。"}, "sentence_index": null, "correct_answer": "派出"}, "level_3": {"options": [{"text": "派出", "is_correct": true, "explanation": "符合语境：市里曾派一个小组去那里工作，正是派出过的用法。"}, {"text": "解散", "is_correct": false, "explanation": "语义：“解散”是使集体散开，与后面的“去那里工作”矛盾。"}, {"text": "撤销", "is_correct": false, "explanation": "搭配：“撤销”多用于撤销决定或命令，不用于让小组去工作。"}, {"text": "召回", "is_correct": false, "explanation": "语义：“召回”是叫回，与“去那里工作”的方向相反。"}], "explanations": {"派出": "符合语境：市里曾派一个小组去那里工作，正是派出过的用法。", "解散": "语义：“解散”是使集体散开，与后面的“去那里工作”矛盾。", "撤销": "搭配：“撤销”多用于撤销决定或命令，不用于让小组去工作。", "召回": "语义：“召回”是叫回，与“去那里工作”的方向相反。"}, "sentence_index": 6, "correct_answer": "派出"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老板派出任务给小王。", "explanation": "这里应该用〈派给〉。派出指派人员去某处执行任务，把任务分给某人要用派给。"}, {"text": "电视台下周派出一档新节目。", "explanation": "这里应该用〈播出〉。派出只用于派人或车辆去某处，节目的播放要用播出。"}, {"text": "这个词派出很多新词。", "explanation": "这里应该用〈派生〉。派出指派人员，词语衍生出新词要用派生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91024, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "学校派出着一名老师去外地培训。", "corrected_sentence": "学校派出了一名老师去外地培训。", "error_description": "体标错误：“派出”表示一次完成的指派，应用“了”，不能用“着”，应说“派出了一名老师”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91024, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "总部派出着一位翻译去现场。", "corrected_sentence": "总部派出了一位翻译去现场。", "error_description": "体标错误：“派出”表示一次完成的指派，应用“了”，不能用“着”，应说“派出了一位翻译”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5b3ad32-f774-4069-8045-2320bc9599ed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91025, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "战争", "is_correct": true, "explanation": "正确：“和平”与“战争”是反义词，“世界和平”指各国不打仗的状态，两者在这一义项上相对。"}, {"text": "友谊", "is_correct": false, "explanation": "“友谊”是人与人之间的情感，与“世界和平”的意思没有对立关系。"}, {"text": "团结", "is_correct": false, "explanation": "“团结”指人们齐心协力，与“世界和平”并不构成反义关系。"}, {"text": "繁荣", "is_correct": false, "explanation": "“繁荣”指经济或文化兴盛，与“世界和平”的意思没有对立关系。"}], "correct_answer": "战争", "explanations": {"战争": "正确：“和平”与“战争”是反义词，“世界和平”指各国不打仗的状态，两者在这一义项上相对。", "友谊": "“友谊”是人与人之间的情感，与“世界和平”的意思没有对立关系。", "团结": "“团结”指人们齐心协力，与“世界和平”并不构成反义关系。", "繁荣": "“繁荣”指经济或文化兴盛，与“世界和平”的意思没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91025, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "战争", "is_correct": true, "explanation": "正确：“和平”与“战争”是反义词，“世界和平”指没有战争的状态，两者在这一义项上相对。"}, {"text": "秩序", "is_correct": false, "explanation": "“秩序”指有条理的状态，与“世界和平”并不构成反义关系。"}, {"text": "文明", "is_correct": false, "explanation": "“文明”指社会发展的进步状态，与“世界和平”的意思没有对立关系。"}, {"text": "进步", "is_correct": false, "explanation": "“进步”指向前发展，与“世界和平”的意思没有对立关系。"}], "correct_answer": "战争", "explanations": {"战争": "正确：“和平”与“战争”是反义词，“世界和平”指没有战争的状态，两者在这一义项上相对。", "秩序": "“秩序”指有条理的状态，与“世界和平”并不构成反义关系。", "文明": "“文明”指社会发展的进步状态，与“世界和平”的意思没有对立关系。", "进步": "“进步”指向前发展，与“世界和平”的意思没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91025, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "世界和平是全世界的人都不打仗，好好生活。", "primary_collocate": null, "pronunciation": "shì jiè hé píng", "ipa": "ʂʐ̩˥˩ tɕjɛ˥˩ xɤ˧˥ pʰiŋ˧˥", "syllable_count": 4, "sentences": [{"text": "我的愿望是世界和平。", "target_word": "世界和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界和平，就是大家都不打仗。", "target_word": "世界和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明在作文里写了世界和平。", "target_word": "世界和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，爷爷说希望世界和平。", "target_word": "世界和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我们：世界和平是什么？", "target_word": "世界和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界和平让孩子们都能安心上学。", "target_word": "世界和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她唱了一首关于世界和平的歌。", "target_word": "世界和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们都追求世界和平。", "target_word": "世界和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界和平的那一天，大家都会很高兴。", "target_word": "世界和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友们在墙上写着“世界和平”。", "target_word": "世界和平", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "世界和平：全世界的人不打仗、安心过日子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '422192c1-2427-4ec1-9369-3724e9165a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91025, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "世界和平", "is_correct": true, "explanation": "正确：“我的愿望是……”后面接“世界和平”，符合句意。"}, {"text": "战争", "is_correct": false, "explanation": "语义：战争是人们不希望的事情，不能作为“愿望”的内容。"}, {"text": "饥荒", "is_correct": false, "explanation": "语义：饥荒是人们想要避免的灾难，与“愿望”的意思相反。"}, {"text": "污染", "is_correct": false, "explanation": "搭配：“愿望是污染”不搭配，人们不会把环境污染当作愿望。"}], "explanations": {"世界和平": "正确：“我的愿望是……”后面接“世界和平”，符合句意。", "战争": "语义：战争是人们不希望的事情，不能作为“愿望”的内容。", "饥荒": "语义：饥荒是人们想要避免的灾难，与“愿望”的意思相反。", "污染": "搭配：“愿望是污染”不搭配，人们不会把环境污染当作愿望。"}, "sentence_index": 0, "correct_answer": "世界和平"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他借了我一份世界和平，一直没还。", "explanation": "这里应该用〈书〉这类可以借的物品。“世界和平”是抽象状态，不能被借来借去。"}, {"text": "这间屋子里放着一个世界和平。", "explanation": "这里应该用〈花瓶〉这类具体物品。“世界和平”是抽象状态，不能当作实物放在屋子里。"}, {"text": "他很喜欢吃世界和平。", "explanation": "这里应该用〈饭菜〉。“世界和平”是抽象状态，不能被吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91025, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "世界和平", "is_correct": true, "explanation": "正确：“关于……的歌”中，“世界和平”作为主题，符合句意。"}, {"text": "已经", "is_correct": false, "explanation": "语法：“已经”是副词，不能放在“关于……的”中间作名词用。"}, {"text": "非常", "is_correct": false, "explanation": "语法：“非常”是副词，不能作“关于”的宾语。"}, {"text": "刚才", "is_correct": false, "explanation": "语义：“刚才”只表示时间，“关于刚才的歌”说不通。"}], "explanations": {"世界和平": "正确：“关于……的歌”中，“世界和平”作为主题，符合句意。", "已经": "语法：“已经”是副词，不能放在“关于……的”中间作名词用。", "非常": "语法：“非常”是副词，不能作“关于”的宾语。", "刚才": "语义：“刚才”只表示时间，“关于刚才的歌”说不通。"}, "sentence_index": 6, "correct_answer": "世界和平"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她把世界和平放进了行李箱。", "explanation": "这里应该用〈衣服〉这类可以放进行李箱的物品。“世界和平”是抽象状态，不能放进行李箱。"}, {"text": "这棵树的世界和平很大。", "explanation": "这里应该用〈树冠〉。“世界和平”是状态，没有大小，不能像树冠那样说“大”。"}, {"text": "这位老人每天都在修理世界和平。", "explanation": "这里应该用〈收音机〉这类可以修理的机器。“世界和平”是抽象状态，不能修理。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91025, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老师带我们世界和平写了祝福卡。", "corrected_sentence": "老师带我们为世界和平写了祝福卡。", "error_description": "错误形式：“世界和平写了祝福卡”漏掉了介词“为”。正确形式：“为世界和平写了祝福卡”，“为”引出目的。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91025, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在歌里唱着对世界和平期盼。", "corrected_sentence": "她在歌里唱着对世界和平的期盼。", "error_description": "错误形式：“世界和平”修饰“期盼”时漏掉了“的”。正确形式：“对世界和平的期盼”，定语后面要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91026, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "战争", "is_correct": true, "explanation": "正确：“和平”与“战争”是反义词，“世界和平”指没有战争的状态，两者在这一义项上相对。"}, {"text": "友谊", "is_correct": false, "explanation": "“友谊”是人与人之间的情感，与“世界和平”的意思没有对立关系。"}, {"text": "合作", "is_correct": false, "explanation": "“合作”指共同完成某事，与“世界和平”并不构成反义关系。"}, {"text": "繁荣", "is_correct": false, "explanation": "“繁荣”指经济或文化兴盛，与“世界和平”的意思没有对立关系。"}], "correct_answer": "战争", "explanations": {"战争": "正确：“和平”与“战争”是反义词，“世界和平”指没有战争的状态，两者在这一义项上相对。", "友谊": "“友谊”是人与人之间的情感，与“世界和平”的意思没有对立关系。", "合作": "“合作”指共同完成某事，与“世界和平”并不构成反义关系。", "繁荣": "“繁荣”指经济或文化兴盛，与“世界和平”的意思没有对立关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91026, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "战争", "is_correct": true, "explanation": "正确：“和平”与“战争”是反义词，“世界和平”指没有战争的状态，两者在这一义项上相对。"}, {"text": "秩序", "is_correct": false, "explanation": "“秩序”指有条理的状态，与“世界和平”并不构成反义关系。"}, {"text": "文明", "is_correct": false, "explanation": "“文明”指社会发展的进步状态，与“世界和平”的意思没有对立关系。"}, {"text": "进步", "is_correct": false, "explanation": "“进步”指向前发展，与“世界和平”的意思没有对立关系。"}], "correct_answer": "战争", "explanations": {"战争": "正确：“和平”与“战争”是反义词，“世界和平”指没有战争的状态，两者在这一义项上相对。", "秩序": "“秩序”指有条理的状态，与“世界和平”并不构成反义关系。", "文明": "“文明”指社会发展的进步状态，与“世界和平”的意思没有对立关系。", "进步": "“进步”指向前发展，与“世界和平”的意思没有对立关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91026, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "指各国之间没有战争、人们安定共处的状态。", "primary_collocate": null, "pronunciation": "shì jiè hé píng", "ipa": "ʂʐ̩˥˩ tɕjɛ˥˩ xɤ˧˥ pʰiŋ˧˥", "syllable_count": 4, "sentences": [{"text": "大家都希望世界和平。", "target_word": "世界和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界和平对每个国家都很重要。", "target_word": "世界和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老人一生都在为世界和平工作。", "target_word": "世界和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各国携手合作，才能迎来世界和平。", "target_word": "世界和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在会上说，世界和平需要大家一起努力。", "target_word": "世界和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们画了一幅关于世界和平的画。", "target_word": "世界和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "联合国想让世界和平的梦想成真。", "target_word": "世界和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "世界和平不是一句空话。", "target_word": "世界和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各国领导人都谈到了世界和平。", "target_word": "世界和平", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了世界和平，两国同意停火。", "target_word": "世界和平", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "世界和平：各国之间没有战争、安定共处的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '422192c1-2427-4ec1-9369-3724e9165a9e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91026, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "世界和平", "is_correct": true, "explanation": "正确：“希望”的宾语是“世界和平”，指各国之间没有战争、安定共处的状态，符合句意。"}, {"text": "战争", "is_correct": false, "explanation": "语义：战争是人们不希望出现的状态，“大家都希望战争”与常识相反。"}, {"text": "饥荒", "is_correct": false, "explanation": "语义：饥荒是人们想要避免的灾难，不能作为“希望”的对象。"}, {"text": "污染", "is_correct": false, "explanation": "搭配：“希望”后面接“污染”不搭配，人们不会希望环境被污染。"}], "explanations": {"世界和平": "正确：“希望”的宾语是“世界和平”，指各国之间没有战争、安定共处的状态，符合句意。", "战争": "语义：战争是人们不希望出现的状态，“大家都希望战争”与常识相反。", "饥荒": "语义：饥荒是人们想要避免的灾难，不能作为“希望”的对象。", "污染": "搭配：“希望”后面接“污染”不搭配，人们不会希望环境被污染。"}, "sentence_index": 0, "correct_answer": "世界和平"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们昨天举行了一次世界和平。", "explanation": "这里把“世界和平”当成了可以举行的活动，应该用〈和平会议〉这类表示活动的词。“世界和平”指一种状态，不能被举行。"}, {"text": "这个小盒子里装着一份世界和平。", "explanation": "这里把抽象的“世界和平”当成了具体事物，应该用〈礼物〉这类实物。“世界和平”是抽象状态，不能装进盒子。"}, {"text": "他每天早上都喝一杯世界和平。", "explanation": "这里应该用〈茶〉这类饮品。“世界和平”是抽象状态，不能被喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91026, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "世界和平", "is_correct": true, "explanation": "正确：“联合国想让……的梦想成真”中，“世界和平”修饰“梦想”，符合句意。"}, {"text": "饥饿", "is_correct": false, "explanation": "语义：“饥饿”是人们想要摆脱的困境，不能作为“梦想”的内容。"}, {"text": "贫困", "is_correct": false, "explanation": "语义：“贫困”是需要消除的问题，把它作为“梦想”的内容与句意不符。"}, {"text": "灾难", "is_correct": false, "explanation": "语义：“灾难”是人们想要避免的事情，不能作为“梦想”的内容。"}], "explanations": {"世界和平": "正确：“联合国想让……的梦想成真”中，“世界和平”修饰“梦想”，符合句意。", "饥饿": "语义：“饥饿”是人们想要摆脱的困境，不能作为“梦想”的内容。", "贫困": "语义：“贫困”是需要消除的问题，把它作为“梦想”的内容与句意不符。", "灾难": "语义：“灾难”是人们想要避免的事情，不能作为“梦想”的内容。"}, "sentence_index": 6, "correct_answer": "世界和平"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "那个人的世界和平很高，大家都很佩服他。", "explanation": "这里应该用〈境界〉。“世界和平”是状态，没有高低，不能像境界那样说“高”。"}, {"text": "妈妈每天都在厨房里洗世界和平。", "explanation": "“洗”的对象应该是衣服、碗等具体的东西。“世界和平”是抽象状态，不能被洗。"}, {"text": "我借了他一份世界和平，还没还。", "explanation": "这里把“世界和平”当成了可以借出的东西，应该用〈书〉这类可以借的物品。“世界和平”是抽象状态，不能借。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91026, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们都希望世界和平做贡献。", "corrected_sentence": "我们都希望为世界和平做贡献。", "error_description": "错误形式：“世界和平做贡献”漏掉了介词“为”。正确形式：“为世界和平做贡献”，“为”引出做贡献的目的，要放在“世界和平”前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91026, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这首歌表达了人们对世界和平渴望。", "corrected_sentence": "这首歌表达了人们对世界和平的渴望。", "error_description": "错误形式：“世界和平”修饰“渴望”时漏掉了“的”。正确形式：“对世界和平的渴望”，定语后面要加“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ceb23b19-1d3b-4a6c-a3a0-566c7aa9e9d9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
