INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91027, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "听见是耳朵知道了声音。", "primary_collocate": null, "pronunciation": "tīng jiàn", "ipa": "tʰiŋ˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "我在门外听见有人叫我。", "target_word": "听见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天晚上你听见雷声了吗？", "target_word": "听见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他戴着耳机，没听见我说话。", "target_word": "听见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我好像听见楼上有小孩在哭。", "target_word": "听见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她听见门铃响了，马上去开门。", "target_word": "听见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你听见我刚才说的话了吗？", "target_word": "听见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里很安静，我听见了自己的心跳。", "target_word": "听见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人耳朵不好，大声说他才听见。", "target_word": "听见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我从来没听见过这么好听的歌。", "target_word": "听见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们听见铃声，都跑出了教室。", "target_word": "听见", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "听见了", "label": "体标（完成）"}, {"form": "听见过", "label": "体标（经历）"}, {"form": "没听见", "label": "否定式"}, {"form": "听得见", "label": "可能补语（肯定）"}, {"form": "听不见", "label": "可能补语（否定）"}], "register": "中性", "sense_fingerprint": "耳朵知道了声音；结果补语式动词，常说听见了、没听见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940b2af-c4cb-48b8-9d0b-57e75b82fbed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91027, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "听见", "is_correct": true, "explanation": "听见：耳朵感知到声音，与“有人叫我”相符。"}, {"text": "闻到", "is_correct": false, "explanation": "语义：“闻到”是嗅觉，不能感知“有人叫我”的声音，句子不通。"}, {"text": "摸到", "is_correct": false, "explanation": "搭配：“摸到”的宾语应是实物，不能接“有人叫我”这样的声音内容。"}, {"text": "尝到", "is_correct": false, "explanation": "语义：“尝到”是味觉，与“有人叫我”的语义无关，句子不通。"}], "explanations": {"听见": "听见：耳朵感知到声音，与“有人叫我”相符。", "闻到": "语义：“闻到”是嗅觉，不能感知“有人叫我”的声音，句子不通。", "摸到": "搭配：“摸到”的宾语应是实物，不能接“有人叫我”这样的声音内容。", "尝到": "语义：“尝到”是味觉，与“有人叫我”的语义无关，句子不通。"}, "sentence_index": 0, "correct_answer": "听见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在路上听见了一个熟人。", "explanation": "这里应该用〈看见〉。听见表示听到声音，遇到人要用“看见”。"}, {"text": "我听见了他的意思。", "explanation": "这里应该用〈听懂〉。听见只表示听到声音，理解意思要用“听懂”。"}, {"text": "我听见了饭菜的香味。", "explanation": "这里应该用〈闻到〉。听见用于声音，香味是气味，要用“闻到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91027, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "听见", "is_correct": true, "explanation": "听见：耳朵感知到声音，与“自己的心跳”的语境相符。"}, {"text": "看见", "is_correct": false, "explanation": "语义：“看见”是视觉，不能用于“心跳”这类声音，句子不通。"}, {"text": "嗅到", "is_correct": false, "explanation": "语义：“嗅到”是嗅觉，不能感知“心跳”，句子不通。"}, {"text": "舔到", "is_correct": false, "explanation": "搭配：“舔到”的宾语应是可接触的物体，不能接“心跳”。"}], "explanations": {"听见": "听见：耳朵感知到声音，与“自己的心跳”的语境相符。", "看见": "语义：“看见”是视觉，不能用于“心跳”这类声音，句子不通。", "嗅到": "语义：“嗅到”是嗅觉，不能感知“心跳”，句子不通。", "舔到": "搭配：“舔到”的宾语应是可接触的物体，不能接“心跳”。"}, "sentence_index": 6, "correct_answer": "听见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师让我们听见生词。", "explanation": "这里应该用〈听写〉。听见指听到声音，听写是听声音后把内容写下来，此处不能用“听见”。"}, {"text": "我仔细听见了他的表情。", "explanation": "这里应该用〈观察〉。听见只表示听到声音，观察表情要用“观察”。"}, {"text": "我听见了温暖的阳光。", "explanation": "这里应该用〈感受到〉。听见只能用于声音，阳光的温暖要用“感受到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91027, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我刚才没听见了门口的敲门声。", "corrected_sentence": "我刚才没听见门口的敲门声。", "error_description": "“没”否定已发生的动作时，句中不加“了”。应为“没听见”，不能说“没听见了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91027, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我从来没听见着这么好听的声音。", "corrected_sentence": "我从来没听见过这么好听的声音。", "error_description": "表示有过这种经历时，“听见”后用“过”，否定说“没听见过”。这里误用“着”，“没听见着”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
