INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91028, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "耳朵感受到声音。", "primary_collocate": null, "pronunciation": "tīng jiàn", "ipa": "tʰiŋ˥ tɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "太吵了，我什么也没听见。", "target_word": "听见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "窗外下雨了，我听见了雨声。", "target_word": "听见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他站在远处，听见了鸟叫。", "target_word": "听见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你在房间里能听见外面的音乐吗？", "target_word": "听见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "半夜我听见猫在院子里叫。", "target_word": "听见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喊了好几次，她都没听见。", "target_word": "听见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她听见自己的名字，回头看了看。", "target_word": "听见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山里很静，能听见河水的声音。", "target_word": "听见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你再说一遍，我刚才没听见。", "target_word": "听见", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗听见主人回来，高兴地跑过去。", "target_word": "听见", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "听见了", "label": "体标（完成）"}, {"form": "听见过", "label": "体标（经历）"}, {"form": "没听见", "label": "否定式"}, {"form": "听得见", "label": "可能补语（肯定）"}, {"form": "听不见", "label": "可能补语（否定）"}], "register": "中性", "sense_fingerprint": "耳朵感受到外界的声音（雨声、鸟叫、名字等）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd940b2af-c4cb-48b8-9d0b-57e75b82fbed') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91028, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "听见", "is_correct": true, "explanation": "听见：耳朵感受到声音，与“太吵”的语境相符。"}, {"text": "闻到", "is_correct": false, "explanation": "语义：“闻到”是嗅觉，与“太吵”的听觉语境不符，句子不通。"}, {"text": "尝到", "is_correct": false, "explanation": "语义：“尝到”是味觉，与“太吵”的语境不符，句子不通。"}, {"text": "舔到", "is_correct": false, "explanation": "搭配：“舔到”的宾语必须是物体，不能与“太吵”这种声音语境搭配。"}], "explanations": {"听见": "听见：耳朵感受到声音，与“太吵”的语境相符。", "闻到": "语义：“闻到”是嗅觉，与“太吵”的听觉语境不符，句子不通。", "尝到": "语义：“尝到”是味觉，与“太吵”的语境不符，句子不通。", "舔到": "搭配：“舔到”的宾语必须是物体，不能与“太吵”这种声音语境搭配。"}, "sentence_index": 0, "correct_answer": "听见"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我站在窗口，听见了外面的大树。", "explanation": "这里应该用〈看见〉。听见用于声音，看到树木要用“看见”。"}, {"text": "这段英文我听见了意思。", "explanation": "这里应该用〈听懂〉。听见只表示听到声音，理解意思要用“听懂”。"}, {"text": "我听见了厨房里的饭香。", "explanation": "这里应该用〈闻到〉。听见用于声音，饭香是气味，要用“闻到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91028, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "听见", "is_correct": true, "explanation": "听见：耳朵感受到声音或信息，与“自己的名字”相符。"}, {"text": "嗅到", "is_correct": false, "explanation": "语义：“嗅到”是嗅觉，不能用于“自己的名字”这类声音信息，句子不通。"}, {"text": "品尝", "is_correct": false, "explanation": "搭配：“品尝”的宾语应是食物，不能接“自己的名字”。"}, {"text": "拥抱", "is_correct": false, "explanation": "搭配：“拥抱”的宾语是人或物体，不能接“自己的名字”，句子不通。"}], "explanations": {"听见": "听见：耳朵感受到声音或信息，与“自己的名字”相符。", "嗅到": "语义：“嗅到”是嗅觉，不能用于“自己的名字”这类声音信息，句子不通。", "品尝": "搭配：“品尝”的宾语应是食物，不能接“自己的名字”。", "拥抱": "搭配：“拥抱”的宾语是人或物体，不能接“自己的名字”，句子不通。"}, "sentence_index": 6, "correct_answer": "听见"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师让我们听见生词。", "explanation": "这里应该用〈听写〉。听见指听到声音，听写是听声音后把内容写下来，此处不能用“听见”。"}, {"text": "我仔细听见了他的表情。", "explanation": "这里应该用〈观察〉。听见只表示听到声音，观察表情要用“观察”。"}, {"text": "我听见了温暖的阳光。", "explanation": "这里应该用〈感受到〉。听见只能用于声音，阳光的温暖要用“感受到”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91028, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我刚才听见到门外有雨声。", "corrected_sentence": "我刚才听见门外有雨声。", "error_description": "结果补语“见”后面不能再加补语“到”，“听见到”是重复补语。应为“听见”，不能说“听见到”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91028, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我在屋里听见着外面的雨声。", "corrected_sentence": "我在屋里听见了外面的雨声。", "error_description": "“听见”是动结式（“见”为结果补语），表示已经听到，不能与“着”连用。应为“听见了”；若要表示持续地听，应说“听着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3cde68e5-a9af-4d19-ba99-458cbbb0db1b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
