INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91030, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "海边由沙或砾石堆积而成的平坦地带。", "primary_collocate": null, "pronunciation": "hǎi tān", "ipa": "xaɪ˨˩˦ tʰan˥", "syllable_count": 2, "sentences": [{"text": "我们周末去海滩晒太阳。", "target_word": "海滩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海滩上的沙子又细又软。", "target_word": "海滩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子们在海滩上堆沙堡。", "target_word": "海滩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "海滩上有很多人在散步。", "target_word": "海滩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "退潮以后，海滩变得很宽。", "target_word": "海滩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在海滩捡了几个漂亮的贝壳。", "target_word": "海滩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这片海滩很长，也很干净。", "target_word": "海滩", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "傍晚的海滩上吹着凉凉的风。", "target_word": "海滩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她光着脚走在海滩上。", "target_word": "海滩", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夏天海滩边有人卖冰淇淋。", "target_word": "海滩", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一片海滩", "label": "量词"}, {"form": "海灘", "label": "繁体"}], "register": "中性", "sense_fingerprint": "海边由沙或砾石堆成的平坦地带", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '72962ab9-2347-4d76-bde0-711257f30022') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91030, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "海滩", "is_correct": true, "explanation": "正确：海滩是可以晒太阳的沙质海岸，符合“去……晒太阳”的语境。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是上课的地方，不能去那里晒太阳。"}, {"text": "图书馆", "is_correct": false, "explanation": "搭配：“晒太阳”需要在室外进行，不能和“图书馆”搭配。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是做饭的地方，与晒太阳毫不相干。"}], "explanations": {"海滩": "正确：海滩是可以晒太阳的沙质海岸，符合“去……晒太阳”的语境。", "教室": "语义：教室是上课的地方，不能去那里晒太阳。", "图书馆": "搭配：“晒太阳”需要在室外进行，不能和“图书馆”搭配。", "厨房": "语义：厨房是做饭的地方，与晒太阳毫不相干。"}, "sentence_index": 0, "correct_answer": "海滩"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我把海滩放进了冰箱。", "explanation": "这里应该用〈海鲜〉。海滩是一大片沙地，不能放进冰箱；可以放进冰箱的是海鲜。"}, {"text": "我们在海滩里游泳。", "explanation": "这里应该用〈海洋〉。游泳要在水里进行，海滩是岸边的沙地，不能说“在海滩里游泳”。"}, {"text": "我们在一只海滩上玩了一天。", "explanation": "这里应该用〈一片〉。海滩是一大片沙地，量词要用“片”，不用“只”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '368b17be-b77b-4d2e-91c3-c770dd783268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91030, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "海滩", "is_correct": true, "explanation": "正确：海滩是一大片沙地，可以用“这片”修饰，并且“很长、很干净”符合海滩的特点。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音看不见，不能用“这片……很长，也很干净”来描述。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：“片”不用于书包，“很长”也不用来形容书包。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是通讯工具，不能用“很长”来描述其范围。"}], "explanations": {"海滩": "正确：海滩是一大片沙地，可以用“这片”修饰，并且“很长、很干净”符合海滩的特点。", "声音": "语义：声音看不见，不能用“这片……很长，也很干净”来描述。", "书包": "搭配：“片”不用于书包，“很长”也不用来形容书包。", "手机": "语义：手机是通讯工具，不能用“很长”来描述其范围。"}, "sentence_index": 6, "correct_answer": "海滩"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把海滩捧在手里看了看。", "explanation": "这里应该用〈沙子〉。海滩是一大片地方，不能捧在手里；捧在手里的是沙子。"}, {"text": "孩子跳进了海滩里。", "explanation": "这里应该用〈水〉。孩子要跳进水里，海滩不是水，不能说“跳进海滩里”。"}, {"text": "这颗海滩很长。", "explanation": "这里应该用〈片〉。海滩是一大片沙地，量词要用“片”，“颗”用于小而圆的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '368b17be-b77b-4d2e-91c3-c770dd783268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91030, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们在一只海滩上搭了帐篷。", "corrected_sentence": "我们在一片海滩上搭了帐篷。", "error_description": "错误：量词“只”不能用于“海滩”，应用“片”；正确为“一片海滩”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '368b17be-b77b-4d2e-91c3-c770dd783268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91030, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "傍晚，一只海滩边有人在放风筝。", "corrected_sentence": "傍晚，海滩边有人在放风筝。", "error_description": "错误：“海滩”前多了“一只”，量词“只”不能用于“海滩”；正确为不加数量短语的“海滩边”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '368b17be-b77b-4d2e-91c3-c770dd783268') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
