INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91031, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "主机是电脑里最主要的那个盒子，里面有芯片。", "primary_collocate": null, "pronunciation": "zhǔ jī", "ipa": "ʈʂu˨˩ tɕi˥", "syllable_count": 2, "sentences": [{"text": "我的电脑主机放在桌子下面。", "target_word": "主机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台主机的声音很大。", "target_word": "主机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屏幕亮着，可是主机没有开。", "target_word": "主机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了新主机，旧的送给弟弟。", "target_word": "主机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主机里面有很多小零件。", "target_word": "主机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把键盘接到主机上。", "target_word": "主机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主机太热了，要关一会儿。", "target_word": "主机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥自己装了一台主机。", "target_word": "主机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台主机是白色的，放在桌上很好看。", "target_word": "主机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主机坏了，电脑打不开。", "target_word": "主机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "电脑主机", "label": "复合"}, {"form": "主机箱", "label": "复合"}], "register": "中性", "sense_fingerprint": "电脑里装着芯片的那个主要盒子（机箱部分）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b342a05-3699-4607-9d19-13216e1ae00e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91031, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "主机", "is_correct": true, "explanation": "正确：“主机”读作 zhǔ jī，指电脑里装有芯片的主要机箱。"}, {"text": "竹鸡", "is_correct": false, "explanation": "zhú 与 zhǔ 声母韵母相同，只差声调（2 声／3 声），意思是一种生活在竹林里的小型鸟类。"}, {"text": "柱基", "is_correct": false, "explanation": "zhù 与 zhǔ 声母韵母相同，只差声调（4 声／3 声），意思是柱子的底座。"}, {"text": "阻击", "is_correct": false, "explanation": "zǔ 与 zhǔ 声母不同（z／zh），声调相同，意思是拦截并打击敌人。"}], "explanations": {"主机": "正确：“主机”读作 zhǔ jī，指电脑里装有芯片的主要机箱。", "竹鸡": "zhú 与 zhǔ 声母韵母相同，只差声调（2 声／3 声），意思是一种生活在竹林里的小型鸟类。", "柱基": "zhù 与 zhǔ 声母韵母相同，只差声调（4 声／3 声），意思是柱子的底座。", "阻击": "zǔ 与 zhǔ 声母不同（z／zh），声调相同，意思是拦截并打击敌人。"}, "sentence_index": null, "correct_answer": "主机"}, "level_3": {"options": [{"text": "主机", "is_correct": true, "explanation": "正确：“我的电脑主机放在桌子下面”符合句意，主机即电脑的机箱。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不是电脑的部件，“电脑冰箱”句子不通。"}, {"text": "沙发", "is_correct": false, "explanation": "搭配：“电脑”不与“沙发”组合，说成“电脑沙发”不通。"}, {"text": "书柜", "is_correct": false, "explanation": "语义：书柜不是电脑的部件，“电脑书柜”句子不通。"}], "explanations": {"主机": "正确：“我的电脑主机放在桌子下面”符合句意，主机即电脑的机箱。", "冰箱": "语义：冰箱不是电脑的部件，“电脑冰箱”句子不通。", "沙发": "搭配：“电脑”不与“沙发”组合，说成“电脑沙发”不通。", "书柜": "语义：书柜不是电脑的部件，“电脑书柜”句子不通。"}, "sentence_index": 0, "correct_answer": "主机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只主机。", "explanation": "这里应该用〈台〉。主机是机器，量词用“台”，“只”多用于动物或成对物品中的一个。"}, {"text": "周末我坐在沙发上，盯着主机看电影。", "explanation": "这里应该用〈显示器〉。主机是放在桌下的机箱，看画面要看显示器。"}, {"text": "我把主机放进背包，带去教室上课。", "explanation": "这里应该用〈笔记本〉。主机是台式机的机箱，不能放进背包随身带。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91031, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "主机", "is_correct": true, "explanation": "正确：“主机”读作 zhǔ jī，指电脑里装有芯片的主要机箱。"}, {"text": "珠玑", "is_correct": false, "explanation": "zhū 与 zhǔ 声母韵母相同，只差声调（1 声／3 声），意思是珍珠和美玉，比喻精美的事物。"}, {"text": "竹鸡", "is_correct": false, "explanation": "zhú 与 zhǔ 声母韵母相同，只差声调（2 声／3 声），意思是一种生活在竹林里的小型鸟类。"}, {"text": "筑基", "is_correct": false, "explanation": "zhù 与 zhǔ 声母韵母相同，只差声调（4 声／3 声），意思是修建地基、打下根基。"}], "explanations": {"主机": "正确：“主机”读作 zhǔ jī，指电脑里装有芯片的主要机箱。", "珠玑": "zhū 与 zhǔ 声母韵母相同，只差声调（1 声／3 声），意思是珍珠和美玉，比喻精美的事物。", "竹鸡": "zhú 与 zhǔ 声母韵母相同，只差声调（2 声／3 声），意思是一种生活在竹林里的小型鸟类。", "筑基": "zhù 与 zhǔ 声母韵母相同，只差声调（4 声／3 声），意思是修建地基、打下根基。"}, "sentence_index": null, "correct_answer": "主机"}, "level_3": {"options": [{"text": "主机", "is_correct": true, "explanation": "正确：“主机太热了，要关一会儿”符合句意。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包不需要关机降温，“面包太热了，要关一会儿”句子不通。"}, {"text": "小说", "is_correct": false, "explanation": "语义：小说不能开关，“小说太热了，要关一会儿”句子不通。"}, {"text": "课桌", "is_correct": false, "explanation": "搭配：“关”不能用于课桌，句子不通。"}], "explanations": {"主机": "正确：“主机太热了，要关一会儿”符合句意。", "面包": "语义：面包不需要关机降温，“面包太热了，要关一会儿”句子不通。", "小说": "语义：小说不能开关，“小说太热了，要关一会儿”句子不通。", "课桌": "搭配：“关”不能用于课桌，句子不通。"}, "sentence_index": 6, "correct_answer": "主机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我用主机点击屏幕上的图标。", "explanation": "这里应该用〈鼠标〉。主机是放在桌下的机箱，不能用来点击图标。"}, {"text": "我用主机打字，很快就写完了。", "explanation": "这里应该用〈键盘〉。主机不是输入设备，打字要用键盘。"}, {"text": "我戴上主机听歌。", "explanation": "这里应该用〈耳机〉。主机是机箱，不能戴在头上，听歌要用耳机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91031, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家新买了一辆主机，速度很快。", "corrected_sentence": "我家新买了一台主机，速度很快。", "error_description": "“主机”是机器，量词应用“台”，不能用“辆”，“辆”只用于车。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91031, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我新买主机很安静。", "corrected_sentence": "我新买的主机很安静。", "error_description": "“新买”修饰“主机”时要加助词“的”，漏掉“的”句子就不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
