INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91032, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大型计算机或服务器中，承担核心运算并连接、控制多台终端的中心主机。", "primary_collocate": null, "pronunciation": "zhǔ jī", "ipa": "ʈʂu˨˩ tɕi˥", "syllable_count": 2, "sentences": [{"text": "银行的主机装有很多处理器和内存。", "target_word": "主机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台主机同时连着上百台终端。", "target_word": "主机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工厂里的主机一直开着。", "target_word": "主机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主机坏了，网站就打不开了。", "target_word": "主机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司的主机放在一个很冷的房间里。", "target_word": "主机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工程师正在检查主机的内存。", "target_word": "主机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主机连着很多台小机器。", "target_word": "主机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种主机能同时处理很多工作。", "target_word": "主机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们换了一台新主机，速度快多了。", "target_word": "主机", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主机出了问题，所有的机器都停了。", "target_word": "主机", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "台", "label": "量词"}, {"form": "大型主机", "label": "复合"}, {"form": "主机房", "label": "复合"}], "register": "中性", "sense_fingerprint": "大型机或服务器的中心主机，连接并控制多台终端（区别于台式机箱）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b342a05-3699-4607-9d19-13216e1ae00e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91032, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "主机", "is_correct": true, "explanation": "正确：“主机”读作 zhǔ jī，指连接并控制多台终端的中心计算机。"}, {"text": "竹鸡", "is_correct": false, "explanation": "zhú 与 zhǔ 声母韵母相同，只差声调（2 声／3 声），意思是一种生活在竹林里的小型鸟类。"}, {"text": "柱基", "is_correct": false, "explanation": "zhù 与 zhǔ 声母韵母相同，只差声调（4 声／3 声），意思是柱子的底座。"}, {"text": "阻击", "is_correct": false, "explanation": "zǔ 与 zhǔ 声母不同（z／zh），声调相同，意思是拦截并打击敌人。"}, {"text": "主计", "is_correct": false, "explanation": "jì 与 jī 韵母相同，只差声调（4 声／1 声），意思是掌管会计统计的主管。"}], "explanations": {"主机": "正确：“主机”读作 zhǔ jī，指连接并控制多台终端的中心计算机。", "竹鸡": "zhú 与 zhǔ 声母韵母相同，只差声调（2 声／3 声），意思是一种生活在竹林里的小型鸟类。", "柱基": "zhù 与 zhǔ 声母韵母相同，只差声调（4 声／3 声），意思是柱子的底座。", "阻击": "zǔ 与 zhǔ 声母不同（z／zh），声调相同，意思是拦截并打击敌人。", "主计": "jì 与 jī 韵母相同，只差声调（4 声／1 声），意思是掌管会计统计的主管。"}, "sentence_index": null, "correct_answer": "主机"}, "level_3": {"options": [{"text": "主机", "is_correct": true, "explanation": "正确：“银行的主机装有很多处理器和内存”符合句意。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱不装处理器和内存，句子不通。"}, {"text": "工人", "is_correct": false, "explanation": "配价：“装有”要求容器作主语，“工人”不能作主语。"}, {"text": "书架", "is_correct": false, "explanation": "语义：书架不装处理器和内存，句子不通。"}], "explanations": {"主机": "正确：“银行的主机装有很多处理器和内存”符合句意。", "冰箱": "语义：冰箱不装处理器和内存，句子不通。", "工人": "配价：“装有”要求容器作主语，“工人”不能作主语。", "书架": "语义：书架不装处理器和内存，句子不通。"}, "sentence_index": 0, "correct_answer": "主机"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工厂新买了一头主机。", "explanation": "这里应该用〈台〉。主机是机器，量词用“台”，“头”只用于牲畜。"}, {"text": "客厅的主机坏了，换个新的，屋里就亮了。", "explanation": "这里应该用〈灯泡〉。主机是机器的主体，不用于照明，这里要说灯泡。"}, {"text": "主机把饭煮熟了。", "explanation": "这里应该用〈电饭煲〉。主机是机器的主体，指电脑或成套设备，不用于煮饭。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91032, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "主机", "is_correct": true, "explanation": "正确：“主机”读作 zhǔ jī，指连接并控制多台终端的中心计算机。"}, {"text": "竹鸡", "is_correct": false, "explanation": "zhú 与 zhǔ 声母韵母相同，只差声调（2 声／3 声），意思是一种生活在竹林里的小型鸟类。"}, {"text": "珠玑", "is_correct": false, "explanation": "zhū 与 zhǔ 声母韵母相同，只差声调（1 声／3 声），意思是珍珠和美玉，比喻精美的事物。"}, {"text": "主祭", "is_correct": false, "explanation": "jì 与 jī 韵母相同，只差声调（4 声／1 声），意思是主持祭礼的人。"}], "explanations": {"主机": "正确：“主机”读作 zhǔ jī，指连接并控制多台终端的中心计算机。", "竹鸡": "zhú 与 zhǔ 声母韵母相同，只差声调（2 声／3 声），意思是一种生活在竹林里的小型鸟类。", "珠玑": "zhū 与 zhǔ 声母韵母相同，只差声调（1 声／3 声），意思是珍珠和美玉，比喻精美的事物。", "主祭": "jì 与 jī 韵母相同，只差声调（4 声／1 声），意思是主持祭礼的人。"}, "sentence_index": null, "correct_answer": "主机"}, "level_3": {"options": [{"text": "主机", "is_correct": true, "explanation": "正确：“主机连着很多台小机器”符合句意。"}, {"text": "花园", "is_correct": false, "explanation": "语义：花园不是连接机器的设备，句子不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不能连接机器，句子不通。"}, {"text": "同学", "is_correct": false, "explanation": "配价：“连着”要求能连接的物件作主语，“同学”不能作主语。"}], "explanations": {"主机": "正确：“主机连着很多台小机器”符合句意。", "花园": "语义：花园不是连接机器的设备，句子不通。", "窗户": "语义：窗户不能连接机器，句子不通。", "同学": "配价：“连着”要求能连接的物件作主语，“同学”不能作主语。"}, "sentence_index": 6, "correct_answer": "主机"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "主机没电了，就不能打电话了。", "explanation": "这里应该用〈手机〉。主机是机器的主体，不能用来打电话。"}, {"text": "主机坏了，里面的菜都热了。", "explanation": "这里应该用〈冰箱〉。主机指一套机器的核心，冰箱不说“主机”。"}, {"text": "主机响了，他起床了。", "explanation": "这里应该用〈闹钟〉。主机不会“响”来叫人起床，闹钟才这样用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91032, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "机房新装了一只主机，网站快多了。", "corrected_sentence": "机房新装了一台主机，网站快多了。", "error_description": "“主机”是机器，量词应用“台”，不能用“只”，“只”多用于动物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91032, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "厂里新换主机速度很快。", "corrected_sentence": "厂里新换的主机速度很快。", "error_description": "“新换”修饰“主机”时要加助词“的”，漏掉“的”句子就不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '29f2e042-4f20-43a4-a4d0-5f9c88b1af45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (91033, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "拘束", "is_correct": true, "explanation": "拘束与自在构成反义关系，指放不开、不自然，与“在朋友家里可以自在一点”相对。"}, {"text": "热闹", "is_correct": false, "explanation": "热闹形容场面喧闹，与“心里舒服”没有反义关系。"}, {"text": "清楚", "is_correct": false, "explanation": "清楚只表示明白、不模糊，与自在无反义关系。"}, {"text": "漂亮", "is_correct": false, "explanation": "漂亮形容外貌或事物好看，与自在无反义关系。"}], "correct_answer": "拘束", "explanations": {"拘束": "拘束与自在构成反义关系，指放不开、不自然，与“在朋友家里可以自在一点”相对。", "热闹": "热闹形容场面喧闹，与“心里舒服”没有反义关系。", "清楚": "清楚只表示明白、不模糊，与自在无反义关系。", "漂亮": "漂亮形容外貌或事物好看，与自在无反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a9ea592-d280-40ce-b3c8-363cfaa4acac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
